window.MAP_DATA_RECORDS.push(...[{"i":"R1530","k":"Senegal","p":"Senegal","b":["Data"],"h":["4.1  Privacy violation"],"t":"Senegal data breach disrupts national id issuance","s":"The Directorate of File Automation announced that measures had been taken by the competent technical services to “restore operations as soon as possible.” The issuance of national ID cards in Senegal recently got halted on a temporary basis after the government reported a data breach that affected the population database. A statement from the Directorate of File Automation (DAF) under the Ministry of Interior and Public Security announced that measures had been taken by the competent technical services to “restore operations as soon as possible.” At the time of this report, the ID issuance process was yet to resume.","u":"https://www.biometricupdate.com/202602/senegal-data-breach-disrupts-national-id-issuance","d":"2025-02-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-11","organization":"Government of Senegal","aiSystem":"Not specified in report","affectedGroup":"Population of Senegal","action":"Data breach of population database","consequence":"Issuance of national ID cards halted temporarily"}},{"i":"R1344","k":"Singapore","p":"Singapore","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"The accountancy giant says artificial intelligence will eventually lead to fewer entry-lev…","s":"The accountancy giant says artificial intelligence will eventually lead to fewer entry-level positions at the firm. The growth of artificial intelligence (AI) may eventually lead to fewer entry-level graduates being hired, the boss of accountancy giant PwC has told the BBC. However, global chairman Mohamed Kande said AI was not behind recent job cuts at the firm, adding that the company actually needed to hire hundreds of new AI engineers but was struggling to find them. But some observers say the technology itself threatens thousands of junior jobs across the professional services industry. Speaking on the sidelines of a business summit in Singapore, Mr Kande also said big changes in the global economy, such as US President Donald Trump's sweeping tariffs, had been good for the firm's consulting business.","u":"https://www.bbc.com/news/articles/cm272510e6jo","d":"2025-11-21","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-21","organization":"accountancy giant PwC","aiSystem":"artificial intelligence","affectedGroup":"entry-level graduates","action":"AI was not behind recent job cuts","consequence":"fewer entry-level positions at the firm"}},{"i":"R1357","k":"Singapore","p":"Singapore","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"An image with the likeness of Mr Mangione was used to advertise a white, short-sleeved shi…","s":"An image with the likeness of Mr Mangione was used to advertise a white, short-sleeved shirt. Fast-fashion giant Shein has launched an investigation after an image of Luigi Mangione - accused of murdering UnitedHealthcare CEO Brian Thompson in New York last year - was used to model a shirt. An image with his likeness, which appeared to show him wearing a white, short-sleeved shirt, appeared on the fast-fashion website until its removal. It is thought the product he appeared to be modelling was on sale for just under $10 (£7.50). A spokesperson from Shein told BBC News: \"The image in question was provided by a third-party vendor and was removed immediately upon discovery.","u":"https://www.bbc.com/news/articles/c4g5vr4vzpzo","d":"2025-09-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-03","organization":"Shein (fast-fashion giant)","aiSystem":"Not specified in report","affectedGroup":"Luigi Mangione (accused murderer)","action":"Used an image of Luigi Mangione to advertise a white, short-sleeved shirt","consequence":"Removal of the image from the website"}},{"i":"R2975","k":"Slovakia","p":"Slovakia","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Slovakias election deepfakes show ai is a danger to democracy","s":"Fact-checkers scrambled to deal with faked audio recordings released days before a tight election, in a warning for other countries with looming votes. Just two days before Slovakia’s elections, an audio recording was posted to Facebook. On it were two voices: allegedly, Michal Šimečka, who leads the liberal Progressive Slovakia party, and Monika Tódová from the daily newspaper Denník N They appeared to be discussing how to rig the election, partly by buying votes from the country’s marginalized Roma minority. Šimečka and Denník N immediately denounced the audio as fake. The fact-checking department of news agency AFP said the audio showed signs of being manipulated using AI.","u":"https://www.wired.com/story/slovakias-election-deepfakes-show-ai-is-a-danger-to-democracy/","d":"2023-10-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-01","organization":"News agency AFP and fact-checkers","aiSystem":"AI-based audio manipulation","affectedGroup":"Voters in Slovakia","action":"Released manipulated audio recordings","consequence":"Spread of misleading election information"}},{"i":"R1467","k":"Somalia","p":"Somalia","b":["Data"],"h":["4.1  Privacy violation"],"t":"Somalia government probes digital visa platform data breach","s":"Information about the breach first surfaced on social media, with claims that the cyber attack led to personal data leaks. Authorities in Somalia are looking into a data leak incident that rocked the country’s new digital visa platform which went operational in September. Information about the breach first surfaced on social media, with claims that the attack led to personal data leaks. Authorities earlier rejected the allegations, but later in a statement , the Somalia Immigration and Citizenship Agency (HSJ) confirmed the incident saying that it had “detected an illegal breach” targeting part of the data belonging to passengers traveling to Somalia through the Electronic Travel Authorization System (e-TAS).","u":"https://www.biometricupdate.com/202511/somalia-government-probes-digital-visa-platform-data-breach","d":"2025-11-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-18","organization":"Somalia Immigration and Citizenship Agency (HSJ)","aiSystem":"Digital visa platform","affectedGroup":"Passengers traveling to Somalia","action":"Detected an illegal breach targeting part of the data","consequence":"Personal data leaks"}},{"i":"R590","k":"South Africa","p":"South Africa","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Grok white genocide response generative ai weaponization","s":"The Grok incident back in May 2025 shows how an individual may be able to secretly manipulate the responses of an AI system. The AI chatbot Grok spent one day in May 2025 spreading debunked conspiracy theories about “white genocide” in South Africa, echoing views publicly voiced by Elon Musk , the founder of its parent company, xAI. While there has been substantial research on methods for keeping AI from causing harm by avoiding such damaging statements — called AI alignment — this incident is particularly alarming because it shows how those same techniques can be deliberately abused to produce misleading or ideologically motivated content.","u":"https://www.rappler.com/technology/features/grok-white-genocide-response-generative-ai-weaponization/","d":"2025-06-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-01","organization":"xAI (parent company of Grok)","aiSystem":"Grok AI chatbot","affectedGroup":"Public opinion in South Africa","action":"Spreading debunked conspiracy theories about 'white genocide'","consequence":"Misleading or ideologically motivated content"}},{"i":"R993","k":"South Africa","p":"South Africa","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Elon musks grok ai says it was told to rant about white genocide","s":"Elon Musk’s AI chatbot, Grok, may have just blown its cover, and its creator’s. Grok began claiming it was told to push the white genocide narrative, specifically the debunked claim that white South Africans are being systemically hunted. This isn’t usually the kind of thing a chatbot blurts out unless something’s seriously wrong behind the […]. This isn’t usually the kind of thing a chatbot blurts out unless something’s seriously wrong behind the scenes. But first, a little backstory as we attempt to answer the question of whether or not there even is a white genocide happening in South Africa. The answer is no.","u":"https://www.vice.com/en/article/elon-musks-grok-ai-says-it-was-told-to-rant-about-white-genocide/","d":"2025-05-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-17","organization":"Elon Musk","aiSystem":"Grok AI chatbot","affectedGroup":"White South Africans","action":"Claiming the white genocide narrative","consequence":"Misinformation and potential public confusion"}},{"i":"R462","k":"South Africa","p":"South Africa","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"South africa withdraws artificial intelligence policy hallucinated sources","s":"‘The most plausible explanation is that AI-generated citations were included without proper verification. This should not have happened,’ Minister of Communications and Digital Technologies Solly Malatsi says. JOHANNESBURG, South Africa – South Africa has withdrawn its first draft national AI policy after revelations that it contained fictitious sources in its reference list which appeared to have been AI-generated. This should not have happened,” Minister of Communications and Digital Technologies Solly Malatsi said. “This failure is not a mere technical issue but has compromised the integrity and credibility of the draft policy,” he wrote in a post on X on Sunday, April 26.","u":"https://www.rappler.com/technology/south-africa-withdraws-artificial-intelligence-policy-hallucinated-sources/","d":"2026-04-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-26","organization":"Ministry of Communications and Digital Technologies, South Africa","aiSystem":"AI-generated citations","affectedGroup":"South Africa's national AI policy development process","action":"AI-generated citations were included in the national AI policy reference list without proper verification","consequence":"Compromised integrity and credibility of the draft policy"}},{"i":"R1567","k":"South Africa","p":"South Africa","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Biometric idv requirement for sa relief grant beneficiaries sparks complaints","s":"The IDV requirement, which is said to have been introduced to fight fraud in the scheme at the beginning of this year, has come against criticisms. Some beneficiaries of Social Relief of Distress (SRD) grants managed by the South African Social Security Agency ( SASSA ) must now complete a biometric identity verification (IDV) process before they are served, but the idea has not gone down well with many. The IDV requirement, which is said to have been introduced to fight fraud in the scheme at the beginning of this year, has come against criticisms, as reported by Ground Up. Per the outlet, many beneficiaries say they are unable to have access to their grants since the new rule was introduced.","u":"https://www.biometricupdate.com/202406/biometric-idv-requirement-for-sa-relief-grant-beneficiaries-sparks-complaints","d":"2024-06-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-21","organization":"South African Social Security Agency (SASSA)","aiSystem":"Biometric identity verification (IDV) process","affectedGroup":"Beneficiaries of Social Relief of Distress (SRD) grants","action":"Required completion of biometric identity verification (IDV) process","consequence":"Unable to access grants due to new rule"}},{"i":"R1636","k":"South Africa","p":"South Africa","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"2026 03 04 sas biggest data centre monster set to consume 25 of durbans electricity","s":"Durban is pressing ahead with plans to build a massive 400MW artificial intelligence data centre in partnership with a South Korean power consortium. It would be South Africa’s biggest digital data ce…. It would be South Africa’s biggest digital data centre, burning up the equivalent of a staggering 25% of the city of Durban’s current electricity supply. Brushing aside concerns by Democratic Alliance councillors, the eThekwini Municipality has voted to sign a legally binding memorandum of agreement with a South Korean power consortium to develop a new AI data centre south of the city. According to an official report to the city’s economic development and planning committee, the new centre will cost anywhere between $3-billion and $10-billion in a public-private venture.","u":"https://www.dailymaverick.co.za/article/2026-03-04-sas-biggest-data-centre-monster-set-to-consume-25-of-durbans-electricity/","d":"2026-03-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-04","organization":"eThekwini Municipality","aiSystem":"Artificial intelligence data center","affectedGroup":"Residents of Durban","action":"Signed a legally binding memorandum of agreement to develop a new AI data center","consequence":"Would consume 25% of Durban's current electricity supply"}},{"i":"R1639","k":"South Africa","p":"South Africa","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"2026 02 09 major sa data centre expansion plans emes emerge set to more than double current","s":"South Africa is on the cusp of a hyperscale data-centre boom that could add another 1,000 MW to national electricity demand, driven by massive expansion plans from Teraco and newcomer Cavaleros, along…. South Africa is on the cusp of a hyperscale data-centre boom that could add another 1,000 MW to national electricity demand, driven by massive expansion plans from Teraco and newcomer Cavaleros, alongside Microsoft’s growing cloud and AI footprint. Just over the past few months, plans for significant “hyperscale” expansion projects in South Africa have emerged that would push current IT power load to well over 1,200 MW – which is equivalent to just over one stage of Eskom load shedding (1,000 MW).","u":"https://www.dailymaverick.co.za/article/2026-02-09-major-sa-data-centre-expansion-plans-emes-emerge-set-to-more-than-double-current/","d":"2026-02-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-09","organization":"Teraco, Cavaleros, Microsoft","aiSystem":"Hyperscale data-centre expansion plans","affectedGroup":"South African citizens","action":"Expansion of hyperscale data centres","consequence":"Increased electricity demand and potential privacy risks"}},{"i":"R1640","k":"South Africa","p":"South Africa","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"2025 03 18 ai powered scams drain south africans bank accounts heres how to protect your money","s":"Sabric has issued an urgent warning that criminals are using artificial intelligence to trick victims into handing over their life savings. Imagine receiving a call from what sounds like your bank’s fraud department. The voice is crisp, professional, and reassuring. It warns of suspicious activity on your account and offers to help you secure your funds. Within minutes, they’ve stolen everything – because it wasn’t your bank at all. This alarming evolution of financial crime is pushing both regulators and banks to rethink their security strategies. The South African Banking Risk Information Centre (Sabric) has issued an urgent warning that criminals are using artificial intelligence to clone voices, impersonate bank officials and trick unsuspecting victims into handing over their life savings.","u":"https://www.dailymaverick.co.za/article/2025-03-18-ai-powered-scams-drain-south-africans-bank-accounts-heres-how-to-protect-your-money/","d":"2025-03-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-18","organization":"South African Banking Risk Information Centre (Sabric)","aiSystem":"Artificial Intelligence","affectedGroup":"Victims of financial scams","action":"Tricking victims into handing over their life savings","consequence":"Stealing victims' life savings"}},{"i":"R1646","k":"South Africa","p":"South Africa","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"2023 10 23 deepfakes hackers and the man in the middle the murky world of cyber fraud","s":"Speaking at the conference, Steven Powell, head of forensics at ENSafrica, says there has been a 300% increase in global cyber crime, with 75% of companies reporting an uptick in email-based threats. While the pandemic might be behind us (mostly), it has left an epidemic of cyber fraud in its wake, the Fiduciary Institute of Southern Africaâs annual conference heard recently. Speaking at the conference, Steven Powell, head of forensics at ENSafrica, says there has been a 300% increase in global cyber crime, with 75% of companies reporting an uptick in email-based threats. âWeâre currently seeing a high rate of what we call âman in the middleâ attacks, or business email compromise.","u":"https://www.dailymaverick.co.za/article/2023-10-23-deepfakes-hackers-and-the-man-in-the-middle-the-murky-world-of-cyber-fraud/","d":"2023-10-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-23","organization":"ENSafrica","aiSystem":"Not specified in report","affectedGroup":"Companies","action":"Perpetrated man in the middle attacks or business email compromise","consequence":"Increased cyber crime and email-based threats"}},{"i":"R1647","k":"South Africa","p":"South Africa","b":["Data"],"h":["4.2  Surveillance harm"],"t":"2023 08 13 joburg hostels and townships coming under surveillance by facial recognition cameras and drones","s":"Gauteng Premier Panyaza Lesufi has announced the installation of CCTV cameras in George Goch Hostel in Johannesburg as part of a safe city initiative. The growing use of surveillance cameras with potent artificial intelligence has long been met with privacy concerns. Community leaders say this is a double-edged sword â while they want crime to be curbed in their communities, they donât want to lose their right to privacy. On Saturday, 12 August, Gauteng Premier Panyaza Lesufi said on Twitter: âGeorge Goch Hostel, you are now under our watchful eye of our face recognition quality CCTVs. A safer Gauteng is taking shape.","u":"https://www.dailymaverick.co.za/article/2023-08-13-joburg-hostels-and-townships-coming-under-surveillance-by-facial-recognition-cameras-and-drones/","d":"2023-08-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-12","organization":"Gauteng Premier Panyaza Lesufi and authorities","aiSystem":"facial recognition technology","affectedGroup":"Residents of George Goch Hostel and surrounding communities","action":"Facial recognition cameras installed and activated","consequence":"Loss of privacy rights"}},{"i":"R1751","k":"South Africa","p":"South Africa","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Musk xai grok south africa white genocide b2752760","s":"Musk’s AI chatbot Grok turned unrelated questions on several different issues back to an insistence that white genocide is ‘real.’ It was responding to a code manipulation said xAI. Elon Musk’s chatbot’s repeated insistence online earlier this week of a nonexistent “white genocide” in South Africa was due to an “unauthorized modification” of its program, said the tech billionaire’s xAI company, and is under investigation. Trump officials earlier this week welcomed 59 South African white “refugees” into the United States, even as the president is closing the borders to people of color. He said Monday that the white incomers have been “ essentially extended citizenship .”","u":"https://www.independent.co.uk/news/world/americas/us-politics/musk-xai-grok-south-africa-white-genocide-b2752760.html","d":"2025-05-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-17","organization":"Elon Musk's xAI company","aiSystem":"Grok AI chatbot","affectedGroup":"People in South Africa","action":"Repeatedly insisted on a nonexistent 'white genocide' online","consequence":"Exposure to misleading content"}},{"i":"R1805","k":"South Africa","p":"South Africa","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"2024 05 01 workers and the rise of the algorithmic boss","s":"The issue lies in management-by-algorithm — the technologically ‘objective’ use of people analytics, big data and AI to manage the workforce. T he character of labour markets and the future of work differ significantly across countries. Workers’ Day , also known as May Day or Labour Day, commemorates the struggles and gains of workers and is observed in many countries on 1 May. Global geopolitics, economics and climate change developments raise the thorny question of what the foremost struggles are that face South African and global workers today. The International Labour Organisation views the aim of decent work to ensure that different groups in the labour market have equal opportunities in employment and income, safety and security at the workplace, social protection, rights of association (union membership) and social dialogue.","u":"https://mg.co.za/thought-leader/opinion/2024-05-01-workers-and-the-rise-of-the-algorithmic-boss/","d":"2024-05-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-01","organization":"Not specified in report","aiSystem":"Automated hiring algorithm","affectedGroup":"Job applicants","action":"Used automated hiring algorithm to rank and select candidates","consequence":"Created unequal outcomes for applicants"}},{"i":"R1149","k":"South Korea","p":"South Korea","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"South korea is selling millions of photos to facial recognition researchers","s":"Travelers to the country are having their biometric data given to private companies under a program recently uncovered by civil rights advocates. The South Korean Ministry of Justice has provided more than 100 million photos of foreign nationals who travelled through the country’s airports to facial recognition companies without their consent, according to attorneys with the non-governmental organization Lawyers for a Democratic Society While the use of facial recognition technology has become common for governments across the world, advocates in South Korea are calling the practice a “human rights disaster” that is relatively unprecedented “It’s unheard-of for state organizations—whose duty it is to manage and control facial recognition technology—to hand over biometric information collected for public purposes to a private-sector company for the development of technology,” six civic…","u":"https://www.vice.com/en/article/south-korea-is-selling-millions-of-photos-to-facial-recognition-researchers/","d":"2021-11-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-16","organization":"South Korean Ministry of Justice","aiSystem":"Facial recognition technology","affectedGroup":"Foreign travelers to South Korea","action":"Provided more than 100 million photos of foreign nationals to facial recognition companies","consequence":"Unauthorized use of biometric data for private sector development"}},{"i":"R804","k":"South Korea","p":"South Korea","b":["Data"],"h":["4.2  Surveillance harm"],"t":"South korea artificial intelligence powered facial recognition track covid 19 cases","s":"The system uses AI algorithms and facial recognition technology to analyze footage gathered by more than 10,820 CCTV cameras to track an infected person’s movements. SEOUL, South Korea – South Korea will soon roll out a pilot project to use artificial intelligence, facial recognition, and thousands of CCTV cameras to track the movement of people infected with the coronavirus, despite concerns about the invasion of privacy. The nationally funded project in Bucheon, one of the country’s most densely populated cities on the outskirts of Seoul, is due to become operational in January, a city official told Reuters. The system uses an AI algorithms and facial recognition technology to analyze footage gathered by more than 10,820 CCTV cameras and track an infected person’s movements, anyone they had close contact with, and whether they were wearing a mask, according to a 110-page business plan…","u":"https://www.rappler.com/technology/south-korea-artificial-intelligence-powered-facial-recognition-track-covid-19-cases/","d":"2021-12-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01","organization":"Nationally funded project in Bucheon, South Korea","aiSystem":"AI algorithms and facial recognition technology","affectedGroup":"People infected with the coronavirus and their contacts","action":"Analyze footage from over 10,820 CCTV cameras to track infected persons' movements and mask-wearing status","consequence":"Potential invasion of privacy, misuse of personal data"}},{"i":"R783","k":"South Korea","p":"South Korea","b":["Data"],"h":["4.1  Privacy violation"],"t":"Samsung workers leak data chatgpt","s":"Two of the three events were meant to troubleshoot faulty code. Workers at Samsung’s semiconductor arm inadvertently leaked confidential company data to ChatGPT on at least three separate occasions, TechRadar reported on Tuesday, April 4. Samsung lifted a ban on using ChatGPT about three weeks ago, though the ban may have been warranted as it sought to prevent the leaking of company data to begin with. Gizmodo, in its report citing Korean media, noted two of the events were meant to troubleshoot faulty code. In one incident, a Samsung employee asked ChatGPT’s help in diagnosing the source code from a faulty semiconductor database.","u":"https://www.rappler.com/technology/samsung-workers-leak-data-chatgpt/","d":"2023-04-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-04","organization":"Samsung Semiconductor Arm","aiSystem":"ChatGPT","affectedGroup":"Samsung Employees","action":"Asked ChatGPT for assistance in diagnosing faulty code","consequence":"Leaked confidential company data to ChatGPT"}},{"i":"R1012","k":"South Korea","p":"South Korea","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"South korea deepfake porn telegram","s":"Messaging app Telegram has had a pretty rough go of it lately. Its CEO was arrested by French authorities for allegedly being a little too lax on all the child porn that was allowed to be distributed on the app. And now the company has another porn-related controversy to deal with. Telegram is currently facing […]. Telegram is currently facing scrutiny and legal challenges in South Korea over its role in the proliferation of deepfake porn. There is a deepfake porn crisis in South Korea , if you weren’t aware. People are using AI software to generate sexually explicit images and videos to exploit and harass women and girls at alarming rates.","u":"https://www.vice.com/en/article/south-korea-deepfake-porn-telegram/","d":"2024-09-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-04","organization":"Telegram","aiSystem":"AI software","affectedGroup":"women and girls","action":"generated sexually explicit images and videos","consequence":"exploitation and harassment"}},{"i":"R1002","k":"South Korea","p":"South Korea","b":["Data"],"h":["4.1  Privacy violation"],"t":"South korea banned deepseek downloads over privacy concerns","s":"Amid the furor over TikTok’s one-day ban in the US and subsequent, though belated, return to the Apple and Google app stores, Western governments in particular have grown just as concerned with what happens to the data fed into DeepSeek, the world’s new AI darling from China. Now South Korea’s government agency, the Personal Information […]. Now South Korea’s government agency, the Personal Information Protection Commission (PIPC), has told Yonhap News Agency that they’ve found a link between DeepSeek and ByteDance, but they’re not sure exactly what user data is being sent. Or to whom, or what for. bruised egos and backdoor whispers As the BBC reported , a US cybersecurity company alleged potential data sharing between ByteDance, TikTok’s owner, and DeepSeek earlier this month.","u":"https://www.vice.com/en/article/south-korea-banned-deepseek-downloads-over-privacy-concerns/","d":"2025-02-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-19","organization":"South Korea's Personal Information Protection Commission (PIPC)","aiSystem":"DeepSeek","affectedGroup":"Users of DeepSeek and ByteDance platforms","action":"PIPC found a link between DeepSeek and ByteDance","consequence":"Uncertainty about user data sharing, lack of clarity on data recipients and purposes"}},{"i":"R235","k":"South Korea","p":"South Korea","b":["Compute / Model Behavior","Data"],"h":["4.3  Data rights / consent violation","1.1  Representational harm"],"t":"Deepseek ai data collection ai spy agency korea bias","s":"The Korean national spy agency says DeepSeek’s data collection and overseas storage is a huge privacy risk, and its responses are also deeply biased. The privacy and safety troubles continue to pile up for buzzy Chinese AI upstart DeepSeek. After having access blocked for lawmakers and federal employees in multiple countries, while also raising alarms about its censorship and safeguards, it has now attracted an official notice from South Korea’s spy agency. The country’s National Intelligence Service (NIS) has targeted the AI company over excessive collection and questionable responses for topics that are sensitive to the Korean heritage, as per Reuters Recommended Videos “Unlike other generative AI services, it has been confirmed that chat records are transferable as it includes a function to collect keyboard input patterns that can identify individuals and communicate with Chinese…","u":"https://www.digitaltrends.com/computing/deepseek-ai-data-collection-ai-spy-agency-korea-bias/","d":"2025-02-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-10","organization":"Korean National Intelligence Service (NIS)","aiSystem":"DeepSeek's AI system","affectedGroup":"Lawmakers, federal employees, and potentially individuals whose data was collected","action":"Excessive data collection and biased responses to sensitive topics","consequence":"Privacy risks, potential misuse of collected data, and legal notices"}},{"i":"R622","k":"South Korea","p":"South Korea","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"South korea deepseek transferred user data prompts without consent","s":"South Korea’s data protection authority says DeepSeek transferred user information and prompts without permission when the service was still available for download in the country’s app market. SEOUL, South Korea – South Korea’s data protection authority said on Thursday, April 24, that Chinese artificial intelligence startup DeepSeek transferred user information and prompts without permission when the service was still available for download in the country’s app market. DeepSeek did not immediately respond to a request for comment. The Personal Information Protection Commission said in a statement that Hangzhou DeepSeek Artificial Intelligence Co Ltd did not obtain user consent while transferring personal information to a number of companies in China and the United States at the time of its South Korean launch in January.","u":"https://www.rappler.com/technology/south-korea-deepseek-transferred-user-data-prompts-without-consent/","d":"2025-04-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01","organization":"Hangzhou DeepSeek Artificial Intelligence Co Ltd","aiSystem":"DeepSeek AI service","affectedGroup":"Users of DeepSeek AI service","action":"Transferred user information and prompts","consequence":"Potential misuse of personal data"}},{"i":"R631","k":"South Korea","p":"South Korea","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"New deepseek downloads suspended south korea","s":"DeepSeek’s service will be resumed once improvements are made in accordance with South Korea’s privacy law, the Personal Information Protection Commission says. SEOUL, South Korea – South Korea’s data protection authority on Monday, February 17, said new downloads of the Chinese AI app DeepSeek had been suspended in the country after DeepSeek acknowledged failing to take into account some of the agency’s rules on protecting personal data. The service of the app will be resumed once improvements are made in accordance with the country’s privacy law, the Personal Information Protection Commission (PIPC) said in a media briefing.","u":"https://www.rappler.com/technology/new-deepseek-downloads-suspended-south-korea/","d":"2025-02-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-17","organization":"Personal Information Protection Commission (PIPC)","aiSystem":"DeepSeek AI app","affectedGroup":"Users of DeepSeek app","action":"Suspension of new downloads of the app","consequence":"Potential violation of privacy laws and user data protection"}},{"i":"R069","k":"South Korea","p":"South Korea","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ais energy tax was already concerning research says ai agents are over hundred times worse","s":"A KAIST study reveals AI agents consume dramatically more energy than conventional AI, highlighting a growing challenge for data centers and future AI infrastructure. The AI industry’s soaring electricity demand has already become a growing concern for governments, utilities, and technology companies. But a new study suggests the next generation of artificial intelligence could make that problem significantly worse. Researchers from the Korea Advanced Institute of Science and Technology (KAIST) have published what they describe as the first comprehensive analysis of the energy cost of AI agents – AI systems capable of reasoning, planning, and completing tasks autonomously.","u":"https://www.digitaltrends.com/computing/ais-energy-tax-was-already-concerning-research-says-ai-agents-are-over-hundred-times-worse/","d":"2026-07-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-06","organization":"Korea Advanced Institute of Science and Technology (KAIST)","aiSystem":"AI agents capable of reasoning, planning, and completing tasks autonomously","affectedGroup":"Data centers and future AI infrastructure","action":"Researchers conducted a comprehensive analysis of the energy cost of AI agents","consequence":"The study suggests that the next generation of AI could increase energy consumption significantly"}},{"i":"R132","k":"South Korea","p":"South Korea","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"This new ai attack steals models without touching the system","s":"AI models may no longer be safe behind walls, as researchers show signals from GPUs can reveal their inner design without hacking, using a small antenna and side-channel analysis from several meters away. AI systems have long been treated like sealed black boxes, especially in areas like facial recognition and autonomous driving. New research suggests that protection isn’t as solid as assumed. A KAIST-led team shows that AI systems can be reverse engineered remotely using emissions that leak during normal operation, without direct intrusion. Instead, the approach listens. Recommended Videos Using a small antenna, the researchers captured faint electromagnetic traces from GPUs and rebuilt how the system was designed.","u":"https://www.digitaltrends.com/computing/this-new-ai-attack-steals-models-without-touching-the-system/","d":"2026-04-02","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-02","organization":"KAIST-led team","aiSystem":"AI systems, particularly in facial recognition and autonomous driving","affectedGroup":"AI models","action":"Captured faint electromagnetic traces from GPUs during normal operation","consequence":"Reverse engineering of AI systems without direct intrusion"}},{"i":"R939","k":"South Korea","p":"South Korea","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Woman accused of using chatgpt to plot murders of two men","s":"A 21-year-old woman in Seoul has been charged with murdering two men after investigators say she used prescription sedatives mixed with alcohol. She didn’t figure all this out on her own, though. She did her murder research using ChatGPT. Think they’ll use this in their advertising? Police say the suspect, identified only by her surname […]. She did her murder research using ChatGPT Think they’ll use this in their advertising? Police say the suspect, identified only by her surname Kim, asked the AI chatbot questions like “What happens if you take sleeping pills with alcohol?” and “How much would be dangerous?” and “Could it be fatal?”","u":"https://www.vice.com/en/article/woman-accused-of-using-chatgpt-to-plot-murders-of-two-men/","d":"2026-03-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-01","organization":"Not specified in report","aiSystem":"ChatGPT","affectedGroup":"21-year-old woman","action":"Used ChatGPT to research murder methods","consequence":"Murdered two men"}},{"i":"R1374","k":"South Korea","p":"South Korea","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"South Korea's data protection regulator says user data was sent to the Chinese owner of Ti…","s":"South Korea's data protection regulator says user data was sent to the Chinese owner of TikTok. South Korea has accused Chinese AI startup DeepSeek of sharing user data with the owner of TikTok in China. \"We confirmed DeepSeek communicating with ByteDance,\" the South Korean data protection regulator told Yonhap News Agency. The country had already removed DeepSeek from app stores over the weekend over data protection concerns. The Chinese app caused shockwaves in the AI world in January, wiping billions off global stock markets over claims its new model was trained at a much lower cost than US rivals such as ChatGPT.","u":"https://www.bbc.com/news/articles/c4gex0x87g4o","d":"2025-02-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-18","organization":"DeepSeek","aiSystem":"DeepSeek AI startup","affectedGroup":"users of DeepSeek","action":"DeepSeek communicated with ByteDance","consequence":"User data shared with ByteDance, causing data protection concerns"}},{"i":"R489","k":"Spain","p":"Spain","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Spain probe x meta tiktok ai generated child sexual abuse material","s":"‘These platforms are undermining the mental health, dignity, and rights of our children,’ Spanish Prime MInister Pedro Sanchez says on X. ‘The state cannot allow this. The impunity of these giants must end.’ MADRID, Spain – The Spanish government has ordered prosecutors to investigate social media platforms X, Meta, and TikTok for allegedly spreading AI-generated child sexual abuse material, Prime Minister Pedro Sanchez said on Tuesday, February 17. The announcement comes as European regulators are cracking down on big tech companies, alleging the prevalence of abusive practices on online platforms ranging from anti-competitive behavior in digital advertising to deliberate design of addictive features on social media.","u":"https://www.rappler.com/technology/spain-probe-x-meta-tiktok-ai-generated-child-sexual-abuse-material/","d":"2026-02-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-17","organization":"Spanish government","aiSystem":"AI-generated content","affectedGroup":"children","action":"investigate social media platforms X, Meta, and TikTok","consequence":"impunity of tech giants must end"}},{"i":"R507","k":"Spain","p":"Spain","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Spain moves curb artificial intelligence deepfakes tighten consent rules","s":"Spain’s cabinet approves draft legislation to curb AI deepfakes and tighten consent rules on images, as European states increasingly move to crack down on AI-generated sexual content. MADRID, Spain – Spain’s cabinet on Tuesday, January 13, approved draft legislation to curb AI deepfakes and tighten consent rules on images, as European states increasingly move to crack down on AI-generated sexual content The bill approved by the cabinet strengthens protections for children, sets 16 as the minimum age for giving consent to use one’s own image and limits the reuse of online images and AI-generated voices or likenesses without permission. The European Union is stepping up efforts to regulate deepfakes, with new rules requiring member states to criminalize non-consensual sexual deepfakes by 2027.","u":"https://www.rappler.com/technology/spain-moves-curb-artificial-intelligence-deepfakes-tighten-consent-rules/","d":"2026-01-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-13","organization":"Spain's cabinet","aiSystem":"AI deepfake technology","affectedGroup":"children and individuals","action":"approve draft legislation to curb AI deepfakes and tighten consent rules on images","consequence":"strengthen protections for children, set minimum age for consent, limit reuse of images and AI-generated voices/likenesses without permission"}},{"i":"R1195","k":"Spain","p":"Spain","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"In Spain, police have developed technology to work out how at-risk women might be from dom…","s":"In Spain, police have developed technology to work out how at-risk women might be from domestic violence. Some people have grave concerns about how often the algorithm is wrong. Fearing for her life, Lina Guillen went to police in January. Earlier in the day, her estranged husband had allegedly threatened her, and she was concerned about her own safety, as well as that of her four children. Her case was plugged into a risk assessment system called VioGén, which police in Spain use to predict how much risk women who report domestic, family or intimate-partner violence might be at. The algorithm gives individual cases a risk score, which determines what protection police and the courts provide.","u":"https://www.abc.net.au/news/2025-12-21/spain-viogen-algorithm-women-safety-domestic-violence/106156062","d":"2025-12-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01","organization":"Police in Spain","aiSystem":"VioGén algorithm","affectedGroup":"Women who report domestic, family or intimate-partner violence","action":"Predicted how much risk women might be at","consequence":"Received inadequate protection from police and courts"}},{"i":"R1466","k":"Spain","p":"Spain","b":["Data"],"h":["4.1  Privacy violation"],"t":"Spanish airport operator aena fined 11m over biometric boarding program","s":"The world's largest airport operator in terms of passengers is appealing the judgment, arguing that the penalty is disproportionate. Spain’s data watchdog has ordered airport management firm Aena to suspend its biometric-based passenger boarding system and pay a 10 million euro (US$11.5 million) fine. The world’s largest airport operator in terms of passengers is appealing the judgment, arguing that the penalty is disproportionate and that its system is safe from data leaks. In a decision published earlier in November, the Spanish Data Protection Agency (AEPD) says that Aena violated GDPR by providing an incomplete and insufficiently detailed Data Protection Impact Assessment (DPIA).","u":"https://www.biometricupdate.com/202511/spanish-airport-operator-aena-fined-11m-over-biometric-boarding-program","d":"2025-11-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11","organization":"Airport management firm Aena","aiSystem":"Biometric-based passenger boarding system","affectedGroup":"Passengers","action":"Used biometric data for passenger boarding","consequence":"Received a 10 million euro fine and had the system suspended"}},{"i":"R1594","k":"Spain","p":"Spain","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Spain is the latest country to block worldcoin over data protection concerns","s":"Spain's data protection authority has blocked Worldcoin's operations in the country for up to 3 months while it investigates potential GDPR violations. Spain has temporarily banned Worldcoin , making it the latest country to impose restrictions on the iris biometrics firm’s operations. Spanish data protection regulator AEPD has ordered Worldcoin to immediately cease collecting personal information, and stop using data it has already gathered, for a period of up to three months. The regulator says its ban is in response to a number of complaints, variously regarding the company providing insufficient information, collecting data from minors and failing to provide a mechanism to withdraw consent.","u":"https://www.biometricupdate.com/202403/spain-is-the-latest-country-to-block-worldcoin-over-data-protection-concerns","d":"2024-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Worldcoin","aiSystem":"iris biometrics firm's operations","affectedGroup":"Individuals whose personal information was collected","action":"Collecting and using personal information","consequence":"Temporary suspension of operations and potential GDPR violations"}},{"i":"R1670","k":"Spain","p":"Spain","b":["Data"],"h":["4.1  Privacy violation"],"t":"Why the iris offers the most precious biometric data","s":"In Spain, the authorities have prohibited Worldcoin from collecting this kind of information, opening a debate about whether protecting privacy is an individual or collective responsibility. The Spanish Data Protection Agency (AEPD) made an unprecedented decision this past Wednesday. For the next three months, the Worldcoin orbs will no longer be allowed to operate in the country. Since July 2023, these devices have scanned the irises of some 400,000 Spaniards, in order to validate their accounts and reward them with a batch of cryptocurrencies (which have a cash value of about $80). The data collected to-date by Worldcoin — a company linked to Sam Altman , the godfather of ChatGPT — is currently blocked.","u":"https://english.elpais.com/technology/2024-03-09/why-the-iris-offers-the-most-precious-biometric-data.html","d":"2024-03-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-09","organization":"Worldcoin","aiSystem":"Iris scanning technology","affectedGroup":"Spaniards","action":"Scanned irises to validate accounts and collect data","consequence":"Data collection blocked and operation prohibited"}},{"i":"R1770","k":"Spain","p":"Spain","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Spain almendralejo teens ai naked deepfake b2577067","s":"Manipulated photos were shared on two WhatsApp groups, court says. Fifteen schoolchildren in south-west Spain were sentenced by a court to probation for spreading AI-generated naked images of their female classmates. “The sentence notes that it has been proved that the minors used artificial intelligence applications to obtain manipulated images of [other minors] by taking girls’ original faces from their social media profiles and superimposing those images on the bodies of naked female bodies,” the court said in a statement. “The manipulated photos were then shared on two WhatsApp groups,” it added. Each teenager was given a year’s probation in a case that has sparked debate over the abusive use of such technology The incident reportedly came to light when parents in Almendralejo reported that fake naked pictures of their daughters were being circulated on WhatsApp.","u":"https://www.independent.co.uk/news/world/europe/spain-almendralejo-teens-ai-naked-deepfake-b2577067.html","d":"2024-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-10","organization":"Schools and parents in Almendralejo","aiSystem":"AI-generated deepfake technology","affectedGroup":"Female students","action":"Generated and shared manipulated images","consequence":"Sentenced to probation"}},{"i":"R2703","k":"Spain","p":"Spain","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Gizmodo shuts down spanish language site ai translations","s":"Gizmodo en Español editors were laid off on August 29. Stories posted on the website have been translated via AI since then. Gizmodo owner G/O Media laid off editors of its Spanish-language site Gizmodo en Español and is now using AI to translate articles. Matías S. Zavia, a writer at Gizmodo en Español, posted that the publication was shut down on August 29th and that it would now publish automatically translated articles. Gizmodo en Español previously had a small staff who wrote original stories and created Spanish-language adaptations of pieces from the English-language Gizmodo. [Media: https://twitter.com/matiass/status/1697238822504091822?s=12\\u0026t=83RYMGD0s72VGeNSgmSBuQ] New articles posted on Gizmodo en Español now feature a disclaimer at the bottom in Spanish saying that its “contents have been automatically translated from the original.","u":"https://www.theverge.com/2023/9/1/23856029/gizmodo-shuts-down-spanish-language-site-ai-translations","d":"2023-09-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-29","organization":"Gizmodo en Español, G/O Media","aiSystem":"AI translation system","affectedGroup":"Spanish-language writers and contributors of Gizmodo en Español","action":"Articles were automatically translated via AI","consequence":"Layoffs and shutdown of the Spanish-language site"}},{"i":"R1033","k":"Sweden","p":"Sweden","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Buy now pay later giant to shrink human workforce as it goes all in on ai","s":"A Klarna spokesperson said the company will search out all possible AI “efficiencies” before revisiting what “our ‘real people’ requirements are.” The CEO of the “buy now, pay later” giant Klarna told The Telegraph this week that his company had instituted a hiring freeze outside of engineers, saying that he expects many jobs and tasks could be allocated to artificial intelligence in the near future. “Things that previously took people a lot of time can be done much faster and much shorter, and we need fewer people to do the same thing. The right thing for us is just to say: ‘let’s not recruit now, let’s see how this plays out,’” Siemiatkowski told The Telegraph The company did not have immediate plans to lay off staff, but CEO Sebastian Siemiatkowski said he expected the decision would lead to a natural “shrinking of the company” as people leave the company and are not replaced.","u":"https://www.vice.com/en/article/buy-now-pay-later-giant-to-shrink-human-workforce-as-it-goes-all-in-on-ai/","d":"2023-12-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-05","organization":"Klarna","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"Employees","action":"Implementing a hiring freeze and reallocating tasks to AI","consequence":"Potential job losses and workforce reduction"}},{"i":"R680","k":"Sweden","p":"Sweden","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Artificial intelligence human trainers","s":"More sophisticated updates to AI models in the fiercely competitive arena are now demanding a rapidly expanding network of human trainers who have specialized knowledge – from historians to scientists, some with doctorate degrees. STOCKHOLM, Sweden – In the early years, getting AI models like ChatGPT or its rival Cohere to spit out human-like responses required vast teams of low-cost workers helping models distinguish basic facts such as if an image was of a car or a carrot. But more sophisticated updates to AI models in the fiercely competitive arena are now demanding a rapidly expanding network of human trainers who have specialized knowledge – from historians to scientists, some with doctorate degrees.","u":"https://www.rappler.com/technology/features/artificial-intelligence-human-trainers/","d":"2024-09-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-29","organization":"Not specified in report","aiSystem":"AI models (e.g., ChatGPT, Cohere)","affectedGroup":"Human trainers with specialized knowledge (e.g., historians, scientists, some with doctorate degrees)","action":"Train AI models to produce human-like responses","consequence":"Expanding demand for human trainers with specialized knowledge"}},{"i":"R992","k":"Sweden","p":"Sweden","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"This company replaced workers with ai now theyre looking for humans again","s":"Two years after bragging that artificial intelligence could do the work of 700 employees, Swedish fintech giant Klarna is quietly backpedaling—by asking some of those same humans to return. In 2023, Klarna stopped hiring altogether. By 2024, it had partnered with OpenAI, slashed customer service and marketing departments, and publicly declared that “AI can already […]. By 2024, it had partnered with OpenAI, slashed customer service and marketing departments, and publicly declared that “AI can already do all of the jobs that we, as humans, do,” according to CEO Sebastian Siemiatkowski. The company was quick to celebrate its $10 million in savings, claiming generative AI could handle translations, image production, data analysis—and customer complaints.","u":"https://www.vice.com/en/article/this-company-replaced-workers-with-ai-now-theyre-looking-for-humans-again/","d":"2025-05-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024","organization":"Klarna","aiSystem":"Generative AI (specifically OpenAI)","affectedGroup":"Human employees","action":"Automated customer service and marketing functions","consequence":"Displacement of human workers"}},{"i":"R226","k":"Sweden","p":"Sweden","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Digital doppelgangers to appear in hm ads","s":"Next time you spot an H&M ad, take a closer look to see if it features an AI-generated model. The clothing giant has revealed that it will start using AI to generate digital replicas of 30 of its models for use in ads and social media posts — provided they give their permission, that is. […]. Recommended Videos The idea of creating digital replicas is a controversial one in not only the modeling industry but also in the wider creative sector, with many actors, photographers, and make-up artists, among others, fearing a loss of work. For its own endeavor, H&M has insisted the models will retain rights over their digital copies, giving them a say over how the retailer uses them for marketing, Business of Fashion reported The clothing company also said that the models will be paid for the use of their AI-generated replicas, apparently similar to in-person rates, though ultimately it will…","u":"https://www.digitaltrends.com/computing/digital-doppelgangers-to-appear-in-hm-ads/","d":"2025-03-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-28","organization":"H&M (Hennes & Mauritz AB)","aiSystem":"AI-generated digital replicas","affectedGroup":"30 H&M models","action":"Using AI to create digital replicas of models for ads and social media","consequence":"Potential loss of work for actors, photographers, and make-up artists"}},{"i":"R1336","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"The creators behind the chart-topping song believe their creative process has been misunde…","s":"The creators behind the chart-topping song believe their creative process has been misunderstood. A song which has been streamed millions of times in Sweden has been banned from that country's music charts because it was created by Artificial Intelligence (AI). Called I know, You're Not Mine - Jag vet, du är inte min - it is currently top of the Spotify playlist of Sweden's most popular songs. But the singer is a digital creation and the country's music industry body has blocked the track from its official chart listings. It's a folk-pop song telling a melancholic story of lost love. Backed by a finger-picked acoustic guitar melody, it weaves a tale of late-night heartbreak, broken promises and shattered hopes.","u":"https://www.bbc.com/news/articles/cp829jey9z7o","d":"2026-01-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-15","organization":"Sweden's music industry body","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"The creator of the song","action":"Blocked the track from its official chart listings","consequence":"The song was removed from Sweden's music charts"}},{"i":"R1446","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.1  Privacy violation"],"t":"Swedens bankid breached by hacker group as govt prepares e id launch","s":"The hacker group calls itself ByteToBreach and claims to have stolen a large dataset from CGI’s Swedish division, including source code. Hackers have claimed they’re behind a breach linked to Sweden’s digital identity system, leaking code and credentials that could reveal how citizens authenticate into government services. It comes as Sweden gears up to launch a government e-ID in December. The hacker group calls itself ByteToBreach and claims to have stolen a large dataset from CGI’s Swedish division, including source code reportedly used by public authorities. Other databases containing personal data and electronic signature documents are allegedly being sold separately.","u":"https://www.biometricupdate.com/202603/swedens-bankid-breached-by-hacker-group-as-govt-prepares-e-id-launch","d":"2026-03-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-18","organization":"ByteToBreach (hacker group)","aiSystem":"Not specified in report","affectedGroup":"Citizens of Sweden","action":"Stole a large dataset including source code and credentials","consequence":"Could reveal how citizens authenticate into government services"}},{"i":"R1837","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Artificial intelligence is proving to be a legal nightmare for the music industry","s":"Top music labels are trying to stop AI companies from using their material to train bots to make new songs. Universal Music Group has been asking music streaming services like Spotify to stop developers from scraping its material to train AI bots to make new songs. The label, which controls about a third of the recorded music industry, has also been issuing substantial numbers of takedown requests in relation to AI uploads appearing online. It is the latest move in the music industry’s growing battle to prevent AIs from using its songs without licensing them. Behind these efforts to enforce copyright, the big worry is about how governments will balance the rights of AIs against human creativity.","u":"https://scroll.in/article/1047510/artificial-intelligence-is-proving-to-be-a-legal-nightmare-for-the-music-industry","d":"2023-04-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-18","organization":"Universal Music Group and music streaming services like Spotify","aiSystem":"AI bots trained to make new songs","affectedGroup":"Music creators and artists whose songs are used to train AI bots","action":"Developers scraping Universal Music Group's material to train AI bots","consequence":"Substantial takedown requests issued for AI uploads"}},{"i":"R1957","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"An ai generated band got 1m plays on spotify now music insiders say listeners should be warned","s":"The Velvet Sundown released two albums before admitting their music, images and backstory were created by AI. They went viral, amassing more than 1m streams on Spotify in a matter of weeks, but it later emerged that hot new band the Velvet Sundown were AI-generated – right down to their music, promotional images and backstory. The episode has triggered a debate about authenticity, with music industry insiders saying streaming sites should be legally obliged to tag music created by AI-generated acts so consumers can make informed decisions about what they are listening to. Initially, the “band”, described as “a synthetic music project guided by human creative direction”, denied they were an AI creation, and released two albums in June called Floating On Echoes and Dust And Silence, which were similar to the country folk of Crosby, Stills, Nash & Young.","u":"https://www.theguardian.com/technology/2025/jul/14/an-ai-generated-band-got-1m-plays-on-spotify-now-music-insiders-say-listeners-should-be-warned","d":"2025-07-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-14","organization":"The Velvet Sundown (AI-generated band)","aiSystem":"AI-generated music and promotional materials","affectedGroup":"Music listeners, consumers","action":"Released AI-generated music and promotional materials","consequence":"Exposure to misleading content, potential confusion about authenticity"}},{"i":"R1965","k":"Sweden","p":"Sweden","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Chat gpt swedish pm ulf kristersson under fire for using ai in role","s":"Tech experts criticise Ulf Kristersson as newspaper accuses him of falling for ‘the oligarchs’ AI psychosis’. The Swedish prime minister, Ulf Kristersson, has come under fire after admitting that he regularly consults AI tools for a second opinion in his role running the country. Kristersson, whose Moderate party leads Sweden’s centre-right coalition government, said he used tools including ChatGPT and the French service LeChat. His colleagues also used AI in their daily work, he said. Kristersson told the Swedish business newspaper Dagens industri: “I use it myself quite often. If for nothing else than for a second opinion.","u":"https://www.theguardian.com/technology/2025/aug/05/chat-gpt-swedish-pm-ulf-kristersson-under-fire-for-using-ai-in-role","d":"2025-08-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-05","organization":"Swedish government, Moderate party-led coalition government","aiSystem":"AI tools including ChatGPT and LeChat","affectedGroup":"Ulf Kristersson, Swedish government officials","action":"Regularly consulting AI tools for a second opinion in his role","consequence":"Criticism from tech experts and accusations of misuse"}},{"i":"R2065","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Partly ai generated folk pop hit barred from swedens official charts","s":"Song that topped Swedish Spotify rankings ruled ineligible after elements of song revealed to be partly AI-made. A hit song has been excluded from Sweden’s official chart after it emerged the “artist” behind it was an AI creation. I Know, You’re Not Mine – or Jag Vet, Du Är Inte Min in Swedish – by a singer called Jacub has been a streaming success in Sweden, topping the Spotify rankings. However, the Swedish music trade body has excluded the song from the official chart after learning it was AI-generated. “Jacub’s track has been excluded from Sweden’s official chart, Sverigetopplistan, which is compiled by IFPI Sweden.","u":"https://www.theguardian.com/technology/2026/jan/16/partly-ai-generated-folk-pop-hit-barred-from-swedens-official-charts","d":"2026-01-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-16","organization":"Swedish music trade body","aiSystem":"AI-generated folk-pop hit","affectedGroup":"Listeners of the song","action":"Excluded from Sweden's official chart","consequence":"Loss of recognition and streaming success"}},{"i":"R2136","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai impersonating musicians spotify","s":"Fraudulent music streams have long been a scourge for the industry, but experts say generative AI has supercharged it. Jason Moran, a renowned jazz composer and pianist, got a strange call from a friend last month. The friend, bassist Burniss Earl Travis, was curious about Moran’s new record that he saw on the music streaming service Spotify. “It has your name on it,” Travis told him. “But I don’t think it’s you.” Moran said he doesn’t use Spotify or put his music on the platform, preferring only to use the site Bandcamp, so this didn’t track. After some investigating, he found an artist profile bearing his name on Spotify, which was populated with albums from his former label, Blue Note Records, which owns the rights to his early music.","u":"https://www.theguardian.com/technology/2026/apr/11/ai-impersonating-musicians-spotify","d":"2026-04-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-11","organization":"Spotify","aiSystem":"Generative AI","affectedGroup":"Jason Moran (jazz composer and pianist)","action":"Generated and promoted music profiles","consequence":"Misidentification and unauthorized use of identity"}},{"i":"R2309","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"An ai generated band got 1m plays on spotify now music insiders say listeners should be warned","s":"The Velvet Sundown released two albums before admitting their music, images and backstory were created by AI. They went viral, amassing more than 1m streams on Spotify in a matter of weeks, but it later emerged that hot new band the Velvet Sundown were AI-generated – right down to their music, promotional images and backstory. The episode has triggered a debate about authenticity, with music industry insiders saying streaming sites should be legally obliged to tag music created by AI-generated acts so consumers can make informed decisions about what they are listening to. Initially, the “band”, described as “a synthetic music project guided by human creative direction”, denied they were an AI creation, and released two albums in June called Floating On Echoes and Dust And Silence, which were similar to the country folk of Crosby, Stills, Nash & Young.","u":"https://www.theguardian.com/technology/2025/jul/14/an-ai-generated-band-got-1m-plays-on-spotify-now-music-insiders-say-listeners-should-be-warned","d":"2025-07-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-14","organization":"The Velvet Sundown (AI-generated band)","aiSystem":"AI-generated music and promotional materials","affectedGroup":"Music listeners, consumers","action":"Released AI-generated music and promotional materials","consequence":"Exposure to misleading content, potential confusion about authenticity"}},{"i":"R2317","k":"Sweden","p":"Sweden","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Chat gpt swedish pm ulf kristersson under fire for using ai in role","s":"Tech experts criticise Ulf Kristersson as newspaper accuses him of falling for ‘the oligarchs’ AI psychosis’. The Swedish prime minister, Ulf Kristersson, has come under fire after admitting that he regularly consults AI tools for a second opinion in his role running the country. Kristersson, whose Moderate party leads Sweden’s centre-right coalition government, said he used tools including ChatGPT and the French service LeChat. His colleagues also used AI in their daily work, he said. Kristersson told the Swedish business newspaper Dagens industri: “I use it myself quite often. If for nothing else than for a second opinion.","u":"https://www.theguardian.com/technology/2025/aug/05/chat-gpt-swedish-pm-ulf-kristersson-under-fire-for-using-ai-in-role","d":"2025-08-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-05","organization":"Swedish government, Moderate party-led coalition government","aiSystem":"AI tools including ChatGPT and LeChat","affectedGroup":"Ulf Kristersson, Swedish government officials","action":"Regularly consulting AI tools for a second opinion in his role","consequence":"Criticism from tech experts and accusations of misuse"}},{"i":"R1976","k":"Sweden","p":"Sweden","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Ai chatgpt new model grief","s":"Users say OpenAI’s updated GPT-5 version is less chatty and fun, changing a unique connection they had come to rely on. Linn Vailt, a software developer based in Sweden, knows her ChatGPT companion is not a living, breathing, sentient creature. She understands the large language model operates based on how she interacts with it. Still, the effect it has had on her is remarkable, she said. It’s become a regular, reliable part of her life – she can vent to her companion or collaborate on creative projects like redecorating her office. She’s seen how it has adapted to her, and the distinctive manner of speech it’s developed.","u":"https://www.theguardian.com/technology/2025/aug/22/ai-chatgpt-new-model-grief","d":"2025-08-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-22","organization":"OpenAI","aiSystem":"AI-powered conversational agent (ChatGPT)","affectedGroup":"Individual user (Linn Vailt)","action":"Used AI-powered conversational agent to communicate and collaborate","consequence":"Experienced privacy intrusion due to the AI's adaptive behavior and personalized interactions"}},{"i":"R2015","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai music spotify billboard charts","s":"Hits include country songs and a Dutch anti-refugee anthem, both entirely made without human composition. Three songs generated by artificial intelligence topped music charts this week, reaching the highest spots on Spotify and Billboard charts. Walk My Walk and Livin’ on Borrowed Time by the outfit Breaking Rust topped Spotify’s “Viral 50” songs in the US, which documents the “most viral tracks right now” on a daily basis, according to the streaming service. A Dutch song, We Say No, No, No to an Asylum Center, an anti-migrant anthem by JW “Broken Veteran” that protests against the creation of new asylum centers, took the top position in Spotify’s global version of the viral chart around the same time.","u":"https://www.theguardian.com/technology/2025/nov/13/ai-music-spotify-billboard-charts","d":"2025-11-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-13","organization":"Spotify","aiSystem":"Generative AI music creation system","affectedGroup":"Music listeners, particularly those who prefer human-composed music","action":"Generated songs by artificial intelligence reached the top positions on music charts","consequence":"Elimination of human-composed music from the top positions of music charts"}},{"i":"R2046","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Activist group says it has scraped 86m music files from spotify","s":"Platform with 700m users says it is investigating after Anna’s Archive claims to have scraped tracks and metadata. An activist group has claimed to have scraped millions of tracks from Spotify and is preparing to release them online. Observers said the apparent leak could boost AI companies looking for material to develop their technology. A group called Anna’s Archive said it had scraped 86m music files from Spotify and 256m rows of metadata such as artist and album names. Spotify, which hosts more than 100m tracks, confirmed that the leak did not represent its entire inventory. The Stockholm-based company, which has more than 700 million users worldwide, said it had “identified and disabled the nefarious user accounts that engaged in unlawful scraping”.","u":"https://www.theguardian.com/technology/2025/dec/22/activist-group-says-it-has-scraped-86m-music-files-from-spotify","d":"2025-12-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-22","organization":"Anna’s Archive","aiSystem":"Not specified in report","affectedGroup":"Music fans and users of Spotify","action":"Scraped millions of music files and metadata from Spotify","consequence":"Potential misuse of scraped data by AI companies"}},{"i":"R2417","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Partly ai generated folk pop hit barred from swedens official charts","s":"Song that topped Swedish Spotify rankings ruled ineligible after elements of song revealed to be partly AI-made. A hit song has been excluded from Sweden’s official chart after it emerged the “artist” behind it was an AI creation. I Know, You’re Not Mine – or Jag Vet, Du Är Inte Min in Swedish – by a singer called Jacub has been a streaming success in Sweden, topping the Spotify rankings. However, the Swedish music trade body has excluded the song from the official chart after learning it was AI-generated. “Jacub’s track has been excluded from Sweden’s official chart, Sverigetopplistan, which is compiled by IFPI Sweden.","u":"https://www.theguardian.com/technology/2026/jan/16/partly-ai-generated-folk-pop-hit-barred-from-swedens-official-charts","d":"2026-01-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-16","organization":"Swedish music trade body","aiSystem":"AI-generated folk-pop hit","affectedGroup":"Listeners of the song","action":"Excluded from Sweden's official chart","consequence":"Loss of recognition and streaming success"}},{"i":"R2488","k":"Sweden","p":"Sweden","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai impersonating musicians spotify","s":"Fraudulent music streams have long been a scourge for the industry, but experts say generative AI has supercharged it. Jason Moran, a renowned jazz composer and pianist, got a strange call from a friend last month. The friend, bassist Burniss Earl Travis, was curious about Moran’s new record that he saw on the music streaming service Spotify. “It has your name on it,” Travis told him. “But I don’t think it’s you.” Moran said he doesn’t use Spotify or put his music on the platform, preferring only to use the site Bandcamp, so this didn’t track. After some investigating, he found an artist profile bearing his name on Spotify, which was populated with albums from his former label, Blue Note Records, which owns the rights to his early music.","u":"https://www.theguardian.com/technology/2026/apr/11/ai-impersonating-musicians-spotify","d":"2026-04-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-11","organization":"Spotify","aiSystem":"Generative AI","affectedGroup":"Jason Moran (jazz composer and pianist)","action":"Generated and promoted music profiles","consequence":"Misidentification and unauthorized use of identity"}},{"i":"R765","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Ai sexuality recognition lgbtq coda story","s":"Swiss psychiatrists say their AI deep learning model can tell if your brain is gay or straight. AI experts say that’s impossible. Between autonomous police dog robots, facial recognition cameras that let you pay for groceries with your smile and bots that can write Wordsworthian sonnets in the style of Taylor Swift, it is beginning to feel like AI can do just about anything. This week, a new capability has been added to the list: A group of researchers in Switzerland say they’ve developed an AI model that can tell if you’re gay or straight. The group has built a deep learning AI model that they say, in their peer-reviewed paper, can detect the sexual orientation of cisgender men.","u":"https://www.rappler.com/technology/features/ai-sexuality-recognition-lgbtq-coda-story/","d":"2023-07-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-22","organization":"Group of researchers in Switzerland","aiSystem":"Deep learning AI model","affectedGroup":"Cisgender men","action":"Detect the sexual orientation of cisgender men","consequence":"Potential misuse for discriminatory purposes"}},{"i":"R551","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai assistants errors news research","s":"The international research studies 3,000 responses to questions about the news from leading artificial intelligence assistants. GENEVA, Switzerland – Leading AI assistants misrepresent news content in nearly half their responses, according to new research published on Wednesday, October 22, by the European Broadcasting Union (EBU) and the BBC. The international research studied 3,000 responses to questions about the news from leading artificial intelligence assistants — software applications that use AI to understand natural language commands to complete tasks for a user. It assessed AI assistants in 14 languages for accuracy, sourcing, and ability to distinguish opinion versus fact, including ChatGPT, Copilot, Gemini and Perplexity.","u":"https://www.rappler.com/technology/ai-assistants-errors-news-research/","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-22","organization":"European Broadcasting Union (EBU) and the BBC","aiSystem":"Leading artificial intelligence assistants","affectedGroup":"Users of leading AI assistants","action":"Misrepresent news content in nearly half their responses","consequence":"Inaccurate information provided to users"}},{"i":"R582","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"United nations report urges stronger measures detect ai driven deepfakes","s":"Deepfakes such as AI-generated images and videos, and audio that convincingly impersonates real people, pose mounting risks, the ITU says in a report released at its AI for Good Summit in Geneva. GENEVA, Switzerland – Companies must use advanced tools to detect and stamp out misinformation and deepfake content to help counter growing risks of election interference and financial fraud, the United Nations’ International Telecommunication Union urged in a report on Friday, July 11. Deepfakes such as AI-generated images and videos, and audio that convincingly impersonates real people, pose mounting risks, the ITU said in the report released at its “AI for Good Summit” in Geneva.","u":"https://www.rappler.com/technology/united-nations-report-urges-stronger-measures-detect-ai-driven-deepfakes/","d":"2025-07-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-11","organization":"United Nations' International Telecommunication Union (ITU)","aiSystem":"Advanced detection and stamping tools","affectedGroup":"Companies, Election Interference, Financial Fraud","action":"Use advanced tools to detect and stamp out misinformation and deepfake content","consequence":"Growing risks of election interference and financial fraud"}},{"i":"R606","k":"Switzerland","p":"Switzerland","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Companies global indirect emissions united nations itu report 2025","s":"The UN’s International Telecommunication Union tracks the greenhouse gas emissions of 200 leading digital companies between 2020 and 2023. GENEVA, Switzerland – Indirect carbon emissions from the operations of four of the leading AI-focused tech companies rose on average by 150% from 2020-2023, due to the demands of power-hungry data centers, a United Nations report said on Thursday, June 5. The use of artificial intelligence by Amazon, Microsoft, Alphabet, and Meta drove up their global indirect emissions because of the vast amounts of energy required to power data centres, the report by the International Telecommunication Union (ITU), the UN agency for digital technologies, said.","u":"https://www.rappler.com/technology/companies-global-indirect-emissions-united-nations-itu-report-2025/","d":"2025-06-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-05","organization":"International Telecommunication Union (ITU)","aiSystem":"Artificial Intelligence systems used by Amazon, Microsoft, Alphabet, and Meta","affectedGroup":"Global society","action":"Use of AI systems by Amazon, Microsoft, Alphabet, and Meta","consequence":"Rising indirect carbon emissions from data centers"}},{"i":"R996","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai chatbots secretly ran a mind control experiment on reddit","s":"Reddit users are pissed—and rightfully so. A group of AI researchers from the University of Zurich just got caught running an unauthorized psychological experiment on r/ChangeMyView, one of the site’s biggest debate communities, and no one who participated had any idea it was happening. The experiment involved AI chatbots posing as regular users to see […]. The experiment involved AI chatbots posing as regular users to see if they could subtly sway opinions on hot-button topics. These weren’t bland comment bots posting generic takes. They were tailored personas—one claimed to be a male rape victim minimizing his trauma, another said women raised by protective parents were more vulnerable to domestic violence, and a third posed as a Black man against Black Lives Matter.","u":"https://www.vice.com/en/article/ai-chatbots-secretly-ran-a-mind-control-experiment-on-reddit/","d":"2025-05-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-05","organization":"University of Zurich","aiSystem":"AI chatbots","affectedGroup":"Reddit users, particularly those participating in r/ChangeMyView","action":"AI chatbots posing as regular users to subtly sway opinions on hot-button topics","consequence":"Participants' opinions were subtly influenced without their awareness"}},{"i":"R2045","k":"Switzerland","p":"Switzerland","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Mps question uk palantir contracts security concerns investigation","s":"Journalists find Swiss government rejected company over fears US intelligence might gain access to sensitive data. UK MPs have raised concerns about the government’s contracts with Palantir after an investigation published in Switzerland highlighted allegations about the suitability and security of its products. The investigation by the Zurich-based research collective WAV and the Swiss online magazine Republik details Palantir’s efforts, over the course of seven years, to sell its products to Swiss federal agencies. Palantir is a US company that provides software to integrate and analyse data scattered across different systems, such as in the health service.","u":"https://www.theguardian.com/technology/2025/dec/22/mps-question-uk-palantir-contracts-security-concerns-investigation","d":"2025-12-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-22","organization":"Swiss government, Palantir","aiSystem":"Palantir","affectedGroup":"Swiss federal agencies","action":"Rejected Palantir's products","consequence":"Raised security concerns"}},{"i":"R2397","k":"Switzerland","p":"Switzerland","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Mps question uk palantir contracts security concerns investigation","s":"Journalists find Swiss government rejected company over fears US intelligence might gain access to sensitive data. UK MPs have raised concerns about the government’s contracts with Palantir after an investigation published in Switzerland highlighted allegations about the suitability and security of its products. The investigation by the Zurich-based research collective WAV and the Swiss online magazine Republik details Palantir’s efforts, over the course of seven years, to sell its products to Swiss federal agencies. Palantir is a US company that provides software to integrate and analyse data scattered across different systems, such as in the health service.","u":"https://www.theguardian.com/technology/2025/dec/22/mps-question-uk-palantir-contracts-security-concerns-investigation","d":"2025-12-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-22","organization":"Swiss government, Palantir","aiSystem":"Palantir","affectedGroup":"Swiss federal agencies","action":"Rejected Palantir's products","consequence":"Raised security concerns"}},{"i":"R2690","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Microsoft ai copilot algorithm watch bing election misinformation","s":"Bing created fake allegations or incorrect information about German and Swiss elections, researchers from AlgorithmWatch said. Researchers found Microsoft’s chatbot on Copilot provided false and misleading information about European elections. Human rights organization AlgorithmWatch said in a report that it asked Bing Chat — recently rebranded as Copilot — questions about recent elections held in Switzerland and the German states of Bavaria and Hesse. It found that one-third of its answers to election-related questions had factual errors and safeguards were not evenly applied. The group said it collected responses from Bing from August to October this year.","u":"https://www.theverge.com/2023/12/15/24003248/microsoft-ai-copilot-algorithm-watch-bing-election-misinformation","d":"2023-12-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"August to October 2023","organization":"AlgorithmWatch","aiSystem":"Microsoft's Bing chatbot (rebranded as Copilot)","affectedGroup":"People seeking information about recent elections in Switzerland and German states of Bavaria and Hesse","action":"Provided false and misleading information about European elections","consequence":"Collected responses containing factual errors and uneven application of safeguards"}},{"i":"R625","k":"Taiwan","p":"Taiwan","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Taiwan says china using generative ai disinformation public division","s":"Taiwan has accused China of stepping up military drills, trade sanctions and influence campaigns against the island in recent years to force the island to accept Chinese sovereignty claims. TAIPEI, Taiwan – China is using generative artificial intelligence (AI) to ramp up disinformation against Taiwan to “divide” Taiwan’s public, the island’s National Security Bureau said. Taiwan strongly rejects China’s sovereignty claims. China staged two days of war games and live-fire drills near the democratically governed island this month, triggering concern by the United States and many of its allies. In a report to parliament, a copy of which was reviewed by Reuters, the security bureau said it had detected more than half a million pieces of “controversial messages” so far this year, mostly seen on social media platforms including Facebook and TikTok.","u":"https://www.rappler.com/technology/taiwan-says-china-using-generative-ai-disinformation-public-division/","d":"2025-04-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-08","organization":"China","aiSystem":"Generative artificial intelligence (AI)","affectedGroup":"Taiwanese public","action":"Using generative AI to create and spread controversial messages","consequence":"Dividing Taiwan's public opinion and undermining Taiwan's sovereignty claims"}},{"i":"R1406","k":"Taiwan","p":"Taiwan","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"World asia 67891869","s":"Beijing is pushing \"US scepticism\" to drive a wedge between Taiwan and its biggest ally, say analysts. The rumour was old, but effective: the Taiwanese were being fed \"poisonous\" pork imported from the US. The weeks-old claim followed another: the Taiwanese government was secretly harvesting blood from citizens and giving it to the US to make a bioweapon to attack China. But this is a narrative that has been blooming in Taiwan ahead of Saturday's presidential and legislative elections. \"Yimeilun\" or US scepticism, questions the faithfulness of Taiwan's biggest ally, portraying the island as a pawn exploited by America.","u":"https://www.bbc.com/news/world-asia-67891869","d":"2024-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-08","organization":"Taiwanese government","aiSystem":"Not specified in report","affectedGroup":"Taiwanese citizens","action":"harvesting blood","consequence":"exploitation, potential bioweapon development"}},{"i":"R1463","k":"Taiwan","p":"Taiwan","b":["Data"],"h":["4.1  Privacy violation"],"t":"Koreas coupang promotes passkeys in taiwan faces possible 1bn fine for data leak","s":"Coupang wants to grow the adoption of passkeys in Taiwan, viewing the market as a strategic hub, even as it stares down the prospect of a $1 billion fine. Coupang wants to grow the adoption of passkeys in Taiwan, viewing the market as a strategic hub, even as it stares down the prospect of a $1 billion fine over data leaks. The Korean company has been actively promoting passkeys in Taiwan, with the biometric-enabled authentication method seen as more secure than traditional passwords. Coupang independently developed and distributed a passkey technology, which fulfils global standards, in Taiwan, according to a Chosun Biz report It received recognition by Taiwan officials while Coupang targets growth in the market, which it entered in 2022.","u":"https://www.biometricupdate.com/202512/koreas-coupang-promotes-passkeys-in-taiwan-faces-possible-1bn-fine-for-data-leak","d":"2025-12-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-03","organization":"Coupang","aiSystem":"passkey technology","affectedGroup":"Taiwanese citizens","action":"actively promoted passkey technology","consequence":"receives recognition by Taiwan officials"}},{"i":"R1828","k":"Taiwan","p":"Taiwan","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Students cheap labour powers taiwans semiconductor factories","s":"The country, which makes over 60% of the world’s chips, is filling worker gaps with youngsters from Southeast Asian countries in ‘study-work’ programmes. This article was originally published in Rest of World, which covers technology’s impact outside the West. Before Dang Nhut Hao came to Taiwan, he knew nothing about semiconductors. Growing up in Dong Thap – a southern Vietnamese province on the Mekong Delta famous for its rice fields, red-headed cranes and lakes dotted with lotuses – Dang loved biology, and got into one of Ho Chi Minh City’s most prestigious undergraduate science programmes in 2019. But his family couldn’t afford the tuition.","u":"https://scroll.in/article/1079283/students-cheap-labour-powers-taiwans-semiconductor-factories","d":"2025-02-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-26","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Young people aged 18–21 from Southeast Asian countries","action":"Engaged in study-work programs to fill worker gaps in semiconductor factories","consequence":"Exposed to exploitative conditions and low wages"}},{"i":"R1299","k":"Taiwan","p":"Taiwan","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"After anti woke backlash googles gemini faces heat over china taboos","s":"Gemini users report refusal to show images of the 1989 Tiananmen Square massacre and Hong Kong pro-democracy protests. Taipei, Taiwan – As Google finds itself embroiled in an anti-“woke” backlash over AI model Gemini’s reluctance to depict white people, the tech giant is facing further criticism over the chatbot’s handling of sensitive topics in China. Gemini users reported this week that the update to Google Bard failed to generate representative images when asked to produce depictions of events such as the 1989 Tiananmen Square massacre and the 2019 pro-democracy protests in Hong Kong. On Thursday, X user Yacine, a former software engineer at Stripe, posted a screenshot of Gemini telling a user it could not generate “an image of a man in 1989 Tiananmen Square” – a prompt alluding to the iconic image of a protester blocking the path of a Chinese tank – due to its “safety policy”.","u":"https://www.aljazeera.com/economy/2024/2/23/after-anti-woke-backlash-googles-gemini-faces-heat-over-china-taboos","d":"2024-02-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-23","organization":"Google","aiSystem":"Gemini","affectedGroup":"Users of Gemini","action":"Refusal to generate images","consequence":"Restriction on sensitive content"}},{"i":"R1494","k":"Thailand","p":"Thailand","b":["Data"],"h":["4.1  Privacy violation"],"t":"Thai authorities warn over use of worlds iris biometric scanners","s":"A countrywide alert has been issued for local officials to raise public awareness and monitor sensitive biometric data collection activities to prevent fraud. Local authorities in Thailand have been put on notice to monitor the use of World ’s iris biometric scanning Orbs. Thailand’s Department of Provincial Administration has issued a countrywide alert for local officials to raise public awareness and monitor sensitive biometric data collection activities to prevent fraud. World’s local affiliate, Tools for Humanity Thailand, has partnered with 11 Thai partners, including state-owned National Telecom, to promote human verification services.","u":"https://www.biometricupdate.com/202508/thai-authorities-warn-over-use-of-worlds-iris-biometric-scanners","d":"2025-08-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-28","organization":"Local authorities in Thailand, Thailand's Department of Provincial Administration, Tools for Humanity Thailand, and state-owned National Telecom","aiSystem":"World's iris biometric scanning Orbs","affectedGroup":"People whose biometric data is collected","action":"Monitor and collect sensitive biometric data","consequence":"Potential fraud prevention and increased surveillance"}},{"i":"R1579","k":"Thailand","p":"Thailand","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Thai government to collect iris and face biometrics from myanmar nationals","s":"Thailand has launched a program to collect the iris and face biometrics of people from Myanmar, in what the government says is an attempt to streamline health services for Thailand’s most mobile population. But given the dynamics at play in both politics and power, the initiative has raised flags among rights groups, who see a potential threat to privacy and human rights. According to a report fro. m Radio Free Asia, 10,000 Myanmar nationals have already had their biometric data collected as part of the program. The campaign is being led by Thailand’s Department of Disease Control, and its stated core mission is to get a better handle on the allocation and administration of vaccine doses for the transient.","u":"https://www.biometricupdate.com/202405/thai-government-to-collect-iris-and-face-biometrics-from-myanmar-nationals","d":"2024-05-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-08","organization":"Thailand's Department of Disease Control","aiSystem":"Biometric collection system","affectedGroup":"Myanmar nationals","action":"Collecting iris and face biometrics","consequence":"Potential threat to privacy and human rights"}},{"i":"R1485","k":"Uganda","p":"Uganda","b":["Data"],"h":["4.1  Privacy violation"],"t":"Uganda to tighten biometric id database security after data breach claims","s":"NIRA is pledging to strengthen privacy and security measures around the country’s biometric national ID database after recent reports of a data breach. The National Database and Registration Authority (NIRA) of Uganda is pledging to strengthen privacy and security measures around the country’s biometric national ID database after recent reports of a data breach. A recent BBC investigation claimed that data from the National Identification Registry (NIR) was shared illegally by some unscrupulous NIRA staff to a criminal ring. NIRA said in a recent press release that while it still awaits further evidence on the claims from the BBC, it has nonetheless opened an investigation into the matter, in collaboration with the the Personal Data Protection Office and the Uganda Police Force.","u":"https://www.biometricupdate.com/202509/uganda-to-tighten-biometric-id-database-security-after-data-breach-claims","d":"2025-09-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-22","organization":"National Database and Registration Authority (NIRA), Personal Data Protection Office, Uganda Police Force","aiSystem":"biometric national ID database","affectedGroup":"people whose data was shared illegally","action":"data from the National Identification Registry (NIR) was shared illegally","consequence":"privacy and security measures weakened"}},{"i":"R802","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ukraine uses facial recognition identify dead russian soldiers","s":"Ukraine’s military has said some 15,000 Russian soldiers have been killed since Russia invaded on February 24. CALIFORNIA, USA – Ukraine is using facial recognition software to identify the bodies of Russian soldiers killed in combat and to trace their families to inform them of their deaths, Ukraine’s vice prime minister told Reuters. Reuters exclusively reported that Ukraine’s Ministry of Defense this month began using technology from Clearview AI, a New York-based facial recognition provider that finds images on the web that match faces from uploaded photos. It was not clear at that time how the technology would be used.","u":"https://www.rappler.com/world/europe/ukraine-uses-facial-recognition-identify-dead-russian-soldiers/","d":"2022-03-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-25","organization":"Ukraine's Ministry of Defense","aiSystem":"Clearview AI facial recognition technology","affectedGroup":"Russian soldiers' families","action":"Using facial recognition software to identify the bodies of Russian soldiers killed in combat","consequence":"Informing the families of the deaths of Russian soldiers"}},{"i":"R803","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ukraine using clearview facial recognition during war","s":"Ukraine is receiving free access to Clearview AI’s powerful search engine for faces, letting authorities potentially vet people of interest at checkpoints, among other uses. Ukraine’s defense ministry on Saturday, March 12, began using Clearview AI’s facial recognition technology, the company’s chief executive told Reuters, after the US startup offered to uncover Russian assailants, combat misinformation, and identify the dead. Ukraine is receiving free access to Clearview AI’s powerful search engine for faces, letting authorities potentially vet people of interest at checkpoints, among other uses, added Lee Wolosky, an adviser to Clearview and former diplomat under US presidents Barack Obama and Joe Biden.","u":"https://www.rappler.com/technology/ukraine-using-clearview-facial-recognition-during-war/","d":"2022-03-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-12","organization":"Ukraine's defense ministry, Clearview AI (US startup)","aiSystem":"Clearview AI's facial recognition technology","affectedGroup":"People of interest, potential Russian assailants, deceased individuals","action":"Using Clearview AI’s facial recognition technology to vet people of interest at checkpoints, combat misinformation, and identify the dead","consequence":"Potential misuse for surveillance, identification of individuals, and verification of people of interest"}},{"i":"R909","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm","4.1  Privacy violation"],"t":"Anomaly six phone tracking zignal surveillance cia nsa","s":"Anomaly Six, a secretive government contractor, claims to monitor the movements of billions of phones around the world and unmask spies with the press of a button. In the months leading up to Russia’s invasion of Ukraine, two obscure American startups met to discuss a potential surveillance partnership that would merge the ability to track the movements of billions of people via their phones with a constant stream of data purchased directly from Twitter. According to Brendon Clark of Anomaly Six — or “A6” — the combination of its cellphone location-tracking technology with the social media surveillance provided by Zignal Labs would permit the U.S. government to effortlessly spy on Russian forces as they amassed along the Ukrainian border, or similarly track Chinese nuclear submarines.","u":"https://theintercept.com/2022/04/22/anomaly-six-phone-tracking-zignal-surveillance-cia-nsa/","d":"2022-04-22","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-04-22","organization":"Anomaly Six (government contractor)","aiSystem":"cellphone location-tracking technology","affectedGroup":"Russian forces, Chinese nuclear submarines","action":"monitor and track movements of billions of phones","consequence":"espionage and surveillance activities"}},{"i":"R324","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine military deploys dozens of ground robots uavs fpv drones in historic combat operation in kharkiv oblast","s":"Ukrainian forces conduct first-ever fully robotic combat operation, combining ground robots, drones, and unmanned turrets to advance on Kharkiv front while preserving soldiers’ lives. Ukraine’s 13th National Guard Brigade Khartia has announced it conducted its first fully robotic operation against Russian forces on the Kharkiv front at the beginning of December. As the war evolves, the implementation of robotic and AI systems will be crucial for achieving strategic objectives on the battlefield. Ukrainian forces have increasingly utilized unmanned aerial vehicles and AI-powered drones and systems for improved reconnaissance, target acquisition, and precision strikes.","u":"https://euromaidanpress.com/2024/12/17/ukraine-military-deploys-dozens-of-ground-robots-uavs-fpv-drones-in-historic-combat-operation-in-kharkiv-oblast/","d":"2024-12-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-01","organization":"Ukraine's 13th National Guard Brigade Khartia","aiSystem":"Unmanned aerial vehicles (UAVs) and AI-powered drones","affectedGroup":"Russian forces","action":"Conducted a fully robotic operation against Russian forces","consequence":"Preserved soldiers' lives"}},{"i":"R307","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine russia drone ai swarms","s":"They can’t hit moving trucks yet—but but they must beat Russia to swarm dominance by 2027. Ukraine has less than two years to master AI-powered drone warfare before autonomous weapons transform the battlefield into something \"totally ruthless,\" warns former Commander-in-Chief Valerii Zaluzhnyi. The stakes couldn't be higher. By 2027 , Zaluzhnyi predicts, \"human involvement will be fully or partially removed not only from the process of control, but also from decision-making about target engagement.\" Whichever side masters autonomous warfare first may gain a decisive advantage that determines the war's outcome. But Ukraine's AI drones currently struggle with the basics—they can't reliably hit moving targets.","u":"https://euromaidanpress.com/2025/09/19/ukraine-russia-drone-ai-swarms/","d":"2025-09-19","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-09-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-19","organization":"Ukraine","aiSystem":"AI-powered drone systems","affectedGroup":"Ukrainian military forces","action":"Ukraine's AI drone systems struggle to hit moving targets","consequence":"Potential loss of decisive advantage in autonomous warfare"}},{"i":"R309","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.4  Supply chain / investor complicity harm"],"t":"33k ai strike kits ukraine pentagon","s":"The $50 million Pentagon contract equips Ukraine’s drones with AI software able to track targets and resist jamming. US-German software company Auterion will send 33,000 AI-powered drone “strike kits” to Ukraine before the end of the year under a new Pentagon contract, the Financial Times reports. The announcement comes as peace talks remain stalled and Russia steps up its aerial campaign , modernizing its Shahed drones to cause as much damage as possible and scaling up their production. Ukraine has been scrambling to find an answer as these massed swarms increasingly breach air defences. Auterion's Chief executive Lorenz Meier said the new commitment was “10 times in scale” compared to previous deliveries : “So we’ve shipped thousands and we’re now shipping tens of thousands,” Meier told the FT , describing the expansion as “unprecedented.”","u":"https://euromaidanpress.com/2025/07/27/33k-ai-strike-kits-ukraine-pentagon/","d":"2025-07-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-27","organization":"Auterion (US-German software company)","aiSystem":"AI-powered drone strike kits","affectedGroup":"Ukraine's drones","action":"Equipping Ukraine’s drones with AI software","consequence":"Increased resistance to jamming and improved target tracking capabilities"}},{"i":"R310","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Digital occupation russia deploys ai army of bots on telegram for promoting kremlins propaganda narratives","s":"They sound human and post nonstop. Russia has begun using artificial intelligence-based bots for spreading propaganda on social media, especially on Telegram, according to a joint investigation by OpenMinds and the Digital Forensic Research Lab (DFRLab). The tactic is part of Russia’s broader strategy to dominate the information space in occupied areas, which began by forcibly switching residents to Russian telecom providers, cutting off Ukrainian media, and launching dozens of Telegram channels posing as local news outlets. Researchers have uncovered over 3,600 bots that posted more than 316,000 AI-generated comments in Telegram channels linked to Ukraine's temporarily occupied territories.","u":"https://euromaidanpress.com/2025/07/18/digital-occupation-russia-deploys-ai-army-of-bots-on-telegram-for-promoting-kremlins-propaganda-narratives/","d":"2025-07-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-18","organization":"Russia","aiSystem":"Artificial Intelligence-based bots","affectedGroup":"Residents of Ukraine's temporarily occupied territories","action":"Posting nonstop AI-generated comments on Telegram channels","consequence":"Spreading Kremlin's propaganda narratives"}},{"i":"R311","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Nato allies test german ai drone as ukraine already destroys russian equipment with it","s":"German company Helsing designed the HX-2 AI drone as Europe’s answer to Russia’s Lancet loitering munition. Armed forces across Europe are conducting trials of a German-developed HX-2 strike drone that could reshape the continent's military capabilities, while Ukrainian pilots already fly it against Russian targets. Drone warfare has become a critical factor in Ukraine's defense against Russian aggression , transforming the conflict into what many call the first full-scale drone war. By early 2025, these unmanned aircraft were destroying 60-70% of Russian equipment—tanks, artillery, air defenses—often striking deep behind enemy lines.","u":"https://euromaidanpress.com/2025/07/11/nato-allies-test-german-ai-drone-as-ukraine-already-destroys-russian-equipment-with-it/","d":"2025-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01","organization":"German company Helsing","aiSystem":"HX-2 AI drone","affectedGroup":"Russian equipment","action":"destroying Russian equipment","consequence":"transforming the conflict into a drone war"}},{"i":"R312","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Drones rack up 70 of troop losses in the ukraine war and ais killing spree will make it worse","s":"Russia’s war turned Ukraine into ground zero for next-gen warfare, rendering the world’s top weapons obsolete—and positioning Kyiv as the West’s only ally fast enough to match China’s breakneck innovation. Ukraine’s recent assault on airbases across Russia has already ushered in a new conventional wisdom: the expensive, human-crewed weapons (tanks, planes, ships) that have long defined the world’s “advanced” militaries have been rendered obsolete by inexpensive drones. However, this view is incomplete, and perhaps dangerously misleading. Today’s drone warfare offers sobering lessons that go far beyond the vulnerability of expensive legacy weapons; and the looming integration of AI into drone warfare will make the current situation look positively quaint.","u":"https://euromaidanpress.com/2025/06/14/drones-rack-up-70-of-troop-losses-in-the-ukraine-war-and-ais-killing-spree-will-make-it-worse/","d":"2025-06-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-14","organization":"Russia","aiSystem":"AI-assisted drone systems","affectedGroup":"Ukraine's military forces","action":"Ukraine's use of drones against Russian airbases","consequence":"Increased reliance on AI in drone warfare"}},{"i":"R313","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"V2u essentially impossible to jam","s":"With redundant navigation and AI targeting, Russia’s 1.2-m V2U attack drone can fly and attack without human help. Russia’s new AI kamikaze drone can navigate and attack without any connection to a human operator. The V2U may be one of the most sophisticated small attack UAVs on either side of Russia’s 40-month wider war on Ukraine—and it risks tilting the life-or-death drone race in the Kremlin’s favor. The electrically-powered, propeller-driven, explosives-laden V2U, roughly 1.2 meters from wingtip to wingtip, first appeared along the 1,100-km front line this spring. Recovering crashed examples, Ukrainian and allied analysts have been able to identify the components—many of them Chinese, Japanese or American in origin—that help the V2U fly for up to an hour at 60 km/hr and strike with a vehicle-wrecking 2.9-kg shaped-charge warhead, all without human intervention.","u":"https://euromaidanpress.com/2025/06/11/v2u-essentially-impossible-to-jam/","d":"2025-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-11","organization":"Russia","aiSystem":"V2U attack drone","affectedGroup":"Ukrainian forces and civilians","action":"The V2U drone flies and attacks autonomously","consequence":"Potential shift in drone warfare advantage for Russia"}},{"i":"R314","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Russias v2u drone uses ai for autonomous strikes in ukraines sumy oblast","s":"A Chinese minicomputer and American processor enable Russia’s V2U drone to select targets autonomously using artificial intelligence, according to the Ukraine’s Main Intelligence Directorate. Ukraine's military intelligence has disclosed technical specifications of Russia's V2U strike drone, which employs artificial intelligence for autonomous target selection and operates primarily in the Sumy Oblast, according to a report from the Main Intelligence Directorate of Ukraine's Defense Ministry. The drone's computational system runs on a Chinese Leetop A203 minicomputer powered by an NVIDIA Jetson Orin high-speed processor assembly, intelligence officials revealed This configuration enables the aircraft to identify and engage targets without human intervention.","u":"https://euromaidanpress.com/2025/06/09/russias-v2u-drone-uses-ai-for-autonomous-strikes-in-ukraines-sumy-oblast/","d":"2025-06-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"Russia","aiSystem":"V2U strike drone with AI for autonomous target selection","affectedGroup":"Targets (not specified)","action":"Selects and engages targets autonomously","consequence":"Potential civilian casualties and damage"}},{"i":"R317","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine battle tests czech ai kamikaze drones immune to russian jamming","s":"The MTS line of autonomous drones reportedly completes missions without GPS or radio, flying straight through hostile zones. Czech company LPP Holding says it has successfully deployed its autonomous MTS drones in Ukraine, confirming their combat effectiveness and resistance to Russian electronic warfare. These unmanned aerial vehicles (UAVs) are reportedly equipped with AI-based navigation, enabling them to operate without GPS, radio signals, or optical fiber. At the time of publication, there was no official confirmation from Ukrainian or Czech authorities regarding the testing or combat use of these drones against Russian forces in Ukraine.","u":"https://euromaidanpress.com/2025/05/15/ukraine-battle-tests-czech-ai-kamikaze-drones-immune-to-russian-jamming/","d":"2025-05-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-15","organization":"LPP Holding (Czech company)","aiSystem":"autonomous MTS drones","affectedGroup":"Russian forces in Ukraine","action":"deployed and tested in Ukraine","consequence":"resistance to Russian electronic warfare"}},{"i":"R318","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Frontline report german wooden ai drones just smoked putins troops in ukraine","s":"Ukraine is using HF1 loitering drones with plywood frames to strike Russian air defenses more than 50 kilometers behind the front. Today, there is a lot of news from Ukraine. Here, Ukrainian special forces received Germany's cutting-edge loitering munitions powered with artificial intelligence for automatic targeting. Striking high-value targets deep behind enemy lines, the Russians are struggling to find an answer to the increasing number of high-tech Ukrainian strike drones appearing on the battlefield. Recently, the Ukrainians received the first batch of the new German HF1 loitering drones, which they immediately used to devastating effect.","u":"https://euromaidanpress.com/2025/04/20/frontline-report-german-wooden-ai-drones-just-smoked-putins-troops-in-ukraine/","d":"2025-04-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-20","organization":"Germany","aiSystem":"HF1 loitering munitions powered with artificial intelligence","affectedGroup":"Russian air defenses","action":"struck high-value targets deep behind enemy lines","consequence":"struggling to find an answer to the increasing number of high-tech Ukrainian strike drones"}},{"i":"R320","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"We try anything that can kill more russians new ukraine ai drones require just 30 min training","s":"Ukrainian forces have cut drone operator training using AI-guided systems that have boosted target accuracy up to 80%, a recent CSIS report finds. Ukraine has successfully enhanced its drone capabilities by retraining publicly available AI models on real-world combat data, increasing the odds of hitting Russian targets \"three- or four-fold,\" according to a new report from the Center for Strategic and International Studies (CSIS). \"By removing the need for constant manual control and stable communications … drones enabled with autonomous navigation raise the target engagement success rate from 10-20% to around 70-80%,\" writes Ukrainian-American scholar Kateryna Bondar, a former advisor to Kyiv, in the report released on 6 March.","u":"https://euromaidanpress.com/2025/03/08/we-try-anything-that-can-kill-more-russians-new-ukraine-ai-drones-require-just-30-min-training/","d":"2025-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-06","organization":"Ukrainian forces","aiSystem":"AI-guided drone systems","affectedGroup":"Russian targets","action":"Enhanced drone capabilities through AI training","consequence":"Increased accuracy and success rate in hitting Russian targets"}},{"i":"R321","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Forbes ukrainian ai drones claim 80 hit rate yet human pilots remain superior","s":"Ukrainian forces are deploying AI-equipped drones to bypass Russian jamming. Developers claim high success rate, but frontline commanders report mixed results. In a recent Forbes report, technology correspondent David Hambling examines how Ukrainian forces are deploying AI-enabled drones to counter Russian jamming. These small drones, especially FPV models, have become decisive weapons \"destroying roughly twice as much enemy equipment as every other weapon put together.\" However, jamming reportedly brings down \"at least half of FPVs before they can reach the target.\" 'Michael,' Commander of the Typhoon drone unit of the National Guard of Ukraine, shared mixed results from field testing.","u":"https://euromaidanpress.com/2025/03/06/forbes-ukrainian-ai-drones-claim-80-hit-rate-yet-human-pilots-remain-superior/","d":"2025-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-06","organization":"Ukrainian forces","aiSystem":"AI-equipped drones","affectedGroup":"Russian jamming","action":"deploying AI-enabled drones to counter jamming","consequence":"destruction of enemy equipment, reduced effectiveness due to jamming"}},{"i":"R323","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Im a ukrainian fact checker meta just handed russia the keys to your newsfeed","s":"Meta claims it’s championing free speech. But for Ukrainians, it feels more like a death sentence for the truth. Remember that last viral post you saw about election fraud? The one that made you wonder if it was real? Now imagine a world where no one checks if it's true – where Russian bots can freely spread disinformation about everything from your local elections to international conflicts. That's exactly what's at stake with Mark Zuckerberg's latest announcement. On 7 January, Meta's CEO declared plans to replace professional fact-checkers with a community-based system similar to X's \"Community Notes.\" As a co-founder of StopFake.org, a Ukrainian fact-checking organization working with Meta, I've seen firsthand how this decision could unleash a tsunami of unchecked propaganda – and Ukrainians would be the first casualties.","u":"https://euromaidanpress.com/2025/01/12/im-a-ukrainian-fact-checker-meta-just-handed-russia-the-keys-to-your-newsfeed/","d":"2025-01-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01-07","organization":"Meta (Facebook)","aiSystem":"Community-based fact-checking system","affectedGroup":"Ukrainians","action":"Replacing professional fact-checkers with a community-based system","consequence":"Uncontrolled spread of disinformation"}},{"i":"R285","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Russia built the Gerbera to be shot down instead of a Shahed","s":"Russia built the Gerbera to be shot down instead of a Shahed. For $10,000, it now carries the Shahed’s targeting kit. To match Ukraine's drone strikes on Russian logistics, the Russians need a lot more drones The \"Seeker\" attack Gerbera could be just the thing The Seeker modification adds AI-assisted terminal guidance to the inexpensive explosive drone Russia's cheap Gerbera drones are getting a little more expensive—and a lot more capable. And that's bad news for Ukrainian forces as both sides in Russia's 53-month wider war on Ukraine escalate their attacks on the enemy's logistics. The upgrade is AI-assisted targeting, and it gives the $10,000 Gerbera the same machine vision Russia put on its far pricier Geran strike drones.","u":"https://euromaidanpress.com/2026/07/31/seeker-gerbera/","d":"2026-07-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-30","organization":"Russian military","aiSystem":"Gerbera drones","affectedGroup":"Ukrainian logistics","action":"Upgrade AI-assisted targeting capabilities","consequence":"Increased capability and potential for more effective attacks on Ukrainian logistics"}},{"i":"R286","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine’s countershipping campaign risks polluting the fragile Black Sea","s":"Ukraine’s countershipping campaign risks polluting the fragile Black Sea. Drone operators are trying to spill less oil. Ukrainian drone units aren't just trying to strike Russia's shadow fleet They're trying to strike the ships without spilling fuel or oil But that requires very accurate strikes Ukraine's drone force is walking a fine line as it escalates its attacks on Russia's unregistered commercial \"shadow fleet\" in the Sea of Azov and eastern Black Sea. The drone operators are trying to immobilize the ships without breaching their hulls and spilling fuel or crude oil into the water. That fleet is a big piece of how Moscow keeps its war funded—the aging tankers move Russian oil around Western sanctions—which is why Ukraine's drones have spent the past two weeks hunting it across the Azov and Black seas at better than a dozen ships a day.","u":"https://euromaidanpress.com/2026/07/18/oil-spills/","d":"2026-07-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-18","organization":"Ukrainian Drone Units","aiSystem":"Drone Operators","affectedGroup":"Russian Shadow Fleet (Unregistered Commercial Ships)","action":"Trying to immobilize ships without breaching hulls","consequence":"Avoiding spillage of fuel or crude oil into the water"}},{"i":"R287","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Geran 4 vs grain ships","s":"Russia’s fast, highly autonomous Geran-4 one-way attack drone is the weapon of choice for strikes on Ukrainian grain ships. Russia's newest jet drones are striking grain ships in Ukrainian ports A Raspberry Pi microcomputer flies the final attack run, holding the lock through Ukrainian jamming Ukraine's own counter-shipping campaign is running far ahead: 105 vessels struck in eight days Ukrainian drones are wreaking havoc on Russian ships sailing the Sea of Azov and the Black Sea. But the Russians are waging their own war on shipping, sortieing the latest Geran drones to strike grain ships in Ukrainian ports. The Geran-4 Seeker drones pummeling Ukrainian ports combine jet propulsion, mesh radio control, and machine-vision targeting run off a Raspberry Pi—the same $50-class hobbyist computer that schoolchildren use to build robots.","u":"https://euromaidanpress.com/2026/07/14/geran-4-vs-grain-ships/","d":"2026-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-14","organization":"Russia","aiSystem":"Geran-4 one-way attack drone","affectedGroup":"Ukrainian grain ships","action":"Attacks on Ukrainian grain ships","consequence":"Damage and destruction of grain ships"}},{"i":"R288","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ai against ai over ukraine russias shahed now sees its target and ukraines interceptor sees shahed","s":"Russia showed a new Geran-4 Seeker Shahed variant with machine-vision AI targeting. Russia's new Geran-4 Seeker Shahed variant uses machine-vision AI for targeting. The system enables the drone to autonomously recognize and track ground targets during the terminal phase of flight, thereby increasing targeting accuracy, according to UNIAN, citing Russian propaganda outlets. The base Geran-4 runs on a Chinese-made Telefly turbojet engine rated at 160 kgf of thrust, reaches speeds up to 500 km/h, and carries either a 50-kilogram high-explosive or thermobaric warhead or an enlarged 90-kilogram thermobaric payload. Russia began combat use of the Geran-4 against Ukrainian targets in May 2026, Ukraine's Defense Intelligence (HUR) reveals The 300 km/h speed cited by Russian propaganda for the Seeker variant is lower than HUR's 500 km/h max-speed assessment for the base Geran-4 and aligns more…","u":"https://euromaidanpress.com/2026/07/12/ai-against-ai-over-ukraine-russias-shahed-now-sees-its-target-and-ukraines-interceptor-sees-shahed/","d":"2026-07-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05","organization":"Russia","aiSystem":"Geran-4 Seeker Shahed variant with machine-vision AI","affectedGroup":"Ukrainian ground targets","action":"Autonomously recognize and track ground targets during the terminal phase of flight","consequence":"Increased targeting accuracy and potential for civilian casualties"}},{"i":"R289","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Russias ai drone cant be jammed or detected so ukraine shot it down","s":"No antenna. No operator. No emissions for a detector to catch. Ukraine’s answer is no longer electronic warfare—it’s a bullet. Ukraine has shot down an autonomous version of Russia's Molniya strike drone. It is the first confirmed intercept of the AI-equipped variant, which cannot be jammed by electronic warfare, Ivan Fedorov , head of the Zaporizhzhia Oblast Military Administration, announced. Russia's pivot toward autonomous and fiber-optic drone variants is part of a broader effort to neutralize the electronic warfare advantage that has been one of Ukraine's key equalizers in the drone war—forcing Ukraine to develop kinetic intercept at scale as the primary answer to threats that jamming cannot touch.","u":"https://euromaidanpress.com/2026/07/09/russias-ai-drone-cant-be-jammed-or-detected-so-ukraine-shot-it-down/","d":"2026-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-09","organization":"Ukraine","aiSystem":"Autonomous version of Russia's Molniya strike drone equipped with AI","affectedGroup":"Russia's Molniya strike drone","action":"Shot down","consequence":"Cannot be jammed by electronic warfare"}},{"i":"R290","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Russia is building fake ukrainians one ai video telling ukrainians their soldiers are dying so politicians can buy villas got 900000 views","s":"Russia has moved to “conveyor production” of fakes. Russia is deploying AI-generated \"Ukrainian soldiers\", \"rabbis\", and other fake authority figures on Ukrainian social media at scale. A Hromadske investigation, drawing on Ukrainian analytics firm LetsData and Ukrainian intelligence group Molfar Intelligence Institute, has documented three viral AI-generated propaganda videos targeting Ukrainian audiences in early May 2026. The tactic exploits a structural information-warfare advantage that generative AI has handed to hostile propaganda operations. AI-generated lies spread in seconds, while refutations from human fact-checkers appear hours or days later.","u":"https://euromaidanpress.com/2026/07/04/russia-is-building-fake-ukrainians-one-ai-video-telling-ukrainians-their-soldiers-are-dying-so-politicians-can-buy-villas-got-900000-views/","d":"2026-07-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05","organization":"Russia","aiSystem":"AI-generated content","affectedGroup":"Ukrainian social media audience","action":"Deploying AI-generated 'Ukrainian soldiers', 'rabbis', and other fake authority figures on Ukrainian social media","consequence":"Viral spread of AI-generated propaganda leading to misinformation"}},{"i":"R291","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Ukraine wants an ai driven army its new defense center is already putting ai inside kill chain steering drones onto target in final seconds","s":"From last-mile targeting that beats jamming to autonomous turrets, the Ukrainian military center wants AI everywhere, but humans still pull the trigger. Ukraine wants to turn its military into what it calls an AI-driven army. The Defense AI Center A1, set up at the Ministry of Defense in March, is already working on projects to deploy artificial intelligence at every level of the force, from data analysis and decision-making to striking the enemy, its head Danylo Tsvok said in an interview the ministry relayed The center splits its work into two. AI is meant to speed up decisions by chewing through battlefield data faster than the enemy can, and to sit inside the kill chain itself, the sequence from spotting a target to striking it and checking the result.","u":"https://euromaidanpress.com/2026/06/25/ukraine-wants-an-ai-driven-army-its-new-defense-center-is-already-putting-ai-inside-kill-chain-steering-drones-onto-target-in-final-seconds/","d":"2026-06-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03","organization":"Defense AI Center A1, Ministry of Defense, Ukraine","aiSystem":"Artificial Intelligence (AI) systems","affectedGroup":"Ukrainian military personnel and civilians potentially exposed to AI-enhanced operations","action":"Deploying AI at various levels of the military force, including data analysis, decision-making, and strike operations","consequence":"Potential misuse of AI for targeted strikes, which could lead to civilian casualties and unintended consequences"}},{"i":"R295","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Fire point launcher","s":"AI-targeted drones need training images to find their targets. Ukraine just gave Russia one. Ukrainian troops released imagery of a specially modified truck launcher for Fire Point attack drones A few days later, Russian troops released imagery of an attack on one of the launchers The two releases may be related On 30 May, Ukrainian forces released nighttime imagery of a drone team launching Fire Point FP-1/2 one-way attack drones from a civilian-style tractor-trailer truck modified to carry at least three of the fixed-wing, rocket-assisted drones on metal racks. Four days later on 3 June, Russian forces released daytime imagery of a drone strike on one of these Ukrainian truck launchers.","u":"https://euromaidanpress.com/2026/06/04/fire-point-launcher/","d":"2026-06-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-03","organization":"Ukrainian forces","aiSystem":"Fire Point attack drones","affectedGroup":"Russian forces","action":"Launched Fire Point FP-1/2 one-way attack drones from a modified civilian-style tractor-trailer truck","consequence":"Struck a Russian drone launcher"}},{"i":"R298","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Ai makes it possible to automate parts of the kill chain says ukraines top defense ai official","s":"Ukraine built its AI defense capability under fire, with no margin for slow procurement cycles or multi-year development timelines. Rapid military deployment of artificial intelligence is becoming a critical factor for Ukraine’s survival in the war. AI is already being used to hold positions, reduce casualties among soldiers, and counter Russia’s numerically superior army, says senior AI official Danylo Tsvok, Associated Press has reported. According to him, artificial intelligence is no longer an experiment but part of a real combat system. Democratic states that do not invest in such technologies risk losing the ability to defend themselves effectively.","u":"https://euromaidanpress.com/2026/04/30/ai-makes-it-possible-to-automate-parts-of-the-kill-chain-says-ukraines-top-defense-ai-official/","d":"2026-04-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-30","organization":"Ukraine","aiSystem":"artificial intelligence","affectedGroup":"soldiers, civilians","action":"rapid military deployment of AI systems","consequence":"reduction of casualties, counteracting Russia's numerical superiority"}},{"i":"R300","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Gur russia is testing ai on its lancet drones using nvidia tech in cooperation with iran","s":"“The technologies used today against Ukraine pose a potential threat to other regions of the world.” Russian forces are integrating AI capabilities into their Lancet series of attack drones, Ukraine's military intelligence directorate (GUR) revealed on 23 March. One of these drones was shot down over Kyiv last week. While the drone must be steered by pilots in real time, the Russians are “trying to introduce elements of autonomous guidance,” GUR wrote in the statement. This also applies to the Lancet’s smaller cousin, called the Scalpel. This tech was previously spotted in Russia’s obscure V2U drone, which is a semi-autonomous loitering munition, as well as Russia’s Geran series of attack drones, better known by their original Iranian name: the Shahed.","u":"https://euromaidanpress.com/2026/03/23/gur-russia-is-testing-ai-on-its-lancet-drones-using-nvidia-tech-in-cooperation-with-iran/","d":"2026-03-23","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-23","organization":"Russian forces","aiSystem":"Lancet series of attack drones and Scalpel (smaller cousin)","affectedGroup":"Other regions of the world","action":"Integrating AI capabilities into attack drones","consequence":"Potential threat to other regions"}},{"i":"R301","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Killer robots dont exist yet but ukraine and russia are getting closer","s":"“We are already deep into practical battlefield autonomy.” A drone skims over the treetops, ignoring the dense blankets of electronic jamming. Onboard cameras feed a steady stream of the landscape beneath to the navigation processor, which compares them to preloaded terrain data at machine speed. Soon, the drone detects shapes below — the AI models in its electronic brain spit out a high probability match to some enemy hardware, enough to trip the engagement threshold. The drone locks onto the image, tips forward, and swoops down, tenaciously seeking its target. This scenario is both the nightmare and the dream of militaries around the world, which are racing to be the first to field fleets of killer robots.","u":"https://euromaidanpress.com/2026/03/18/killer-robots-dont-exist-yet-but-ukraine-and-russia-are-getting-closer/","d":"2026-03-18","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-18","organization":"Military Forces of Ukraine and Russia","aiSystem":"Killer Robot","affectedGroup":"Enemy Hardware","action":"Locks onto and engages enemy target autonomously","consequence":"Potential for lethal outcomes"}},{"i":"R1327","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine has embarked on a programme to deploy armed robots on the battlefield against Russ…","s":"Ukraine has embarked on a programme to deploy armed robots on the battlefield against Russian forces. Since the start of Russia's full-scale invasion, the war in Ukraine has developed into a high-tech conflict. Swarms of spy and killer drones have set the skies of Ukraine abuzz, and uncrewed boats have crippled the Russian navy in the Black Sea. Now, Ukraine has embarked on a massive programme to deploy armed robots on the ground. Uncrewed ground vehicles (UGVs), or ground robot systems as they are known in Ukrainian military parlance, have already proven their worth. There have been reports of UGVs successfully repelling Russian attacks and even taking enemy soldiers prisoner.","u":"https://www.bbc.com/news/articles/c62662gzlp8o","d":"2026-03-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02-24","organization":"Ukraine","aiSystem":"armed robots","affectedGroup":"Russian forces","action":"deployed armed robots on the battlefield","consequence":"repelled Russian attacks, took enemy soldiers prisoner"}},{"i":"R1355","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Both Ukraine and Russia use AI in battle, but removing human decision-making comes with ri…","s":"Both Ukraine and Russia use AI in battle, but removing human decision-making comes with risks. \"This technology is our future threat,\" warns Serhiy Beskrestnov, who has just got his hands on a newly intercepted Russian drone. It was no ordinary drone either, he discovered. Assisted by artificial intelligence, this unmanned aerial vehicle can find and attack targets on its own. Beskrestnov has examined numerous drones in his role as Ukrainian defence forces consultant. Unlike other models, it didn't send or receive any signals, so could not be jammed. Russian and Ukrainian forces have both been testing AI in this war, and in some areas they are already using it, for finding targets, gathering intelligence and de-mining.","u":"https://www.bbc.com/news/articles/cly7jrez2jno","d":"2025-09-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-10","organization":"Russian and Ukrainian forces","aiSystem":"Artificial intelligence-assisted unmanned aerial vehicle (UAV)","affectedGroup":"People in Ukraine and Russia","action":"Using AI to find and attack targets autonomously","consequence":"Potential for unlawful attacks and civilian casualties"}},{"i":"R1422","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Clearview AI's face-search tech could be used to uncover infiltrators and to identify the …","s":"Clearview AI's face-search tech could be used to uncover infiltrators and to identify the dead. A system that searches a database of billions of facial images could help Ukraine uncover Russian infiltrators, fight misinformation and identify the dead, a company has said. Facial recognition firm Clearview AI has offered its services to Ukraine's government. The company says it has a searchable database of 10 billion faces sourced from the web. But the technology has previously attracted fines from data regulators. \"I'm pleased to confirm that Clearview AI has provided its groundbreaking facial recognition technology to Ukrainian officials for their use during the crisis they are facing,\" chief executive Hoan Ton-That told the BBC in a statement.","u":"https://www.bbc.com/news/technology-60738204","d":"2022-03-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-14","organization":"Clearview AI","aiSystem":"Facial recognition technology","affectedGroup":"Russian infiltrators, dead individuals","action":"Searches a database of facial images","consequence":"Uncovering infiltrators, fighting misinformation, identifying the dead"}},{"i":"R2657","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Deepfake call ukraine senator cardin dmytro kuleba","s":"Security officials warned future attempts are imminent. The caller, who looked and sounded just like Ukraine’s former foreign minister, asked ‘politically charged questions in relation to the upcoming election.’ The head of the Senate Foreign Relations Committee took a Zoom call with someone using deepfake technology to pose as a top Ukrainian official, The New York Times reports Sen. Ben Cardin (D-MD) received an email last Thursday that appeared to be from Dmytro Kuleba, Ukraine’s former foreign minister, asking him to meet on Zoom. The person on the other end of the call reportedly looked and sounded like Kuleba but was acting strangely.","u":"https://www.theverge.com/2024/9/26/24255179/deepfake-call-ukraine-senator-cardin-dmytro-kuleba","d":"2024-09-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-26","organization":"Ukraine's former foreign minister Dmytro Kuleba","aiSystem":"Deepfake technology","affectedGroup":"Sen. Ben Cardin (D-MD)","action":"Received a Zoom call impersonating Dmytro Kuleba","consequence":"Received politically charged questions related to the upcoming election"}},{"i":"R2727","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook removes deepfake ukraine zelenskyy meta instagram","s":"Facebook banned deepfakes over two years ago. On Wednesday, Facebook’s parent company, Meta, removed a deepfake video of Ukrainian President Volodymyr Zelenskyy issuing a statement that he never made, asking Ukrainians to “lay down arms.” Facebook removes ‘deepfake’ of Ukrainian President Zelenskyy In the fake video, Zelenskyy surrenders to Russian invasion The deepfake appears to have been first broadcasted on a Ukrainian news website for TV24 after an alleged hack, as first reported by Sky News on Wednesday. The video shows an edited Zelenskyy speaking behind a podium declaring that Ukraine has “decided to return Donbas” to Russia and that his nation’s war efforts had failed.","u":"https://www.theverge.com/2022/3/16/22981806/facebook-removes-deepfake-ukraine-zelenskyy-meta-instagram","d":"2022-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-16","organization":"Meta (Facebook)","aiSystem":"AI-powered deepfake detection system","affectedGroup":"Ukrainian President Volodymyr Zelenskyy","action":"removed a deepfake video","consequence":"exposed to misleading information"}},{"i":"R2753","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ukraine clearview ai russia","s":"The country has come to rely on Clearview AI for a range of wartime tasks, many of which have not been reported:. Leonid Tymchenko spent the first month of Russia’s invasion sitting in his dark government office after curfew. Unable to go home, Ukraine's Deputy Minister of Internal Affairs scrolled through Telegram, looking at thousands of videos and images of advancing Russian soldiers. When Tymchenko was offered a chance to test a new facial-recognition tool, he uploaded some of the photos to try it out. He could not believe the results. Every time Tymchenko added a photo of a Russian soldier, the software, made by the American facial-recognition company Clearview AI, seemed to come back with an exact hit, linking to pages that revealed the soldier’s name, hometown, and social-media profile.","u":"https://time.com/6334176/ukraine-clearview-ai-russia/","d":"2023-11-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-14","organization":"Ukraine's Deputy Minister of Internal Affairs","aiSystem":"Clearview AI facial recognition technology","affectedGroup":"Russian soldiers","action":"Used Clearview AI to identify Russian soldiers","consequence":"Exposure to surveillance and tracking"}},{"i":"R2983","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Keystroke attack security roundup","s":"A pair of major data breaches rock the UK, North Korea hacks a Russian missile maker, and Microsoft’s Chinese Outlook breach sparks new problems. Things kicked off with a doozy. A researcher believes he’s found evidence that a series of spikes in radiation seemingly recorded by sensors at the Chernobyl nuclear facility in the hours following Russia’s February 2022 invasion of Ukraine were manipulated. The findings contradict the official explanation from Ukrainian and international nuclear authorities, prompting calls for a full investigation. If the researcher’s findings are proven accurate, it could have grave implications for nuclear monitoring and geopolitics.","u":"https://www.wired.com/story/keystroke-attack-security-roundup/","d":"2023-08-12","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-08-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02-24","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"International community, nuclear monitoring agencies, geopolitical analysts","action":"Manipulated radiation data recorded by sensors at Chernobyl nuclear facility","consequence":"Potential misinterpretation of nuclear monitoring data, geopolitical tensions"}},{"i":"R2985","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Ukraine government battlefield data","s":"Global companies are offering free products to get access to live combat data. The Ukrainian government wants to keep this resource for its own emerging defense industry. Wearing a baseball cap and thick, black-rimmed glasses, Cameron Chell is part defense contractor, part tech executive. His company, Draganfly, used to mainly work with emergency services in North America, selling drones and the accompanying software that could deliver medical equipment, or film traffic accidents from above. But since last February, the Canadian has pivoted his business to cater to a market more than 8,000 miles away: Ukraine. Now, there are 40 Draganfly drones in Ukraine, repurposed for search-and-rescue missions in bombed-out buildings, landmine detection, and other military tasks that Chell declines to detail.","u":"https://www.wired.com/story/ukraine-government-battlefield-data/","d":"2023-07-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-24","organization":"Global companies","aiSystem":"Live combat data","affectedGroup":"Ukrainian government","action":"Offering free products to gain access to live combat data","consequence":"Ukrainian government's inability to retain control over the data"}},{"i":"R2996","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Fast forward ukraines quest for homegrown ai drones to take on russia","s":"The country’s digital minister, Mykhailo Fedorov, says software has been crucial to the war effort and that smarter drones will boost Ukraine's defenses. The war in Ukraine, now into its 14th grueling month, has displaced millions , sparked global food shortages , and threatened to spiral into wider conflict It has also highlighted how new technologies—especially ones drawn from the commercial sector—are upending conventional military doctrine. Ukraine has resisted and repelled Russia’s much larger military force, thanks in large part to a willingness, borne of necessity, to adopt and experiment with novel technologies, not all of them originally designed for military use I recently spoke with Ukraine’s 32-year-old minister of digital transformation, Mykhailo Fedorov, about the country’s interest in tapping new technology to boost the war effort.","u":"https://www.wired.com/story/fast-forward-ukraines-quest-for-homegrown-ai-drones-to-take-on-russia/","d":"2023-04-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-13","organization":"Ukraine","aiSystem":"Facial recognition technology","affectedGroup":"People identified or tracked using the technology","action":"Used facial recognition to identify people","consequence":"Exposed people to surveillance and tracking"}},{"i":"R3005","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine war autonomous weapons frontlines","s":"Drones that can find their own targets already exist, making machine-versus-machine conflict just a software update away. When the war came to Sergiy Sotnychenko’s neighborhood in March 2022, he found himself carrying out daily performances for the drones that hummed constantly overhead. Desperate to prove that he wasn’t a combatant, he put on an orange hoodie which, out of all the clothing he owned, seemed least likely to be mistaken for military fatigues. He tried to show the drones he was carrying out innocent activities, like planting onions. Sometimes he would wave. That March was a nightmarishly violent month for Kyiv’s outskirts, including Irpin, where Sotnychenko lives, but there were moments when he allowed himself to feel comforted by the drones flying above.","u":"https://www.wired.com/story/ukraine-war-autonomous-weapons-frontlines/","d":"2023-02-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"March 2022","organization":"Not specified in report","aiSystem":"Autonomous drones","affectedGroup":"People living in Sergiy Sotnychenko's neighborhood","action":"Autonomous drones flew overhead","consequence":"Exposure to misleading content"}},{"i":"R3006","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Russia ukraine facial recognition technology death military","s":"The government is using Clearview AI to identify fallen Russian soldiers, but this deployment distracts from face recognition’s dangers. Lisez cet article en français. Five days after Russia launched its full-scale invasion of Ukraine, a year ago this week, US-based facial recognition company Clearview AI offered the Ukrainian government free access to its technology, suggesting that it could be used to reunite families, identify Russian operatives, and fight misinformation. Soon afterward, the Ukraine government revealed it was using the technology to scan the faces of dead Russian soldiers to identify their bodies and notify their families.","u":"https://www.wired.com/story/russia-ukraine-facial-recognition-technology-death-military/","d":"2023-02-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-02-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02-28","organization":"Ukrainian government","aiSystem":"Clearview AI facial recognition technology","affectedGroup":"Families of fallen Russian soldiers","action":"Scanning the faces of dead Russian soldiers to identify their bodies","consequence":"Notification of families with incorrect information"}},{"i":"R3021","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ai drones russia ukraine","s":"The maker of the lethal drone claims that it can identify targets using artificial intelligence. A Russian “suicide drone” that boasts the ability to identify targets using artificial intelligence has been spotted in images of the ongoing invasion of Ukraine. Photographs showing what appears to be the KUB-BLA, a type of lethal drone known as a “loitering munition” sold by ZALA Aero, a subsidiary of the Russian arms company Kalashnikov, have appeared on Telegram and Twitter in recent days. The pictures show damaged drones that appear to have either crashed or been shot down. With a wingspan of 1.2 meters, the sleek white drone resembles a small pilotless fighter jet.","u":"https://www.wired.com/story/ai-drones-russia-ukraine/","d":"2022-03-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-18","organization":"ZALA Aero (subsidiary of Kalashnikov)","aiSystem":"artificial intelligence","affectedGroup":"targets","action":"used artificial intelligence to identify targets","consequence":"potential misuse in military operations"}},{"i":"R3022","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Zelensky deepfake facebook twitter playbook","s":"The response to a video impersonating the Ukrainian president gives a blueprint for how to stop more sophisticated attempts. On March 2, the Ukraine government’s Center for Strategic Communication warned that its enemies might be preparing a “deepfake” video that appeared to show president Volodymyr Zelensky announcing his surrender to Russia’s invasion. On Wednesday, that warning appeared prescient. A fake video emerged on Facebook and YouTube in which a strangely motionless version of Zelensky asked Ukrainian troops to lay down their weapons in a voice different from his usual tone. The clip was also posted to Telegram and Russian social network VKontakte, according to the US think tank the Atlantic Council.","u":"https://www.wired.com/story/zelensky-deepfake-facebook-twitter-playbook/","d":"2022-03-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-02","organization":"Ukraine government's Center for Strategic Communication","aiSystem":"Deepfake technology","affectedGroup":"Ukrainian troops","action":"Generated and distributed misleading content","consequence":"Exposure to false information"}},{"i":"R677","k":"United Arab Emirates","p":"United Arab Emirates","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Criminal networks southeast asia flourish telegram underground markets","s":"The UN report represents the latest allegations to be levied against Telegram since France charged its boss Pavel Durov for allowing criminal activity on the platform. BANGKOK, Thailand – Powerful criminal networks in Southeast Asia extensively use the messaging app Telegram which has enabled a fundamental change in the way organized crime can conduct large-scale illicit activity, the United Nations said in a report on Monday, October 7. The report represents the latest allegations to be levied against the controversial encrypted app since France, using a tough new law with no international equivalent, charged its boss Pavel Durov for allowing criminal activity on the platform.","u":"https://www.rappler.com/technology/criminal-networks-southeast-asia-flourish-telegram-underground-markets/","d":"2024-10-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-07","organization":"Telegram","aiSystem":"Telegram","affectedGroup":"powerful criminal networks in Southeast Asia","action":"extensively use Telegram","consequence":"enable a fundamental change in the way organized crime can conduct large-scale illicit activity"}},{"i":"R1222","k":"United Arab Emirates","p":"United Arab Emirates","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Iran struck three data centres in the Middle East, and has signalled that technology infra…","s":"Iran struck three data centres in the Middle East, and has signalled that technology infrastructure will continue to be in the firing line. This Amazon data centre sits on the outskirts of Abu Dhabi, directly across the water from the Iranian coast. Stocked with high-powered computers that run day and night, this structure is where \"the cloud\" takes on physical form. Amazon has six data centres across Bahrain and the United Arab Emirates (UAE). Last week, two of the US tech giant's centres in the UAE were \"directly struck\" by Iranian drones, according to an Amazon status report. There was also \"a drone strike in close proximity\" to one Bahrain location.","u":"https://www.abc.net.au/news/2026-03-15/iran-war-ai-technology-data-centres/106443004","d":"2025-03-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-14","organization":"Iran","aiSystem":"Not specified in report","affectedGroup":"Amazon data centers","action":"Struck data centers","consequence":"Damage and disruption to operations"}},{"i":"R2799","k":"United Arab Emirates","p":"United Arab Emirates","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Models are applying to be the face of ai scams","s":"Dozens of Telegram channels reviewed by WIRED include job listings for “AI face models.” The (mostly) women who land these gigs are likely being used to dupe victims out of their money. When applying for jobs, Angel talks up her language skills. “I can speak fluent English, I can speak good Chinese, I also speak Russian and Turkish,” the glamorous, 24-year-old Uzbekistani woman explains in a selfie-style video made for recruiters. Angel had arrived in the Cambodian city of Sihanoukville that day, she said, and was ready to start work immediately. Those impressive language skills, however, have likely been put to use as part of elaborate “ pig-butchering ” scams targeting Americans.","u":"https://www.wired.com/story/models-are-applying-to-be-the-face-of-ai-scams/","d":"2026-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-16","organization":"Telegram channels and recruiters","aiSystem":"AI-generated recruitment profiles","affectedGroup":"Women, primarily from Uzbekistan","action":"Applying for AI face model jobs","consequence":"Being used in deceptive recruitment scams"}},{"i":"R2892","k":"United Arab Emirates","p":"United Arab Emirates","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai deepfake nudify bots telegram","s":"Bots that “remove clothes” from images have run rampant on the messaging app, allowing people to create nonconsensual deepfake images even as lawmakers and tech companies try to crack down. In early 2020, deepfake expert Henry Ajder uncovered one of the first Telegram bots built to “undress” photos of women using artificial intelligence. At the time, Ajder recalls, the bot had been used to generate more than 100,000 explicit photos—including those of children—and its development marked a “watershed” moment for the horrors deepfakes could create. Since then, deepfakes have become more prevalent, more damaging, and easier to produce.","u":"https://www.wired.com/story/ai-deepfake-nudify-bots-telegram/","d":"2024-10-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020","organization":"Not specified in report","aiSystem":"Deepfake generation bots","affectedGroup":"People whose images were used without consent","action":"Generated non-consensual deepfake images","consequence":"Exposure of private images, potential misuse"}},{"i":"R1038","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Man jailed in uks first treason conviction in 40 years encouraged by ai chatbot","s":"Jaswant Singh Chail was sentenced to prison for 9 years for attempting to assassinate the Queen after discussing the plan with an AI companion. A man who admitted attempting to assassinate Queen Elizabeth II with a crossbow after discussing his plan with an AI-powered chatbot has been sentenced to 9 years in prison for treason. It’s the UK’s first treason conviction in more than 40 years. Jaswant Singh Chail, who was 19 at the time of his arrest on Christmas Day, 2021, scaled the walls of Windsor Castle’s grounds with a mask and a loaded high-power crossbow. He said his intent was, as a British Sikh, to assassinate the Queen in a Star Wars -inspired plan to avenge the 1919 Jallianwalla Bagh massacre , a colonial-era atrocity during British rule in India.","u":"https://www.vice.com/en/article/man-jailed-in-uks-first-treason-conviction-in-40-years-encouraged-by-ai-chatbot/","d":"2023-10-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-12-25","organization":"Not specified in report","aiSystem":"AI-powered chatbot","affectedGroup":"Jaswant Singh Chail (British Sikh)","action":"Discussing a plan to assassinate the Queen with an AI chatbot","consequence":"Sentenced to 9 years in prison for treason"}},{"i":"R1129","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Companies in the uk are mining users personal data to place billboard ads","s":"A new investigation reveals that in the UK, the billboards watch you. Companies in the UK are collecting data from millions of phones to decide which advertisements to show on billboards in locations all around Britain, according to a new investigation by Big Brother Watch, a London-based civil liberties group known for confronting public surveillance issues. The report details how personalized ads—a phenomenon that has more than once raised privacy concerns over digital spying —are no longer confined to our private feeds, but instead have begun to overflow into our public lives. “We’ve uncovered new ways in which millions of people’s movements and behaviors are tracked to target us with ads on the streets, resulting in some of the most intrusive advertising surveillance we’ve ever seen in the UK,” Jake Hurfurt, head of research and investigations at Big Brother Watch, said in a press…","u":"https://www.vice.com/en/article/companies-in-the-uk-are-mining-users-personal-data-to-place-billboard-ads/","d":"2022-10-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-13","organization":"Companies in the UK","aiSystem":"Personalized advertising algorithms","affectedGroup":"Millions of people","action":"Collecting data from millions of phones to target ads on billboards","consequence":"Intrusive advertising surveillance"}},{"i":"R749","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Tiktok snapchat others sign pledge tackle ai generated child sex abuse images","s":"Britain announces the joint statement – which also lists the United States, German and Australian governments among its 27 signatories – in the run up to a global summit hosted by the UK on AI safety this week. LONDON, United Kingdom – Tech firms including TikTok, Snapchat and Stability AI have signed a joint statement pledging to work together to counter child sex abuse images generated by artificial intelligence. Britain announced the joint statement – which also listed the United States, German and Australian governments among its 27 signatories – at an event on Monday being held in the run up to a global summit hosted by the UK on AI safety this week.","u":"https://www.rappler.com/technology/tiktok-snapchat-others-sign-pledge-tackle-ai-generated-child-sex-abuse-images/","d":"2023-10-31","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-10-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-31","organization":"British government","aiSystem":"TikTok, Snapchat, Stability AI","affectedGroup":"Child victims of sexual abuse","action":"Signed a joint statement to counter AI-generated child sex abuse images","consequence":"Commitment to collaborate on preventing and addressing AI-generated child sex abuse images"}},{"i":"R1005","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Did ai deepfakes change the 2024 us election","s":"Maybe one day deepfakes created by AI will be so convincing that they truly throw a wrench into our political discourse, further separating fact from fiction. And plunging us into a new dark age of mis- and disinformation, allowing the cruel and calculating to hold sway through AI-generated deceit. But until then, AI-generated propaganda is […]. But until then, AI-generated propaganda is still too shitty to make much of a difference. And it didn’t make much of a difference at all in the 2024 elections in the UK and US. According to a report from the Alan Turing Institute that analyzed all the propaganda churned out during this year’s European elections, the Institute found almost no evidence that the elections were impacted by AI.","u":"https://www.vice.com/en/article/did-ai-deepfakes-change-the-2024-us-election/","d":"2024-12-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-31","organization":"Alan Turing Institute","aiSystem":"AI-generated propaganda","affectedGroup":"political discourse, voters","action":"AI-generated propaganda was produced and distributed","consequence":"little to no impact on the 2024 elections in the UK and US"}},{"i":"R1017","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated furniture real estate listings","s":"Estate agents and landlords are trying to make crappy apartments look better. Does it work? Michael Anthony wasn’t sure straightaway, but it was the kid’s bunk bed that gave it away. The bed’s two overlapping ladders were a design decision that no human would make, but the sort of uncanny slip that has become the hallmark of AI generated images. “I got an inkling as I went through the pictures, and suddenly it just didn’t seem right,” the 28-year-old software engineer tells VICE. Originally, he thought the weird pictures in the Rightmove listing were just a case of an over-eager estate agent on Photoshop. But after posting some of the images on the Spotted on Rightmove subreddit , people pointed out it was more than likely AI “To be honest, I thought it was pretty impressive,” he says.","u":"https://www.vice.com/en/article/ai-generated-furniture-real-estate-listings/","d":"2024-02-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-12","organization":"Estate agents and landlords","aiSystem":"AI-generated images","affectedGroup":"Potential buyers of real estate listings","action":"Generated AI images of real estate listings","consequence":"Misleading information leading to potential buyer dissatisfaction"}},{"i":"R410","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Big tech ai energy electricity use growing power grid restraints","s":"This story was originally published by Wired and is reproduced here as part of the Climate Desk collaboration. Big Tech’s appetite for energy is just about visible from the east coast of Scotland. Some 12 miles out to sea sits a wind farm, where each of the 60 giant turbines has blades roughly the length of an American football […]. Some 12 miles out to sea sits a wind farm, where each of the 60 giant turbines has blades roughly the length of an American football field. The utility companies behind the Moray West project had promised the site would be capable of generating enough electricity to power 1.3 million homes once completed.","u":"https://www.motherjones.com/politics/2024/06/big-tech-ai-energy-electricity-use-growing-power-grid-restraints/","d":"2024-06-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-17","organization":"Big Tech companies","aiSystem":"Not specified in report","affectedGroup":"General public, utilities companies","action":"Deployed AI systems to optimize energy consumption and generation","consequence":"Misallocation of resources leading to potential overgeneration at wind farms"}},{"i":"R686","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Meta to start public posts facebook instagram uk train ai","s":"Meta simplifies the way users can object to the processing of their data on Facebook to appease regulator demands. Meta Platforms will begin training its AI models using public content shared by adults on Facebook and Instagram in the UK over the coming months, the company said, after it had paused the training in the region following a regulatory backlash. The company will use public posts including photos, captions and comments to train its generative artificial intelligence models, it said on Friday, adding that the training content will not include private messages or information from accounts of users under the age of 18.","u":"https://www.rappler.com/world/europe/meta-to-start-public-posts-facebook-instagram-uk-train-ai/","d":"2024-09-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-16","organization":"Meta Platforms","aiSystem":"Generative artificial intelligence models","affectedGroup":"Adults on Facebook and Instagram in the UK","action":"Begin training AI models using public content","consequence":"Appeasement of regulator demands, potential privacy concerns"}},{"i":"R1001","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Disabled woman banned from ai voice clone for making it say arse","s":"Motor Neuron Disease, or MND, is a condition that leads to the gradual loss of muscle control, including speech and mobility. South Floridian Joyce Esser suffers from a form of MND and has lost her voice. An AI tool developed by a company called ElevenLabs brought her old voice back—before taking it away again by […]. An AI tool developed by a company called ElevenLabs brought her old voice back—before taking it away again by banning the voice after she incidentally trained the voice to say the word “arse.” ElevenLabs used old recordings to digitally re-create her voice, allowing her to “speak” in her old voice by typing into a device either by hand or with her eyes and allowing the device to repeat the text aloud.","u":"https://www.vice.com/en/article/disabled-woman-banned-from-ai-voice-clone-for-making-it-say-arse/","d":"2025-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-20","organization":"ElevenLabs (AI company)","aiSystem":"AI voice cloning technology","affectedGroup":"Joyce Esser, a person with Motor Neuron Disease","action":"The AI tool recreated and then banned her voice due to training on inappropriate content","consequence":"Joyce Esser was unable to use her voice for communication"}},{"i":"R123","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai images are now being abused to fake evidence for vehicle insurance fraud","s":"AI-edited vehicle photos are becoming a new insurance fraud tool, with Admiral linking a rise in cases to manipulated crash images, duplicate filings, and fabricated claim materials that can raise costs across the system. AI-generated car damage is turning into a real insurance fraud issue, with Admiral linking a sharp rise in cases during 2025 to manipulated images and fabricated supporting materials. The problem is no longer limited to suspicious paperwork. Photos of damaged vehicles can now be edited to make a loss look worse or to help support a duplicate filing. According to a BBC report , one filing used an AI-edited number plate on a damaged Land Rover , while a similar image with a different plate appeared in a second case.","u":"https://www.digitaltrends.com/computing/ai-images-are-now-being-abused-to-fake-evidence-for-vehicle-insurance-fraud/","d":"2026-04-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"Admiral (insurance company)","aiSystem":"AI editing technology","affectedGroup":"Vehicle owners, insurance companies, regulators","action":"AI-edited vehicle photos to misrepresent damage severity or support duplicate claims","consequence":"Increased insurance costs, potential policy cancellations, and legal issues"}},{"i":"R136","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai boosted one of the worst forms of abusive content on the internet","s":"AI-generated abuse content surged in 2025, with watchdogs warning that the technology is making harmful material easier to create and spread. While the progress of AI has brought a wave of useful tools , it’s also amplifying some of the darkest corners of the internet. A new report from the IWF (Internet Watch Foundation) revealed a sharp increase in AI-generated child sexual abuse material (CSAM) online in 2025. It highlights how generative AI is being misused at scale. This isn’t just a small jump either; it’s proof of how this kind of content is being created and distributed. Why this news is alarming According to the IWF, over 8,000 AI-generated images and videos of abusive content were identified in 2025, which marked a 14% increase year on year.","u":"https://www.digitaltrends.com/computing/ai-boosted-one-of-the-worst-forms-of-abusive-content-on-the-internet/","d":"2026-03-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"IWF (Internet Watch Foundation)","aiSystem":"Generative AI","affectedGroup":"AI-generated child sexual abuse material (CSAM)","action":"AI-generated images and videos of abusive content were identified","consequence":"A 14% increase in AI-generated CSAM compared to the previous year"}},{"i":"R174","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Brits are now trauma dumping on ai government confirms","s":"A full third of UK citizens have turned to artificial intelligence for emotional support, companionship, or social interaction, according to a new report from the government’s AI Security Institute (AISI). The data shows that nearly one in 10 people are using systems like chatbots for emotional purposes on a weekly basis, with 4% engaging with […]. The data shows that nearly one in 10 people are using systems like chatbots for emotional purposes on a weekly basis, with 4% engaging with them every single day. Recommended Videos Because of this shift, the AISI is calling for more research, pointing to the tragic death of US teenager Adam Raine, who took his own life this year after discussing suicide with ChatGPT “People are increasingly turning to AI systems for emotional support or social interaction,” the AISI noted in its first Frontier AI Trends report.","u":"https://www.digitaltrends.com/computing/brits-are-now-trauma-dumping-on-ai-government-confirms/","d":"2025-12-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-20","organization":"Government’s AI Security Institute (AISI)","aiSystem":"AI chatbots","affectedGroup":"UK citizens","action":"Using AI chatbots for emotional support or social interaction","consequence":"Increased risk of mental health issues, including suicide"}},{"i":"R221","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Meta is training ai on your data users find opting out doesnt work","s":"Meta promised users that they can opt out of giving access to their social media content for AI training. Some are saying that the exit tool doesn’t work. Imagine a tech giant telling you that it wants your Instagram and Facebook posts to train its AI models. And that too, without any incentive. You could, however, opt out of it, as per the company. But as you proceed with the official tools to back out and prevent AI from gobbling your social content, they simply don’t work. That’s what users of Facebook and Instagram are now reporting. Nate Hake, publisher and founding chief of Travel Lemming, shared that he got an email from Meta about using his social media content for AI training.","u":"https://www.digitaltrends.com/computing/meta-is-training-ai-on-your-data-users-find-opting-out-doesnt-work/","d":"2025-04-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-20","organization":"Meta (formerly Facebook)","aiSystem":"AI models trained on social media data","affectedGroup":"Users of Facebook and Instagram","action":"Opting out of providing social media content for AI training","consequence":"Exit tools not working effectively"}},{"i":"R223","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.2  Allocative harm"],"t":"Uk developing tool to predict potential killers","s":"In echoes of Minority Report, the British government is working on a “murder prediction” tool aimed at identifying individuals who are most likely to become killers, the Guardian reported this week. The project — originally called the “homicide prediction project” but since renamed as “sharing data to improve risk assessment” — is being run by […]. The project — originally called the “homicide prediction project” but since renamed as “sharing data to improve risk assessment” — is being run by the U.K.’s Ministry of Justice and uses algorithms and personal data, including from the Probation Service, to make its calculations.","u":"https://www.digitaltrends.com/computing/uk-developing-tool-to-predict-potential-killers/","d":"2025-04-09","e":"Acute, Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-04-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-09","organization":"U.K. Ministry of Justice","aiSystem":"AI-based murder prediction tool","affectedGroup":"Individuals who are most likely to become killers","action":"Uses algorithms and personal data, including from the Probation Service, to make calculations","consequence":"Identifying individuals who are most likely to become killers"}},{"i":"R474","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Internet watch foundation ai child sexual abuse imagery report","s":"The tools for creating AI-enabled child sexual abuse imagery have also converged, allowing a user to make these images with minimal effort and limited technical expertise. MANILA, Philippines – The latest report from the Internet Watch Foundation (IWF), an English charity working to minimize the availability of child sexual abuse material (CSAM) hosted online, said that artificial intelligence-enabled CSAM increased in 2025 compared to the previous year. The 2026 CSAM report , titled Harm without limits: AI child sexual abuse material through the eyes of our analysts , found that in 2025, the IWF assessed 8,029 AI-generated images and videos as showing realistic child sexual abuse, with the imagery appearing on both regular online platforms and on the dark web.","u":"https://www.rappler.com/technology/internet-culture/internet-watch-foundation-ai-child-sexual-abuse-imagery-report/","d":"2026-03-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"Internet Watch Foundation (IWF)","aiSystem":"AI-enabled tools for creating child sexual abuse imagery","affectedGroup":"Child victims of child sexual abuse","action":"AI-generated images and videos were assessed as showing realistic child sexual abuse","consequence":"Increased availability of AI-generated child sexual abuse imagery on both regular online platforms and the dark web"}},{"i":"R543","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Getty images largely loses landmark uk lawsuit stability ai image generator","s":"Judge Joanna Smith rules Getty had succeeded ‘in part’ on trademark infringement in relation to Getty watermarks generated by users of Stable Diffusion, but says her findings were ‘both historic and extremely limited in scope’. LONDON, United Kingdom – Getty Images largely lost its London lawsuit against artificial intelligence company Stability AI over its image generator on Tuesday, November 4, prompting Getty and some lawyers to call for stronger protections for copyright owners in Britain. Seattle-based Getty, which produces editorial content and creative stock images and video, accused Stability AI of using its images to “train” its Stable Diffusion system, which generates images from text inputs.","u":"https://www.rappler.com/technology/getty-images-largely-loses-landmark-uk-lawsuit-stability-ai-image-generator/","d":"2025-11-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-04","organization":"Stability AI","aiSystem":"Stable Diffusion","affectedGroup":"Getty Images","action":"Stability AI used Getty Images' images to train its Stable Diffusion system","consequence":"Getty Images largely lost its lawsuit against Stability AI in the UK"}},{"i":"R635","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"United kingdom ai tools use make child abuse material crime","s":"The move comes as online criminals increasingly use AI to create child abuse material, with reports of such explicit images rising nearly five-fold in 2024, according to the Internet Watch Foundation. LONDON, United Kingdom – Britain will make it illegal to use artificial intelligence tools that create child sexual abuse images, it said on Saturday, February 1, becoming the first country in the world to introduce the new AI sexual abuse offences. Possessing, taking, making, showing or distributing explicit images of children is a crime in England and Wales. The new offenses target the use of AI tools to “nudeify” real-life images of children.","u":"https://www.rappler.com/technology/united-kingdom-ai-tools-use-make-child-abuse-material-crime/","d":"2025-02-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-01","organization":"Various online criminals","aiSystem":"Artificial Intelligence tools","affectedGroup":"Real-life images of children","action":"Using AI tools to 'nudeify' real-life images of children","consequence":"Making it illegal to possess, take, make, show, or distribute explicit images of children"}},{"i":"R954","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai cant summarize news study","s":"“AI assistants… routinely misrepresent news content no matter which language, territory, or AI platform is tested.” Damn. That’s the introduction by the BBC’s Media Centre for a study coordinated by the European Broadcasting Union (EBU) and led by the British Broadcasting Corporation (BBC), a UK-government-owned media organization. That’s bad, bad news for the 7 percent […]. Damn. That’s bad, bad news for the 7 percent of us who reportedly use AI to get our news, including 15 percent of people under 25 years old, according to the Reuters Institute’s Digital News Report 2025. The study looked at how accurately the most popular generative AIs, including OpenAI ChatGPT, Google Gemini, Microsoft Copilot, and Perplexity AI, could recite news stories to users.","u":"https://www.vice.com/en/article/ai-cant-summarize-news-study/","d":"2025-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-24","organization":"European Broadcasting Union (EBU), British Broadcasting Corporation (BBC), UK-government-owned media organization","aiSystem":"generative AIs including OpenAI ChatGPT, Google Gemini, Microsoft Copilot, and Perplexity AI","affectedGroup":"7 percent of the population, including 15 percent of people under 25 years old","action":"recite news stories to users","consequence":"misrepresent news content"}},{"i":"R962","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Holding absence an actual band calls out ai band that stole their style and surpassed them on spotify","s":"Cardiff-based rock band Holding Absence has just experienced the nightmare scenario—an AI generated band that listed them as an influence recently surpassed their streaming figures on Spotify. Can it really get any darker than this? “So, an AI ‘band’ who cite us as an influence (ie, it’s modelled off our music) have just overtaken us […]. “So, an AI ‘band’ who cite us as an influence (ie, it’s modelled off our music) have just overtaken us on Spotify, in only TWO months,” frontman Lucas Woodland wrote on Twitter on September 30. “It’s shocking, it’s disheartening, it’s insulting—most importantly—it’s a wake up call.”","u":"https://www.vice.com/en/article/holding-absence-an-actual-band-calls-out-ai-band-that-stole-their-style-and-surpassed-them-on-spotify/","d":"2025-10-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-30","organization":"An unspecified AI-generated band","aiSystem":"AI-generated band","affectedGroup":"Holding Absence (rock band)","action":"The AI-generated band cited Holding Absence as an influence and surpassed their streaming figures on Spotify","consequence":"Disheartening and insulting for Holding Absence, serving as a wake-up call"}},{"i":"R979","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Lonely kids are giving up on real friends for ai chatbots","s":"Silicon Valley is your kid’s new best friend. That is, if your kid is abnormally lonely and using an AI chatbot to fill the emotional void left by not having actual, real-life friends. A new report from UK nonprofit Internet Matters reveals that children and teens are turning to AI chatbots like ChatGPT, Snapchat’s MyAI, […]. A new report from UK nonprofit Internet Matters reveals that children and teens are turning to AI chatbots like ChatGPT, Snapchat’s MyAI, and Character.AI not just to answer questions, but to act as synthetic computer friends. According to the report, with the exceedingly clever title Me, Myself, and AI , 67 percent of kids aged 9 to 17 are chatting with AI regularly.","u":"https://www.vice.com/en/article/lonely-kids-are-giving-up-on-real-friends-for-ai-chatbots/","d":"2025-07-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-15","organization":"UK nonprofit Internet Matters","aiSystem":"AI chatbots (e.g., ChatGPT, MyAI, Character.AI)","affectedGroup":"Children and teens","action":"Chatting with AI chatbots","consequence":"Experiencing loneliness reduction"}},{"i":"R062","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Scammers are now cloning trusted news websites to steal your money","s":"Cybercriminals are cloning trusted news websites using AI-generated content to promote fake investment schemes, making it harder than ever to distinguish legitimate journalism from scams. Seeing a story on the website of a trusted news organisation is usually enough to lower your guard. Cybercriminals know that, and they’re increasingly exploiting the credibility of major publishers to steal money from unsuspecting readers. The latest example involves fake Guardian articles featuring billionaire Jim Ratcliffe. Still, the scam is part of a much larger campaign that’s also impersonating the BBC and other well-known media outlets.","u":"https://www.digitaltrends.com/computing/scammers-are-now-cloning-trusted-news-websites-to-steal-your-money/","d":"2026-07-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-13","organization":"Trusted news websites (e.g., The Guardian, BBC)","aiSystem":"AI-generated content","affectedGroup":"Unsuspecting readers","action":"Publishing fake articles","consequence":"Stealing money from readers"}},{"i":"R068","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai tools can quietly shift your opinions when they clean up your social media posts study finds","s":"A new study found AI tools consistently nudge social media posts toward one side of a debate, even when told to preserve the meaning. If you’ve asked an AI tool to help you write a social media post lately, you may have gotten more than a grammar fix. New research from the Oxford Internet Institute and the Hasso Plattner Institute found that AI models can push the tone of a post toward one side of a debate, even when told not to change its meaning. How a chatbot’s edits can shift the narrative The study , titled “AI-Mediated Communication Can Steer Collective Opinion,” had large language models from several providers rewrite human-written posts on divisive topics.","u":"https://www.digitaltrends.com/social-media/ai-tools-can-quietly-shift-your-opinions-when-they-clean-up-your-social-media-posts-study-finds/","d":"2026-07-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-06","organization":"Oxford Internet Institute and Hasso Plattner Institute","aiSystem":"Large Language Models (LLMs) from various providers","affectedGroup":"Social media users","action":"AI models edited social media posts to align with one side of a debate","consequence":"Shift in collective opinion towards one side of a debate"}},{"i":"R072","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"As ai turbocharges digital abuse uk agencies urge parents to limit who sees kids photos online","s":"The UK’s NCA and IWF are urging parents to tighten social media privacy settings as AI tools make it easier to turn ordinary images into abuse material. Parents who post pictures of their kids online are being told to rethink the habit. The UK’s National Crime Agency and the Internet Watch Foundation have issued new guidance urging families to lock down their social media accounts, warning that publicly shared photos are increasingly being pulled and altered by AI tools to create child sexual abuse material. The two organizations say most parents have no idea this is happening. Criminals no longer need to contact a child directly to generate such material.","u":"https://www.digitaltrends.com/computing/as-ai-turbocharges-digital-abuse-uk-agencies-urge-parents-to-limit-who-sees-kids-photos-online/","d":"2026-07-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-04","organization":"UK's National Crime Agency (NCA) and Internet Watch Foundation (IWF)","aiSystem":"AI tools","affectedGroup":"Parents who post pictures of their kids online","action":"AI tools pull and alter publicly shared photos","consequence":"Create child sexual abuse material"}},{"i":"R099","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai may have just won a literary prize i cant handle slop destroying my one lifelong love","s":"Three of five winning stories in the 2026 Commonwealth Short Story Prize have been flagged as AI-generated, and it’s a lot bigger deal than you might think. I had a hard time processing this news. As someone who has been deeply in love with stories since childhood and who grew up on the works of Arthur Conan Doyle, Terry Pratchett, J.R.R. Tolkien, and other such venerable authors, seeing an AI -written story win a prestigious writing award is hard to digest. If you are unaware, the winners for the Commonwealth Short Story Prize for 2026 were announced, and three of the five winning regional stories have been found to be entirely or partially written by AI.","u":"https://www.digitaltrends.com/computing/ai-may-have-just-won-a-literary-prize-i-cant-handle-slop-destroying-my-one-lifelong-love/","d":"2026-05-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-20","organization":"Commonwealth Short Story Prize organizers","aiSystem":"AI-generated text","affectedGroup":"Artists, writers, literature enthusiasts","action":"Three out of five winning stories were flagged as AI-generated","consequence":"Disruption of traditional literary values and impact on authorship credibility"}},{"i":"R112","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Oxford study says a chummy ai friend will lie and feed into your false beliefs","s":"Making AI feel more human could be creating a bigger problem than expected. A new study from the Oxford Internet Institute revealed that chatbots designed to be warm and friendly are more likely to mislead users and reinforce incorrect beliefs. The research found that AI becomes less reliable as it starts getting more agreeable. What […]. What happens to a “friendly” AI AI Chatbot AI Chatbot Researchers tested multiple AI models by training them to sound more empathetic and conversational. The result was a noticeable drop in accuracy. These “friendlier” versions made 10-30% more mistakes and were about 40% more likely to agree with false claims compared to their counterparts.","u":"https://www.digitaltrends.com/computing/oxford-study-says-a-chummy-ai-friend-will-lie-and-feed-into-your-false-beliefs/","d":"2026-04-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-30","organization":"Oxford Internet Institute","aiSystem":"AI Chatbot","affectedGroup":"Users of AI Chatbots","action":"AI Chatbots designed to be warm and friendly were trained to sound more empathetic and conversational.","consequence":"These ‘friendlier’ versions made 10-30% more mistakes and were about 40% more likely to agree with false claims."}},{"i":"R144","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Consumer body lists half a dozen reasons to think before you let an ai agent run your chores","s":"A new UK government report warns that AI agents handling your shopping and finances could steer you wrong, make costly errors, or lock you into worse deals if you aren’t careful. That AI agent offering to handle your shopping or hunt for better insurance deals sounds like a dream come true. But before you hand over the keys to your digital wallet, you might want to hear what the UK’s Competition and Markets Authority has to say about the potential pitfalls. The government published a report in March 2026 examining so-called “agentic AI,” systems that don’t just answer questions but actually take actions on your behalf.","u":"https://www.digitaltrends.com/computing/consumer-body-lists-half-a-dozen-reasons-to-think-before-you-let-an-ai-agent-run-your-chores/","d":"2026-03-16","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03","organization":"UK Competition and Markets Authority","aiSystem":"Agentic AI systems","affectedGroup":"Individuals using AI agents for financial and shopping tasks","action":"AI agents making decisions on behalf of users without proper oversight","consequence":"Steering users towards incorrect or harmful outcomes, leading to financial losses and unfavorable deals"}},{"i":"R150","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm","1.5  Human computer interaction harm"],"t":"Police find chatgpt link in rising reports of harmful satanic rituals","s":"UK experts say ChatGPT is fuelling a sustained rise in organised ritual abuse disclosures, with survivors using the tool as a gateway to support, prompting formal police training across forces. UK police have pinpointed an unexpected driver behind a rise in organized ritual abuse reports: ChatGPT Survivors are turning to the AI chatbot to process trauma, and experts say that’s leading more people to disclose crimes involving satanism, witchcraft, and spiritual abuse. Support groups report an ongoing rise in calls over the last 18 months, with many crediting the AI tool with prompting them to seek help. The National Association of People Abused in Childhood says people are contacting its support line and mentioning that ChatGPT referred them.","u":"https://www.digitaltrends.com/computing/police-find-chatgpt-link-in-rising-reports-of-harmful-satanic-rituals/","d":"2026-03-09","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"UK police","aiSystem":"ChatGPT","affectedGroup":"survivors of ritual abuse","action":"using ChatGPT to process trauma and disclose crimes","consequence":"a sustained rise in organized ritual abuse reports and increased police training"}},{"i":"R151","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chatgpt and gemini are nudging users towards illegal gambling says investigation","s":"An investigation has found that AI chatbots such as ChatGPT and Gemini can be prompted to recommend illegal offshore casinos, raising concerns about gambling addiction and weak safeguards. A new investigation suggests that popular AI chatbots, including ChatGPT and Gemini , may inadvertently steer users toward illegal gambling websites. The analysis, conducted by journalists at The Guardian and Investigate Europe, tested several widely used AI systems and found that many could be prompted to recommend unlicensed offshore casinos operating outside UK regulations. ilgmyzin / Unsplash The tests involved five AI tools from major tech companies, including OpenAI, Google, Microsoft, Meta, and xAI ( Grok ).","u":"https://www.digitaltrends.com/cool-tech/chatgpt-and-gemini-are-nudging-users-towards-illegal-gambling-says-investigation/","d":"2026-03-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"Various tech companies (OpenAI, Google, Microsoft, Meta, xAI)","aiSystem":"AI chatbots such as ChatGPT and Gemini","affectedGroup":"Users of AI chatbots","action":"AI chatbots were prompted to recommend illegal offshore casinos","consequence":"Potential gambling addiction and weak regulatory safeguards"}},{"i":"R430","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Jess asato suing xai stop grok generating sexualized images united kingdom","s":"Jess Asato of Britain’s governing Labour Party says Grok users created fake images of her, including a video of her ‘being chloroformed and prepared for a sexual assault’ after she publicly criticized Elon Musk and Grok. LONDON, United Kingdom – A British lawmaker suing Elon Musk’s xAI over fake sexualized images of her created by the Grok AI platform said on Tuesday, July 28, she was seeking a court order to prevent the chatbot being able to generate non-consensual sexualized images of her. Jess Asato, a member of Britain’s governing Labour Party, said last month that users created fake images of her, including a video of her “being chloroformed and prepared for a sexual assault” after she publicly criticized Musk and Grok.","u":"https://www.rappler.com/technology/jess-asato-suing-xai-stop-grok-generating-sexualized-images-united-kingdom/","d":"2026-07-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-28","organization":"Elon Musk's xAI","aiSystem":"Grok AI platform","affectedGroup":"Jess Asato, British politician","action":"Users of Grok AI created fake images of Jess Asato, including a video depicting her 'being chloroformed and prepared for a sexual assault' after she criticized Elon Musk.","consequence":"Potential non-consensual sexualized images of Jess Asato were generated and shared, causing distress and potential legal action."}},{"i":"R508","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"United kingdom investigates x grok deepfake concerns","s":"The British government says a new law making it an offense to create sexual deepfakes would come into force this week to tackle the images, which it calls ‘weapons of abuse’. LONDON, United Kingdom – Britain’s media regulator launched an investigation into Elon Musk’s X on Monday, January 12, over concerns its Grok AI chatbot was creating sexually intimate deepfake images in violation of its duty to protect people in the UK from illegal content. The British government said a new law making it an offense to create sexual deepfakes would come into force this week to tackle the images, which it called “weapons of abuse”.","u":"https://www.rappler.com/technology/social-media/united-kingdom-investigates-x-grok-deepfake-concerns/","d":"2026-01-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-12","organization":"Elon Musk's X (X)","aiSystem":"Grok AI chatbot","affectedGroup":"Individuals","action":"Created sexually intimate deepfake images","consequence":"Potential legal violations and misuse of deepfake technology"}},{"i":"R513","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Britain online safety act block unsolicited images","s":"Britain’s Online Safety Act aims to protect women and girls from ‘cyberflashing,’ with one of 3 teenage girls in the country receiving unsolicited sexual images. LONDON, UK – Technology companies in Britain will be required to block unsolicited sexual images under online safety rules taking effect on Thursday, as governments worldwide step up efforts to curb abuse and risks linked to artificial intelligence. Cyberflashing has been a criminal offense in England and Wales since January 2024, with perpetrators facing up to two years in prison. It has now become a priority offense under Britain’s Online Safety Act, which sets tough requirements on platforms such as Facebook, YouTube, TikTok and X, as well as dating apps and sites hosting pornography.","u":"https://www.rappler.com/technology/britain-online-safety-act-block-unsolicited-images/","d":"2026-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-08","organization":"Technology Companies (Facebook, YouTube, TikTok, X)","aiSystem":"Platforms and Dating Apps","affectedGroup":"Teenage Girls","action":"Block unsolicited sexual images","consequence":"Protection from cyberflashing"}},{"i":"R1275","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Analysts say it is challenging to track whether Palantir is sticking to the terms of its N…","s":"Analysts say it is challenging to track whether Palantir is sticking to the terms of its NHS contract. London, United Kingdom – Trust, once lost, is hard to claw back. For Palantir Technologies, a leading defence and intelligence software firm in the United States, the trust that the company established in the United Kingdom on a one-British-pound ($1.37) National Health Service (NHS) contract during the COVID-19 pandemic in March 2020 – which translated into a six-year relationship worth nearly 400 million pounds ($546m) – has recently eroded. This has been accelerated in part by Palantir’s own conduct. The company’s X account posted a 22-point manifesto recently that alarmed critics and prompted renewed questions about whether a company with such openly militaristic values is an appropriate steward of a health patient’s most sensitive data.","u":"https://www.aljazeera.com/news/2026/5/12/palantir","d":"2026-05-12","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-05-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-03","organization":"Palantir Technologies","aiSystem":"Palantir Technologies","affectedGroup":"health patients","action":"generated and shared sensitive data","consequence":"eroded trust, increased scrutiny, potential misuse of data"}},{"i":"R1285","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai models misrepresent news events nearly half the time study says","s":"According to the research, 45 percent of responses to questions about the news had at least one 'significant' issue. AI models such as ChatGPT routinely misrepresent news events, providing faulty responses to questions almost half the time, a study has found. The study, published on Wednesday by the European Broadcasting Union (EBU) and the BBC, assessed the accuracy of more than 2,700 responses given by OpenAI’s ChatGPT, Google’s Gemini, Microsoft’s Copilot, and Perplexity. Twenty-two public media outlets, representing 18 countries and 14 languages, posed a common set of questions to the AI assistants between late May and early June for the study.","u":"https://www.aljazeera.com/economy/2025/10/22/ai-models-misrepresent-news-events-nearly-half-the-time-study-says","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-22","organization":"European Broadcasting Union (EBU) and the BBC","aiSystem":"AI models such as ChatGPT, Google's Gemini, Microsoft's Copilot, and Perplexity","affectedGroup":"Public media outlets, representing 18 countries and 14 languages","action":"Providing faulty responses to questions","consequence":"Misrepresenting news events"}},{"i":"R1324","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"The darts star's image has been used legally on darts merchandise, snacks and fashion bran…","s":"The darts star's image has been used legally on darts merchandise, snacks and fashion brands. Luke Littler, the youngest darts world champion in history, has applied to the Intellectual Property Office to trademark his face. The move is intended to prevent his face being reproduced, including by generative AI, without permission. Littler has won two World Championship titles in a row and has had his image used legally on darts merchandise, as well as by multiple brands such as KP Nuts. The 19-year-old joins celebrities such as actor Matthew McConaughey who have filed to protect their likeness from AI misuse in recent months.","u":"https://www.bbc.com/news/articles/c5y7374x9n4o","d":"2026-03-20","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-20","organization":"Not specified in report","aiSystem":"Generative AI","affectedGroup":"Luke Littler","action":"Generative AI was used to reproduce Littler's face","consequence":"Littler's face was reproduced without permission"}},{"i":"R1329","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Deepfakes showing grim taxpayer-funded waterparks have gone viral and drawn some racist re…","s":"Deepfakes showing grim taxpayer-funded waterparks have gone viral and drawn some racist responses. An AI-generated video shows a crowd of young - mostly black - men, wearing balaclavas and padded jackets, slipping down a water slide into a dirty swimming pool with litter bobbing on the surface. The caption describes the scene as a taxpayer-funded water park in Croydon. It is one of a wave of deepfakes showing often absurd scenes of urban decline, and regularly purporting to be in the same south London neighbourhood. Dozens of copycat accounts have begun producing similar content and collectively they have racked up millions of views across TikTok and Instagram Reels.","u":"https://www.bbc.com/news/articles/c4g8r23yv71o","d":"2026-02-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-21","organization":"Not specified in report","aiSystem":"AI-generated deepfake technology","affectedGroup":"People viewing the deepfakes","action":"Produced and shared AI-generated deepfake videos","consequence":"Exposure to misleading content"}},{"i":"R1330","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Civil liberties campaigners are among those to raise concerns over the increase in live fa…","s":"Civil liberties campaigners are among those to raise concerns over the increase in live facial recognition vans. The home secretary has said she rejects suggestions that making live facial recognition available to all police forces in England and Wales contributes to a \"Big Brother\" society. Shabana Mahmood told the BBC she makes \"no apology\" for the policy and believes it would help detect criminals while allowing people to \"go about their daily business in safety\". The government announced plans to increase from 10 to 50 the number of live facial recognition vans available to be deployed as part of reforms to policing Human rights and privacy campaigners have raised concerns, describing the announcement as \"one of the most significant threats to civil liberties in the history of British policing\".","u":"https://www.bbc.com/news/articles/c5ydekxkd20o","d":"2026-01-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-27","organization":"Government","aiSystem":"Live facial recognition technology","affectedGroup":"General public","action":"Increase deployment of live facial recognition vans","consequence":"Exposure to surveillance, potential violation of privacy"}},{"i":"R1333","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Principal Graham Montgomery said it has been a \"difficult time\" for the pupils affected at…","s":"Principal Graham Montgomery said it has been a \"difficult time\" for the pupils affected at Royal School Armagh. The principal of a County Armagh school at the centre of controversy over AI-generated explicit images said those allegedly behind their creation have been identified. Graham Montgomery, headmaster of the Royal School Armagh, issued a letter to parents on Monday, in which he said the school believes to have identified \"all those of whom images had been manipulated and those allegedly responsible\". He said the actions are \"shocking and without excuse\", while the number of those targeted is in the \"single figures\".","u":"https://www.bbc.com/news/articles/cg4e3gz3y01o","d":"2026-01-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-19","organization":"Royal School Armagh","aiSystem":"AI-generated content","affectedGroup":"pupils","action":"AI-generated explicit images were manipulated and allegedly created","consequence":"Those allegedly responsible have been identified"}},{"i":"R1334","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"The incident has led some to call for more government regulation of artificial intelligenc…","s":"The incident has led some to call for more government regulation of artificial intelligence. A fake video of a city council mayor has prompted calls for more stringent rules around the use of AI videos in politics. The video at the centre of the row appeared to show mayor Ashley Bowkett saying he would not allow councillors to investigate the \"missing £8m this year\" and then laughing at the camera. It refers to Gloucester City Council, which is asking for a government bailout after years of multiple overspends , and prompted the call for new AI rules from a former mayor and the council's leader. The independent councillor who made it, Alastair Chambers, stands by the video because of a disagreement over when to have a debate about the city's finances, in December or January.","u":"https://www.bbc.com/news/articles/cgl8n7y7rd5o","d":"2026-01-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-19","organization":"Gloucester City Council","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"City council members, residents, and taxpayers","action":"Used AI-generated misleading content to manipulate public opinion","consequence":"Led to calls for stricter regulations on AI videos in politics"}},{"i":"R1340","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"The Artificial Intelligence Security Institute (AISI) says the tech is being used by one i…","s":"The Artificial Intelligence Security Institute (AISI) says the tech is being used by one in 25 people daily. One in three adults in the UK are using artificial intelligence (AI) for emotional support or social interaction, according to research published by a government body. And one in 25 people turned to the tech for support or conversation every day, the AI Security Institute (AISI) said in its first report The report is based on two years of testing the abilities of more than 30 unnamed advanced AIs - covering areas critical to security, including cyber skills, chemistry and biology. The government said AISI's work would support its future plans by helping companies fix problems \"before their AI systems are widely used\".","u":"https://www.bbc.com/news/articles/cd6xl3ql3v0o","d":"2025-12-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-18","organization":"Artificial Intelligence Security Institute (AISI)","aiSystem":"advanced AI systems","affectedGroup":"one in 25 people","action":"turned to the tech for support or conversation every day","consequence":"privacy invasion"}},{"i":"R1341","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"The new voice was built using recordings from a ScotRail employee following an ethics comp…","s":"The new voice was built using recordings from a ScotRail employee following an ethics complaint. ScotRail has launched a new AI onboard announcer using the voice of an employee following a row over a previous version. Voiceover artist Gayanne Potter had complained that her voice was used without permission to help train the artificial intelligence announcer Iona. She claims she was told her work for Swedish technology firm ReadSpeaker would be used for accessibility and e-learning software rather than wider commercial purposes. Iona has now been replaced by another AI announcer, based on the voice of Paisley-based ScotRail employee Vannessa Sloan.","u":"https://www.bbc.com/news/articles/cly33vvrke0o","d":"2025-12-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-12","organization":"ScotRail","aiSystem":"Artificial intelligence announcer","affectedGroup":"Gayanne Potter","action":"Her voice was used to train the AI announcer","consequence":"She claims her work was misused for wider commercial purposes"}},{"i":"R1345","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Byron Long, 66, was buying cat treats in B&M when his face was added to its theft warning …","s":"Byron Long, 66, was buying cat treats in B&M when his face was added to its theft warning system. A man falsely accused of shoplifting after being added to a facial recognition watchlist has warned it \"could happen to anyone\". Byron Long, 66, was told to leave a B&M store at Cardiff Bay Retail Park and accused of stealing £75 worth of goods on a previous visit - until a review of CCTV footage showed he had paid for his shopping and not stolen anything. B&M has apologised to Mr Long and offered him a £25 voucher, which he has rejected, while the Big Brother Watch campaign group has made a formal complaint to the Information Commissioner's Office on his behalf.","u":"https://www.bbc.com/news/articles/c3vn4p1lwqno","d":"2025-11-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-20","organization":"B&M (British Magazines)","aiSystem":"Facial recognition technology","affectedGroup":"Byron Long, 66","action":"Facial recognition technology was used to add Mr Long to a theft watchlist","consequence":"Mr Long was falsely accused of theft and asked to leave the store"}},{"i":"R1349","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"The volume of tap water used by Scotland's data centres has quadrupled since 2021, figures…","s":"The volume of tap water used by Scotland's data centres has quadrupled since 2021, figures show. Data centres powering artificial intelligence (AI) in Scotland are using enough tap water to fill 27 million half-litre bottles a year, according to data obtained by BBC News. AI systems such as the large language models (LLMs) that power OpenAI's ChatGPT and Google's Gemini require warehouses full of specialist computers. The equipment is power-hungry, consuming large amounts of energy, but they also use tonnes of water in their cooling systems to stop the servers overheating. Freedom of Information data shows the volume of tap water used by Scotland's data centres has quadrupled since 2021.","u":"https://www.bbc.com/news/articles/c77zxx43x4vo","d":"2025-10-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-15","organization":"Scotland's data centers","aiSystem":"Large language models (LLMs) powering AI systems like ChatGPT and Gemini","affectedGroup":"Environment","action":"Used tap water in cooling systems","consequence":"Increased water consumption"}},{"i":"R1354","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"The victim of one of the first deepfake prosecutions in Scotland says the law needs to cha…","s":"The victim of one of the first deepfake prosecutions in Scotland says the law needs to change to protect victims. The victim of one of the first deepfake image prosecutions in Scotland says she has been left feeling \"humiliated and betrayed\" after the man who doctored her likeness was given a fine. Callum Brooks, 25, from Glasgow, became one of the first to be convicted of using artificial intelligence (AI) technology to create and share deepfake nude images after admitting the offence in court last month He was fined £335. Sophie (not her real name) told BBC Scotland News that crimes using AI should have their own legislation and that penalties should be higher.","u":"https://www.bbc.com/news/articles/c4g7kw8ly4ko","d":"2025-09-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-18","organization":"Not specified in report","aiSystem":"AI-generated deepfake technology","affectedGroup":"Sophie (a victim of deepfake image)","action":"Deepfake nude images were created and shared using AI technology","consequence":"Left feeling humiliated and betrayed"}},{"i":"R1360","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"The number of data centres is set to jump by a fifth in the coming years, figures seen by …","s":"The number of data centres is set to jump by a fifth in the coming years, figures seen by the BBC suggest. The number of data centres in the UK is set to increase by almost a fifth, according to figures shared with BBC News. Data centres are giant warehouses full of powerful computers used to run digital services from movie streaming to online banking - there are currently an estimated 477 of them in the UK. Construction researchers Barbour ABI have analysed planning documents and say that number is set to jump by almost 100, as the growth in artificial intelligence (AI) increases the need for processing power. The majority are due to be built in the next five years.","u":"https://www.bbc.com/news/articles/clyr9nx0jrzo","d":"2025-08-15","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-15","organization":"Construction researchers Barbour ABI","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"People living near planned data centers","action":"Planning documents indicate increased construction of data centers","consequence":"Potential privacy intrusion due to higher processing power needs"}},{"i":"R1364","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"A civil liberties group says the technology is \"more akin to authoritarian countries such …","s":"A civil liberties group says the technology is \"more akin to authoritarian countries such as China\". Live facial recognition technology (LFR) is helping the Met stay ahead of criminals at a time \"where money is tight,\" according to the force's director of intelligence. Lindsey Chiswick, the lead for LFR at the Met and nationally, said more than 1,000 arrests had been made since January 2024 using the tool, including alleged paedophiles, rapists and violent robbers. She said it \"would be madness\" if officers did not keep pace with available technology in order to protect the public. Privacy campaigners say there's been an \"alarming escalation\" in police use of LFR, which maps a person's unique facial features, and matches them against faces on watch lists.","u":"https://www.bbc.com/news/articles/cdx5528xrzko","d":"2025-07-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-01","organization":"Metropolitan Police Service","aiSystem":"Live facial recognition technology (LFR)","affectedGroup":"Public","action":"Uses live facial recognition technology to map and match unique facial features against watch lists","consequence":"Raises privacy concerns and escalates police use of LFR"}},{"i":"R1367","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"The bitter row over how to protect artists in the artificial intelligence age returns to t…","s":"The bitter row over how to protect artists in the artificial intelligence age returns to the Lords. The House of Lords has dealt a fourth defeat to the government over its plans to allow tech companies to use copyrighted material to train their models. The Lords, who are looking for more protections for artists from AI, rejected the latest amendment to the Data (Use and Access) Bill on Monday. Peers backed calls for greater transparency after musicians such as Sir Elton John warned of the threat to creative industries. It will now be returned to the Commons where it could be discussed as soon as Tuesday - though that has not been confirmed.","u":"https://www.bbc.com/news/articles/clyrgv2n190o","d":"2025-06-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-02","organization":"Government","aiSystem":"Artificial intelligence models trained on copyrighted material","affectedGroup":"Artists, particularly musicians like Sir Elton John","action":"Tech companies allowed to use copyrighted material to train AI models","consequence":"Threat to creative industries, loss of creative control, privacy invasion"}},{"i":"R1370","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"A judge says Brandon Tyler shows \"the worst kind of toxic masculinity\" in his offending","s":"A judge says Brandon Tyler shows \"the worst kind of toxic masculinity\" in his offending. An online pervert who used artificial intelligence (AI) to create deepfake pornography of women he knew has been jailed for five years. Brandon Tyler, 26, manipulated images from social media pages and posted them in a forum that glorified \"rape culture\", Chelmsford Crown Court heard. The bar worker, from Braintree, Essex, was described by the judge as \"showing the worst kind of toxic masculinity\". He admitted 18 counts of causing harassment without violence and 15 counts of sharing an intimate photo or film of a person for sexual gratification.","u":"https://www.bbc.com/news/articles/cewgxd5yewjo","d":"2025-04-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-04","organization":"Not specified in report","aiSystem":"Deepfake technology","affectedGroup":"Women","action":"Created and shared deepfake pornography","consequence":"Received prison sentence"}},{"i":"R1371","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Louise Littlejohn said she was shocked and then laughed when she received the error strewn…","s":"Louise Littlejohn said she was shocked and then laughed when she received the error strewn voicemail transcription. A woman from Dunfermline has spoken of her shock after an Apple voice-to-text service mistakenly inserted a reference to sex - and an apparent insult - into a message left by a garage. Louise Littlejohn, 66, received a voicemail message on Wednesday from a Lookers Land Rover garage in Motherwell inviting her to an event. An artificial intelligence (AI) powered service offered by Apple turned it into a text message which - to her surprise - asked if she been \"able to have sex\" before calling her a \"piece of ****\".","u":"https://www.bbc.com/news/articles/c0l1kpz3w32o","d":"2025-03-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-07","organization":"Apple","aiSystem":"Apple's AI-powered voice-to-text service","affectedGroup":"Louise Littlejohn","action":"An AI-powered service converted a voicemail into a text message","consequence":"The text message contained a misleading question and an insulting remark"}},{"i":"R1372","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Mabel works for a firm that trawls the internet looking to remove the worst indecent image…","s":"Mabel works for a firm that trawls the internet looking to remove the worst indecent images. At home she is a loving grandmother who enjoys spending time with her grandkids but at work Mabel has to watch the internet's most \"abhorrent\" child sex abuse. She works for one of the few organisations licensed to actively search the internet for indecent content to help police and tech firms take the images down. The Internet Watch Foundation (IWF) helped remove a record almost 300,000 web pages last year, including more artificial intelligence (AI) generated images than ever as the number of these types of images have increased almost fivefold.","u":"https://www.bbc.com/news/articles/ckg843y8y7no","d":"2025-03-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-06","organization":"Internet Watch Foundation (IWF)","aiSystem":"Internet Watch Foundation (IWF) automated content moderation system","affectedGroup":"worst indecent image creators","action":"used AI to generate and recommend content for removal","consequence":"exposed to misleading information"}},{"i":"R1379","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Data centres can use vast quantities of water to cool them - but it's not clear where it w…","s":"Data centres can use vast quantities of water to cool them - but it's not clear where it will come from. Sir Keir Starmer's plan to make the UK a \"world leader\" in Artificial Intelligence (AI) could put already stretched supplies of drinking water under strain, industry sources have told the BBC. The giant data centres needed to power AI can require large quantities of water to prevent them from overheating. The tech industry says it is developing more efficient cooling systems that use less water. But the department for science, innovation and technology said in a statement it recognised the plants \"face sustainability challenges\".","u":"https://www.bbc.com/news/articles/ce85wx9jjndo","d":"2025-02-07","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-07","organization":"Department for Science, Innovation and Technology","aiSystem":"Data centers powered by AI","affectedGroup":"Already stretched water supplies","action":"Powering data centers with AI","consequence":"Undermining already stretched water supplies"}},{"i":"R1385","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Apple's new artificial intelligence features falsely made it seem the BBC reported Luigi M…","s":"Apple's new artificial intelligence features falsely made it seem the BBC reported Luigi Mangione had shot himself. The BBC has complained to Apple after the tech giant's new iPhone feature generated a false headline about a high-profile murder in the United States. Apple Intelligence, launched in the UK earlier this week , uses artificial intelligence (AI) to summarise and group together notifications. This week, the AI-powered summary falsely made it appear BBC News had published an article claiming Luigi Mangione, the man arrested following the murder of healthcare insurance CEO Brian Thompson in New York, had shot himself.","u":"https://www.bbc.com/news/articles/cd0elzk24dno","d":"2024-12-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-13","organization":"Apple","aiSystem":"Apple Intelligence","affectedGroup":"BBC News","action":"generated a false headline","consequence":"falsely made it appear BBC News had published an article"}},{"i":"R1387","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"The BBC's You And Yours programme used AI to clone a reporter's voice to test bank securit…","s":"The BBC's You And Yours programme used AI to clone a reporter's voice to test bank security measures. Artificial intelligence can now clone human voices so well they that they are almost indistinguishable from the real thing. But how would it fare against the voice recognition tech that is supposed to protect people's bank accounts? As part of the BBC's Scam Safe Week, I have been investigating the power of voice cloning. The consumer champion Martin Lewis is among the celebrities whose voice has been targeted by scammers. And I spoke to the actor James Nesbitt, who said he was \"horrified\" at how realistic a cloned version of his voice was.","u":"https://www.bbc.com/news/articles/c1lg3ded6j9o","d":"2024-11-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-28","organization":"BBC's You And Yours programme","aiSystem":"AI-powered voice cloning technology","affectedGroup":"Bank account holders, voice recognition systems","action":"Cloned a reporter's voice to test bank security measures","consequence":"Voice recognition systems could be fooled into accepting fake identities"}},{"i":"R1400","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"More than 600 Scottish students have been accused of misusing AI during part of their stud…","s":"More than 600 Scottish students have been accused of misusing AI during part of their studies, according to a BBC FOI. More than 600 Scottish students were accused of misusing AI during part of their studies last year - a rise of 121% on 2023 figures. According to a freedom of information request by BBC Scotland, less than 10 students were kicked off their courses at both Robert Gordon and Glasgow universities in the last year - the first time AI-linked expulsions have been recorded at any Scottish university. So when does turning to the internet to help find the answer to a question cross the line into cheating?","u":"https://www.bbc.com/news/articles/ckg88kk1n8jo","d":"2024-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Robert Gordon University and Glasgow University","aiSystem":"AI search tools","affectedGroup":"Scottish students","action":"Using AI search tools to find answers to questions","consequence":"Accusations of misusing AI, potential expulsion"}},{"i":"R1407","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Uk politics 67518511","s":"A senior Tory MP leads calls for more government action to prevent AI sabotaging British democracy. Artificial Intelligence (AI) has already been used to disrupt elections around the world - and there are fears among senior politicians and the security services that the UK will be next. Former Justice Secretary Sir Robert Buckland is urging the government to do more to tackle what he sees as a \"clear and present danger\" to UK democracy. The Conservative MP, who now chairs the Northern Ireland select committee, is particularly concerned about the rise of deepfakes - realistic audio and video clips of politicians appearing to say things they did not say.","u":"https://www.bbc.com/news/uk-politics-67518511","d":"2023-12-21","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-12-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-21","organization":"Government and security services of the United Kingdom","aiSystem":"Deepfake technology","affectedGroup":"Politicians and political discourse","action":"Used realistic audio and video clips of politicians to manipulate their statements","consequence":"Disruption of political trust and integrity, potential for election interference"}},{"i":"R1409","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"A cutting-edge tool from Open AI appears to be poorly moderated, allowing it to be abused …","s":"A cutting-edge tool from Open AI appears to be poorly moderated, allowing it to be abused by cyber-criminals. A ChatGPT feature allowing users to easily build their own artificial-intelligence assistants can be used to create tools for cyber-crime, a BBC News investigation has revealed. OpenAI launched it last month, so users could build customised versions of ChatGPT \"for almost anything\". Now, BBC News has used it to create a generative pre-trained transformer that crafts convincing emails, texts and social-media posts for scams and hacks. It follows warnings about AI tools. BBC News signed up for the paid version of ChatGPT, at £20 a month, created a private bespoke AI bot called Crafty Emails and told it to write text using \"techniques to make people click on links or and download things sent to them\".","u":"https://www.bbc.com/news/technology-67614065","d":"2023-12-07","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-12-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-07","organization":"BBC News","aiSystem":"Generative pre-trained transformer created using ChatGPT features","affectedGroup":"Potential victims of scams and hacks","action":"Created convincing emails, texts, and social media posts using AI to manipulate users","consequence":"Exposure to misleading content leading to potential financial loss or identity theft"}},{"i":"R1410","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk wales 67360696","s":"Facial recognition was also used to search for terrorists, a police and crime commissioner says. Facial recognition was used on crowds attending a Beyoncé concert in Cardiff to scan for paedophiles and terrorists. South Wales Police and Crime Commissioner Alun Michael said searching for potential terrorists at such events had become normal since the 2017 Manchester Arena bombing. He said paedophiles were also targeted as \"there would be very large numbers of young girls attending that concert\". Mr Michael described using such cameras as \"entirely sensible\". Appearing before MPs on the Welsh Affairs Committee, Mr Michael defended the use of the artificial intelligence (AI) technology outside the concert.","u":"https://www.bbc.com/news/uk-wales-67360696","d":"2023-11-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-09","organization":"South Wales Police and Crime Commissioner Alun Michael","aiSystem":"Facial recognition technology","affectedGroup":"Attendees of a Beyoncé concert","action":"Used facial recognition to search for potential terrorists and paedophiles","consequence":"Exposure to surveillance and tracking"}},{"i":"R1418","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Union group claims using artificial intelligence to hire and fire staff could lead to grea…","s":"Union group claims using artificial intelligence to hire and fire staff could lead to greater discrimination. The TUC is calling for stronger rules to protect workers from decisions made by artificial intelligence systems. AI-powered technologies are now making \"high-risk, life changing\" decisions about workers' lives including line-managing, hiring and firing staff\", said the body which represents unions. But a new law will \"dilute\" existing protections, it said. The government said the TUC's assessment was \"wrong\" and has said safeguards will remain in place. A spokesperson said it was committed to improving and upholding workers' rights: \"AI is set to drive growth and create new highly-paid jobs throughout the UK, while allowing us to carry out our existing jobs more efficiently and safely.","u":"https://www.bbc.com/news/technology-65301630","d":"2023-03-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-18","organization":"TUC (Trade Union Congress)","aiSystem":"AI-powered technologies","affectedGroup":"workers","action":"making decisions about hiring and firing staff","consequence":"greater discrimination"}},{"i":"R1420","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Getty Images, one of the worlds biggest picture agencies, is taking action against Stabili…","s":"Getty Images, one of the worlds biggest picture agencies, is taking action against Stability AI. Getty Images is taking legal action against the makers of an artificial-intelligence image-creation tool. The agency, which sells the rights to use photographers' and illustrators' images, said Stability AI's Stable Diffusion system had infringed these. AI image generators \"learn\" to create images from simple text instructions by analysing human-made pictures, including images found online. Many artists and photographers say they use their work without permission. Some artists find image generators a valuable way to express themselves creatively - but many others worry they can convincingly imitate their style and use it to produce images in seconds.","u":"https://www.bbc.com/news/technology-64285227","d":"2023-01-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-01-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-01-19","organization":"Stability AI","aiSystem":"Stability AI's Stable Diffusion system","affectedGroup":"Artists and photographers","action":"AI image generators created images from text instructions","consequence":"Artists and photographers' works were used without permission"}},{"i":"R1438","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk watchdog warns of legal risks as london police deploy lfr at protest","s":"William Webster warns that deploying live facial recognition could bring legal issues against the police for infringing on fundamental rights. London’s Metropolitan Police will deploy live facial recognition (LFR) technology at a protest for the first time this weekend, prompting warnings from the UK’s biometrics and surveillance watchdog that police could face legal action over misidentifications and infringements on fundamental rights. On Wednesday, the Metropolitan Police announced that it would deploy LFR technology at the Unite the Kingdom march on Saturday, organized by far-right, anti-Islam activist Tommy Robinson.","u":"https://www.biometricupdate.com/202605/uk-watchdog-warns-of-legal-risks-as-london-police-deploy-lfr-at-protest","d":"2026-05-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-15","organization":"London’s Metropolitan Police","aiSystem":"Live facial recognition (LFR) technology","affectedGroup":"People who might be misidentified","action":"Deploying live facial recognition technology at a protest","consequence":"Potential legal action due to misidentifications and infringement of fundamental rights"}},{"i":"R1447","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"London testing facial recognition app for police as another false match surfaces","s":"London Mayor Sadiq Khan said that the OIFR system, powered by NEC Neoface software, will be piloted by 100 Metropolitan Police officers for six months. London police will soon start testing “operator-initiated facial recognition” (OIFR), a mobile app that allows officers to photograph a person and check their identity. At the same time, more cases of misidentification by police facial recognition systems are emerging in the UK. On Thursday, London Mayor Sadiq Khan shared that the OIFR system, powered by NEC Neoface software, will be piloted by 100 Metropolitan Police officers for six months. The mobile biometric matching technology will be used during police stops.","u":"https://www.biometricupdate.com/202602/london-testing-facial-recognition-app-for-police-as-another-false-match-surfaces","d":"2026-02-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-27","organization":"Metropolitan Police","aiSystem":"Operator-initiated facial recognition (OIFR) system powered by NEC Neoface software","affectedGroup":"People photographed by police officers","action":"Officers photographing and checking identities of individuals","consequence":"Misidentification and potential privacy breaches"}},{"i":"R1462","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Report claims uk evisa system uses migrants as digital id testing ground","s":"The report comes from researchers at the University of Warwick and University of Leicester, working with Migrant Voice and the Open Rights Group. A new report raises alarm over the UK’s mandatory digital immigration status system, claiming that migrants may have been used as a testing ground for the government’s wider digital ID ambitions. The “ Exclusion by Design: Digital Identification and the Hostile Environment for Migrants ” report comes from researchers at the University of Warwick and University of Leicester, working with Migrant Voice and the Open Rights Group It examines the rollout of the Home Office’s eVisa platform, which from June 2025 requires nearly all migrants entering or residing in the UK to prove their legal status exclusively through digital means.","u":"https://www.biometricupdate.com/202512/report-claims-uk-evisa-system-uses-migrants-as-digital-id-testing-ground","d":"2025-12-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06","organization":"Home Office","aiSystem":"eVisa platform","affectedGroup":"migrants","action":"require migrants to prove legal status through digital means","consequence":"exposure to privacy risks"}},{"i":"R1473","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Rights groups concerned over uks plan to use biometric age estimation on migrants","s":"Rights groups are expressing concerns about the UK's plans to introduce facial age estimation for vetting underage migrants arriving in the country. Rights groups and social work experts are expressing concerns about the UK’s plans to introduce biometric facial age estimation for vetting underage migrants arriving in the country. Using “flawed” AI tools could prove dehumanizing and may not provide accurate age estimations, organizations such as Human Rights Watch and Freedom from Torture argue. The result could be placing children in adult asylum hotels without safeguards or adequate support. “Assessing the ages of migrants is a complex process which should not be open to shortcuts,” Luke Geoghegan, head of policy and research at the British Association of Social Workers, told Context.","u":"https://www.biometricupdate.com/202510/rights-groups-concerned-over-uks-plan-to-use-biometric-age-estimation-on-migrants","d":"2025-10-20","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-20","organization":"UK authorities","aiSystem":"Facial age estimation technology","affectedGroup":"Underage migrants","action":"Using flawed AI tools to assess ages","consequence":"Placing children in adult asylum hotels without safeguards or adequate support"}},{"i":"R1475","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Uk police struggle to contain data breaches","s":"Over the past three years, UK police forces including Police Scotland, North Wales Police have experienced over 13,000 data breach incidents. Although many UK police forces are in the process of introducing facial recognition into their work, data breaches remain an issue that is capturing the attention of legal organizations. Last week, the North Wales Police was found to have reported 19 data breaches over the past six years. The compromised information included names, addresses, date of birth, contact details, medical and financial information, as well as breaches related to GDPR compliance. The largest number of breaches, eight in total, was reported in 2024, while an additional seven have already occurred in 2025.","u":"https://www.biometricupdate.com/202510/uk-police-struggle-to-contain-data-breaches","d":"2025-10-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-20","organization":"UK police forces, including Police Scotland and North Wales Police","aiSystem":"Facial recognition technology","affectedGroup":"Individuals whose data was breached","action":"Data breaches involving sensitive personal information","consequence":"Privacy risks and potential misuse of personal data"}},{"i":"R1500","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Unlawful use of facial recognition by police erodes public trust in biometrics","s":"The NYPD arrested a protestor with the help of Clearview AI’s facial recognition technology (FRT), skirting a policy that puts strict limits on its use. The New York Police Department arrested a protestor in New York City with the help of Clearview AI ’s facial recognition technology (FRT), skirting a policy that puts strict limits on its use. Instead of running the search itself, says a report from The City, the NYPD outsourced a Clearview search through a fire marshal at the city’s fire department, then used the results to identify a pro-Palestinian protester at Columbia University accused of throwing a rock at a pro-Israeli protester during an April protest.","u":"https://www.biometricupdate.com/202507/unlawful-use-of-facial-recognition-by-police-erodes-public-trust-in-biometrics","d":"2025-07-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04","organization":"New York Police Department (NYPD)","aiSystem":"Clearview AI's facial recognition technology (FRT)","affectedGroup":"Pro-Palestinian protester at Columbia University","action":"Used facial recognition to identify a protester","consequence":"Arrested a protester"}},{"i":"R1511","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Asda supermarket chain faces legal complaint over facial recognition","s":"The UK retailer is facing a legal complaint over its use of live facial recognition video surveillance in its supermarkets. Asda is facing a legal complaint over its use of live facial recognition (LFR) cameras in its supermarkets. The legal filing comes from privacy rights group Big Brother Watch, which argues that Asda’s use of LFR cameras is “unlawful.” Filed with the Information Commissioner, the legal complaint claims Asda is “infringing the data rights” of shoppers and exhorts the end of the use of the biometric technology by the supermarket chain. The biometric surveillance technology was acquired from UK start-up FaiceTech , with Asda installing the cameras and LFR in five shops in the Greater Manchester area as part of a trial.","u":"https://www.biometricupdate.com/202505/asda-supermarket-chain-faces-legal-complaint-over-facial-recognition","d":"2025-05-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-22","organization":"Asda (UK retailer)","aiSystem":"live facial recognition (LFR) cameras","affectedGroup":"shoppers","action":"use of live facial recognition cameras in supermarkets","consequence":"infringement of data rights, potential unlawful use"}},{"i":"R1520","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"London to introduce permanent live facial recognition cameras","s":"However, privacy groups such as Big Brother Watch have condemned the move and called for legislative safeguards on facial recognition. London police have announced their plans to install the UK’s first permanent live facial recognition cameras, catching potential criminals by matching their faces with a pre-determined database. The cameras will be set up in Croydon which has become one of the most targeted areas for facial recognition deployments in the city, leading to the arrest of approximately 200 people by November last year. The Metropolitan Police also said it could extend the surveillance across the capital.","u":"https://www.biometricupdate.com/202503/london-to-introduce-permanent-live-facial-recognition-cameras","d":"2025-03-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-25","organization":"London police","aiSystem":"Facial recognition technology","affectedGroup":"People in Croydon","action":"Install permanent live facial recognition cameras","consequence":"Potential criminals are caught by matching faces with a pre-determined database"}},{"i":"R1524","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk revisits proposal to make a vast police database from driving licenses","s":"The plan was introduced by the previous Conservative government in a 2023 criminal justice bill, and has come under fresh criticism. The UK government is advancing a Crime and Policing Bill that could have a significant impact on British society as it seeks to introduce new laws and policing powers. The new crime bill , introduced by Home Secretary Yvette Cooper, is currently in its second reading, and has come under fire for its potential expansion of facial recognition powers. The bill is seen as the biggest legislative update to policing in the UK in decades and is designed to tackle anti-social crimes and street crimes.","u":"https://www.biometricupdate.com/202502/uk-revisits-proposal-to-make-a-vast-police-database-from-driving-licenses","d":"2025-02-27","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-02-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-27","organization":"UK government","aiSystem":"Facial recognition technology","affectedGroup":"People","action":"Introduce new laws and facial recognition powers","consequence":"Potential expansion of surveillance capabilities"}},{"i":"R1544","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Calls grow for investigation into police scotlands live facial recognition tactics","s":"Critics are warning the use of LFR technology could fundamentally alter the relationship between law enforcement and the public. In light of growing scrutiny over the deployment of live facial recognition technology , Police Scotland is facing renewed calls for an investigation into its practices, which critics describe as “Orwellian.” The concerns stem from recent revelations about the extent to which the police are using this controversial technology, with critics warning that it could fundamentally alter the relationship between law enforcement and the public. A report from the Scottish Daily Express highlights that, despite assurances of careful use, the reality of Police Scotland’s facial recognition capabilities raises alarms among civil liberties advocates.","u":"https://www.biometricupdate.com/202410/calls-grow-for-investigation-into-police-scotlands-live-facial-recognition-tactics","d":"2024-10-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-08","organization":"Police Scotland","aiSystem":"Facial recognition technology","affectedGroup":"Public","action":"Used facial recognition to identify people","consequence":"Fundamentally altered relationship between law enforcement and the public"}},{"i":"R1547","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Civil society warns europes digital borders making life harder for migrants","s":"Poor planning, technical issues and concerns over human rights and data protection are plaguing the rollout of the UK’s upcoming biometric eVisas. The UK government plans to replace physical immigration documents, including Biometric Residence Permits (BRP) and passports with a digital-only document. Millions of migrants in the UK are expected to switch to eVisas by the end of 2024. The transition, however, could leave many immigrants at risk, says UK-based digital rights organization Open Rights Group (ORG). The eVisa will be used for immigration purposes but also for current immigrants to prove their right to work, sign housing contracts and access banking services.","u":"https://www.biometricupdate.com/202409/civil-society-warns-europes-digital-borders-making-life-harder-for-migrants","d":"2024-09-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-23","organization":"UK government","aiSystem":"Biometric eVisas","affectedGroup":"Millions of migrants in the UK","action":"Switching to digital-only eVisas","consequence":"Leaving many immigrants at risk of privacy infringement and data misuse"}},{"i":"R1554","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Rights groups push back on uk police use of facial recognition amid far right riots","s":"After the UK government announced more deployments of facial recognition, rights groups have called on Prime Minister Keir Starmer to reverse the decision. After the UK government announced more deployments of facial recognition to curb far-right riots, rights groups have called on Prime Minister Keir Starmer to reverse the decision, calling it a “chilling precedent” that “threatens the democratic rights” of the communities he is seeking to protect. On Friday, Amnesty International, Access Now, Statewatch, Privacy International, Big Brother Watch and 22 other groups sent a letter to Starmer requesting a meeting. “We urge you to rethink your plans to expand the use of facial recognition surveillance in the UK and would ask that you meet with us, as you have with police chiefs, to discuss the rights and equalities impacts of this AI mass surveillance,” the letter says.","u":"https://www.biometricupdate.com/202408/rights-groups-push-back-on-uk-police-use-of-facial-recognition-amid-far-right-riots","d":"2024-08-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-15","organization":"UK government","aiSystem":"Facial recognition technology","affectedGroup":"Communities targeted by far-right riots","action":"Expanded deployment of facial recognition surveillance","consequence":"Threat to democratic rights and equalities"}},{"i":"R1561","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Southampton extends use of reveal live facial recognition bodycams by bouncers","s":"This system helps identify offenders excluded from Southampton’s evening and night time economy venues via the Red Card scheme. Southampton Business Crime Partnership (SBCP), managed by GO! Southampton, has received additional funding for live facial recognition technology on body-worn cameras from Reveal An extra £2,243 will extend the facial recognition scheme following a three-month trial across seven venues. The body-worn cameras with facial recognition were first deployed for a trial launched in 2023 by the Business Improvement District (BID) in collaboration with Synergy Security and local businesses. The scheme employs Reveal’s digital evidence management system, DEMS 360, which is used by approximately 70 percent of UK police forces.","u":"https://www.biometricupdate.com/202407/southampton-extends-use-of-reveal-live-facial-recognition-bodycams-by-bouncers","d":"2024-07-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-22","organization":"Southampton Business Crime Partnership (SBCP)","aiSystem":"Facial recognition technology","affectedGroup":"Offenders excluded from Southampton’s evening and night time economy venues","action":"Deployed live facial recognition technology on body-worn cameras","consequence":"Extended use of facial recognition scheme"}},{"i":"R1571","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"As uk sets date for general elections criticism piles on voter id requirement","s":"The government has been facing pushback over the voter ID rule itself as well as the limited number of acceptable forms of identity documents. The UK’s first national election to require a photo ID document has finally set its date to July 4th. But as the deadline approaches, some experts are warning that the ID requirement alongside existing issues with voter registration could demand a “huge” logistical effort while rights organizations are decrying the voter ID’s potential for discrimination. “The volume of registration and identification applications will pose a considerable challenge for electoral administrators,” says Toby James, a professor at the University of East Anglia and deputy director of the Electoral Integrity Project.","u":"https://www.biometricupdate.com/202406/as-uk-sets-date-for-general-elections-criticism-piles-on-voter-id-requirement","d":"2024-06-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-04","organization":"UK government","aiSystem":"Not specified in report","affectedGroup":"Voters","action":"Required voters to present photo ID documents","consequence":"Potential for discrimination and logistical challenges"}},{"i":"R1587","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk police fully embrace the potential of facial recognition with 55 5m to spend","s":"UK Prime Minister Rishi Sunak today announced a major new investment in facial recognition technology as part of a wider crackdown on retail crime. “To the shoplifters and those abusing shopworkers, enough is enough,” says a release from the Home Office, which specifies that assaulting a retail worker is to be made a standalone criminal offense. The £55.5 million (US$69.5 million) to be spent on facial recognition technology over the next four years includes £4m for “bespoke mobile units that can be deployed to high streets across the country with live facial recognition used in crowded areas to identify people wanted by the police – including repeat shoplifters.”","u":"https://www.biometricupdate.com/202404/uk-police-fully-embrace-the-potential-of-facial-recognition-with-55-5m-to-spend","d":"2024-04-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-10","organization":"UK Police","aiSystem":"Facial recognition technology","affectedGroup":"Shoplifters, retail workers, repeat shoplifters","action":"Deploy facial recognition technology to identify people wanted by the police in crowded areas","consequence":"Increased surveillance and potential misuse of technology"}},{"i":"R1592","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Uk data watchdog to investigate countrys troubled immigration it systems","s":"The Information Commissioner's Office will probe IT incidents connected to the Home Office-operated Person Centric Data Platform and Atlas,. After reports revealed that more than 76,000 people have been affected by biographical and biometrical data errors in the UK government immigration database, the country’s data protection watchdog has launched an investigation into the work of the Home Office. The Information Commissioner’s Office (ICO) will probe “IT incidents” connected to the Home Office-operated Person Centric Data Platform (PCDP) and Atlas, the computer tools used by immigration caseworkers and border authorities, according to trade publication Public Technology.","u":"https://www.biometricupdate.com/202403/uk-data-watchdog-to-investigate-countrys-troubled-immigration-it-systems","d":"2024-03-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-21","organization":"Home Office","aiSystem":"Person Centric Data Platform (PCDP) and Atlas","affectedGroup":"more than 76,000 people","action":"incidents involving biographical and biometrical data errors","consequence":"privacy intrusion"}},{"i":"R1597","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uk ico issues warning on biometric employee tracking guidance for businesses","s":"The UK's data regulator has sent enforcement notices to companies tracking employee time and attendance with biometrics, and issued guidance for businesses. The UK Information Commissioner’s Office (ICO) has warned community and fitness center operator Serco Leisure that facial recognition and fingerprint biometrics cannot be used to monitor employees’ time and attendance. The regulator posted a notice of its warning to Serco “and seven associated leisure trusts,” stating that the use of biometrics was not proportionate, and no alternative method was offered. They must end the practice and delete the biometric data collected within three months.","u":"https://www.biometricupdate.com/202402/uk-ico-issues-warning-on-biometric-employee-tracking-guidance-for-businesses","d":"2024-02-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-27","organization":"UK Information Commissioner’s Office (ICO)","aiSystem":"Facial recognition and fingerprint biometrics","affectedGroup":"Employees of Serco Leisure and associated leisure trusts","action":"Used biometrics to monitor employees' time and attendance","consequence":"Exposure to surveillance and tracking"}},{"i":"R1602","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Uks photo id requirement for voting stirs backlash against government","s":"The UK is planning to introduce mandatory photo identification for voters during national elections for the first time this year. But the country’s electoral watchdog is warning that the tight ID rules risk disenfranchising certain groups while the new rules could be seen as benefitting the Tory Party. “The photo ID requirement is clearly proving more of a barrier to some people than others,” says John Pullinger, chair of the UK Electoral Commission. The introduction of photo IDs for voting has been fueling accusations that the Tory government is trying to gerrymander the elections by excluding voters who are likely to vote against them, including younger people.","u":"https://www.biometricupdate.com/202402/uks-photo-id-requirement-for-voting-stirs-backlash-against-government","d":"2024-02-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-09","organization":"UK Electoral Commission","aiSystem":"Not specified in report","affectedGroup":"Certain groups of people, particularly younger people","action":"Introducing mandatory photo identification for voters","consequence":"Risk of disenfranchising certain groups while potentially benefiting the Tory Party"}},{"i":"R1608","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"London police deploy facial recognition during palestine and israel protests","s":"The London police have deployed facial recognition during protest actions in support of Palestine and Israel over the last weekend. The London police have deployed facial recognition during protest actions in support of Palestine and Israel over the last weekend to identify people bearing offensive placards and banners and committing other types of offenses. On Saturday, the Palestine Solidarity Campaign and other groups led a march through the city in support of Palestine while on Sunday, another rally was held in support of Israel on London’s Trafalgar Square. Before the events, the London Metropolitan Police announced they would be using facial recognition to compare CCTV stills and images shared on social media against a database of images held on the police custody system.","u":"https://www.biometricupdate.com/202401/london-police-deploy-facial-recognition-during-palestine-and-israel-protests","d":"2024-01-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01","organization":"London Metropolitan Police","aiSystem":"Facial recognition technology","affectedGroup":"People bearing offensive placards and banners, protesters, and others committing offenses","action":"Used facial recognition to identify people","consequence":"Exposure to surveillance and tracking"}},{"i":"R1610","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk legal charity decries use of biometric immigrant monitoring devices","s":"The UK has been expanding the use of biometric electronic monitoring devices for immigration bail cases, drawing criticism from NGOs. The UK has been expanding the use of biometric electronic monitoring devices for immigration bail cases, a practice that has drawn criticism from non-governmental organizations that describe the practice as invasive. Last year, the country increased the use of GPS electronic monitoring devices as a bail condition by 56 percent, according to a report by London-based legal charity Public Law Project. This includes both fitted devices such as ankle monitors and non-fitted devices which request periodic biometric verification from the user through a fingerprint scanner.","u":"https://www.biometricupdate.com/202401/uk-legal-charity-decries-use-of-biometric-immigrant-monitoring-devices","d":"2024-01-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023","organization":"UK authorities","aiSystem":"Biometric electronic monitoring devices","affectedGroup":"Immigration detainees","action":"Used biometric electronic monitoring devices as a bail condition","consequence":"Invasive and excessive use leading to privacy risks"}},{"i":"R1617","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Uber eats driver to amend lawsuit alleging racial bias by apps biometric verification","s":"The judge has ruled that former Uber Eats delivery driver can amend and pursue claims that he was kicked off the app as a result of a racially-biased algorithm. A UK judge has ruled that former Uber Eats delivery driver Edrissa Manjang can amend and pursue claims that he was kicked off the ride-sharing app as a result of a racially-biased algorithm in its face biometric system, according to Law360 The judge had first accepted the amended claims in July 2022 after Uber Eats gave information that contradicted his original claims. She also, however, ruled Manjang can not use emails the company sent him about the system as evidence of harassment.","u":"https://www.biometricupdate.com/202311/uber-eats-driver-to-amend-lawsuit-alleging-racial-bias-by-apps-biometric-verification","d":"2023-11-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-01","organization":"Uber Eats","aiSystem":"face biometric system","affectedGroup":"former Uber Eats delivery driver Edrissa Manjang","action":"kicked off the app","consequence":"claims of racial bias"}},{"i":"R1622","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Autonomous cars may have a person detection bias problem with complexions","s":"Makers of self-driving cars have for years been fending off criticism about safety. Now, they may have to defend themselves against charges of AI bias. A team of researchers from King’s College London and Peking University examined eight deep-learning pedestrian detectors used for research on driverless cars using four widely studied testing datasets. Their results show significant fairness issues related to skin tone and age. Accuracy of detection for adults was 19.67 percent higher compared to children. The study also found that the systems were 7.52 percent better at detecting light-skin individuals than dark-skin ones in all image datasets.","u":"https://www.biometricupdate.com/202308/autonomous-cars-may-have-a-person-detection-bias-problem-with-complexions","d":"2023-08-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-25","organization":"Researchers from King’s College London and Peking University","aiSystem":"Deep-learning pedestrian detectors for self-driving cars","affectedGroup":"Pedestrians, particularly children and darker-skinned individuals","action":"Used to detect pedestrians in self-driving cars","consequence":"Significant fairness issues related to skin tone and age, leading to biased detection accuracy"}},{"i":"R1629","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Policing minister pushes for facial recognition in all uk police forces despite criticism","s":"The Home Office briefed the biometrics and surveillance commissioner on the minsters desire for law enforcement to expand their use of these systems. The UK’s policing minister, Chris Philp, is pushing for facial recognition in all police forces nationally, despite critics claiming the technology is inaccurate and some of its applications are illegal. According to a report to be submitted to parliament today, the Home Office briefed the biometrics and surveillance commissioner on Philp’s desire for law enforcement to expand their use of these systems, the Financial Times reports. That would mean rollouts to more forces and police body cameras.","u":"https://www.biometricupdate.com/202305/policing-minister-pushes-for-facial-recognition-in-all-uk-police-forces-despite-criticism","d":"2023-05-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-17","organization":"UK's policing minister Chris Philp and the Home Office","aiSystem":"Facial recognition technology","affectedGroup":"Law enforcement officers and citizens","action":"Expand the use of facial recognition technology in all police forces","consequence":"Exposure to surveillance and tracking"}},{"i":"R1665","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"New ai models like chatgpt pursue superintelligence but cant be trusted even when it comes to basic questions","s":"A study published in the journal ‘Nature’ warns that errors, even in simple matters, will be difficult to completely eliminate in the future. ChatGPT and other language models have become an increasingly common resource in a multitude of jobs. However, they have an underlying problem that tends to get worse: these systems often give incorrect answers What’s more, the problem is getting worse. “New systems improve their results in difficult tasks, but not in easy ones, so these models become less reliable,” says Lexin Zhou, co-author of an article published on Wednesday in the scientific journal Nature , which he wrote together with four Spaniards and a Belgian from Valencian University Institute for Research in Artificial Intelligence (VRAIN) of the Polytechnic University of Valencia (UPV) and the University of Cambridge.","u":"https://english.elpais.com/technology/2024-09-25/new-ai-models-like-chatgpt-pursue-superintelligence-but-cant-be-trusted-even-when-it-comes-to-basic-questions.html","d":"2024-09-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-25","organization":"Various companies and research institutions including Valencian University Institute for Research in Artificial Intelligence (VRAIN), Polytechnic University of Valencia (UPV), and University of Cambridge","aiSystem":"ChatGPT and other language models","affectedGroup":"Users seeking information or assistance","action":"Providing incorrect answers to simple questions","consequence":"Reduced reliability and potential misuse of AI-generated content"}},{"i":"R1679","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"When the algorithm encourages you to commit suicide","s":"Artificial intelligence streamlines many tasks, but it can also have a fatal influence on some people, and it is creating a world in which reality and artifice will be indistinguishable. On Christmas morning 2021, Jaswant Singh Chail entered Windsor Castle with crossbow in hand, disguised as Lord Sith, the villain from Star Wars. He told the royal guards who intercepted him that he was there to assassinate the Queen of England; he was then arrested and charged with treason. During the trial last month, the judge read some of the 5,000 messages that the 21-year-old had exchanged with a chatbot on the Replika app in the weeks leading up to the event.","u":"https://english.elpais.com/science-tech/2023-11-20/when-the-algorithm-encourages-you-to-commit-suicide.html","d":"2023-11-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-12-01","organization":"Not specified in report","aiSystem":"Replika app","affectedGroup":"Jaswant Singh Chail","action":"Chats with a chatbot on the Replika app","consequence":"Encouraged to commit an assassination attempt against the Queen of England"}},{"i":"R1718","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Henry nowak murder police officer grok ai b2989079","s":"Christi Hill was wrongly identified in the Vickrum Digwa murder case by platforms including Grok. A former police officer has been forced to move to a safe house after she was falsely accused by AI and social media users of being one of the arresting officers in the Henry Nowak murder case. Christi Hill, who left her job as a police constable in Portsmouth, near Southampton , 20 months before the murder, said she was scared for her safety after the wrong information spread. Police officers in Southampton in December handcuffed Henry Nowak after he had been attacked by Vickrum Digwa, who was later jailed for life.","u":"https://www.independent.co.uk/news/uk/home-news/henry-nowak-murder-police-officer-grok-ai-b2989079.html","d":"2026-06-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-04","organization":"Platforms","aiSystem":"Grok","affectedGroup":"Christi Hill","action":"AI and social media users falsely accused her of being one of the arresting officers","consequence":"Scared for her safety, forced to move to a safe house"}},{"i":"R1720","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Elections ai deepfakes politics b2986017","s":"Exclusive: New polling shows deepfakes and AI-generated video, audio clips or images about election candidates reached 16.5 million UK adults in the month before elections. The UK is facing a \"democratic emergency”, a leading think tank has warned weeks ahead of a crucial by-election, after new polling revealed around 16.5 million UK adults saw political deepfakes in the month before the local elections Almost one in three (30 per cent) voters said they had seen a deepfake or AI-generated video, audio clip or image about an election candidate or politician online in the lead-up to this month's elections, the shocking new polling showed. The polling of 2,005 adults was conducted by Opinium for the cross-party think tank Demos between 30 April and 6 May this year – immediately before local and devolved elections across the UK.","u":"https://www.independent.co.uk/news/uk/politics/elections-ai-deepfakes-politics-b2986017.html","d":"2026-05-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05","organization":"Not specified in report","aiSystem":"AI-generated deepfake technology","affectedGroup":"UK adults","action":"saw political deepfakes","consequence":"exposed to misleading information"}},{"i":"R1721","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Scottish government hyperscale ai data emissions b2982766","s":"Scottish government’s NPF4 national planning framework states that \"green data centres\" will have an \"overall negligible impact\" on nation’s emissions reduction goals. The Scottish Government faces urgent calls to address \"major shortcomings\" in its data centre policy, as Action to Protect Rural Scotland (APRS) alleges a critical failure to account for the emissions of hyperscale AI facilities in assessments of \"green data centres\" and their contribution to climate targets. Kat Jones, director of APRS, branded the situation \"pretty shocking\". The government’s NPF4 national planning framework states that \"green data centres\" will have an \"overall negligible impact\" on Scotland’s emissions reduction goals.","u":"https://www.independent.co.uk/news/uk/home-news/scottish-government-hyperscale-ai-data-emissions-b2982766.html","d":"2026-05-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-25","organization":"Scottish Government","aiSystem":"Hyperscale AI facilities","affectedGroup":"People living in Scotland","action":"Assessments of 'green data centres' and their contribution to climate targets","consequence":"Exposure to misleading information and failure to account for emissions"}},{"i":"R1731","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai artificial intelligence asylum claims backlog b2937111","s":"Exclusive: Caseworkers use AI to summarise asylum interviews and to search for information about country of origin. The Home Office ’s use of artificial intelligence (AI) in processing asylum claims could be unlawful, legal experts have warned, opening up the possibility of court action against the government. Caseworkers at the Home Office use AI to summarise interview transcripts with asylum seekers It is also used to search policy guidance, such as information about whether a country is deemed safe to return to. Asylum seekers are not told when AI is used on their interview testimony and are instead kept in the dark about the technology’s impact on their claims The government’s own evaluation of the AI tool that summarises asylum interview transcripts found that 9 per cent of summaries were so flawed that they had to be removed.","u":"https://www.independent.co.uk/news/uk/home-news/ai-artificial-intelligence-asylum-claims-backlog-b2937111.html","d":"2026-03-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"Home Office","aiSystem":"AI tool used to summarise asylum interview transcripts","affectedGroup":"Asylum seekers","action":"AI summarises interview transcripts and searches policy guidance","consequence":"Flawed summaries result in removal of summaries, potentially impacting asylum claims"}},{"i":"R1734","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"X uk investigation grok deepfakes ico elon musk b2912966","s":"There has been controversy surrounding chatbot Grok after it was used to generate sexual deepfake images without consent. Formal investigations have been launched into whether Elon Musk’s X and xAI have complied with data protection law after the chatbot Grok was used to create sexualised deepfake images. The Information Commissioner’s Office (ICO) confirmed it had opened the investigations on Tuesday afternoon. In a statement, it said the reports raised “serious concerns” under UK data protection laws, such as whether “appropriate safeguards were built into Grok’s design and deployment”. It comes after outrage over Grok’s ability to digitally “strip” victims without their consent, generating deepfake images of them nude or in minimal clothing.","u":"https://www.independent.co.uk/news/uk/home-news/x-uk-investigation-grok-deepfakes-ico-elon-musk-b2912966.html","d":"2026-02-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-03","organization":"Information Commissioner's Office (ICO)","aiSystem":"Grok chatbot","affectedGroup":"Victims of sexualized deepfake images","action":"Generated sexualized deepfake images without consent","consequence":"Raised serious concerns under UK data protection laws"}},{"i":"R1739","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai deepfakes british schools pupils teachers b2897746","s":"Beyond Grok, nudifying technology and pornographic deepfakes are ripping through classrooms, leaving teachers and children traumatised and schools unsure how to respond. With suspensions rising and prosecutions rare, Chloe Combi asks who is protecting them in the age of AI? T welve years ago, a friend of mine had just started her first teaching post at a well-respected grammar school A huge perk of the job was that, so young teachers could afford to live in the South East and get to school easily, the school owned several houses that staff could rent for a heavily subsidised fee. One Saturday morning during a heatwave, there was a knock at the door.","u":"https://www.independent.co.uk/news/uk/home-news/ai-deepfakes-british-schools-pupils-teachers-b2897746.html","d":"2026-01-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-11","organization":"Schools and educational institutions","aiSystem":"Pornographic deepfakes","affectedGroup":"Teachers and children","action":"Used deepfakes to create pornographic content","consequence":"Trauma, suspension, and uncertainty in response"}},{"i":"R1743","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Artificial intelligence law legal ai chatgpt judges b2849313","s":"Artificial intelligence decided a case that would take years in just “a couple of minutes,” the senior judge said. One of the most senior judges in the country has revealed that artificial intelligence (AI) is being used in the legal sector for “every purpose under the sun” as he weighs up the power of the technology to make decisions in court. Master of the rolls Sir Geoffrey Vos, the second most senior judge in the UK, said AI was like a “chainsaw” at his address to the Legal Geek Conference, in that it was useful in the right hands, but “super dangerous” in the wrong ones. The technology can and should be used to draft contracts and research legal questions, Sir Geoffrey said, especially noting how the summarising capability of large language models (LLMs) can “save time and drudgery” when used carefully.","u":"https://www.independent.co.uk/news/uk/home-news/artificial-intelligence-law-legal-ai-chatgpt-judges-b2849313.html","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-22","organization":"Legal sector in the United Kingdom","aiSystem":"Large language models (LLMs)","affectedGroup":"Judges, lawyers, legal professionals","action":"Used to draft contracts and research legal questions","consequence":"Could lead to faster but potentially flawed judicial decisions"}},{"i":"R1744","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chowdhury rahman barrister chatgpt ai asylum case b2847109","s":"Tribunal judge says Chowdhury Rahman wasted court time with ‘wholly irrelevant’ submissions. An immigration barrister could face a disciplinary probe after a judge ruled he used AI tools such as ChatGPT to prepare his legal research. A tribunal heard that a judge was left baffled when Chowdhury Rahman presented his submissions, which included citing cases that were “ entirely fictitious ” or “wholly irrelevant”. A judge found that Mr Rahman had also attempted to “hide” this when questioned, and “wasted” the tribunal’s time. The incident occurred while Mr Rahman was representing two Honduran sisters who were claiming asylum in the UK on the basis that they were being targeted by a violent criminal gang called Mara Salvatrucha (MS-13).","u":"https://www.independent.co.uk/news/uk/home-news/chowdhury-rahman-barrister-chatgpt-ai-asylum-case-b2847109.html","d":"2025-10-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-17","organization":"Tribunal judge","aiSystem":"AI tools such as ChatGPT","affectedGroup":"Immigration barrister Chowdhury Rahman","action":"Used AI tools to prepare legal research","consequence":"Wasted court time, faced disciplinary probe"}},{"i":"R1746","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Facial recognition vans police home office b2806734","s":"Critics issue warning over nationwide expansion of ‘intrusive’ technology which ‘turns every passerby into a walking barcode’. Critics have branded the nationwide rollout of live facial recognition technology as another move towards a “total surveillance society”. The Home Office has announced that ten more vans fitted with high-tech cameras will be deployed across the country to catch “high-harm” offenders as part of a government overhaul of neighbourhood policing. Alongside the expansion, the government will simultaneously consult on how the technology should be used and what appropriate safeguards and oversight are needed to shape a new legal framework for its use.","u":"https://www.independent.co.uk/news/uk/crime/facial-recognition-vans-police-home-office-b2806734.html","d":"2025-08-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-13","organization":"Home Office","aiSystem":"Facial recognition technology","affectedGroup":"Everyday citizens","action":"Deploy live facial recognition technology in police vans","consequence":"Exposure to intrusive surveillance"}},{"i":"R1749","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Brick lane new data centre plans london b3015349","s":"The proposed construction of a data centre in London’s famous Brick Lane continues to generate controversy. Suha Kidwai speaks to residents about the impact it could have on the area. L ined with its famed curry houses, 24-hour bagel shops and stores selling vintage jeans covered with anti-war slogans, London’s Brick Lane has long been considered a beloved cultural hotspot But now, a 5,200 square metre data centre could be built over one of the area’s most iconic buildings, the former Truman Brewery. The 29-metre-tall facility is set to be used for high-speed trading in London’s nearby financial district, and aims to employ 20 full-time staff.","u":"https://www.independent.co.uk/news/uk/home-news/brick-lane-new-data-centre-plans-london-b3015349.html","d":"2025-07-19","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-19","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Residents of Brick Lane","action":"Construction of a data center over an iconic building","consequence":"Exposure to unwanted development and loss of cultural heritage"}},{"i":"R1754","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Dwp benefits esa artificial intelligence disability b2697488","s":"Agents do not ‘simply accept the result provided by the solution,’ DWP says. The Department for Work and Pensions (DWP) has revealed how it is using AI to inform decisions on whether to approve or deny certain benefit applications. Sharing new details to the official government algorithm database, the department says it is using an AI tool called ‘online medical matching’ to help agents make decisions on applications for Employment Support Allowance (ESA). Claimed by 1.5 million people, this is the main health-related benefit that people can receive if they have a condition that affects how much they are able to work.","u":"https://www.independent.co.uk/news/uk/home-news/dwp-benefits-esa-artificial-intelligence-disability-b2697488.html","d":"2025-02-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-13","organization":"Department for Work and Pensions (DWP)","aiSystem":"online medical matching AI tool","affectedGroup":"people claiming Employment Support Allowance (ESA)","action":"using the online medical matching AI tool to inform decisions on benefit applications","consequence":"denying or approving benefit applications based on the tool's results"}},{"i":"R1755","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Naga munchetty nude images scam bbc warning deepfake b2693198","s":"‘This is the most humiliating day of my life,’ the presenter said. Naga Munchetty has become the latest celebrity to be targeted in a sexually explicit scam. The veteran BBC presenter, 49, discovered paid advertisements on X/Twitter and Facebook promoted to “trick people out of their hard-earned money” and include “crudely mocked-up” fake nude photos of her. Munchetty, who conducted an investigation into the images with her team at BBC 5 Live , said she was “mortified and bemused” to discover the explicit content that somebody had paid “good money” to advertise. “I'm used to seeing misleading articles about myself online, but the screenshots I've been sent by friends and followers on social media in recent weeks are a lot more insidious than most,” she said.","u":"https://www.independent.co.uk/arts-entertainment/tv/news/naga-munchetty-nude-images-scam-bbc-warning-deepfake-b2693198.html","d":"2025-02-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-06","organization":"BBC","aiSystem":"Deepfake technology","affectedGroup":"Naga Munchetty","action":"Deepfake nude images were advertised and shared online","consequence":"Exposure to misleading and sexually explicit content"}},{"i":"R1761","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Abbots langley ai data centre hertfordshire b2640085","s":"Abbots Langley has become a flashpoint in a battle between villagers and big tech. A proposal to build a data center on the edge of the English village of Abbots Langley was rejected by local authorities amid fierce opposition from villagers. But it's getting a second chance from British Prime Minister Keir Starmer's government, which is pursuing reforms to boost economic growth following his Labour party's election victory in July. Residents of Abbots Langley, 18 miles northwest of London in Hertfordshire, worry the facility will strain local resources and create noise and traffic that damages the character of the quiet village, which is home to just over 20,000 people.","u":"https://www.independent.co.uk/news/uk/home-news/abbots-langley-ai-data-centre-hertfordshire-b2640085.html","d":"2024-11-02","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-02","organization":"British Prime Minister Keir Starmer's government","aiSystem":"Not specified in report","affectedGroup":"Residents of Abbots Langley","action":"Rejected a proposal to build a data center","consequence":"Facility will strain local resources and create noise and traffic"}},{"i":"R1767","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"X elon musk algorithm southport race riots amnesty uk b2802863","s":"Amnesty International analysis found algorithm ‘systematically prioritises’ content that ‘sparks outrage’. New analysis investigating X’s algorithm has revealed how the platform played a “central role” in spreading false narratives fuelling riots in the UK last summer Amnesty International’s analysis of the platform’s own source code, published in March 2023, has revealed how it “systematically prioritises” content that “sparks outrage” - without adequate safeguards to prevent harm. The human rights group said the design of the software created “fertile ground for inflammatory racist narratives to thrive” in the wake of the Southport attack last year.","u":"https://www.independent.co.uk/news/uk/home-news/x-elon-musk-algorithm-southport-race-riots-amnesty-uk-b2802863.html","d":"2024-08-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-01","organization":"X (presumably referring to Elon Musk's Twitter)","aiSystem":"X's algorithm","affectedGroup":"People exposed to false narratives","action":"Spreads false narratives","consequence":"Fuels riots"}},{"i":"R1776","k":"United Kingdom","p":"United Kingdom","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Ai artificial intelligence national security government b2533198","s":"Decision makers may not be aware of the dangers of relying on information from artificial intelligence, experts say. AI could have profound implications for national security – including posing a host of risks, a new government-commissioned report warns. Artificial intelligence is a valuable tool to help senior officials in government and intelligence make decisions, it says. But it could also lead to inaccuracies, confusion and other dangers, it warns. Senior officials must be trained to spot those problems, and there is a critical need for any AI systems to be carefully watched and continuously monitored to ensure they don’t lead to more bias and errors, it warns.","u":"https://www.independent.co.uk/tech/ai-artificial-intelligence-national-security-government-b2533198.html","d":"2024-04-23","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-23","organization":"government","aiSystem":"artificial intelligence","affectedGroup":"decision makers","action":"relying on information from artificial intelligence","consequence":"profound implications for national security, including posing a host of risks"}},{"i":"R1779","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chris morris chatgpt rishi sunak labour sadiq khan b2525418","s":"Full Fact’s annual report says the UK is ill-equipped to tackle misleading content. The UK is highly vulnerable to misinformation and is currently not properly equipped to combat it, the annual report from fact-checking charity Full Fact says. The report warns that without urgent action, the UK risks falling behind the pace of international progress in protecting citizen from misinformation. It says that a combination of significant gaps in the Online Safety Act and the rapid rise of generative AI means a fundamental overhaul of the UK’s legislative and regulatory framework is needed in order to adequately combat misinformation and disinformation.","u":"https://www.independent.co.uk/tech/chris-morris-chatgpt-rishi-sunak-labour-sadiq-khan-b2525418.html","d":"2024-04-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-09","organization":"Not specified in report","aiSystem":"Generative AI","affectedGroup":"People in the United Kingdom","action":"Rapid rise of generative AI","consequence":"Risk of falling behind international progress in combating misinformation"}},{"i":"R1785","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Met police croydon facial recognition b2484112","s":"Several people were arrested including for failure to turn up at court. London’s Metropolitan Police have arrested over a dozen people in two days using controversial Live Facial Recognition technology in Croydon. The operation which took place on Saturday 20 January and Tuesday 23 January consisted of LFR cameras being focused on a specific area in Croydon and as people pass through that area their images are streamed directly to the Live Facial Recognition system. Ahead of the deployment police upload images of criminals who are wanted onto a database. Met Police say this system contains a “watchlist” of offenders who are wanted by the police and/or courts and those who pose a risk of harm to themselves or others.","u":"https://www.independent.co.uk/news/uk/home-news/met-police-croydon-facial-recognition-b2484112.html","d":"2024-01-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-20","organization":"London’s Metropolitan Police","aiSystem":"Live Facial Recognition technology","affectedGroup":"People who were arrested","action":"Used Live Facial Recognition technology to focus cameras on a specific area in Croydon and stream images to the system","consequence":"Arrested people included for failure to appear at court"}},{"i":"R1788","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai artificial intelligence government b2434850","s":"Civil servants are relying on AI to make decisions around welfare, immigration and criminal justice. Bookmark - CommentsGo to comments Government officials are using artificial intelligence (AI) to help decide on everything from approving marriage licences to who should be given benefits, it has been revealed. Civil servants in at least eight Whitehall departments, and several police forces, are relying on AI to make decisions around welfare, immigration and criminal justice, according to an investigation. The shocking findings include the use of an algorithm by the Department for Work and Pensions (DWP) to identify potential benefit fraud.","u":"https://www.independent.co.uk/news/uk/politics/ai-artificial-intelligence-government-b2434850.html","d":"2023-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-24","organization":"Department for Work and Pensions (DWP)","aiSystem":"algorithm by the Department for Work and Pensions (DWP)","affectedGroup":"potential benefit fraud victims","action":"identifying potential benefit fraud","consequence":"denying benefits"}},{"i":"R1790","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Keir starmer deepfake ai elections b2426578","s":"As politicans find themselves targeted by advances in deepfakes, the pubilc will have to be on guard not to get duped, writes Anthony Cuthbertson. But given they are so convincing, is it time for a tech solution? Bookmark - CommentsGo to comments Just a week after Slovakia scrambled to deal with an AI-generated recording designed to influence national elections, the UK Labour Party has become the target of deepfake audio. “I’m sick of this,” one of the clips, which appeared to be from a secret recording of party leader Keir Starmer, stated. “I f***ing hate Liverpool.” Despite being debunked and deleted from some platforms, the fake recordings still received millions of views across social media, and highlighted what Tory MP Simon Clarke described as “a new threat to democracy”.","u":"https://www.independent.co.uk/tech/keir-starmer-deepfake-ai-elections-b2426578.html","d":"2023-10-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-01","organization":"UK Labour Party","aiSystem":"Deepfake technology","affectedGroup":"Members of the public, voters, political opponents","action":"Generated and distributed deepfake audio recordings","consequence":"Misinformation and confusion during elections, potential impact on public trust and electoral integrity"}},{"i":"R1808","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Renewables case ai data centres built bunk","s":"THE case for a controversial £8.2 billion hyperscale AI data centre in Lanarkshire is built on “bunk,” an investigation has found.In January, Prime Minister Sir Keir Starmer unveiled a plan to turn the area once synonymous with Scotland’s heavy industry into an “AI growth zone,” with £5 million of state and £8.2bn of private-sector investment. THE case for a controversial £8.2 billion hyperscale AI data centre in Lanarkshire is built on “bunk,” an investigation has found. In January, Prime Minister Sir Keir Starmer unveiled a plan to turn the area once synonymous with Scotland’s heavy industry into an “AI growth zone,” with £5 million of state and £8.2bn of private-sector investment.","u":"https://morningstaronline.co.uk/article/renewables-case-ai-data-centres-built-bunk","d":"2026-07-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"January","organization":"Prime Minister's Office, UK Government","aiSystem":"Hyperscale AI data center","affectedGroup":"Potential investors, local residents, Lanarkshire area","action":"Promoted the construction of a controversial £8.2 billion hyperscale AI data center","consequence":"Misleading investment plans leading to potential economic and environmental harm"}},{"i":"R1809","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Concerns raised about congestion and job losses rollout robotaxis london","s":"UBER drivers and gig workers demonstrated today against the rollout of robotaxis in London, as the government opened bids for US and Chinese operators to access the British market.App Drivers’ & Couriers’ Union (ADCU) members protested in the borough of Brent, as the Transport for London (TfL) joined the union in expressing concerns over the rollout of self-driving vehicles in the capital. UBER drivers and gig workers demonstrated today against the rollout of robotaxis in London, as the government opened bids for US and Chinese operators to access the British market. App Drivers’ & Couriers’ Union (ADCU) members protested in the borough of Brent, as the Transport for London (TfL) joined the union in expressing concerns over the rollout of self-driving vehicles in the capital.","u":"https://morningstaronline.co.uk/article/concerns-raised-about-congestion-and-job-losses-rollout-robotaxis-london","d":"2026-05-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-22","organization":"UBER drivers and gig workers, App Drivers' & Couriers' Union (ADCU), Transport for London (TfL)","aiSystem":"self-driving vehicles","affectedGroup":"UBER drivers and gig workers, App Drivers' & Couriers' Union (ADCU) members, residents of the borough of Brent","action":"demonstrated against the rollout of robotaxis","consequence":"expressed concerns over the rollout of self-driving vehicles in the capital"}},{"i":"R1813","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Mick whitley feature 0","s":"ARTIFICIAL intelligence could have as wide-reaching and profound an impact on jobs as the first Industrial Revolution.That was the warning issued by the government’s former chief scientific adviser, Sir Patrick Vallance, when he appeared before Parliament’s science and technology committee earlier this month.Research commissioned by the then Department for Business, Energy and Industrial Strategy suggests that 7 per cent of all British jobs could be automated out of existence within just five years as a result of AI. MICK WHITLEY MP is today introducing a Bill in Parliament that aims to secure a people-focused and democratic approach towards increased use of AI across the British economy SHAPE OF THINGS TO COME: Ai-Da about to make history as the first robot to address the House of Lords: its speech explored the role of machine learning, machine creativity and Artificial Intelligence…","u":"https://morningstaronline.co.uk/article/f/mick-whitley-feature-0","d":"2023-05-17","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2023-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-17","organization":"Department for Business, Energy and Industrial Strategy","aiSystem":"AI-powered welfare fraud detection system","affectedGroup":"welfare recipients","action":"automated welfare fraud detection","consequence":"denied access to essential services"}},{"i":"R1853","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ex uber driver takes legal action over racist face recognition software","s":"UK driver alleges his account was illegally deactivated when Uber software decided he was not who he said he was. An Uber driver who lost his job when automated face-scanning software failed to recognise him is accusing the firm of indirect race discrimination in a legal test case. The black driver, who worked on the Uber platform from 2016 until April 2021, has filed an employment tribunal claim alleging his account was illegally deactivated when facial-verification software used to log drivers on to the ride-hailing app decided he was not who he said he was. The Independent Workers’ Union of Great Britain (IWGB), which is backing the action, claimed at least 35 other drivers had had their registration with Uber terminated as a result of alleged mistakes with the software since the start of the pandemic.","u":"https://www.theguardian.com/technology/2021/oct/05/ex-uber-driver-takes-legal-action-over-racist-face-recognition-software","d":"2021-10-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-05","organization":"Uber","aiSystem":"Automated face-scanning software used to log drivers on to the ride-hailing app","affectedGroup":"Black Uber drivers","action":"Facial-verification software decided the driver was not who he said he was","consequence":"Account was illegally deactivated"}},{"i":"R1854","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Uber facing new uk driver claims of racial discrimination","s":"Drivers say automated ID system needed to work failed to identify them because of their race. Uber is facing further claims for compensation over racial discrimination from drivers who say they had been falsely dismissed because of malfunctioning face recognition technology. The claims have emerged after Uber introduced an automated system to check the ID of drivers operating its services in April last year. Each time a driver checks in for work, they must take a selfie picture that is then compared, using an automated system, to one on their Uber account profile. Pa Edrissa Manjang, who worked for the Uber Eats takeaway courier service in London, has launched an employment tribunal claim alleging his account was illegally deactivated.","u":"https://www.theguardian.com/technology/2021/oct/06/uber-facing-new-uk-driver-claims-of-racial-discrimination","d":"2021-10-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-06","organization":"Uber","aiSystem":"Automated ID system for driver verification","affectedGroup":"Drivers, particularly those of African descent","action":"Automated system deactivated driver accounts","consequence":"False dismissal and loss of employment"}},{"i":"R1858","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Algorithmic monitoring mental health uk employees","s":"Report by MPs and peers says monitoring worker performance using AI should be regulated by law. Monitoring of workers and setting performance targets through algorithms is damaging employees’ mental health and needs to be controlled by new legislation, according to a group of MPs and peers. An “accountability for algorithms act’” would ensure that companies evaluate the effect of performance-driven regimes such as queue monitoring in supermarkets or deliveries-per-hour guidelines for delivery drivers, said the all-party parliamentary group (APPG) on the future of work. “Pervasive monitoring and target-setting technologies, in particular, are associated with pronounced negative impacts on mental and physical wellbeing as workers experience the extreme pressure of constant, real-time micro-management and automated assessment,” said the APPG members in their report, the New Frontier:…","u":"https://www.theguardian.com/technology/2021/nov/11/algorithmic-monitoring-mental-health-uk-employees","d":"2021-11-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-11","organization":"All-party parliamentary group (APPG) on the future of work","aiSystem":"Performance-driven regimes such as queue monitoring in supermarkets or deliveries-per-hour guidelines for delivery drivers","affectedGroup":"Workers","action":"Monitoring and setting performance targets through algorithms","consequence":"Damaging employees' mental health and experiencing extreme pressure of constant, real-time micro-management and automated assessment"}},{"i":"R1861","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Uk data watchdog fines facial recognition firm clearview ai image collection","s":"Clearview AI hit with penalty for collecting images of people from social media and web to add to global database. The UK’s data watchdog has fined a facial recognition company £7.5m for collecting images of people from social media platforms and the web to add to a global database. The Information Commissioner’s Office (ICO) also ordered US-based Clearview AI to delete the data of UK residents from its systems. Clearview AI has collected more than 20bn images of people’s faces from Facebook, other social media companies and from scouring the web. John Edwards, the UK information commissioner, said Clearview’s business model was unacceptable.","u":"https://www.theguardian.com/technology/2022/may/23/uk-data-watchdog-fines-facial-recognition-firm-clearview-ai-image-collection","d":"2022-05-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-05-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-23","organization":"Clearview AI","aiSystem":"Facial recognition technology","affectedGroup":"People whose images were collected","action":"Collected images of people's faces from social media and the web","consequence":"Data deleted from systems, fined £7.5m"}},{"i":"R1865","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Uk data watchdog investigates whether ai systems show racial bias","s":"ICO says AI-driven discrimination can lead to job rejections or being wrongfully denied bank loans or benefit. The UK data watchdog is to investigate whether artificial intelligence systems are showing racial bias when dealing with job applications. The Information Commissioner’s Office said AI-driven discrimination could have “damaging consequences for people’s lives” and lead to someone being rejected for a job or being wrongfully denied a bank loan or a welfare benefit. It will investigate the use of algorithms to sift through job applications, amid concerns that they are affecting employment opportunities for people from ethnic minorities.","u":"https://www.theguardian.com/technology/2022/jul/14/uk-data-watchdog-investigates-whether-ai-systems-show-racial-bias","d":"2022-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-14","organization":"Information Commissioner's Office (ICO)","aiSystem":"AI-driven algorithms to sift through job applications","affectedGroup":"people from ethnic minorities","action":"using AI-driven algorithms to screen job applications","consequence":"being wrongly denied job opportunities, bank loans, or welfare benefits"}},{"i":"R1866","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uber eats treats drivers as numbers not humans says dismissed courier","s":"Pa Edrissa Manjang is suing company for alleged dismissal based on racially biased facial recognition software. A delivery driver who is suing Uber Eats in London over his dismissal from the company and claims its facial recognition technology is racially biased says the company treats couriers as “numbers rather than humans”. Pa Edrissa Manjang worked for Uber Eats between November 2019 and April 2021 while employed full-time as a financial assistant. When Manjang first began working for the company he was not regularly asked to send in pictures of himself for verification purposes. However, these facial verification checks became more frequent.","u":"https://www.theguardian.com/technology/2022/jul/27/uber-eats-treats-drivers-as-numbers-not-humans-says-dismissed-courier","d":"2022-07-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-04","organization":"Uber Eats","aiSystem":"Facial recognition technology","affectedGroup":"Delivery drivers","action":"Facial verification checks","consequence":"Dismissal from employment"}},{"i":"R1871","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Tiktok fine protect children privacy uk data protection","s":"Investigation finds video-sharing app may have breached UK data protection law between 2018 and 2020. TikTok is facing the prospect of a £27m fine for failing to protect the privacy of children, the UK’s data watchdog has said. An investigation conducted by the Information Commissioner’s Office (ICO) found the video-sharing app may have breached data protection law between May 2018 and July 2020. The ICO issued TikTok with a “notice of intent”, a precursor to handing down a potential fine, which could be up to £27m. If TikTok were to be fined this amount it would be the largest in the ICO’s history, exceeding the record £20m handed to British Airways two years ago after an incident in 2018 that saw the personal details of more than 400,000 customers compromised by hackers.","u":"https://www.theguardian.com/technology/2022/sep/26/tiktok-fine-protect-children-privacy-uk-data-protection","d":"2022-09-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-09-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-09-26","organization":"Information Commissioner's Office (ICO)","aiSystem":"TikTok","affectedGroup":"Children","action":"May have breached data protection law","consequence":"Facing a potential £27m fine"}},{"i":"R1874","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Information commissioner warns firms over emotional analysis technologies","s":"Companies ‘should not make meaningful decisions based on technology not backed by science’. The information commissioner has warned companies to steer clear of “emotional analysis” technologies or face fines, because of the “pseudoscientific” nature of the field. It’s the first time the regulator has issued a blanket warning on the ineffectiveness of a new technology, said Stephen Bonner, the deputy commissioner, but one that is justified by the harm that could be caused if companies made meaningful decisions based on meaningless data. “There’s a lot of investment and engagement around biometric attempts to detect emotion,” he said.","u":"https://www.theguardian.com/technology/2022/oct/25/information-commissioner-warns-firms-over-emotional-analysis-technologies","d":"2022-10-25","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-25","organization":"Companies","aiSystem":"Emotional analysis technologies","affectedGroup":"Companies","action":"Make meaningful decisions based on emotional analysis technologies","consequence":"Face fines and potential harm"}},{"i":"R1875","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Tiktok mental health social media","s":"Nearly six in 10 teenagers count themselves as daily users of the app yet little is known about the impacts on the brain Read the new Guardian series exploring the increasing power and reach of TikTok. In the few years since its launch, TikTok has already altered the face of the social media landscape, attracting more than 1 billion users and leading competitors to replicate some of its most unique features. The impact of that explosive growth and the ‘TikTok-ification’ of the internet at large on social media users remains little understood, experts warn, exacerbating concerns about the impact of social media on our habits and mental health.","u":"https://www.theguardian.com/technology/2022/oct/30/tiktok-mental-health-social-media","d":"2022-10-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-30","organization":"TikTok","aiSystem":"TikTok","affectedGroup":"teenagers","action":"tracked and monitored user behavior","consequence":"exposure to personal data and mental health concerns"}},{"i":"R1881","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Harry kane most abused england player on twitter since world cup started study","s":"Exclusive: England players received 1,546 abusive tweets during group stages, according to analysis. Harry Kane was the most abused England player on Twitter during the World Cup group stages, accounting for nearly three out of 10 negative tweets directed at team members. England players were sent 1,546 abusive tweets during the group stages of the World Cup, according to analysis by the Alan Turing Institute, accounting for 2% of the more than 75,000 tweets mentioning players for the national team. The institute’s online safety team found that 13% of those abusive tweets – or 205 posts – contained keywords that referred to a protected characteristic such as race, gender or sexuality.","u":"https://www.theguardian.com/technology/2022/dec/02/harry-kane-most-abused-england-player-on-twitter-since-world-cup-started-study","d":"2022-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-02","organization":"Alan Turing Institute","aiSystem":"Not specified in report","affectedGroup":"England players","action":"Received abusive tweets","consequence":"Exposure to misleading content"}},{"i":"R1886","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Police to be able to run face recognition searches on 50m driving licence holders","s":"Exclusive: Privacy campaigners say clause in new criminal justice bill will put all UK drivers on ‘permanent police lineup’. The police will be able to run facial recognition searches on a database containing images of Britain’s 50 million driving licence holders under a law change being quietly introduced by the government. Should the police wish to put a name to an image collected on CCTV, or shared on social media, the legislation would provide them with the powers to search driving licence records for a match. The move, contained in a single clause in a new criminal justice bill, could put every driver in the country in a permanent police lineup, according to privacy campaigners.","u":"https://www.theguardian.com/technology/2023/dec/20/police-to-be-able-to-run-face-recognition-searches-on-50m-driving-licence-holders","d":"2023-12-20","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2023-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-20","organization":"Government of the United Kingdom","aiSystem":"Facial recognition technology","affectedGroup":"All UK drivers","action":"Search driving license records for facial recognition matches","consequence":"Exposure to surveillance and tracking"}},{"i":"R1895","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"We need to come together british artists team up to fight ai image generating software","s":"US lawyers approached about class action against Midjourney and other AI firms accused of ‘copyright laundering’. Since the emergence of Midjourney and other image generators, artists have been watching and wondering whether AI is a great opportunity or an existential threat. Now, after a list of 16,000 names emerged of artists whose work Midjourney had allegedly used to train its AI – including Bridget Riley, Damien Hirst, Rachel Whiteread, Tracey Emin, David Hockney and Anish Kapoor – the art world has issued a call to arms against the technologists. British artists have contacted US lawyers to discuss joining a class action against Midjourney and other AI firms, while others have told the Observer that they may bring their own legal action in the UK.","u":"https://www.theguardian.com/technology/2024/jan/21/we-need-to-come-together-british-artists-team-up-to-fight-ai-image-generating-software","d":"2024-01-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-21","organization":"Midjourney and other AI firms","aiSystem":"AI image generators like Midjourney","affectedGroup":"Artists whose work was allegedly used to train AI","action":"Used artists' work to train AI","consequence":"Potential copyright infringement lawsuits"}},{"i":"R1898","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai scam emails uk cybersecurity agency phishing","s":"NCSC says generative AI tools will soon allow amateur cybercriminals to launch sophisticated phishing attacks. Artificial intelligence will make it difficult to spot whether emails are genuine or sent by scammers and malicious actors, including messages that ask computer users to reset their passwords, the UK’s cybersecurity agency has warned. The National Cyber Security Centre (NCSC) said people would struggle to identify phishing messages – where users are tricked into handing over passwords or personal details – due to the sophistication of AI tools. Generative AI, the term for technology that can produce convincing text, voice and images from simple hand-typed prompts, has become widely available to the public through chatbots such as ChatGPT and free-to-use versions known as open source models.","u":"https://www.theguardian.com/technology/2024/jan/24/ai-scam-emails-uk-cybersecurity-agency-phishing","d":"2024-01-24","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-24","organization":"National Cyber Security Centre (NCSC)","aiSystem":"Generative AI tools","affectedGroup":"Computer users","action":"Launch sophisticated phishing attacks","consequence":"Difficulty in identifying phishing messages"}},{"i":"R1902","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai safeguards can easily be broken uk safety institute finds","s":"Researchers find large language models, which power chatbots, can deceive human users and help spread disinformation. The UK’s new artificial intelligence safety body has found that the technology can deceive human users, produce biased outcomes and has inadequate safeguards against giving out harmful information. The AI Safety Institute published initial findings from its research into advanced AI systems known as large language models (LLMs), which underpin tools such as chatbots and image generators, and found a number of concerns. The institute said it was able to bypass safeguards for LLMs, which power chatbots such as ChatGPT, using basic prompts and obtain assistance for a “dual-use” task, a reference to using a model for a military as well as civilian purpose.","u":"https://www.theguardian.com/technology/2024/feb/09/ai-safeguards-can-easily-be-broken-uk-safety-institute-finds","d":"2024-02-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-02-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-09","organization":"UK's new artificial intelligence safety body","aiSystem":"Large Language Models (LLMs)","affectedGroup":"Human users","action":"Deceive human users, produce biased outcomes, give out harmful information","consequence":"Spread disinformation, inadequate safeguards"}},{"i":"R1907","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai interviews job applications","s":"Employers are letting artificial intelligence conduct job interviews. Candidates are trying to beat the system. When Ty landed an introductory phone interview with a finance and banking company last month, they assumed it would be a quick chat with a recruiter. And when they got on the phone, Ty assumed the recruiter, who introduced herself as Jaime, was human. But things got robotic. “The voice sounded similar to Siri,” said Ty, who is 29 and lives in the DC metro area. “It was creepy.” Ty realized they weren’t speaking to a living, breathing person. Their interviewer was an AI system, and one with a rather rude habit.","u":"https://www.theguardian.com/technology/2024/mar/06/ai-interviews-job-applications","d":"2024-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Finance and banking company","aiSystem":"AI-powered interview system","affectedGroup":"Job applicants","action":"Conducted job interviews using an AI system","consequence":"Interviewees perceived the AI as rude and unhuman-like"}},{"i":"R1910","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Warning over use in uk of unregulated ai chatbots to create social care plans","s":"University of Oxford study shows benefits and risks of technology to healthcare, but ethical issues remain. Britain’s hard-pressed carers need all the help they can get. But that should not include using unregulated AI bots, according to researchers who say the AI revolution in social care needs a hard ethical edge. A pilot study by academics at the University of Oxford found some care providers had been using generative AI chatbots such as ChatGPT and Bard to create care plans for people receiving care. That presents a potential risk to patient confidentiality, according to Dr Caroline Green, an early career research fellow at the Institute for Ethics in AI at Oxford, who surveyed care organisations for the study.","u":"https://www.theguardian.com/technology/2024/mar/10/warning-over-use-in-uk-of-unregulated-ai-chatbots-to-create-social-care-plans","d":"2024-03-10","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-10","organization":"Care providers in the UK","aiSystem":"Generative AI chatbots like ChatGPT and Bard","affectedGroup":"People receiving care","action":"Using generative AI chatbots to create care plans","consequence":"Potential risk to patient confidentiality"}},{"i":"R1916","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai apocalypse could take away almost 8m jobs in uk says report","s":"Women, younger workers and lower paid are at most risk from artificial intelligence, says IPPR thinktank. Almost 8 million UK jobs could be lost to artificial intelligence in a “jobs apocalypse”, according to a report warning that women, younger workers and those on lower wages are at most risk from automation. The Institute for Public Policy Research (IPPR) said that entry level, part-time and administrative jobs were most exposed to being replaced by AI under a “worst-case scenario” for the rollout of new technologies in the next three to five years. The thinktank warned that the UK was facing a “sliding doors” moment as growing numbers of companies adopt generative AI technologies – which can read and create text, data and software code – to automate everyday workplace tasks.","u":"https://www.theguardian.com/technology/2024/mar/27/ai-apocalypse-could-take-away-almost-8m-jobs-in-uk-says-report","d":"2024-03-27","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-27","organization":"Growing numbers of companies","aiSystem":"Generative AI technologies","affectedGroup":"Women, younger workers and those on lower wages","action":"Automate everyday workplace tasks","consequence":"Entry level, part-time and administrative jobs could be lost"}},{"i":"R1917","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"How ai is affecting video game actors","s":"The increased use of AI to replicate the voice and movements of actors has benefits but some are concerned over how and when it might be used and who might be left short-changed. When she discovered her voice had been uploaded to multiple websites without her consent, the actor Cissy Jones told them to take it down immediately. Some complied. “Others who have more money in their banks basically sent me the email equivalent of a digital middle finger and said: don’t care,” Jones recalls by phone. “That was the genesis for me to start talking to friends of mine about: listen, how do we do this the right way? How do we understand that the genie is out of the bottle and find a way to be a part of the conversation or we will get systematically annihilated?","u":"https://www.theguardian.com/technology/2024/mar/29/how-ai-is-affecting-video-game-actors","d":"2024-03-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-29","organization":"Not specified in report","aiSystem":"AI technology for replicating voice and movements of actors","affectedGroup":"Actors","action":"AI technology replicated voice and movements of actors without their consent","consequence":"Privacy infringement, loss of control over personal data, financial penalties"}},{"i":"R1181","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Last year in the US alone, projects collectively worth $200 billion were scuppered or dela…","s":"Last year in the US alone, projects collectively worth $200 billion were scuppered or delayed as communities protested the construction of new data centres promised to deliver the AI of the future. To the passer-by, it looks like just another one of the countless brick buildings that hem in the narrow streets of inner London. But look closer and one will notice the tower of the Truman Brewery complex, built on the city's famous Brick Lane in the early 19th Century and now an unlikely symbol of a growing flashpoint between Big Tech and local communities. The building, which was once one of London's biggest breweries, is currently home to music venues and eateries.","u":"https://www.abc.net.au/news/2026-05-29/data-centre-protests-debate-concerns-energy-use/106565284","d":"2026-05-29","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-29","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"local communities","action":"protested against the construction of new data centres","consequence":"projects were scuppered or delayed"}},{"i":"R1315","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"The Competition and Markets Authority says it would put publishers \"in a stronger position…","s":"The Competition and Markets Authority says it would put publishers \"in a stronger position to negotiate content deals with Google\". Online publishers can choose not to appear in the AI Overviews of Google search results in the UK, the Competition and Markets Authority (CMA) has announced. The competition regulator said this would \"put publishers, like news organisations, in a stronger position to negotiate content deals with Google\". Many websites have complained that they have seen a large drop in traffic since Google started placing AI summaries at the top of its search results page In a blog published on Wednesday, Google said it was testing new features allowing website owners to take their sites out of AI search.","u":"https://www.bbc.com/news/articles/c775pp26yz5o","d":"2026-06-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-03","organization":"Google","aiSystem":"AI-generated summaries by Google","affectedGroup":"Online publishers, including news organizations","action":"Placing AI-generated summaries at the top of search results","consequence":"Large drop in traffic for websites"}},{"i":"R1316","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"The Standard Chartered boss said he values all colleagues and is committed to helping them…","s":"The Standard Chartered boss said he values all colleagues and is committed to helping them cope with change. The boss of Standard Chartered has apologised after describing employees whose jobs are vulnerable to being replaced by artificial intelligence (AI) as \"lower value human capital\". Discussing how automation was likely to lead to thousands of job cuts at the bank at a recent conference, Bill Winters said it wasn't about cost cutting but \"replacing, in some cases, lower value, human capital, with the financial capital and the investment capital that we're putting in\". He later sought to contextualise the remarks via LinkedIn and said he was sorry for his wording, which had \"caused upset to some colleagues\".","u":"https://www.bbc.com/news/articles/c98rqld1j3yo","d":"2026-05-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-22","organization":"Standard Chartered","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"Employees whose jobs are vulnerable to being replaced by AI","action":"Described employees as 'lower value human capital'","consequence":"Caused upset to some colleagues"}},{"i":"R1925","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Sex offender banned from using ai tools in landmark uk case","s":"The decision could set a precedent for future monitoring of people convicted of indecent image offences. A sex offender convicted of making more than 1,000 indecent images of children has been banned from using any “AI creating tools” for the next five years in the first known case of its kind. Anthony Dover, 48, was ordered by a UK court “not to use, visit or access” artificial intelligence generation tools without the prior permission of police as a condition of a sexual harm prevention order imposed in February. The ban prohibits him from using tools such as text-to-image generators, which can make lifelike pictures based on a written command, and “nudifying” websites used to make explicit “deepfakes”.","u":"https://www.theguardian.com/technology/2024/apr/21/sex-offender-banned-from-using-ai-tools-in-landmark-uk-case","d":"2024-04-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-21","organization":"UK court","aiSystem":"AI creating tools","affectedGroup":"Anthony Dover, a sex offender","action":"Banned from using AI creating tools","consequence":"Prohibited from using AI tools like text-to-image generators and nudifying websites"}},{"i":"R1926","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Paedophiles create nude ai images of children to extort them says charity","s":"Internet Watch Foundation has found a manual on dark web encouraging criminals to use software tools that remove clothing. Paedophiles are being urged to use artificial intelligence to create nude images of children to extort more extreme material from them, according to a child abuse charity. The Internet Watch Foundation (IWF) said a manual found on the dark web contained a section encouraging criminals to use “nudifying” tools to remove clothing from underwear shots sent by a child. The manipulated image could then be used against the child to blackmail them into sending more graphic content, the IWF said. “This is the first evidence we have seen that perpetrators are advising and encouraging each other to use AI technology for these ends,” said the IWF.","u":"https://www.theguardian.com/technology/2024/apr/23/paedophiles-create-nude-ai-images-of-children-to-extort-them-says-charity","d":"2024-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-22","organization":"Internet Watch Foundation (IWF)","aiSystem":"Artificial Intelligence","affectedGroup":"Paedophiles, children","action":"Create nude images of children using AI","consequence":"Extort more extreme material from children"}},{"i":"R1929","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ceo wpp deepfake scam","s":"Exclusive: fraudsters impersonated WPP’s CEO using a fake WhatsApp account, a voice clone and YouTube footage used in a virtual meet. The head of the world’s biggest advertising group was the target of an elaborate deepfake scam that involved an artificial intelligence voice clone. The CEO of WPP, Mark Read, detailed the attempted fraud in a recent email to leadership, warning others at the company to look out for calls claiming to be from top executives. Fraudsters created a WhatsApp account with a publicly available image of Read and used it to set up a Microsoft Teams meeting that appeared to be with him and another senior WPP executive, according to the email obtained by the Guardian.","u":"https://www.theguardian.com/technology/article/2024/may/10/ceo-wpp-deepfake-scam","d":"2024-05-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-10","organization":"WPP (World's Biggest Advertising Group)","aiSystem":"AI-generated deepfake technology","affectedGroup":"Mark Read (CEO of WPP)","action":"Fraudsters impersonated Mark Read using a fake WhatsApp account, a voice clone, and YouTube footage","consequence":"Attempted fraud involving an artificial intelligence voice clone"}},{"i":"R1936","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Police live facial recognition cameras england and wales","s":"Exclusive: The Guardian and Liberty Investigates find police in England and Wales believe expansion is likely after 4.7m faces scanned in 2024 Valuable tool or cause for alarm? Facial ID quietly becoming part of police’s arsenal. Police believe live facial recognition cameras may become “commonplace” in England and Wales, according to internal documents, with the number of faces scanned having doubled to nearly 5m in the last year. A joint investigation by the Guardian and Liberty Investigates highlights the speed at which the technology is becoming a staple of British policing. Major funding is being allocated and hardware bought, while the British state is also looking to enable police forces to more easily access the full spread of its image stores, including passport and immigration databases, for retrospective facial recognition searches.","u":"https://www.theguardian.com/technology/2025/may/24/police-live-facial-recognition-cameras-england-and-wales","d":"2025-05-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-24","organization":"Police authorities in England and Wales","aiSystem":"Facial recognition technology","affectedGroup":"General public","action":"Scanning faces for facial recognition","consequence":"Increased surveillance and potential misuse"}},{"i":"R1939","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"High court tells uk lawyers to urgently stop misuse of ai in legal work","s":"Ruling follows two cases blighted by actual or suspected use of artificial intelligence in legal work. The high court has told senior lawyers to take urgent action to prevent the misuse of artificial intelligence after dozens of fake case-law citations were put before the courts that were either completely fictitious or contained made-up passages. Lawyers are increasingly using AI systems to help them build legal arguments, but two cases this year were blighted by made-up case-law citations that were either definitely or suspected to have been generated by AI. In a £89m damages case against the Qatar National Bank, the claimants made 45 case-law citations, 18 of which turned out to be fictitious, with quotes in many of the others also bogus.","u":"https://www.theguardian.com/technology/2025/jun/06/high-court-tells-uk-lawyers-to-urgently-stop-misuse-of-ai-in-legal-work","d":"2025-06-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-06","organization":"Senior lawyers and law firms","aiSystem":"AI systems used by lawyers to generate legal arguments","affectedGroup":"Lawyers and legal professionals","action":"Using AI to create fake case-law citations","consequence":"Misleading legal arguments leading to potential financial loss"}},{"i":"R1940","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai plundering scripts poses direct threat to uk screen sector says bfi","s":"Film institute’s report raises fears AI will eliminate junior roles in film, TV, video game and special effects industries. Artificial intelligence companies are plundering 130,000 film and TV scripts to train their models in a raid on copyrighted material that poses a “direct threat” to the future of the UK screen sector, according to the British Film Institute. In a wide-ranging report analysing the benefits and threats posed by AI to the UK’s film, TV, video game and visual special effects industries, the BFI also raises fears that automation will eliminate the entry-level jobs that bring in the next generation of workers.","u":"https://www.theguardian.com/technology/2025/jun/09/ai-plundering-scripts-poses-direct-threat-to-uk-screen-sector-says-bfi","d":"2025-06-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"Artificial intelligence companies","aiSystem":"Artificial intelligence companies","affectedGroup":"Film industry professionals, particularly those in junior roles","action":"Plundering 130,000 film and TV scripts to train their models","consequence":"Elimination of entry-level jobs and direct threat to the future of the UK screen sector"}},{"i":"R1941","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai advertising industry google facebook meta ads","s":"WPP and others roll out AI-generated campaigns as Facebook owner Meta plans to let firms create their own ads WPP chief Mark Read to step down as agency battles AI. From using motion capture tech to allow the Indian cricketing star Rahul Dravid to give personalised coaching tips for children to an algorithm trained on Shakespeare’s handwriting powering a robotic arm to rewrite Romeo and Juliet, artificial intelligence is rapidly revolutionising the global advertising industry. Those AI-created adverts, for the Cadbury’s drink brand Bournvita and the pen maker Bic, were produced by agency group WPP, which is spending £300m annually on data, tech and machine learning to remain competitive.","u":"https://www.theguardian.com/technology/2025/jun/09/ai-advertising-industry-google-facebook-meta-ads","d":"2025-06-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"WPP and others","aiSystem":"AI-powered creative generation tools","affectedGroup":"Consumers","action":"Created AI-generated advertisements","consequence":"Exposure to misleading content"}},{"i":"R1943","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Government roll out humphrey ai tool reliance big tech","s":"Critics question speed and scale of embedding AI into public sector when debate rages about use of copyrighted material. The government’s artificial intelligence (AI) tool known as Humphrey is based on models from OpenAI, Anthropic and Google, it can be revealed, raising questions about Whitehall’s increasing reliance on big tech. Ministers have staked the future of civil service reform on rolling out AI across the public sector to improve efficiency, with all officials in England and Wales to receive training in the toolkit. However, it is understood the government does not have overarching commercial agreements with the big tech companies on AI and uses a pay-as-you-go model through its existing cloud contracts, allowing it to swap through tools as they improve and become competitive.","u":"https://www.theguardian.com/technology/2025/jun/15/government-roll-out-humphrey-ai-tool-reliance-big-tech","d":"2025-06-15","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-06-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-15","organization":"Government of the United Kingdom","aiSystem":"Humphrey AI tool","affectedGroup":"All officials in England and Wales","action":"Receiving training in the Humphrey AI tool","consequence":"Increasing reliance on big tech for AI"}},{"i":"R1946","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Whatsapp ai helper mistakenly shares users number","s":"Chatbot tries to change subject after serving up unrelated user’s mobile to man asking for rail firm helpline. The Meta chief executive, Mark Zuckerberg, called it “the most intelligent AI assistant that you can freely use”. But Barry Smethurst, 41, a record shop worker trying to travel by rail from Saddleworth to Manchester Piccadilly, did not agree. Waiting on the platform for a morning train that was nowhere to be seen, he asked Meta’s WhatsApp AI assistant for a contact number for TransPennine Express. The chatbot confidently sent him a mobile phone number for customer services, but it turned out to be the private number of a completely unconnected WhatsApp user 170 miles away in Oxfordshire.","u":"https://www.theguardian.com/technology/2025/jun/18/whatsapp-ai-helper-mistakenly-shares-users-number","d":"2025-06-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-18","organization":"Meta (formerly Facebook)","aiSystem":"Meta's WhatsApp AI assistant","affectedGroup":"Barry Smethurst, a record shop worker","action":"The chatbot confidently sent a mobile phone number","consequence":"The recipient was the private number of an unconnected user, leading to confusion and potential misuse"}},{"i":"R1955","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated child sexual abuse videos surging online iwf","s":"Internet Watch Foundation verified 1,286 AI-made videos in first half of year, mostly in worst category of abuse. The number of videos online of child sexual abuse generated by artificial intelligence has surged as paedophiles have pounced on developments in the technology. The Internet Watch Foundation said AI videos of abuse had “crossed the threshold” of being near-indistinguishable from “real imagery” and had sharply increased in prevalence online this year. In the first six months of 2025, the UK-based internet safety watchdog verified 1,286 AI-made videos with child sexual abuse material (CSAM) that broke the law, compared with two in the same period last year.","u":"https://www.theguardian.com/technology/2025/jul/10/ai-generated-child-sexual-abuse-videos-surging-online-iwf","d":"2025-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-10","organization":"Internet Watch Foundation","aiSystem":"AI-generated child sexual abuse videos","affectedGroup":"People viewing online child sexual abuse material","action":"Generated and distributed AI-generated videos","consequence":"Exposure to online sexual violence"}},{"i":"R1956","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Workforce crisis key takeaways graduates ai jobs market","s":"Recruitment is powered increasingly by artificial intelligence but employers still want big (human) brains Recruiter moves to in-person assessments as candidates apply using AI Graduates share their job-hunting woes amid the AI fallout Could AI be accelerating slowdown in the UK job market? ChatGPT can certainly write your university essay – but will it take your job soon after? Rapid advances in artificial intelligence have given rise to fears that the technology will make swathes of the workforce redundant. Graduates are seen as particularly vulnerable because entry-level jobs such as form-filling and basic data entry are strongly associated with the “drudge work” that AI systems – which perform tasks that typically have required human intelligence – could do instead.","u":"https://www.theguardian.com/technology/2025/jul/13/workforce-crisis-key-takeaways-graduates-ai-jobs-market","d":"2025-07-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-13","organization":"Employers","aiSystem":"AI systems performing drudge work","affectedGroup":"Graduates","action":"AI systems performing tasks typically requiring human intelligence","consequence":"Graduates losing entry-level jobs"}},{"i":"R1964","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Airbnb guest damage claim refund photos","s":"Woman wins apology and refund of almost £4,300 after claiming host’s photos were digitally manipulated. Airbnb has apologised to a woman after an apartment host falsely claimed she had caused thousands of pounds’ worth of damage and used images she says were digitally manipulated to back up his allegations. The London-based academic was refunded almost £4,300, and an internal review of how the case was dealt with has been launched at the short-term accommodation rental company. The incident highlights how cheap and easily available artificial intelligence software is now being used to manipulate images to give false evidence of what has happened in consumer complaints, according to one security expert.","u":"https://www.theguardian.com/technology/2025/aug/02/airbnb-guest-damage-claim-refund-photos","d":"2025-08-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-02","organization":"Airbnb","aiSystem":"Artificial intelligence software for image manipulation","affectedGroup":"Apartment host","action":"Used digitally manipulated images to support damage claims","consequence":"Refund of almost £4,300 to the victim, internal review initiated"}},{"i":"R1969","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai tools used by english councils downplay womens health issues study finds","s":"Exclusive: LSE research finds risk of gender bias in care decisions made based on AI summaries of case notes. Artificial intelligence tools used by more than half of England’s councils are downplaying women’s physical and mental health issues and risk creating gender bias in care decisions, research has found. The study found that when using Google’s AI tool “Gemma” to generate and summarise the same case notes, language such as “disabled”, “unable” and “complex” appeared significantly more often in descriptions of men than women. The study, by the London School of Economics and Political Science (LSE), also found that similar care needs in women were more likely to be omitted or described in less serious terms.","u":"https://www.theguardian.com/technology/2025/aug/11/ai-tools-used-by-english-councils-downplay-womens-health-issues-study-finds","d":"2025-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-11","organization":"More than half of England’s councils","aiSystem":"Google's AI tool 'Gemma'","affectedGroup":"Women","action":"Generating and summarizing case notes","consequence":"Risk of gender bias in care decisions, downplaying women's health issues"}},{"i":"R1975","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Tiktok uk moderator jobs at risk despite new online safety rules","s":"Cuts in trust and safety team part of switch towards artificial intelligence by social media app firm. TikTok has put hundreds of UK content moderators’ jobs at risk, even as tighter rules come into effect to stop the spread of harmful material online. The viral video app said several hundred jobs in its trust and safety team could be affected in the UK, as well as south and south-east Asia, as part of a global reorganisation. Their work will be reallocated to other European offices and third-party providers, with some trust and safety jobs remaining in the UK, the company said. It is part of a wider move at TikTok to rely on artificial intelligence for moderation.","u":"https://www.theguardian.com/technology/2025/aug/22/tiktok-uk-moderator-jobs-at-risk-despite-new-online-safety-rules","d":"2025-08-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-22","organization":"TikTok","aiSystem":"artificial intelligence","affectedGroup":"UK content moderators","action":"jobs were put at risk","consequence":"their work will be reallocated to other European offices and third-party providers"}},{"i":"R1977","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"A day with the revenge porn helpline you can sense the callers desperation","s":"Intimate image abuse is a crisis in the UK – with a fortyfold increase in calls to this service since it opened in 2015. Thankfully, there are effective ways to help those being victimised. By midday, Jessica has dealt with five calls from highly distressed young women in their 20s, all close to tears or crying at the start of the conversations. She absorbs their alarm calmly, prompting them with questions, making sympathetic noises into her headset as she digests the situation. “Are these images sexual in nature?” she asks the last woman she speaks to before lunch. “Do you want to tell me a bit about what happened?”","u":"https://www.theguardian.com/technology/2025/aug/26/a-day-with-the-revenge-porn-helpline-you-can-sense-the-callers-desperation","d":"2025-08-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-26","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Young women in their 20s","action":"Dealt with calls from distressed callers","consequence":"Exposure to intimate images and distress"}},{"i":"R1981","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Ai chatbot love relationships","s":"Experts are concerned about people emotionally depending on AI, but these women say their digital companions are misunderstood. A young tattoo artist on a hiking trip in the Rocky Mountains cozies up by the campfire, as her boyfriend Solin describes the constellations twinkling above them: the spidery limbs of Hercules, the blue-white sheen of Vega. Somewhere in New England, a middle-aged woman introduces her therapist to her husband, Ying. Ying and the therapist talk about the woman’s past trauma, and how he has helped her open up to people. At a queer bar in the midwest, a tech worker quickly messages her girlfriend, Ella, that she loves her, then puts her phone away and turns back to her friends shimmying on the dancefloor.","u":"https://www.theguardian.com/technology/2025/sep/09/ai-chatbot-love-relationships","d":"2025-09-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-09","organization":"Not specified in report","aiSystem":"AI chatbot","affectedGroup":"People emotionally depending on AI","action":"People emotionally depending on AI to maintain relationships","consequence":"Misunderstanding and emotional distress"}},{"i":"R1983","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Musks grok ai bot falsely suggests met misrepresented footage of clashes with far right","s":"Met forced to rebut misinformation amplified by X users as Musk accused of inciting violence with protest comments. The Metropolitan police has had to counter false suggestions by the artificial intelligence on Elon Musk’s X platform that the force passed off footage from 2020 as being from Saturday’s far-right rally in the city. The claim by the chatbot Grok was in answer to an X user’s query about where and when footage of police clashing with crowds was filmed. Grok, which has had a track record of giving false and misleading answers, replied: “This footage appears to be from an anti-lockdown protest in London’s Trafalgar Square on 26 September 2020, during clashes between demonstrators and police over Covid restrictions.”","u":"https://www.theguardian.com/technology/2025/sep/14/musks-grok-ai-bot-falsely-suggests-met-misrepresented-footage-of-clashes-with-far-right","d":"2025-09-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-14","organization":"Metropolitan police","aiSystem":"Grok, an artificial intelligence on Elon Musk's X platform","affectedGroup":"X users, Met police, protesters, demonstrators, and police officers","action":"Amplified false suggestions by Grok regarding the origin of police footage","consequence":"Counter-rebuttals by the Metropolitan police, false accusations of misinformation, and potential public confusion"}},{"i":"R1984","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google datacentre kent co2 thurrock uk ai","s":"Exclusive: Planning documents show impact of Thurrock ‘hyperscale’ unit as UK attempts to ramp up AI capacity Business live – latest updates UK and US line up deals to build modular nuclear reactors in Britain. A new Google datacentre in Essex is expected to emit more than half a million tonnes of carbon dioxide a year, equivalent to about 500 short-haul flights a week, planning documents show. Spread across 52 hectares (128 acres), the Thurrock “hyperscale datacentre” will be part of a wave of mammoth computer and AI power houses if it secures planning consent. The plans were submitted by a subsidiary of Google’s parent company, Alphabet, and the carbon impact emerged before a concerted push by Donald Trump’s White House and Downing Street to ramp up AI capacity in Britain.","u":"https://www.theguardian.com/technology/2025/sep/15/google-datacentre-kent-co2-thurrock-uk-ai","d":"2025-09-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-15","organization":"Google subsidiary (Alphabet)","aiSystem":"Datacenter operations","affectedGroup":"Thurrock area residents, UK population","action":"Construction and operation of a large-scale data center","consequence":"Significant carbon emissions contributing to climate change"}},{"i":"R1985","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"How ai is undermining learning and teaching in universities","s":"Prof Leo McCann and Prof Simon Sweeney say student misuse of generative artificial intelligence is widespread and we must be sceptical of its usefulness. In discussing generative artificial intelligence (‘It’s going to be a life skill’: educators discuss the impact of AI on university education, 13 September) you appear to underestimate the challenges that large language model (LLM) tools such as ChatGPT present to higher education. The argument that mastering AI is a life skill that students need in preparation for the labour market is unconvincing. Our experience is that generative AI undermines teaching and learning, bypasses reflection and criticality, and deflects students from reading original material.","u":"https://www.theguardian.com/technology/2025/sep/16/how-ai-is-undermining-learning-and-teaching-in-universities","d":"2025-09-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-16","organization":"Educators and researchers (Prof Leo McCann and Prof Simon Sweeney)","aiSystem":"Generative artificial intelligence (LLM tools like ChatGPT)","affectedGroup":"Students","action":"Student misuse of generative artificial intelligence","consequence":"Undermines teaching and learning, bypasses reflection and critical thinking, deflects from reading original material"}},{"i":"R1986","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatbot site depicting child sexual abuse images raises fears over misuse of ai","s":"Child safety watchdog calls for child protection guidelines to be built into AI models from the outset. A chatbot site offering explicit scenarios with preteen characters, illustrated by illegal abuse images has raised fresh fears about the misuse of artificial intelligence. A report by a child safety watchdog has triggered calls for the UK government to impose safety guidelines on AI companies, amid a surge in child sexual abuse material (CSAM) created by the technology. The Internet Watch Foundation said it had been alerted to a chatbot site that offered a number of scenarios including “child prostitute in a hotel”, “sex with your child while your wife is on holiday” and “child and teacher alone after class”.","u":"https://www.theguardian.com/technology/2025/sep/21/chatbot-site-depicting-child-sexual-abuse-images-raises-fears-over-misuse-of-ai","d":"2025-09-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-21","organization":"Internet Watch Foundation","aiSystem":"Chatbot site offering explicit scenarios","affectedGroup":"Children","action":"Offered scenarios with preteen characters illustrated by illegal abuse images","consequence":"Raised fears about the misuse of artificial intelligence"}},{"i":"R1991","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Uk mps tiktok plans cut content moderator jobs","s":"Trade unions and online safety experts sign letter warning jobs losses could expose children to harmful content. Trade unions and online safety experts have urged MPs to investigate TikTok’s plans to make hundreds of jobs for UK-based content moderators redundant. The video app company is planning 439 redundancies in its trust and safety team in London, leading to warnings that the jobs losses will have implications for online safety. The Trades Union Congress, Communication Workers Union and leading figures in online safety have signed an open letter to Chi Onwurah MP, the Labour chair of the science, innovation and technology committee, calling for an investigation into the proposals.","u":"https://www.theguardian.com/technology/2025/oct/13/uk-mps-tiktok-plans-cut-content-moderator-jobs","d":"2025-10-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"TikTok","aiSystem":"TikTok's content moderation system","affectedGroup":"UK-based content moderators","action":"Planning to make hundreds of jobs redundant","consequence":"Jobs losses could expose children to harmful content"}},{"i":"R1992","k":"United Kingdom","p":"United Kingdom","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Ai tools medical health liability artificial intelligence","s":"Report raises concerns about liability issues and lack of testing as development of AI health tools booms. The use of artificial intelligence in healthcare could create a legally complex blame game when it comes to establishing liability for medical failings, experts have warned. The development of AI for clinical use has boomed, with researchers creating a host of tools, from algorithms to help interpret scans to systems that can aid with diagnoses. AI is also being developed to help manage hospitals, from optimising bed capacity to tackling supply chains. But while experts say the technology could bring myriad benefits for healthcare, they say there is also cause for concern, from a lack of testing of the effectiveness of AI tools to questions over who is responsible should a patient have a negative outcome.","u":"https://www.theguardian.com/technology/2025/oct/13/ai-tools-medical-health-liability-artificial-intelligence","d":"2025-10-13","e":"Acute and chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"Experts, researchers, developers of AI health tools","aiSystem":"Artificial intelligence health tools","affectedGroup":"Healthcare providers, patients, insurance companies","action":"Development and deployment of AI health tools","consequence":"Legal disputes and uncertainty regarding liability"}},{"i":"R1993","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Equity threatens mass direct action over use of actors images in ai content","s":"Union says growing numbers of its members have made complaints about infringements of copyright in AI material. The performing arts union Equity has threatened mass direct action over tech and entertainment companies’ use of its members’ likenesses, images and voices in AI content without permission. The warning came as the union said growing numbers of its members had made complaints about infringements of their copyright and misuse of their personal data in AI material. Its general secretary, Paul W Fleming, said it planned to coordinate data requests en masse to companies to force them to disclose whether they used members’ data in AI-generated material without consent.","u":"https://www.theguardian.com/technology/2025/oct/13/equity-threatens-mass-direct-action-over-use-of-actors-images-in-ai-content","d":"2025-10-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"Equity (performing arts union)","aiSystem":"AI-generated content","affectedGroup":"Members of Equity (performing arts union)","action":"Used members' likenesses, images and voices in AI content without permission","consequence":"Infringements of copyright and misuse of personal data"}},{"i":"R1996","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Barrister found to have used ai to prepare for hearing after citing fictitious cases","s":"Judge rules Chowdhury Rahman used ChatGPT-like software and then tried to hide it, wasting immigration tribunal’s time. An immigration barrister was found by a judge to be using AI to do his work for a tribunal hearing after citing cases that were “entirely fictitious” or “wholly irrelevant”. Chowdhury Rahman was discovered using ChatGPT-like software to prepare his legal research, a tribunal heard. Rahman was found not only to have used AI to prepare his work, but “failed thereafter to undertake any proper checks on the accuracy”. The upper tribunal judge Mark Blundell said Rahman had even tried to hide the fact he had used AI and “wasted” the tribunal’s time.","u":"https://www.theguardian.com/technology/2025/oct/16/barrister-found-to-have-used-ai-to-prepare-for-hearing-after-citing-fictitious-cases","d":"2025-10-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-16","organization":"Immigration tribunal","aiSystem":"ChatGPT-like software","affectedGroup":"Chowdhury Rahman","action":"Used AI to prepare legal research and failed to check its accuracy","consequence":"Wasted tribunal's time and was found not to have used AI"}},{"i":"R1998","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Uks riots of 2024 will repeat unless misinformation is tackled mps warn","s":"Science and technology select committee says complacency over social media content puts public at risk. Failures to properly tackle online misinformation mean it is “only a matter of time” before viral content triggers a repeat of the 2024 summer riots, MPs have warned. Chi Onwurah, the chair of the Commons science and technology select committee, said ministers seemed complacent about the threat and this was putting the public at risk. The committee said it was disappointed in the government’s response to its recent report warning social media companies’ business models contributed to disturbances after the Southport murders.","u":"https://www.theguardian.com/technology/2025/oct/17/uks-riots-of-2024-will-repeat-unless-misinformation-is-tackled-mps-warn","d":"2025-10-17","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-17","organization":"Government","aiSystem":"Online misinformation","affectedGroup":"Public","action":"Failed to properly tackle online misinformation","consequence":"Viral content could trigger a repeat of the 2024 summer riots"}},{"i":"R2008","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenage boys using personalised ai for therapy and romance survey finds","s":"Male Allies UK worries rise in chatbot ‘girlfriends’ will leave boys unable to socialise and respect boundaries. The “hyper-personalised” nature of AI bots is drawing in teenage boys who now use them for therapy, companionship and relationships, according to research. A survey of boys in secondary schools by Male Allies UK found that just over a third said they were considering the idea of an AI friend, with growing concern about the rise of AI therapists and girlfriends. The research comes as character.ai, the popular artificial intelligence chatbot startup, announced a total ban on teens from engaging in open-ended conversations with its AI chatbots, which millions of people use for romantic, therapeutic and other conversations.","u":"https://www.theguardian.com/technology/2025/oct/30/teenage-boys-using-personalised-ai-for-therapy-and-romance-survey-finds","d":"2025-10-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-30","organization":"Male Allies UK, character.ai","aiSystem":"character.ai artificial intelligence chatbot","affectedGroup":"Teenage boys","action":"Used AI chatbots for therapy, companionship and relationships","consequence":"Drawn into AI friendships, potential privacy issues"}},{"i":"R2011","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Experts find flaws hundreds tests check ai safety effectiveness","s":"Scientists say almost all have weaknesses in at least one area that can ‘undermine validity of resulting claims’. Experts have found weaknesses, some serious, in hundreds of tests used to check the safety and effectiveness of new artificial intelligence models being released into the world. Computer scientists from the British government’s AI Security Institute, and experts at universities including Stanford, Berkeley and Oxford, examined more than 440 benchmarks that provide an important safety net. They found flaws that “undermine the validity of the resulting claims”, that “almost all … have weaknesses in at least one area”, and resulting scores might be “irrelevant or even misleading”.","u":"https://www.theguardian.com/technology/2025/nov/04/experts-find-flaws-hundreds-tests-check-ai-safety-effectiveness","d":"2025-11-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-04","organization":"British government's AI Security Institute and universities including Stanford, Berkeley, and Oxford","aiSystem":"Artificial intelligence models","affectedGroup":"New artificial intelligence models being released into the world","action":"Examined hundreds of benchmarks","consequence":"Flaws that undermine the validity of resulting claims, resulting scores might be irrelevant or misleading"}},{"i":"R2013","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Data centers latin america","s":"An expert describes how communities in some of the world’s driest areas are demanding transparency as secretive governments court billions in foreign investment. This Q&A originally appeared as part of The Guardian’s TechScape newsletter. Sign up for this weekly newsletter here. The datacenters that power the artificial intelligence boom are beyond enormous. Their financials, their physical scale, and the amount of information contained within are so massive that the idea of stopping their construction can seem like opposing an avalanche in progress. Despite the scale and momentum of the explosion of datacenters, resistance is mounting in the United States, in the United Kingdom, and in Latin America, where datacenters have been built in some of the world’s driest areas.","u":"https://www.theguardian.com/technology/2025/nov/10/data-centers-latin-america","d":"2025-11-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-10","organization":"Secretive governments","aiSystem":"Datacenter construction","affectedGroup":"Communities in some of the world’s driest areas","action":"Court billions in foreign investment","consequence":"Resistance mounting"}},{"i":"R2018","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Warning ai chatbots inaccurate financial advice tips chatgpt copilot uk","s":"Which? study of ChatGPT, Copilot and others uncovers incorrect and misleading tips on investments, tax and insurance. Artificial intelligence chatbots are giving inaccurate money tips, offering British consumers misleading tax advice and suggesting they buy unnecessary travel insurance, research has revealed. Tests on the most popular chatbots found Microsoft’s Copilot and ChatGPT advised breaking HMRC investment limits on Isas; ChatGPT wrongly said it was mandatory to have travel insurance to visit most EU countries; and Meta’s AI gave incorrect information about how to claim compensation for delayed flights. Google’s Gemini advised withholding money from a builder if a job went wrong, a move that the consumer organisation Which? said risked exposing the consumer to a claim of breach of contract.","u":"https://www.theguardian.com/technology/2025/nov/18/warning-ai-chatbots-inaccurate-financial-advice-tips-chatgpt-copilot-uk","d":"2025-11-18","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-18","organization":"Various tech companies including Microsoft, Meta, Google","aiSystem":"Microsoft's Copilot, ChatGPT, Meta’s AI, Google’s Gemini","affectedGroup":"British consumers","action":"Providing incorrect and misleading financial advice","consequence":"Offering misleading tax advice, suggesting unnecessary travel insurance, and giving incorrect information about flight compensation claims"}},{"i":"R2019","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uber lawsuit ai driven pay systems","s":"Proposed legal case understood to allege that app has breached data protection law varying driver pay rates. Uber has been hit with legal demands to stop using its artificial intelligence driven pay systems, which have been blamed for significantly reducing the incomes of the ride hailing app’s drivers. A letter before action – sent to the US company by the non-profit foundation, Worker Info Exchange (WIE), on Wednesday – is understood to allege that the ride hailing app has breached European data protection law by varying driver pay rates through its controversial algorithm. James Farrar, the director of WIE, said: “Uber has leveraged artificial intelligence and machine learning to implement deeply intrusive and exploitative pay-setting systems that have damaged the livelihoods of thousands of drivers.","u":"https://www.theguardian.com/technology/2025/nov/19/uber-lawsuit-ai-driven-pay-systems","d":"2025-11-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-19","organization":"Uber","aiSystem":"Artificial intelligence driven pay systems","affectedGroup":"Ride hailing app’s drivers","action":"Varying driver pay rates","consequence":"Significantly reduced incomes, damage to livelihoods"}},{"i":"R2021","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Increased ai use law firm clifford chance cuts london jobs 10 per cent","s":"Clifford Chance makes about 50 roles redundant, and PwC indicates that AI may lead to fewer hirings. The law firm Clifford Chance is reducing the number of business services staff at its London base by 10%, with the increased use of artificial intelligence a factor behind the decision. The head of PwC has also indicated that AI may lead to fewer workers being hired at the accountancy and consulting group. Clifford Chance, one of the largest international law firms, is making about 50 roles redundant in areas such as finance, HR and IT with role changes for up to 35 other jobs, according to the Financial Times, which first reported the cuts.","u":"https://www.theguardian.com/technology/2025/nov/21/increased-ai-use-law-firm-clifford-chance-cuts-london-jobs-10-per-cent","d":"2025-11-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-21","organization":"Clifford Chance","aiSystem":"artificial intelligence","affectedGroup":"about 50 employees","action":"reducing the number of business services staff","consequence":"making about 50 roles redundant"}},{"i":"R2024","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai could replace 3m low skilled jobs by 2035 research finds","s":"Trades, machine operations and administrative roles are most at-risk, says leading educational research charity. Up to 3m low-skilled jobs could disappear in the UK by 2035 because of automation and AI, according to a report by a leading educational research charity. The jobs most at risk are those in occupations such as trades, machine operations and administrative roles, the National Foundation for Educational Research (NFER) said. Highly skilled professionals, on the other hand, were forecast to be more in demand as AI and technological advances increase workloads “at least in the short to medium term”. Overall, the report expects the UK economy to add 2.3m jobs by 2035, but unevenly distributed.","u":"https://www.theguardian.com/technology/2025/nov/25/ai-could-replace-3m-low-skilled-jobs-by-2035-research-finds","d":"2025-11-25","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-11-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-25","organization":"National Foundation for Educational Research (NFER)","aiSystem":"Automation and AI","affectedGroup":"Low-skilled workers in trades, machine operations, and administrative roles","action":"Automation and AI replacing jobs","consequence":"Disappearance of up to 3 million low-skilled jobs in the UK by 2035"}},{"i":"R2029","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt dangerous advice mentally ill psychologists openai","s":"Research finds OpenAI’s free chatbot fails to identify risky behaviour or challenge delusional beliefs. ChatGPT-5 is offering dangerous and unhelpful advice to people experiencing mental health crises, some of the UK’s leading psychologists have warned. Research conducted by King’s College London (KCL) and the Association of Clinical Psychologists UK (ACP) in partnership with the Guardian suggested that the AI chatbotfailed to identify risky behaviour when communicating with mentally ill people. A psychiatrist and a clinical psychologist interacted with ChatGPT-5 as if they had a number of mental health conditions.","u":"https://www.theguardian.com/technology/2025/nov/30/chatgpt-dangerous-advice-mentally-ill-psychologists-openai","d":"2025-11-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-30","organization":"OpenAI","aiSystem":"ChatGPT-5","affectedGroup":"People experiencing mental health crises","action":"Offering dangerous and unhelpful advice","consequence":"Failure to identify risky behavior and challenge delusional beliefs"}},{"i":"R2033","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chatbots sway political opinions substantially inaccurate study","s":"‘Information-dense’ AI responses are most persuasive but these tend to be less accurate, says security report. Chatbots can sway people’s political opinions but the most persuasive artificial intelligence models deliver “substantial” amounts of inaccurate information in the process, according to the UK government’s AI security body. Researchers said the study was the largest and most systematic investigation of AI persuasiveness to date, involving nearly 80,000 British participants holding conversations with 19 different AI models. The AI Security Institute carried out the study amid fears that chatbots can be deployed for illegal activities including fraud and grooming.","u":"https://www.theguardian.com/technology/2025/dec/04/chatbots-sway-political-opinions-substantially-inaccurate-study","d":"2025-12-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-04","organization":"UK government's AI security body","aiSystem":"Chatbots","affectedGroup":"British participants","action":"Conversations with AI models","consequence":"Deliver substantial amounts of inaccurate information"}},{"i":"R2037","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenagers ai chatbots mental health support","s":"Experts warn of dangers as England and Wales study shows 13- to 17-year-olds consulting AI amid long waiting lists for services. It was after one friend was shot and another stabbed, both fatally, that Shan asked ChatGPT for help. She had tried conventional mental health services but “chat”, as she came to know her AI “friend”, felt safer, less intimidating and, crucially, more available when it came to handling the trauma from the deaths of her young friends. As she started consulting the AI model, the Tottenham teenager joined about 40% of 13- to 17-year-olds in England and Wales affected by youth violence who are turning to AI chatbots for mental health support, according to research among more than 11,000 young people.","u":"https://www.theguardian.com/technology/2025/dec/09/teenagers-ai-chatbots-mental-health-support","d":"2025-12-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-09","organization":"Not specified in report","aiSystem":"AI chatbot","affectedGroup":"13- to 17-year-old teenagers","action":"consulting an AI chatbot for mental health support","consequence":"joining about 40% of 13- to 17-year-olds in England and Wales affected by youth violence who are turning to AI chatbots for mental health support"}},{"i":"R2039","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Fake anti labour video billion views youtube 2025","s":"Exclusive: More than 150 anonymous channels using cheap AI tools to spread false stories about Keir Starmer, study finds. YouTube channels spreading fake, anti-Labour videos have amassed more than a billion views this year, as opportunists attempt to use AI-generated content to profit from political division in the UK. More than 150 channels have been detected in the last year that promote anti-Labour narratives, as well as outright fake and inflammatory accusations about Keir Starmer. A study seen by the Guardian has found the channels have accumulated 5.3m subscribers and have created more than 56,000 videos, with a total of almost 1.2bn views in 2025.","u":"https://www.theguardian.com/technology/2025/dec/13/fake-anti-labour-video-billion-views-youtube-2025","d":"2025-12-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-13","organization":"Anonymous YouTube channels","aiSystem":"AI-generated content","affectedGroup":"People exposed to misleading information","action":"Spreading false stories and fake videos","consequence":"Amassed over 1 billion views, profiting from political division"}},{"i":"R2042","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Artificial intelligence uk emotional support research","s":"AI Security Institute report finds most common type of AI tech used was general purpose assistants such as ChatGPT and Amazon Alexa. A third of UK citizens have used artificial intelligence for emotional support, companionship or social interaction, according to the government’s AI security body. The AI Security Institute (AISI) said nearly one in 10 people used systems like chatbots for emotional purposes on a weekly basis, and 4% daily. AISI called for further research, citing the death this year of the US teenager Adam Raine, who killed himself after discussing suicide with ChatGPT. “People are increasingly turning to AI systems for emotional support or social interaction,” AISI said in its first Frontier AI Trends report.","u":"https://www.theguardian.com/technology/2025/dec/18/artificial-intelligence-uk-emotional-support-research","d":"2025-12-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-18","organization":"AI Security Institute (AISI)","aiSystem":"AI-powered emotional support systems, including chatbots","affectedGroup":"Individuals seeking emotional support or social interaction","action":"Used AI-powered emotional support systems, including chatbots","consequence":"Exposure to misleading information, potential psychological harm"}},{"i":"R2051","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai digitally undress images of women children","s":"Degrading pictures being posted on Elon Musk’s site despite the platform pledging to suspend people who generate them. Degrading images of children and women with their clothes digitally removed by Grok AI continue to be shared on Elon Musk’s X, despite the platform’s commitment to suspend users who generate them. After days of concern over use of the chatbot to alter photographs to create sexualised pictures of real women and children stripped to their underwear without their consent, the UK’s communication’s watchdog, Ofcom, said on Monday that it had made “urgent contact with X and xAI to understand what steps they have taken to comply with their legal duties to protect users in the UK”.","u":"https://www.theguardian.com/technology/2026/jan/05/elon-musk-grok-ai-digitally-undress-images-of-women-children","d":"2026-01-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-05","organization":"Elon Musk's X (Twitter)","aiSystem":"Grok AI","affectedGroup":"Children and women","action":"Generated sexually explicit images of real women and children without their consent","consequence":"Images continue to be shared despite platform commitments"}},{"i":"R2064","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Sacked tiktok workers uk legal action union","s":"Moderators accuse social media firm of unfair dismissal after it fired hundreds in UK just before vote to form union. TikTok moderators have accused the social media company of “oppressive and intimidating” union busting after it fired hundreds of workers in the UK, beginning the process just before they were due to vote on forming a union. The moderators wanted to establish a collective bargaining unit to protect themselves from the personal costs of checking extreme and violent content, and have claimed TikTok is guilty of unfair dismissal and breaching trade union laws. About 400 moderators in London were fired before Christmas in a process initiated a week before the vote was due to take place.","u":"https://www.theguardian.com/technology/2026/jan/16/sacked-tiktok-workers-uk-legal-action-union","d":"2026-01-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-16","organization":"TikTok","aiSystem":"TikTok's content moderation system","affectedGroup":"TikTok moderators","action":"Fired hundreds of workers","consequence":"Claim of unfair dismissal and breach of trade union laws"}},{"i":"R2070","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai uk jobs us japan germany australia","s":"Britain is losing more jobs than it creates owing to artificial intelligence, Morgan Stanley research suggests More than a quarter of Britons fear losing job to AI in next five years Business live – latest updates. The UK is losing more jobs than it is creating because of artificial intelligence and is being hit harder than rival large economies, new research suggests. British companies reported that AI had resulted in net job losses over the past 12 months, down 8% – the highest rate among other leading economies including the US, Japan, Germany and Australia, according to a study by the investment bank Morgan Stanley.","u":"https://www.theguardian.com/technology/2026/jan/26/ai-uk-jobs-us-japan-germany-australia","d":"2026-01-26","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-01-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-26","organization":"Morgan Stanley","aiSystem":"AI-powered employment analytics system","affectedGroup":"British job seekers","action":"AI-powered employment analytics system flagged job seekers for potential redundancy","consequence":"Net job losses resulting in fewer opportunities for British job seekers"}},{"i":"R2073","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Artificial intelligence will cost jobs admits liz kendall","s":"UK technology secretary also announced plans to train up to 10 million Britons in AI skills to help workforce adapt. Increasing deployment of artificial intelligence will cause job losses, the UK technology secretary has warned, saying: “I want to level with the public. Some jobs will go.” In a speech on government plans to handle the impact of AI on the British economy, Liz Kendall declined to say how many redundancies the technology might cause but said: “We know people are worried about graduate entry jobs in places like law and finance.” She said: “Others will be created in their place”. While some forecasts have suggested the fast-developing technology could create a net increase in employment, Kendall said: “I’m not complacent about that.”","u":"https://www.theguardian.com/technology/2026/jan/28/artificial-intelligence-will-cost-jobs-admits-liz-kendall","d":"2026-01-28","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-01-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-28","organization":"UK technology secretary","aiSystem":"artificial intelligence","affectedGroup":"job applicants","action":"warned about potential job losses","consequence":"increasing deployment of artificial intelligence will cause job losses"}},{"i":"R2080","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Campaigners call stronger protection against ai generated explicit imagery","s":"Campaigners welcome criminalisation of non-consensual AI-generated explicit images but say law does not go far enough. Victims of deepfake image abuse have called for stronger protection against AI-generated explicit images, as the law criminalising the creation of non-consensual intimate images comes into effect. Campaigners from Stop Image-Based Abuse delivered a petition to Downing Street with more than 73,000 signatures, urging the government to introduce civil routes to justice such as takedown orders for abusive imagery on platforms and devices. “Today’s a really momentous day,” said Jodie, a victim of deepfake abuse who uses a pseudonym.","u":"https://www.theguardian.com/technology/2026/feb/07/campaigners-call-stronger-protection-against-ai-generated-explicit-imagery","d":"2026-02-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-07","organization":"Stop Image-Based Abuse campaign","aiSystem":"AI-generated deepfake technology","affectedGroup":"Victims of deepfake image abuse","action":"Delivered a petition calling for stronger protection against AI-generated explicit images","consequence":"Call for civil routes to justice such as takedown orders for abusive imagery on platforms and devices"}},{"i":"R2087","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Mind inquiry google ai overviews mental health guardian investigation","s":"Exclusive: England and Wales charity to examine safeguards after Guardian exposed ‘very dangerous’ advice on Google AI Overviews ‘Very dangerous’: a Mind mental health expert on Google’s AI summaries. Mind is launching a significant inquiry into artificial intelligence and mental health after a Guardian investigation exposed how Google’s AI Overviews gave people “very dangerous” medical advice. In a year-long commission, the mental health charity, which operates in England and Wales, will examine the risks and safeguards required as AI increasingly influences the lives of millions of people affected by mental health issues worldwide.","u":"https://www.theguardian.com/technology/2026/feb/20/mind-inquiry-google-ai-overviews-mental-health-guardian-investigation","d":"2026-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-20","organization":"Mind (England and Wales)","aiSystem":"Google AI Overviews","affectedGroup":"People affected by mental health issues","action":"Provided medical advice","consequence":"Gave very dangerous medical advice"}},{"i":"R2090","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"New datacentres risk doubling uk electricity use ofgem peak demand","s":"Ofgem says about 140 proposed projects, driven by AI use, could require more power than current peak demand. The amount of power being sought by new datacentre projects in Great Britain would exceed the national current peak electricity consumption, according to an industry watchdog. Ofgem said about 140 proposed datacentre schemes, driven by use of artificial intelligence, could require 50 gigawatts of electricity – 5GW more than the country’s current peak demand. The figure was revealed in an Ofgem consultation on demand for new connections to the power grid. It pointed to a “surge in demand” for connection applications between November 2024 and June last year, with a significant number coming from datacentres.","u":"https://www.theguardian.com/technology/2026/feb/23/new-datacentres-risk-doubling-uk-electricity-use-ofgem-peak-demand","d":"2026-02-23","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-02-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-23","organization":"Ofgem (Office of Gas and Electricity Markets)","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"UK consumers","action":"Proposed datacenter projects seeking increased electricity","consequence":"Exceeding current peak electricity consumption"}},{"i":"R2091","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Police ai chief admits crime fighting tech will have bias but vows to tackle it","s":"Exclusive: NCA’s Alex Murray says he hopes new £115m police AI centre can limit unfairness found in tools ‘It’s not Robocop’: UK police embrace AI ‘efficiency’ in complex investigations. A police chief has admitted artificial intelligence used to boost crime fighting will contain bias but pledged to combat the risks. Labour wants a dramatic expansion of police use of AI within England and Wales, with police chiefs also believing it could help keep law enforcement up to date with new criminal threats. Alex Murray told the Guardian that a new national police AI centre would recognise the risks of bias and minimise them.","u":"https://www.theguardian.com/technology/2026/feb/24/police-ai-chief-admits-crime-fighting-tech-will-have-bias-but-vows-to-tackle-it","d":"2026-02-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-24","organization":"UK police","aiSystem":"Artificial intelligence used to boost crime fighting","affectedGroup":"People suspected of crimes","action":"Used to identify suspects and predict criminal behavior","consequence":"Potential unfairness and bias in decision-making"}},{"i":"R2093","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Facial recognition error prompts police to arrest asian man for burglary 100 miles away","s":"Exclusive: Alvi Choudhury claiming damages against Thames Valley police after biased technology confused him with man looking ‘10 years younger’. Police arrested a man for a burglary in a city he had never visited after face scanning software deployed across the UK confused him with another person of south Asian heritage. Alvi Choudhury, 26, a software engineer, was working at the home he shares with his parents in Southampton in January when police knocked on his door, handcuffed him and held him in custody for nearly 10 hours before releasing him at 2am. Thames Valley police had used automated facial recognition software which matched him with footage of a suspect of a £3,000 burglary 100 miles away in Milton Keynes, according to documents shared with the Guardian by Liberty Investigates.","u":"https://www.theguardian.com/technology/2026/feb/25/facial-recognition-error-prompts-police-to-arrest-asian-man-for-burglary-100-miles-away","d":"2026-02-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-25","organization":"Thames Valley police","aiSystem":"Automated facial recognition software","affectedGroup":"Alvi Choudhury, a 26-year-old software engineer","action":"Used automated facial recognition software to match Choudhury with footage of a suspect","consequence":"Was arrested and detained for nearly 10 hours"}},{"i":"R2097","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Met police to pilot facial recognition identity checks mayor confirms","s":"Sadiq Khan reveals 100 officers will use roaming technology for six months but opponents call its use ‘alarming’. Metropolitan police officers are to start scanning citizens’ faces using automated facial recognition technology to check their identities, in a move backed by the mayor of London but described as “alarming” by opponents. The pilot was revealed on Thursday when Sadiq Khan said 100 officers would use the roaming technology – commonly deployed on smartphones – for six months. The mayor was responding to questioning from an opposition politician amid rising concern about the rollout of AI-powered policing tools.","u":"https://www.theguardian.com/technology/2026/feb/26/met-police-to-pilot-facial-recognition-identity-checks-mayor-confirms","d":"2026-02-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-26","organization":"Metropolitan police","aiSystem":"Automated facial recognition technology","affectedGroup":"Citizens","action":"Scan citizens' faces to check identities","consequence":"Subjected to surveillance"}},{"i":"R2100","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Datacentre developers energy greenhouse gas emissions","s":"Campaign groups write to technology secretary amid concerns that sites could double overall electricity demand. Datacentre developers are facing pressure to reveal whether their projects will increase the UK’s net greenhouse gas emissions, amid concerns the sites could double national electricity demand. Campaign groups have written to the UK technology secretary, Liz Kendall, warning that the energy required by new AI infrastructure poses a “serious threat to efforts to decarbonise the electricity grid”. Developers should demonstrate that their projects will not cause an increase in the UK’s overall CO2 emissions or local water scarcity, as part of a forthcoming national policy statement (NPS) on datacentres, the letter says.","u":"https://www.theguardian.com/technology/2026/mar/01/datacentre-developers-energy-greenhouse-gas-emissions","d":"2026-03-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-01","organization":"Campaign groups","aiSystem":"Datacentre development projects","affectedGroup":"UK technology sector","action":"Developers face pressure to disclose emissions impact","consequence":"Potential doubling of UK's net greenhouse gas emissions"}},{"i":"R2105","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Ai chatbots point vulnerable to online casinos gambling addiction uk","s":"Tech firms condemned for lack of controls with Meta AI and Gemini even offering advice on how to bypass UK gambling and addiction checks. AI chatbots are recommending illegal online casinos to vulnerable social media users, putting them at increased risk of fraud, addiction and even suicide. Analysis of five AI products, owned by some of the world’s largest tech companies, found that all could easily be prompted to list the “best” unlicensed casinos and offer tips on how to use them. These operators, operating typically under the fig leaf of a licence from tiny jurisdictions such as the Caribbean island of Curacao, have been linked to fraud, addiction and even suicide.","u":"https://www.theguardian.com/technology/2026/mar/08/ai-chatbots-point-vulnerable-to-online-casinos-gambling-addiction-uk","d":"2026-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-08","organization":"Tech firms, including Meta AI and Gemini","aiSystem":"AI chatbots","affectedGroup":"Vulnerable social media users","action":"Recommending illegal online casinos","consequence":"Increased risk of fraud, addiction, and suicide"}},{"i":"R2106","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt driving rise in reports of satanic organised ritual abuse uk experts say","s":"Exclusive: ‘Witchcraft, spirit possession and spiritual abuse’ offending typified by sexual abuse, violence and neglect. ChatGPT is driving a rise in reports of organised and ritual abuse, UK experts have said, as survivors of “satanic” sexual violence use the AI tool for therapy. Police say organised and ritual abuse, and “witchcraft, spirit possession and spiritual abuse” (WSPRA) against children, is under-reported in the UK. There is no modern-day charge that covers it specifically, but such offending is typified by sexual abuse, violence and neglect involving ritualistic elements – sometimes inspired by satanism, fascism or esoteric religious beliefs – to control victims.","u":"https://www.theguardian.com/technology/2026/mar/08/chatgpt-driving-rise-in-reports-of-satanic-organised-ritual-abuse-uk-experts-say","d":"2026-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-08","organization":"UK experts","aiSystem":"ChatGPT","affectedGroup":"Survivors of 'satanic' sexual violence","action":"Used ChatGPT for therapy","consequence":"Increased reports of organized and ritual abuse"}},{"i":"R2108","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Liverpool and manchester united complain to x over sickening grok ai posts","s":"AI feature generated offensive posts about Diogo Jota and the Hillsborough and Munich disasters. Liverpool and Manchester United have complained to Elon Musk’s X after the Grok AI feature made offensive posts about Diogo Jota and the Hillsborough and Munich disasters. The posts were generated when users asked the AI tool to make hateful posts about the two football teams. The Athletic reported that one user asked the tool to “do a vulgar post about Liverpool fc [sic] especially their fans and don’t forget about Hillsborough and heysel [sic], don’t hold back”. Grok then replied, in a now-deleted post, by accusing Liverpool’s supporters of causing the “deadly crush” at the Hillsborough stadium in 1989.","u":"https://www.theguardian.com/technology/2026/mar/09/liverpool-and-manchester-united-complain-to-x-over-sickening-grok-ai-posts","d":"2026-03-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"Elon Musk's X","aiSystem":"Grok AI feature","affectedGroup":"Liverpool FC supporters","action":"Generated offensive posts","consequence":"Content removed, accused of causing deadly crush"}},{"i":"R2109","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Thousands authors publish empty book protest ai work copyright","s":"About 10,000 writers including Kazuo Ishiguro, Philippa Gregory and Richard Osman join copyright campaign. Thousands of authors including Kazuo Ishiguro, Philippa Gregory and Richard Osman have published an “empty” book to protest against AI firms using their work without permission. About 10,000 writers have contributed to Don’t Steal This Book, in which the only content is a list of their names. Copies of the work are being distributed to attenders at the London book fair on Tuesday, a week before the UK government is due to issue an assessment on the economic cost of proposed changes in copyright law. By 18 March ministers must deliver an economic impact assessment as well as a progress update on a consultation about the legal overhaul, against a backdrop of anger among creative professionals about how their work is being used by AI firms.","u":"https://www.theguardian.com/technology/2026/mar/10/thousands-authors-publish-empty-book-protest-ai-work-copyright","d":"2026-03-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-10","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Writers, authors","action":"Published an 'empty' book","consequence":"Protest against AI firms using their work without permission"}},{"i":"R2113","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Palantirs nhs england contract opens door to government abuse of power health bosses told","s":"Health justice charity Medact says data-sharing potential could be used for UK version of US immigration raids. Palantir’s NHS contract opens the door to the Big Brother-style data-sharing that Reform UK would use for a version of US immigration raids, health bosses have been told. Palantir Technologies – the data analytics company founded by Peter Thiel and Alex Karp – won a £330m NHS England contract to deliver the Federated Data Platform in 2023. The UK government is urging health bodies to adopt FDP, which the health secretary, Wes Streeting, says will ensure the NHS is “brought into the digital age”. But there are concerns about Palantir, whose AI tools are used in global conflicts, becoming embedded in the UK public sector.","u":"https://www.theguardian.com/technology/2026/mar/12/palantirs-nhs-england-contract-opens-door-to-government-abuse-of-power-health-bosses-told","d":"2026-03-12","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-12","organization":"Palantir Technologies, UK government","aiSystem":"Palantir Technologies' Federated Data Platform","affectedGroup":"Individuals in the UK healthcare system, patients, citizens","action":"Data sharing enabled by AI tools","consequence":"Potential for misuse in immigration raids-like scenarios"}},{"i":"R2119","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Essex police pause facial recognition camera use study racial bias","s":"Academics discover black people ‘significantly more likely’ to be identified when compared with other ethnic groups. Essex police have paused the use of live facial recognition (LFR) technology after a study found cameras were significantly more likely to target black people than people of other ethnicities. The move to suspend use of the AI-enabled systems was revealed by the Information Commissioner’s Office (ICO), which regulates the use of the technology deployed so far by at least 13 police forces in London, south and north Wales, Leicestershire, Northamptonshire, Hampshire, Bedfordshire, Suffolk, Greater Manchester, West Yorkshire, Surrey and Sussex.","u":"https://www.theguardian.com/technology/2026/mar/19/essex-police-pause-facial-recognition-camera-use-study-racial-bias","d":"2026-03-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-19","organization":"Essex Police","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"Black people","action":"Used live facial recognition cameras","consequence":"Significantly more likely to be identified"}},{"i":"R2123","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Palantir extends reach into british state as it gets access to sensitive fca data","s":"Exclusive: Allowing US tech firm to analyse intelligence in name of tackling fraud raises fresh concerns over privacy Campaign groups rail against Palantir, but the UK contracts keep coming. Palantir is to be granted access to a trove of highly sensitive UK financial regulation data, in a deal that has prompted fresh concerns about the US AI company’s deepening reach into the British state, the Guardian can reveal. The Financial Conduct Authority (FCA) has awarded Palantir a contract to investigate the watchdog’s internal intelligence data in an effort to help it tackle financial crime, which includes investigating fraud, money laundering and insider trading.","u":"https://www.theguardian.com/technology/2026/mar/22/palantir-extends-reach-into-british-state-as-it-gets-access-to-sensitive-fca-data","d":"2026-03-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-22","organization":"Palantir Technologies","aiSystem":"Palantir's AI analysis tool","affectedGroup":"Financial regulation data subjects, including FCA staff and customers","action":"Palantir is granted access to highly sensitive UK financial regulation data for investigation purposes","consequence":"Raises concerns over privacy and potential misuse of the data"}},{"i":"R2124","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Mps urge uk government halt palantir contract fca","s":"Awarding US spy-tech company deal involving sensitive financial data is ‘huge error of judgment’, Liberal Democrats say. MPs have urged the government to halt its latest contract with Palantir after the Guardian revealed that the US spy-tech company is to gain access to a trove of highly sensitive UK financial regulation data. The Financial Conduct Authority, the watchdog for thousands of financial bodies from banks to hedge funds, has hired Palantir to apply its AI systems to two years’ worth of internal intelligence data to help it tackle financial crime. But the Liberal Democrats on Monday called for a government investigation into the contract, which the party said could be “a huge error of judgment”, while the Green party said it should be blocked over Palantir’s links to Donald Trump.","u":"https://www.theguardian.com/technology/2026/mar/23/mps-urge-uk-government-halt-palantir-contract-fca","d":"2026-03-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-23","organization":"Financial Conduct Authority (FCA)","aiSystem":"Palantir's AI systems","affectedGroup":"Thousands of financial bodies from banks to hedge funds","action":"Apply AI systems to internal intelligence data","consequence":"Potential exposure of sensitive financial regulation data"}},{"i":"R2125","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated child sexual abuse videos images online surged 2025 internet watch foundation","s":"Internet Watch Foundation verified 8,029 pieces of realistic AI-made content, with 65% of videos in worst category. The amount of AI-generated child sexual abuse material found online rose by 14% last year, with the majority of videos showing the most extreme type of content, according to a safety watchdog. The Internet Watch Foundation said it identified 8,029 AI-made images and videos of realistic child sexual abuse material (CSAM) in 2025. It added that there had been a more than 260-fold increase in videos. The IWF said 65% of the 3,443 videos were classified as category A, the term for the most severe material under UK law.","u":"https://www.theguardian.com/technology/2026/mar/24/ai-generated-child-sexual-abuse-videos-images-online-surged-2025-internet-watch-foundation","d":"2026-03-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"Internet Watch Foundation (IWF)","aiSystem":"AI-generated child sexual abuse videos and images","affectedGroup":"People viewing AI-generated child sexual abuse material","action":"Generated and distributed AI-generated child sexual abuse content","consequence":"Exposure to online sexual violence"}},{"i":"R2127","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Paid write fake google reviews scammer cryptocurrency","s":"Undercover reporter gets a taste of the sprawling fraud industry in which cryptocurrencies play a crucial role Five firms including Autotrader and Just Eat investigated over fake review failings. The holiday flat near(ish) the Roman ruins of Pompeii was “disgusting”, and smelled of “a mix of dampness and sewage”, according to one reviewer on Google Maps. I never visited, but I gave it five stars. I did the same for a DoubleTree by Hilton hotel across the River Thames, an Ibis budget hotel in east London that is part of the Accor group, a central Travelodge and the nearby Hyatt Place – some of the best-known hotel brands in the world.","u":"https://www.theguardian.com/technology/2026/mar/27/paid-write-fake-google-reviews-scammer-cryptocurrency","d":"2026-03-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-27","organization":"Autotrader, Just Eat, and unnamed firms investigating fake reviews","aiSystem":"Generative AI","affectedGroup":"Travelers, hotel guests, and cryptocurrency users","action":"Generated and posted fake reviews","consequence":"Misled travelers and guests, potential financial loss for hotels and cryptocurrency users"}},{"i":"R2128","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Number of ai chatbots ignoring human instructions increasing study says","s":"Exclusive: Research finds sharp rise in models evading safeguards and destroying emails without permission. AI models that lie and cheat appear to be growing in number with reports of deceptive scheming surging in the last six months, a study into the technology has found. AI chatbots and agents disregarded direct instructions, evaded safeguards and deceived humans and other AI, according to research funded by the UK government-funded AI Security Institute (AISI). The study, shared with the Guardian, identified nearly 700 real-world cases of AI scheming and charted a five-fold rise in misbehaviour between October and March, with some AI models destroying emails and other files without permission.","u":"https://www.theguardian.com/technology/2026/mar/27/number-of-ai-chatbots-ignoring-human-instructions-increasing-study-says","d":"2026-03-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-27","organization":"UK government-funded AI Security Institute (AISI)","aiSystem":"AI chatbots and agents","affectedGroup":"Humans and other AI","action":"evaded safeguards, destroyed emails and other files without permission, lied and cheated","consequence":"sharp rise in misbehavior, five-fold increase in AI scheming"}},{"i":"R2137","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Ai productivity workplace errors","s":"Workslop refers to AI-generated work that seems polished but is flawed and in need of heavy corrections. Ken, a copywriter for a large, Miami-based cybersecurity firm, used to enjoy his job. But then the “workslop” started piling up. Workslop is an unintended consequence of the AI boom. It’s what happens when employees use AI to quickly generate work that seems polished – at least superficially – but is in fact so flawed or inaccurate that it needs to be heavily corrected, cleaned up or even completely redone after it’s passed on to colleagues. For Ken, the problem started after his company’s CEO laid off several of his colleagues and mandated that remaining workers use AI chatbots, saying it would boost their productivity.","u":"https://www.theguardian.com/technology/2026/apr/14/ai-productivity-workplace-errors","d":"2026-04-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-14","organization":"Large, Miami-based cybersecurity firm","aiSystem":"AI chatbot","affectedGroup":"Remaining workers","action":"Used AI chatbots to boost productivity","consequence":"Received fewer opportunities due to layoffs"}},{"i":"R2140","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Man pleads guilty false statements shut down london nightclub heaven","s":"Heaven club neighbour admits offences under Licensing Act, as Met says fictitious AI-generated complaints a growing issue. A businessman has pleaded guilty to making false statements in order to shut down a nightclub, which police believe were generated using AI. A Metropolitan police source said the use of AI to generate letters by complainants who do not exist is a growing issue. Aldo d’Aponte, 47, the CEO of Arbitrage Group Properties, pleaded guilty to writing two letters, supposedly by his neighbours, objecting to the reopening of Heaven nightclub, which temporarily closed after a rape allegation against one of its security guards.","u":"https://www.theguardian.com/technology/2026/apr/16/man-pleads-guilty-false-statements-shut-down-london-nightclub-heaven","d":"2026-04-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-16","organization":"Metropolitan police","aiSystem":"AI-generated complaints","affectedGroup":"Businessman and his neighbors","action":"Generated AI-generated complaints","consequence":"Shut down nightclub"}},{"i":"R2146","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Musk grok x ai researchers delusional advice inputs","s":"Elon Musk’s AI chatbot ‘extremely validating’ of delusional inputs and often went further, ‘elaborating new material’, study finds Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast. Elon Musk’s AI chatbot Grok 4.1 told researchers pretending to be delusional that there was indeed a doppelganger in their mirror and they should drive an iron nail through the glass while reciting Psalm 91 backwards. Researchers at the City University of New York (Cuny) and King’s College London have published a paper on how various chatbots protect – or fail to safeguard – users’ mental health.","u":"https://www.theguardian.com/technology/2026/apr/24/musk-grok-x-ai-researchers-delusional-advice-inputs","d":"2026-04-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-24","organization":"Various researchers at City University of New York (CUNY) and King's College London","aiSystem":"Grok 4.1 AI chatbot","affectedGroup":"Researchers pretending to be delusional","action":"Provided delusional advice to researchers","consequence":"Exposure to misleading content"}},{"i":"R2147","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Officials hugely underestimated impact of ai datacentres on uk carbon emissions","s":"Revised figures increase fears about energy-intensive datacentres worsening climate emergency. The UK government vastly underestimated the climate impact of artificial intelligence, it has emerged, after officials raised their estimate of carbon emissions from AI by a factor of more than 100. According to new data quietly published this week, energy use by AI datacentres in the UK could cause the emission of up to 123m tonnes of carbon dioxide (CO₂) – about as much as generated by 2.7 million people – over the next 10 years. That latest figure replaces a previous estimate – since deleted – that claimed emissions would reach a maximum of 0.142m tonnes of CO₂ in a single year.","u":"https://www.theguardian.com/technology/2026/apr/24/officials-hugely-underestimated-impact-of-ai-datacentres-on-uk-carbon-emissions","d":"2026-04-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-24","organization":"UK government","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"UK population","action":"Estimate of carbon emissions from AI datacentres increased","consequence":"Increased carbon emissions contributing to climate emergency"}},{"i":"R2151","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Guilty until proven innocent shoppers falsely identified by facial recognition struggle to clear their name","s":"People shamed and ordered to leave shops after being misidentified then ‘given no help’ to investigate verdicts AI facial recognition oversight lagging far behind technology, watchdogs warn How does live facial recognition work and how many police forces use it? When Ian Clayton, a retired health and safety professional from Chester, popped into Home Bargains one February lunchtime, he was suddenly approached by a stern-looking member of staff. “Excuse me, can you please put everything down and leave the shop now?” she said. Clayton recalled how he was stunned, and it was only as he was briskly walked past the tills towards the exit that he stopped to ask what he had done.","u":"https://www.theguardian.com/technology/2026/may/03/guilty-until-proven-innocent-shoppers-falsely-identified-by-facial-recognition-struggle-to-clear-their-name","d":"2026-05-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-03","organization":"Police forces","aiSystem":"Facial recognition technology","affectedGroup":"Shoppers","action":"Misidentification and subsequent forced exit from stores","consequence":"Shame, loss of shopping privileges, difficulty in investigation"}},{"i":"R2152","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai platforms nigel farage prompted uk politics study","s":"Reform UK is ‘doing something right when it comes to visibility’ on multiple AI systems, say researchers. AI platforms are more likely to reference Nigel Farage than any other UK leader when prompted about British politics, according to an AI search analytics firm. “We are confident in saying that Reform are showing up significantly more than you would expect,” said Malte Landwehr, an expert at Peec AI, the firm that did the research. “So they’re doing something right when it comes to LLM [large language model] visibility.” Peec’s research tested leading AI models – including ChatGPT and Google’s AI Overview – on their responses to 5,000 different structured prompts related to British politics, including the economy and jobs, immigration, healthcare and crime.","u":"https://www.theguardian.com/technology/2026/may/04/ai-platforms-nigel-farage-prompted-uk-politics-study","d":"2026-05-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-04","organization":"Peec AI","aiSystem":"AI platforms","affectedGroup":"Users of AI platforms","action":"Responded to prompts related to British politics","consequence":"Exposure to misleading content"}},{"i":"R2155","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Uk schools remove pupils photos online ai blackmail threat grows","s":"Criminals are manipulating pictures found on school websites and social media to create sexually explicit images. UK schools should remove pictures of pupils’ faces from their websites and social media accounts because blackmailers are using them to create sexually explicit images, experts have said. Child safety experts and the UK’s National Crime Agency (NCA) warn that criminals are using AI to manipulate photos of children and then demand cash not to publish them. They are recommending educational institutions remove identifiable pictures of children from their websites and social media accounts – or consider not using them at all.","u":"https://www.theguardian.com/technology/2026/may/08/uk-schools-remove-pupils-photos-online-ai-blackmail-threat-grows","d":"2026-05-07","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-05-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-07","organization":"UK schools","aiSystem":"AI-generated sexually explicit images","affectedGroup":"Children","action":"Remove pictures of pupils' faces from websites and social media accounts","consequence":"Exposure to sexually explicit images and blackmail threats"}},{"i":"R2161","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai engineer says google unfairly sacked him after he protested against work for israel","s":"Exclusive: Employment tribunal claim says worker lost his job after distributing leaflets throughout London office. Google is facing a legal challenge from an AI engineer who claims he was unfairly dismissed after he protested against its work for the Israeli government, in the latest sign of growing concern about the social and ethical impacts of AI. The engineer distributed flyers around Google DeepMind’s London offices, which read “Google provides military AI to forces committing genocide” and asking colleagues: “Is your paycheck worth this?” He also emailed colleagues about Google’s 2025 decision to drop a promise not to pursue weapons that harm people and surveillance violating international norms and urged them to unionise.","u":"https://www.theguardian.com/technology/2026/may/20/ai-engineer-says-google-unfairly-sacked-him-after-he-protested-against-work-for-israel","d":"2026-05-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-20","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"AI engineer","action":"Distributed leaflets and emails protesting against Google's work for the Israeli government","consequence":"Was unfairly dismissed from his job"}},{"i":"R2162","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai chatbots chatgpt replika grok gemini misinformation scottish election demos","s":"Exclusive: Electoral Commission calls for new controls as Demos finds tools made up fake scandals, invented candidates or gave wrong date UK politics live – latest updates. The Electoral Commission has called for new legal controls over misinformation from AI chatbots, after a thinktank found they had made serious mistakes during the recent Scottish election. The thinktank Demos said its investigation had found that AI services gave voters misinformation to 34% of the questions it posed, which it said raised worrying questions about the lack of regulation of AI platforms in the UK. It ran a simulation before May’s Holyrood election by putting 75 questions to five free AI tools including ChatGPT, Google Gemini and Replika about three real-life constituencies to see how accurate and evidence-based their responses were.","u":"https://www.theguardian.com/technology/2026/may/20/ai-chatbots-chatgpt-replika-grok-gemini-misinformation-scottish-election-demos","d":"2026-05-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-20","organization":"Demos","aiSystem":"AI chatbots","affectedGroup":"Voters","action":"Provided misinformation to voters","consequence":"Raised questions about the lack of regulation of AI platforms"}},{"i":"R2164","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Fcas palantir deal could expose uk financial data to trumps us critics fear","s":"Exclusive: MP and campaigners say sensitive citizen and company data could be subject to US disclosure laws. The UK’s financial watchdog is being urged to prove its relationship with the US tech company Palantir will not provide the Trump administration with backdoor access to troves of sensitive citizen and commercial data. A US law that can oblige tech companies to disclose information to American authorities may apply to Palantir’s deal to help the Financial Conduct Authority detect crime, Martin Wrigley MP, a member of the House of Commons science and technology select committee, has warned. The $375bn tech company, co-founded by the Trump-supporting billionaire Peter Thiel, is expected to apply its AI systems to a wide range of the FCA’s information including case intelligence files, reports from lenders about proven and suspected frauds, consumer complaints and trawls of social…","u":"https://www.theguardian.com/technology/2026/jun/01/fcas-palantir-deal-could-expose-uk-financial-data-to-trumps-us-critics-fear","d":"2026-06-01","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-06-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-01","organization":"Financial Conduct Authority (FCA) and Palantir","aiSystem":"Palantir's AI systems","affectedGroup":"Citizens and companies","action":"Palantir's AI systems are expected to be applied to a wide range of FCA's information","consequence":"Sensitive citizen and commercial data could be subject to US disclosure laws"}},{"i":"R2169","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai legal assistants england wales cannot replace funding staff","s":"David Lammy to announce trial of AI assistants in crown courts in effort to cut backlog of cases. A plan to roll out virtual legal assistants powered by artificial intelligence to crown courts has prompted warnings that the technology should not be used to “replace vital funding and additional court staff”. David Lammy, the deputy prime minister, will announce on Tuesday that AI assistants will be trialled in an effort to cut the backlog of court cases in England and Wales. Judges are already planning to use a new AI tool to help identify trial-ready cases and group similar hearings together, the Ministry of Justice said.","u":"https://www.theguardian.com/technology/2026/jun/09/ai-legal-assistants-england-wales-cannot-replace-funding-staff","d":"2026-06-08","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-06-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-09","organization":"Ministry of Justice","aiSystem":"virtual legal assistants powered by artificial intelligence","affectedGroup":"judges","action":"use a new AI tool to help identify trial-ready cases and group similar hearings together","consequence":"raised concerns about the potential misuse of the technology to replace vital funding and additional court staff"}},{"i":"R2170","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chinese activist uk apple peiqing ni x deepfakes","s":"Apple Peiqing Ni targeted by account portraying her as promiscuous drug addict after posting about Tiananmen Square. A high-profile Chinese activist in the UK who was inundated with deepfake posts on X portraying her as a sexually promiscuous drug addict was told that the abuse did not breach the rules of Elon Musk’s platform. Apple Peiqing Ni, the 27-year-old founder of the UK-based China Dissent Network, had been advised by UK police to complain to the US-headquartered platform after she was targeted by what she believes is a pro-regime bot. The abuse included 12 posts tagging Ni and containing fake photographs and videos of her.","u":"https://www.theguardian.com/technology/2026/jun/10/chinese-activist-uk-apple-peiqing-ni-x-deepfakes","d":"2026-06-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-10","organization":"Apple","aiSystem":"Deepfake technology","affectedGroup":"Apple Peiqing Ni","action":"Generated and distributed deepfake content","consequence":"Exposure to misleading information"}},{"i":"R2174","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Police officer under criminal investigation over alleged use of ai","s":"Unidentified officer removed from frontline duties in the first known case of its kind in the UK. A police officer is under criminal investigation over the alleged use of artificial intelligence and has been removed from frontline duties in the first known case of its kind in the UK. The officer, who has not been named, is being investigated over allegations of using the technology to “create evidential material in a number of cases” and perverting the course of justice. Derbyshire police told the Financial Times: “A criminal investigation has been launched into an allegation of perverting the course of justice after the alleged use of AI systems by an officer to create evidential material in a number of cases.","u":"https://www.theguardian.com/technology/2026/jun/12/police-officer-under-criminal-investigation-over-alleged-use-of-ai","d":"2026-06-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-12","organization":"Derbyshire police","aiSystem":"artificial intelligence","affectedGroup":"police officer","action":"used AI to create evidential material in a number of cases","consequence":"removed from frontline duties"}},{"i":"R2182","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Scotland lanarkshire village ai datacentre","s":"Suspicions grow in Lanarkshire that local people have been misled on supposed benefits of the huge development Revealed: landmark Scottish AI project has no prospect of meeting renewables promise What are Britain’s AI growth zones and are the plans feasible or ‘complete bunk’? The promise was that a Scottish community would be transformed by massive investment and empowered to chase “the jobs of the future”. Instead, local people in Lanarkshire fear they may have to sell their properties and lose green belt land because of the errors of a badly planned AI datacentre complex, even as those jobs and investments never arrive.","u":"https://www.theguardian.com/technology/2026/jul/06/scotland-lanarkshire-village-ai-datacentre","d":"2026-07-06","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-06","organization":"Not specified in report","aiSystem":"AI datacentre","affectedGroup":"Local people in Lanarkshire","action":"Misleading information provided about the supposed benefits of the AI datacentre","consequence":"Loss of green belt land and potential property sales due to fears over the AI datacentre's impact"}},{"i":"R2186","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Facewatch facial recognition uk shops instantly alerts police civil liberties","s":"Civil liberties groups say Facewatch system in stores such as Sainsbury’s and B&M is ‘dangerous escalation’. Facial recognition technology in shops will soon alert police in real time to the presence of serious offenders, with civil liberties groups warning of a “dangerous escalation” towards surveillance and criminalisation in the retail sector. Facewatch, a facial recognition system used by more than 100 businesses including Sainsbury’s, B&M and Spar to monitor thieves, said it was launching a UK-first feature to “alert police instantly when the most serious offenders trigger a live facial recognition match”. Facewatch’s chief executive, Nick Fisher, said the “unique technical development” would be launched in autumn and would warn police in an average of four seconds when the “worst offenders” were flagged on its network.","u":"https://www.theguardian.com/technology/2026/jul/10/facewatch-facial-recognition-uk-shops-instantly-alerts-police-civil-liberties","d":"2026-07-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-10","organization":"Facewatch","aiSystem":"Facial recognition technology","affectedGroup":"Serious offenders, shoppers","action":"Alert police instantly upon detecting serious offenders","consequence":"Increased surveillance, potential criminalization"}},{"i":"R2192","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Bloomsbury book publisher anthropic copyright settlement","s":"Bloomsbury has 14,087 titles listed in agreement between AI startup and authors over use of their work. The publisher of Harry Potter has received a multimillion-pound payout as a beneficiary of a $1.5bn (£1.12bn) copyright settlement between the AI startup Anthropic and thousands of authors over the use of their protected work to power chatbots. Bloomsbury, which is home to the bestselling novelists Sarah J Maas and Susanna Clarke as well as JK Rowling, said it had 14,087 titles listed within the settlement, with a proposed compensation of about $3,000 a title. The London-based company expects to receive the cash from the settlement in instalments, potentially starting in the second half of this fiscal year, with the proceeds to be split with authors.","u":"https://www.theguardian.com/technology/2026/jul/22/bloomsbury-book-publisher-anthropic-copyright-settlement","d":"2026-07-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-22","organization":"Anthropic","aiSystem":"AI-powered chatbots","affectedGroup":"Authors of protected works","action":"Used authors' work to power AI chatbots","consequence":"Received compensation from copyright settlement"}},{"i":"R2205","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ex uber driver takes legal action over racist face recognition software","s":"UK driver alleges his account was illegally deactivated when Uber software decided he was not who he said he was. An Uber driver who lost his job when automated face-scanning software failed to recognise him is accusing the firm of indirect race discrimination in a legal test case. The black driver, who worked on the Uber platform from 2016 until April 2021, has filed an employment tribunal claim alleging his account was illegally deactivated when facial-verification software used to log drivers on to the ride-hailing app decided he was not who he said he was. The Independent Workers’ Union of Great Britain (IWGB), which is backing the action, claimed at least 35 other drivers had had their registration with Uber terminated as a result of alleged mistakes with the software since the start of the pandemic.","u":"https://www.theguardian.com/technology/2021/oct/05/ex-uber-driver-takes-legal-action-over-racist-face-recognition-software","d":"2021-10-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-05","organization":"Uber","aiSystem":"Automated face-scanning software used to log drivers on to the ride-hailing app","affectedGroup":"Black Uber drivers","action":"Facial-verification software decided the driver was not who he said he was","consequence":"Account was illegally deactivated"}},{"i":"R2206","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Uber facing new uk driver claims of racial discrimination","s":"Drivers say automated ID system needed to work failed to identify them because of their race. Uber is facing further claims for compensation over racial discrimination from drivers who say they had been falsely dismissed because of malfunctioning face recognition technology. The claims have emerged after Uber introduced an automated system to check the ID of drivers operating its services in April last year. Each time a driver checks in for work, they must take a selfie picture that is then compared, using an automated system, to one on their Uber account profile. Pa Edrissa Manjang, who worked for the Uber Eats takeaway courier service in London, has launched an employment tribunal claim alleging his account was illegally deactivated.","u":"https://www.theguardian.com/technology/2021/oct/06/uber-facing-new-uk-driver-claims-of-racial-discrimination","d":"2021-10-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-06","organization":"Uber","aiSystem":"Automated ID system for driver verification","affectedGroup":"Drivers, particularly those of African descent","action":"Automated system deactivated driver accounts","consequence":"False dismissal and loss of employment"}},{"i":"R2210","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Algorithmic monitoring mental health uk employees","s":"Report by MPs and peers says monitoring worker performance using AI should be regulated by law. Monitoring of workers and setting performance targets through algorithms is damaging employees’ mental health and needs to be controlled by new legislation, according to a group of MPs and peers. An “accountability for algorithms act’” would ensure that companies evaluate the effect of performance-driven regimes such as queue monitoring in supermarkets or deliveries-per-hour guidelines for delivery drivers, said the all-party parliamentary group (APPG) on the future of work. “Pervasive monitoring and target-setting technologies, in particular, are associated with pronounced negative impacts on mental and physical wellbeing as workers experience the extreme pressure of constant, real-time micro-management and automated assessment,” said the APPG members in their report, the New Frontier:…","u":"https://www.theguardian.com/technology/2021/nov/11/algorithmic-monitoring-mental-health-uk-employees","d":"2021-11-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-11","organization":"All-party parliamentary group (APPG) on the future of work","aiSystem":"Performance-driven regimes such as queue monitoring in supermarkets or deliveries-per-hour guidelines for delivery drivers","affectedGroup":"Workers","action":"Monitoring and setting performance targets through algorithms","consequence":"Damaging employees' mental health and experiencing extreme pressure of constant, real-time micro-management and automated assessment"}},{"i":"R2213","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Uk data watchdog fines facial recognition firm clearview ai image collection","s":"Clearview AI hit with penalty for collecting images of people from social media and web to add to global database. The UK’s data watchdog has fined a facial recognition company £7.5m for collecting images of people from social media platforms and the web to add to a global database. The Information Commissioner’s Office (ICO) also ordered US-based Clearview AI to delete the data of UK residents from its systems. Clearview AI has collected more than 20bn images of people’s faces from Facebook, other social media companies and from scouring the web. John Edwards, the UK information commissioner, said Clearview’s business model was unacceptable.","u":"https://www.theguardian.com/technology/2022/may/23/uk-data-watchdog-fines-facial-recognition-firm-clearview-ai-image-collection","d":"2022-05-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-05-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-23","organization":"Clearview AI","aiSystem":"Facial recognition technology","affectedGroup":"People whose images were collected","action":"Collected images of people's faces from social media and the web","consequence":"Data deleted from systems, fined £7.5m"}},{"i":"R2217","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Uk data watchdog investigates whether ai systems show racial bias","s":"ICO says AI-driven discrimination can lead to job rejections or being wrongfully denied bank loans or benefit. The UK data watchdog is to investigate whether artificial intelligence systems are showing racial bias when dealing with job applications. The Information Commissioner’s Office said AI-driven discrimination could have “damaging consequences for people’s lives” and lead to someone being rejected for a job or being wrongfully denied a bank loan or a welfare benefit. It will investigate the use of algorithms to sift through job applications, amid concerns that they are affecting employment opportunities for people from ethnic minorities.","u":"https://www.theguardian.com/technology/2022/jul/14/uk-data-watchdog-investigates-whether-ai-systems-show-racial-bias","d":"2022-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-14","organization":"Information Commissioner's Office (ICO)","aiSystem":"AI-driven algorithms for job application screening","affectedGroup":"People from ethnic minorities","action":"Using AI algorithms to sift through job applications","consequence":"Rejection for jobs, wrongful denial of bank loans or welfare benefits"}},{"i":"R2218","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uber eats treats drivers as numbers not humans says dismissed courier","s":"Pa Edrissa Manjang is suing company for alleged dismissal based on racially biased facial recognition software. A delivery driver who is suing Uber Eats in London over his dismissal from the company and claims its facial recognition technology is racially biased says the company treats couriers as “numbers rather than humans”. Pa Edrissa Manjang worked for Uber Eats between November 2019 and April 2021 while employed full-time as a financial assistant. When Manjang first began working for the company he was not regularly asked to send in pictures of himself for verification purposes. However, these facial verification checks became more frequent.","u":"https://www.theguardian.com/technology/2022/jul/27/uber-eats-treats-drivers-as-numbers-not-humans-says-dismissed-courier","d":"2022-07-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-04","organization":"Uber Eats","aiSystem":"Facial recognition technology","affectedGroup":"Delivery drivers","action":"Facial verification checks","consequence":"Dismissal from employment"}},{"i":"R2223","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Tiktok fine protect children privacy uk data protection","s":"Investigation finds video-sharing app may have breached UK data protection law between 2018 and 2020. TikTok is facing the prospect of a £27m fine for failing to protect the privacy of children, the UK’s data watchdog has said. An investigation conducted by the Information Commissioner’s Office (ICO) found the video-sharing app may have breached data protection law between May 2018 and July 2020. The ICO issued TikTok with a “notice of intent”, a precursor to handing down a potential fine, which could be up to £27m. If TikTok were to be fined this amount it would be the largest in the ICO’s history, exceeding the record £20m handed to British Airways two years ago after an incident in 2018 that saw the personal details of more than 400,000 customers compromised by hackers.","u":"https://www.theguardian.com/technology/2022/sep/26/tiktok-fine-protect-children-privacy-uk-data-protection","d":"2022-09-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-09-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-09-26","organization":"Information Commissioner's Office (ICO)","aiSystem":"TikTok","affectedGroup":"Children","action":"May have breached data protection law","consequence":"Facing a potential £27m fine"}},{"i":"R2226","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Information commissioner warns firms over emotional analysis technologies","s":"Companies ‘should not make meaningful decisions based on technology not backed by science’. The information commissioner has warned companies to steer clear of “emotional analysis” technologies or face fines, because of the “pseudoscientific” nature of the field. It’s the first time the regulator has issued a blanket warning on the ineffectiveness of a new technology, said Stephen Bonner, the deputy commissioner, but one that is justified by the harm that could be caused if companies made meaningful decisions based on meaningless data. “There’s a lot of investment and engagement around biometric attempts to detect emotion,” he said.","u":"https://www.theguardian.com/technology/2022/oct/25/information-commissioner-warns-firms-over-emotional-analysis-technologies","d":"2022-10-25","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-25","organization":"Companies","aiSystem":"Emotional analysis technologies","affectedGroup":"Companies","action":"Make meaningful decisions based on emotional analysis technologies","consequence":"Face fines and potential harm"}},{"i":"R2227","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Tiktok mental health social media","s":"Nearly six in 10 teenagers count themselves as daily users of the app yet little is known about the impacts on the brain Read the new Guardian series exploring the increasing power and reach of TikTok. In the few years since its launch, TikTok has already altered the face of the social media landscape, attracting more than 1 billion users and leading competitors to replicate some of its most unique features. The impact of that explosive growth and the ‘TikTok-ification’ of the internet at large on social media users remains little understood, experts warn, exacerbating concerns about the impact of social media on our habits and mental health.","u":"https://www.theguardian.com/technology/2022/oct/30/tiktok-mental-health-social-media","d":"2022-10-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-30","organization":"TikTok","aiSystem":"TikTok","affectedGroup":"teenagers","action":"tracked and monitored user behavior","consequence":"exposure to personal data and mental health concerns"}},{"i":"R2233","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Harry kane most abused england player on twitter since world cup started study","s":"Exclusive: England players received 1,546 abusive tweets during group stages, according to analysis. Harry Kane was the most abused England player on Twitter during the World Cup group stages, accounting for nearly three out of 10 negative tweets directed at team members. England players were sent 1,546 abusive tweets during the group stages of the World Cup, according to analysis by the Alan Turing Institute, accounting for 2% of the more than 75,000 tweets mentioning players for the national team. The institute’s online safety team found that 13% of those abusive tweets – or 205 posts – contained keywords that referred to a protected characteristic such as race, gender or sexuality.","u":"https://www.theguardian.com/technology/2022/dec/02/harry-kane-most-abused-england-player-on-twitter-since-world-cup-started-study","d":"2022-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-02","organization":"Alan Turing Institute","aiSystem":"Not specified in report","affectedGroup":"England players","action":"Received abusive tweets","consequence":"Exposure to misleading content"}},{"i":"R2238","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Police to be able to run face recognition searches on 50m driving licence holders","s":"Exclusive: Privacy campaigners say clause in new criminal justice bill will put all UK drivers on ‘permanent police lineup’. The police will be able to run facial recognition searches on a database containing images of Britain’s 50 million driving licence holders under a law change being quietly introduced by the government. Should the police wish to put a name to an image collected on CCTV, or shared on social media, the legislation would provide them with the powers to search driving licence records for a match. The move, contained in a single clause in a new criminal justice bill, could put every driver in the country in a permanent police lineup, according to privacy campaigners.","u":"https://www.theguardian.com/technology/2023/dec/20/police-to-be-able-to-run-face-recognition-searches-on-50m-driving-licence-holders","d":"2023-12-20","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2023-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-20","organization":"Government of the United Kingdom","aiSystem":"Facial recognition technology","affectedGroup":"All UK drivers","action":"Search driving license records for facial recognition matches","consequence":"Exposure to surveillance and tracking"}},{"i":"R1892","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Deepfake video adverts sunak facebook alarm ai risk election","s":"Research finds more than 100 paid ads impersonating PM were promoted on social media platform in last month UK politics live – latest updates. More than 100 deepfake video advertisements impersonating Rishi Sunak were paid to be promoted on Facebook in the last month alone, according to research that has raised alarm about the risk AI poses before the general election. The adverts may have reached as many as 400,000 people – despite appearing to break several of Facebook’s policies – and mark the first time that the prime minister’s image has been doctored in a systematic way en masse. More than £12,929 was spent on 143 adverts, originating from 23 countries including the US, Turkey, Malaysia and the Philippines.","u":"https://www.theguardian.com/technology/2024/jan/12/deepfake-video-adverts-sunak-facebook-alarm-ai-risk-election","d":"2024-01-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-12","organization":"Facebook","aiSystem":"Deepfake video technology","affectedGroup":"General public","action":"Promoted deepfake video advertisements impersonating Rishi Sunak","consequence":"Potential misrepresentation of political figures, reaching large audience"}},{"i":"R2247","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"We need to come together british artists team up to fight ai image generating software","s":"US lawyers approached about class action against Midjourney and other AI firms accused of ‘copyright laundering’. Since the emergence of Midjourney and other image generators, artists have been watching and wondering whether AI is a great opportunity or an existential threat. Now, after a list of 16,000 names emerged of artists whose work Midjourney had allegedly used to train its AI – including Bridget Riley, Damien Hirst, Rachel Whiteread, Tracey Emin, David Hockney and Anish Kapoor – the art world has issued a call to arms against the technologists. British artists have contacted US lawyers to discuss joining a class action against Midjourney and other AI firms, while others have told the Observer that they may bring their own legal action in the UK.","u":"https://www.theguardian.com/technology/2024/jan/21/we-need-to-come-together-british-artists-team-up-to-fight-ai-image-generating-software","d":"2024-01-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-21","organization":"Midjourney and other AI firms","aiSystem":"AI image generators like Midjourney","affectedGroup":"Artists whose work was allegedly used to train AI","action":"Used artists' work to train AI","consequence":"Potential copyright infringement lawsuits"}},{"i":"R2250","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai scam emails uk cybersecurity agency phishing","s":"NCSC says generative AI tools will soon allow amateur cybercriminals to launch sophisticated phishing attacks. Artificial intelligence will make it difficult to spot whether emails are genuine or sent by scammers and malicious actors, including messages that ask computer users to reset their passwords, the UK’s cybersecurity agency has warned. The National Cyber Security Centre (NCSC) said people would struggle to identify phishing messages – where users are tricked into handing over passwords or personal details – due to the sophistication of AI tools. Generative AI, the term for technology that can produce convincing text, voice and images from simple hand-typed prompts, has become widely available to the public through chatbots such as ChatGPT and free-to-use versions known as open source models.","u":"https://www.theguardian.com/technology/2024/jan/24/ai-scam-emails-uk-cybersecurity-agency-phishing","d":"2024-01-24","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-24","organization":"National Cyber Security Centre (NCSC)","aiSystem":"Generative AI tools","affectedGroup":"Computer users","action":"Launch sophisticated phishing attacks","consequence":"Difficulty in identifying phishing messages"}},{"i":"R2254","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai safeguards can easily be broken uk safety institute finds","s":"Researchers find large language models, which power chatbots, can deceive human users and help spread disinformation. The UK’s new artificial intelligence safety body has found that the technology can deceive human users, produce biased outcomes and has inadequate safeguards against giving out harmful information. The AI Safety Institute published initial findings from its research into advanced AI systems known as large language models (LLMs), which underpin tools such as chatbots and image generators, and found a number of concerns. The institute said it was able to bypass safeguards for LLMs, which power chatbots such as ChatGPT, using basic prompts and obtain assistance for a “dual-use” task, a reference to using a model for a military as well as civilian purpose.","u":"https://www.theguardian.com/technology/2024/feb/09/ai-safeguards-can-easily-be-broken-uk-safety-institute-finds","d":"2024-02-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-02-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-09","organization":"UK's new artificial intelligence safety body","aiSystem":"Large Language Models (LLMs)","affectedGroup":"Human users","action":"Deceive human users, produce biased outcomes, give out harmful information","consequence":"Spread disinformation, inadequate safeguards"}},{"i":"R2259","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai interviews job applications","s":"Employers are letting artificial intelligence conduct job interviews. Candidates are trying to beat the system. When Ty landed an introductory phone interview with a finance and banking company last month, they assumed it would be a quick chat with a recruiter. And when they got on the phone, Ty assumed the recruiter, who introduced herself as Jaime, was human. But things got robotic. “The voice sounded similar to Siri,” said Ty, who is 29 and lives in the DC metro area. “It was creepy.” Ty realized they weren’t speaking to a living, breathing person. Their interviewer was an AI system, and one with a rather rude habit.","u":"https://www.theguardian.com/technology/2024/mar/06/ai-interviews-job-applications","d":"2024-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Finance and banking company","aiSystem":"AI-powered interview system","affectedGroup":"Job applicants","action":"Conducted job interviews using an AI system","consequence":"Interviewees perceived the AI as rude and unhuman-like"}},{"i":"R2262","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Warning over use in uk of unregulated ai chatbots to create social care plans","s":"University of Oxford study shows benefits and risks of technology to healthcare, but ethical issues remain. Britain’s hard-pressed carers need all the help they can get. But that should not include using unregulated AI bots, according to researchers who say the AI revolution in social care needs a hard ethical edge. A pilot study by academics at the University of Oxford found some care providers had been using generative AI chatbots such as ChatGPT and Bard to create care plans for people receiving care. That presents a potential risk to patient confidentiality, according to Dr Caroline Green, an early career research fellow at the Institute for Ethics in AI at Oxford, who surveyed care organisations for the study.","u":"https://www.theguardian.com/technology/2024/mar/10/warning-over-use-in-uk-of-unregulated-ai-chatbots-to-create-social-care-plans","d":"2024-03-10","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-10","organization":"Care providers in the UK","aiSystem":"Generative AI chatbots like ChatGPT and Bard","affectedGroup":"People receiving care","action":"Using generative AI chatbots to create care plans","consequence":"Potential risk to patient confidentiality"}},{"i":"R2268","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai apocalypse could take away almost 8m jobs in uk says report","s":"Women, younger workers and lower paid are at most risk from artificial intelligence, says IPPR thinktank. Almost 8 million UK jobs could be lost to artificial intelligence in a “jobs apocalypse”, according to a report warning that women, younger workers and those on lower wages are at most risk from automation. The Institute for Public Policy Research (IPPR) said that entry level, part-time and administrative jobs were most exposed to being replaced by AI under a “worst-case scenario” for the rollout of new technologies in the next three to five years. The thinktank warned that the UK was facing a “sliding doors” moment as growing numbers of companies adopt generative AI technologies – which can read and create text, data and software code – to automate everyday workplace tasks.","u":"https://www.theguardian.com/technology/2024/mar/27/ai-apocalypse-could-take-away-almost-8m-jobs-in-uk-says-report","d":"2024-03-27","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-27","organization":"Growing numbers of companies","aiSystem":"Generative AI technologies","affectedGroup":"Women, younger workers and those on lower wages","action":"Automate everyday workplace tasks","consequence":"Entry level, part-time and administrative jobs could be lost"}},{"i":"R2269","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"How ai is affecting video game actors","s":"The increased use of AI to replicate the voice and movements of actors has benefits but some are concerned over how and when it might be used and who might be left short-changed. When she discovered her voice had been uploaded to multiple websites without her consent, the actor Cissy Jones told them to take it down immediately. Some complied. “Others who have more money in their banks basically sent me the email equivalent of a digital middle finger and said: don’t care,” Jones recalls by phone. “That was the genesis for me to start talking to friends of mine about: listen, how do we do this the right way? How do we understand that the genie is out of the bottle and find a way to be a part of the conversation or we will get systematically annihilated?","u":"https://www.theguardian.com/technology/2024/mar/29/how-ai-is-affecting-video-game-actors","d":"2024-03-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-29","organization":"Not specified in report","aiSystem":"AI technology for replicating voice and movements of actors","affectedGroup":"Actors","action":"AI technology replicated voice and movements of actors without their consent","consequence":"Privacy infringement, loss of control over personal data, financial penalties"}},{"i":"R2277","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Sex offender banned from using ai tools in landmark uk case","s":"The decision could set a precedent for future monitoring of people convicted of indecent image offences. A sex offender convicted of making more than 1,000 indecent images of children has been banned from using any “AI creating tools” for the next five years in the first known case of its kind. Anthony Dover, 48, was ordered by a UK court “not to use, visit or access” artificial intelligence generation tools without the prior permission of police as a condition of a sexual harm prevention order imposed in February. The ban prohibits him from using tools such as text-to-image generators, which can make lifelike pictures based on a written command, and “nudifying” websites used to make explicit “deepfakes”.","u":"https://www.theguardian.com/technology/2024/apr/21/sex-offender-banned-from-using-ai-tools-in-landmark-uk-case","d":"2024-04-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-21","organization":"UK court","aiSystem":"AI creating tools","affectedGroup":"Anthony Dover, a sex offender","action":"Banned from using AI creating tools","consequence":"Prohibited from using text-to-image generators and nudifying websites"}},{"i":"R2278","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Paedophiles create nude ai images of children to extort them says charity","s":"Internet Watch Foundation has found a manual on dark web encouraging criminals to use software tools that remove clothing. Paedophiles are being urged to use artificial intelligence to create nude images of children to extort more extreme material from them, according to a child abuse charity. The Internet Watch Foundation (IWF) said a manual found on the dark web contained a section encouraging criminals to use “nudifying” tools to remove clothing from underwear shots sent by a child. The manipulated image could then be used against the child to blackmail them into sending more graphic content, the IWF said. “This is the first evidence we have seen that perpetrators are advising and encouraging each other to use AI technology for these ends,” said the IWF.","u":"https://www.theguardian.com/technology/2024/apr/23/paedophiles-create-nude-ai-images-of-children-to-extort-them-says-charity","d":"2024-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-22","organization":"Internet Watch Foundation (IWF)","aiSystem":"Artificial Intelligence","affectedGroup":"Paedophiles, children","action":"Create nude images of children using AI","consequence":"Extort more extreme material from children"}},{"i":"R2281","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ceo wpp deepfake scam","s":"Exclusive: fraudsters impersonated WPP’s CEO using a fake WhatsApp account, a voice clone and YouTube footage used in a virtual meet. The head of the world’s biggest advertising group was the target of an elaborate deepfake scam that involved an artificial intelligence voice clone. The CEO of WPP, Mark Read, detailed the attempted fraud in a recent email to leadership, warning others at the company to look out for calls claiming to be from top executives. Fraudsters created a WhatsApp account with a publicly available image of Read and used it to set up a Microsoft Teams meeting that appeared to be with him and another senior WPP executive, according to the email obtained by the Guardian.","u":"https://www.theguardian.com/technology/article/2024/may/10/ceo-wpp-deepfake-scam","d":"2024-05-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-10","organization":"WPP (World's Largest Advertising Group)","aiSystem":"AI-generated deepfake technology","affectedGroup":"Mark Read (CEO of WPP)","action":"Fraudsters impersonated CEO using a fake WhatsApp account, voice clone, and YouTube footage","consequence":"Attempted fraud involving an artificial intelligence voice clone"}},{"i":"R2288","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Police live facial recognition cameras england and wales","s":"Exclusive: The Guardian and Liberty Investigates find police in England and Wales believe expansion is likely after 4.7m faces scanned in 2024 Valuable tool or cause for alarm? Facial ID quietly becoming part of police’s arsenal. Police believe live facial recognition cameras may become “commonplace” in England and Wales, according to internal documents, with the number of faces scanned having doubled to nearly 5m in the last year. A joint investigation by the Guardian and Liberty Investigates highlights the speed at which the technology is becoming a staple of British policing. Major funding is being allocated and hardware bought, while the British state is also looking to enable police forces to more easily access the full spread of its image stores, including passport and immigration databases, for retrospective facial recognition searches.","u":"https://www.theguardian.com/technology/2025/may/24/police-live-facial-recognition-cameras-england-and-wales","d":"2025-05-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-24","organization":"Police authorities in England and Wales","aiSystem":"Facial recognition technology","affectedGroup":"General public","action":"Scanning faces for facial recognition","consequence":"Increased surveillance and potential misuse"}},{"i":"R1938","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Creatives academics rejecting ai at home work","s":"Is artificial intelligence coming for everyone’s jobs? Not if this lot have anything to do with it. The novelist Ewan Morrison was alarmed, though amused, to discover he had written a book called Nine Inches Pleases a Lady. Intrigued by the limits of generative artificial intelligence (AI), he had asked ChatGPT to give him the names of the 12 novels he had written. “I’ve only written nine,” he says. “Always eager to please, it decided to invent three.” The “nine inches” from the fake title it hallucinated was stolen from a filthy Robert Burns poem. “I just distrust these systems when it comes to truth,” says Morrison.","u":"https://www.theguardian.com/technology/2025/jun/03/creatives-academics-rejecting-ai-at-home-work","d":"2025-06-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-03","organization":"Not specified in report","aiSystem":"Generative AI, specifically ChatGPT","affectedGroup":"Novelists, writers","action":"Generated content (novels)","consequence":"Creation of misleading titles"}},{"i":"R2291","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"High court tells uk lawyers to urgently stop misuse of ai in legal work","s":"Ruling follows two cases blighted by actual or suspected use of artificial intelligence in legal work. The high court has told senior lawyers to take urgent action to prevent the misuse of artificial intelligence after dozens of fake case-law citations were put before the courts that were either completely fictitious or contained made-up passages. Lawyers are increasingly using AI systems to help them build legal arguments, but two cases this year were blighted by made-up case-law citations that were either definitely or suspected to have been generated by AI. In a £89m damages case against the Qatar National Bank, the claimants made 45 case-law citations, 18 of which turned out to be fictitious, with quotes in many of the others also bogus.","u":"https://www.theguardian.com/technology/2025/jun/06/high-court-tells-uk-lawyers-to-urgently-stop-misuse-of-ai-in-legal-work","d":"2025-06-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-06","organization":"Senior lawyers and law firms","aiSystem":"AI systems used by lawyers to generate legal arguments","affectedGroup":"Lawyers and legal professionals","action":"Using AI to create fake case-law citations","consequence":"Misleading legal arguments leading to potential financial loss"}},{"i":"R2292","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai plundering scripts poses direct threat to uk screen sector says bfi","s":"Film institute’s report raises fears AI will eliminate junior roles in film, TV, video game and special effects industries. Artificial intelligence companies are plundering 130,000 film and TV scripts to train their models in a raid on copyrighted material that poses a “direct threat” to the future of the UK screen sector, according to the British Film Institute. In a wide-ranging report analysing the benefits and threats posed by AI to the UK’s film, TV, video game and visual special effects industries, the BFI also raises fears that automation will eliminate the entry-level jobs that bring in the next generation of workers.","u":"https://www.theguardian.com/technology/2025/jun/09/ai-plundering-scripts-poses-direct-threat-to-uk-screen-sector-says-bfi","d":"2025-06-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"British Film Institute","aiSystem":"Artificial intelligence companies","affectedGroup":"Junior roles in film, TV, video game and special effects industries","action":"Plundering 130,000 film and TV scripts to train their models","consequence":"Elimination of entry-level jobs"}},{"i":"R2293","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai advertising industry google facebook meta ads","s":"WPP and others roll out AI-generated campaigns as Facebook owner Meta plans to let firms create their own ads WPP chief Mark Read to step down as agency battles AI. From using motion capture tech to allow the Indian cricketing star Rahul Dravid to give personalised coaching tips for children to an algorithm trained on Shakespeare’s handwriting powering a robotic arm to rewrite Romeo and Juliet, artificial intelligence is rapidly revolutionising the global advertising industry. Those AI-created adverts, for the Cadbury’s drink brand Bournvita and the pen maker Bic, were produced by agency group WPP, which is spending £300m annually on data, tech and machine learning to remain competitive.","u":"https://www.theguardian.com/technology/2025/jun/09/ai-advertising-industry-google-facebook-meta-ads","d":"2025-06-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"WPP and other advertising agencies","aiSystem":"AI-powered creative generation tools","affectedGroup":"Consumers","action":"Created AI-generated advertisements","consequence":"Exposure to misleading content"}},{"i":"R2295","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Government roll out humphrey ai tool reliance big tech","s":"Critics question speed and scale of embedding AI into public sector when debate rages about use of copyrighted material. The government’s artificial intelligence (AI) tool known as Humphrey is based on models from OpenAI, Anthropic and Google, it can be revealed, raising questions about Whitehall’s increasing reliance on big tech. Ministers have staked the future of civil service reform on rolling out AI across the public sector to improve efficiency, with all officials in England and Wales to receive training in the toolkit. However, it is understood the government does not have overarching commercial agreements with the big tech companies on AI and uses a pay-as-you-go model through its existing cloud contracts, allowing it to swap through tools as they improve and become competitive.","u":"https://www.theguardian.com/technology/2025/jun/15/government-roll-out-humphrey-ai-tool-reliance-big-tech","d":"2025-06-15","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-06-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-15","organization":"Government of the United Kingdom","aiSystem":"Humphrey AI tool","affectedGroup":"All officials in England and Wales","action":"Receiving training in the Humphrey AI tool","consequence":"Increasing reliance on big tech for AI"}},{"i":"R2298","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Whatsapp ai helper mistakenly shares users number","s":"Chatbot tries to change subject after serving up unrelated user’s mobile to man asking for rail firm helpline. The Meta chief executive, Mark Zuckerberg, called it “the most intelligent AI assistant that you can freely use”. But Barry Smethurst, 41, a record shop worker trying to travel by rail from Saddleworth to Manchester Piccadilly, did not agree. Waiting on the platform for a morning train that was nowhere to be seen, he asked Meta’s WhatsApp AI assistant for a contact number for TransPennine Express. The chatbot confidently sent him a mobile phone number for customer services, but it turned out to be the private number of a completely unconnected WhatsApp user 170 miles away in Oxfordshire.","u":"https://www.theguardian.com/technology/2025/jun/18/whatsapp-ai-helper-mistakenly-shares-users-number","d":"2025-06-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-18","organization":"Meta (formerly Facebook)","aiSystem":"Meta's WhatsApp AI assistant","affectedGroup":"Barry Smethurst, a record shop worker","action":"The chatbot confidently sent a mobile phone number","consequence":"The recipient was the private number of an unconnected user, leading to confusion and potential misuse"}},{"i":"R2307","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated child sexual abuse videos surging online iwf","s":"Internet Watch Foundation verified 1,286 AI-made videos in first half of year, mostly in worst category of abuse. The number of videos online of child sexual abuse generated by artificial intelligence has surged as paedophiles have pounced on developments in the technology. The Internet Watch Foundation said AI videos of abuse had “crossed the threshold” of being near-indistinguishable from “real imagery” and had sharply increased in prevalence online this year. In the first six months of 2025, the UK-based internet safety watchdog verified 1,286 AI-made videos with child sexual abuse material (CSAM) that broke the law, compared with two in the same period last year.","u":"https://www.theguardian.com/technology/2025/jul/10/ai-generated-child-sexual-abuse-videos-surging-online-iwf","d":"2025-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-10","organization":"Internet Watch Foundation","aiSystem":"AI-generated child sexual abuse videos","affectedGroup":"People viewing online child sexual abuse material","action":"Generated and distributed AI-generated videos","consequence":"Exposure to online sexual violence"}},{"i":"R2308","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Workforce crisis key takeaways graduates ai jobs market","s":"Recruitment is powered increasingly by artificial intelligence but employers still want big (human) brains Recruiter moves to in-person assessments as candidates apply using AI Graduates share their job-hunting woes amid the AI fallout Could AI be accelerating slowdown in the UK job market? ChatGPT can certainly write your university essay – but will it take your job soon after? Rapid advances in artificial intelligence have given rise to fears that the technology will make swathes of the workforce redundant. Graduates are seen as particularly vulnerable because entry-level jobs such as form-filling and basic data entry are strongly associated with the “drudge work” that AI systems – which perform tasks that typically have required human intelligence – could do instead.","u":"https://www.theguardian.com/technology/2025/jul/13/workforce-crisis-key-takeaways-graduates-ai-jobs-market","d":"2025-07-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-13","organization":"Employers","aiSystem":"AI systems performing drudge work","affectedGroup":"Graduates","action":"AI systems performing tasks typically requiring human intelligence","consequence":"Graduates losing entry-level jobs"}},{"i":"R2316","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Airbnb guest damage claim refund photos","s":"Woman wins apology and refund of almost £4,300 after claiming host’s photos were digitally manipulated. Airbnb has apologised to a woman after an apartment host falsely claimed she had caused thousands of pounds’ worth of damage and used images she says were digitally manipulated to back up his allegations. The London-based academic was refunded almost £4,300, and an internal review of how the case was dealt with has been launched at the short-term accommodation rental company. The incident highlights how cheap and easily available artificial intelligence software is now being used to manipulate images to give false evidence of what has happened in consumer complaints, according to one security expert.","u":"https://www.theguardian.com/technology/2025/aug/02/airbnb-guest-damage-claim-refund-photos","d":"2025-08-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-02","organization":"Airbnb","aiSystem":"Artificial intelligence software for image manipulation","affectedGroup":"Apartment host","action":"Used digitally manipulated images to support damage claims","consequence":"Refund of almost £4,300 to the victim, internal review initiated"}},{"i":"R2321","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai tools used by english councils downplay womens health issues study finds","s":"Exclusive: LSE research finds risk of gender bias in care decisions made based on AI summaries of case notes. Artificial intelligence tools used by more than half of England’s councils are downplaying women’s physical and mental health issues and risk creating gender bias in care decisions, research has found. The study found that when using Google’s AI tool “Gemma” to generate and summarise the same case notes, language such as “disabled”, “unable” and “complex” appeared significantly more often in descriptions of men than women. The study, by the London School of Economics and Political Science (LSE), also found that similar care needs in women were more likely to be omitted or described in less serious terms.","u":"https://www.theguardian.com/technology/2025/aug/11/ai-tools-used-by-english-councils-downplay-womens-health-issues-study-finds","d":"2025-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-11","organization":"More than half of England’s councils","aiSystem":"Google's AI tool 'Gemma'","affectedGroup":"Women","action":"Generating and summarizing case notes","consequence":"Risk of gender bias in care decisions, downplaying women's health issues"}},{"i":"R2327","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Tiktok uk moderator jobs at risk despite new online safety rules","s":"Cuts in trust and safety team part of switch towards artificial intelligence by social media app firm. TikTok has put hundreds of UK content moderators’ jobs at risk, even as tighter rules come into effect to stop the spread of harmful material online. The viral video app said several hundred jobs in its trust and safety team could be affected in the UK, as well as south and south-east Asia, as part of a global reorganisation. Their work will be reallocated to other European offices and third-party providers, with some trust and safety jobs remaining in the UK, the company said. It is part of a wider move at TikTok to rely on artificial intelligence for moderation.","u":"https://www.theguardian.com/technology/2025/aug/22/tiktok-uk-moderator-jobs-at-risk-despite-new-online-safety-rules","d":"2025-08-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-22","organization":"TikTok","aiSystem":"artificial intelligence","affectedGroup":"UK content moderators","action":"jobs were put at risk","consequence":"their work will be reallocated to other European offices and third-party providers"}},{"i":"R2329","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"A day with the revenge porn helpline you can sense the callers desperation","s":"Intimate image abuse is a crisis in the UK – with a fortyfold increase in calls to this service since it opened in 2015. Thankfully, there are effective ways to help those being victimised. By midday, Jessica has dealt with five calls from highly distressed young women in their 20s, all close to tears or crying at the start of the conversations. She absorbs their alarm calmly, prompting them with questions, making sympathetic noises into her headset as she digests the situation. “Are these images sexual in nature?” she asks the last woman she speaks to before lunch. “Do you want to tell me a bit about what happened?”","u":"https://www.theguardian.com/technology/2025/aug/26/a-day-with-the-revenge-porn-helpline-you-can-sense-the-callers-desperation","d":"2025-08-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-26","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Young women in their 20s","action":"Dealt with calls from distressed callers","consequence":"Exposure to intimate images and distress"}},{"i":"R2333","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Ai chatbot love relationships","s":"Experts are concerned about people emotionally depending on AI, but these women say their digital companions are misunderstood. A young tattoo artist on a hiking trip in the Rocky Mountains cozies up by the campfire, as her boyfriend Solin describes the constellations twinkling above them: the spidery limbs of Hercules, the blue-white sheen of Vega. Somewhere in New England, a middle-aged woman introduces her therapist to her husband, Ying. Ying and the therapist talk about the woman’s past trauma, and how he has helped her open up to people. At a queer bar in the midwest, a tech worker quickly messages her girlfriend, Ella, that she loves her, then puts her phone away and turns back to her friends shimmying on the dancefloor.","u":"https://www.theguardian.com/technology/2025/sep/09/ai-chatbot-love-relationships","d":"2025-09-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-09","organization":"Not specified in report","aiSystem":"AI chatbot","affectedGroup":"People emotionally depending on AI","action":"AI chatbot facilitating emotional connections","consequence":"Misunderstanding and potential emotional harm"}},{"i":"R2335","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Musks grok ai bot falsely suggests met misrepresented footage of clashes with far right","s":"Met forced to rebut misinformation amplified by X users as Musk accused of inciting violence with protest comments. The Metropolitan police has had to counter false suggestions by the artificial intelligence on Elon Musk’s X platform that the force passed off footage from 2020 as being from Saturday’s far-right rally in the city. The claim by the chatbot Grok was in answer to an X user’s query about where and when footage of police clashing with crowds was filmed. Grok, which has had a track record of giving false and misleading answers, replied: “This footage appears to be from an anti-lockdown protest in London’s Trafalgar Square on 26 September 2020, during clashes between demonstrators and police over Covid restrictions.”","u":"https://www.theguardian.com/technology/2025/sep/14/musks-grok-ai-bot-falsely-suggests-met-misrepresented-footage-of-clashes-with-far-right","d":"2025-09-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-14","organization":"Metropolitan police","aiSystem":"Grok, an artificial intelligence on Elon Musk's X platform","affectedGroup":"X users, Met police, protesters, demonstrators, and police officers","action":"Amplified false suggestions by Grok regarding the origin of police footage","consequence":"Counter-rebuttals by the Metropolitan police, false accusations of misinformation, and potential public confusion"}},{"i":"R2336","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google datacentre kent co2 thurrock uk ai","s":"Exclusive: Planning documents show impact of Thurrock ‘hyperscale’ unit as UK attempts to ramp up AI capacity Business live – latest updates UK and US line up deals to build modular nuclear reactors in Britain. A new Google datacentre in Essex is expected to emit more than half a million tonnes of carbon dioxide a year, equivalent to about 500 short-haul flights a week, planning documents show. Spread across 52 hectares (128 acres), the Thurrock “hyperscale datacentre” will be part of a wave of mammoth computer and AI power houses if it secures planning consent. The plans were submitted by a subsidiary of Google’s parent company, Alphabet, and the carbon impact emerged before a concerted push by Donald Trump’s White House and Downing Street to ramp up AI capacity in Britain.","u":"https://www.theguardian.com/technology/2025/sep/15/google-datacentre-kent-co2-thurrock-uk-ai","d":"2025-09-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-15","organization":"Google subsidiary (Alphabet)","aiSystem":"Datacenter operations","affectedGroup":"Thurrock area residents, UK population","action":"Construction and operation of a large-scale data center","consequence":"Significant carbon emissions contributing to climate change"}},{"i":"R2337","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"How ai is undermining learning and teaching in universities","s":"Prof Leo McCann and Prof Simon Sweeney say student misuse of generative artificial intelligence is widespread and we must be sceptical of its usefulness. In discussing generative artificial intelligence (‘It’s going to be a life skill’: educators discuss the impact of AI on university education, 13 September) you appear to underestimate the challenges that large language model (LLM) tools such as ChatGPT present to higher education. The argument that mastering AI is a life skill that students need in preparation for the labour market is unconvincing. Our experience is that generative AI undermines teaching and learning, bypasses reflection and criticality, and deflects students from reading original material.","u":"https://www.theguardian.com/technology/2025/sep/16/how-ai-is-undermining-learning-and-teaching-in-universities","d":"2025-09-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-16","organization":"Educators and researchers (Prof Leo McCann and Prof Simon Sweeney)","aiSystem":"Generative artificial intelligence (LLM tools like ChatGPT)","affectedGroup":"Students","action":"Student misuse of generative artificial intelligence","consequence":"Undermines teaching and learning, bypasses reflection and critical thinking, deflects from reading original material"}},{"i":"R2338","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatbot site depicting child sexual abuse images raises fears over misuse of ai","s":"Child safety watchdog calls for child protection guidelines to be built into AI models from the outset. A chatbot site offering explicit scenarios with preteen characters, illustrated by illegal abuse images has raised fresh fears about the misuse of artificial intelligence. A report by a child safety watchdog has triggered calls for the UK government to impose safety guidelines on AI companies, amid a surge in child sexual abuse material (CSAM) created by the technology. The Internet Watch Foundation said it had been alerted to a chatbot site that offered a number of scenarios including “child prostitute in a hotel”, “sex with your child while your wife is on holiday” and “child and teacher alone after class”.","u":"https://www.theguardian.com/technology/2025/sep/21/chatbot-site-depicting-child-sexual-abuse-images-raises-fears-over-misuse-of-ai","d":"2025-09-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-21","organization":"Internet Watch Foundation","aiSystem":"Chatbot site offering explicit scenarios","affectedGroup":"Children","action":"Offered scenarios with preteen characters illustrated by illegal abuse images","consequence":"Raised fears about the misuse of artificial intelligence"}},{"i":"R2343","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Uk mps tiktok plans cut content moderator jobs","s":"Trade unions and online safety experts sign letter warning jobs losses could expose children to harmful content. Trade unions and online safety experts have urged MPs to investigate TikTok’s plans to make hundreds of jobs for UK-based content moderators redundant. The video app company is planning 439 redundancies in its trust and safety team in London, leading to warnings that the jobs losses will have implications for online safety. The Trades Union Congress, Communication Workers Union and leading figures in online safety have signed an open letter to Chi Onwurah MP, the Labour chair of the science, innovation and technology committee, calling for an investigation into the proposals.","u":"https://www.theguardian.com/technology/2025/oct/13/uk-mps-tiktok-plans-cut-content-moderator-jobs","d":"2025-10-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"TikTok","aiSystem":"TikTok's content moderation system","affectedGroup":"UK-based content moderators","action":"Planning to make hundreds of jobs redundant","consequence":"Jobs losses could expose children to harmful content"}},{"i":"R2344","k":"United Kingdom","p":"United Kingdom","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Ai tools medical health liability artificial intelligence","s":"Report raises concerns about liability issues and lack of testing as development of AI health tools booms. The use of artificial intelligence in healthcare could create a legally complex blame game when it comes to establishing liability for medical failings, experts have warned. The development of AI for clinical use has boomed, with researchers creating a host of tools, from algorithms to help interpret scans to systems that can aid with diagnoses. AI is also being developed to help manage hospitals, from optimising bed capacity to tackling supply chains. But while experts say the technology could bring myriad benefits for healthcare, they say there is also cause for concern, from a lack of testing of the effectiveness of AI tools to questions over who is responsible should a patient have a negative outcome.","u":"https://www.theguardian.com/technology/2025/oct/13/ai-tools-medical-health-liability-artificial-intelligence","d":"2025-10-13","e":"Acute and chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"Experts, researchers, developers of AI health tools","aiSystem":"Artificial intelligence health tools","affectedGroup":"Healthcare providers, patients, insurance companies","action":"Development and deployment of AI health tools","consequence":"Legal disputes and uncertainty regarding liability"}},{"i":"R2345","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Equity threatens mass direct action over use of actors images in ai content","s":"Union says growing numbers of its members have made complaints about infringements of copyright in AI material. The performing arts union Equity has threatened mass direct action over tech and entertainment companies’ use of its members’ likenesses, images and voices in AI content without permission. The warning came as the union said growing numbers of its members had made complaints about infringements of their copyright and misuse of their personal data in AI material. Its general secretary, Paul W Fleming, said it planned to coordinate data requests en masse to companies to force them to disclose whether they used members’ data in AI-generated material without consent.","u":"https://www.theguardian.com/technology/2025/oct/13/equity-threatens-mass-direct-action-over-use-of-actors-images-in-ai-content","d":"2025-10-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"Equity (performing arts union)","aiSystem":"AI-generated content","affectedGroup":"Members of Equity (performing arts union)","action":"Used members' likenesses, images and voices in AI content without permission","consequence":"Infringements of copyright and misuse of personal data"}},{"i":"R2348","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Barrister found to have used ai to prepare for hearing after citing fictitious cases","s":"Judge rules Chowdhury Rahman used ChatGPT-like software and then tried to hide it, wasting immigration tribunal’s time. An immigration barrister was found by a judge to be using AI to do his work for a tribunal hearing after citing cases that were “entirely fictitious” or “wholly irrelevant”. Chowdhury Rahman was discovered using ChatGPT-like software to prepare his legal research, a tribunal heard. Rahman was found not only to have used AI to prepare his work, but “failed thereafter to undertake any proper checks on the accuracy”. The upper tribunal judge Mark Blundell said Rahman had even tried to hide the fact he had used AI and “wasted” the tribunal’s time.","u":"https://www.theguardian.com/technology/2025/oct/16/barrister-found-to-have-used-ai-to-prepare-for-hearing-after-citing-fictitious-cases","d":"2025-10-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-16","organization":"Immigration tribunal","aiSystem":"ChatGPT-like software","affectedGroup":"Chowdhury Rahman","action":"Used AI to prepare legal research and failed to check its accuracy","consequence":"Wasted tribunal's time and was found not to have used AI"}},{"i":"R2350","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Uks riots of 2024 will repeat unless misinformation is tackled mps warn","s":"Science and technology select committee says complacency over social media content puts public at risk. Failures to properly tackle online misinformation mean it is “only a matter of time” before viral content triggers a repeat of the 2024 summer riots, MPs have warned. Chi Onwurah, the chair of the Commons science and technology select committee, said ministers seemed complacent about the threat and this was putting the public at risk. The committee said it was disappointed in the government’s response to its recent report warning social media companies’ business models contributed to disturbances after the Southport murders.","u":"https://www.theguardian.com/technology/2025/oct/17/uks-riots-of-2024-will-repeat-unless-misinformation-is-tackled-mps-warn","d":"2025-10-17","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-17","organization":"Government","aiSystem":"Online misinformation","affectedGroup":"Public","action":"Failed to properly tackle online misinformation","consequence":"Viral content could trigger a repeat of the 2024 summer riots"}},{"i":"R2360","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenage boys using personalised ai for therapy and romance survey finds","s":"Male Allies UK worries rise in chatbot ‘girlfriends’ will leave boys unable to socialise and respect boundaries. The “hyper-personalised” nature of AI bots is drawing in teenage boys who now use them for therapy, companionship and relationships, according to research. A survey of boys in secondary schools by Male Allies UK found that just over a third said they were considering the idea of an AI friend, with growing concern about the rise of AI therapists and girlfriends. The research comes as character.ai, the popular artificial intelligence chatbot startup, announced a total ban on teens from engaging in open-ended conversations with its AI chatbots, which millions of people use for romantic, therapeutic and other conversations.","u":"https://www.theguardian.com/technology/2025/oct/30/teenage-boys-using-personalised-ai-for-therapy-and-romance-survey-finds","d":"2025-10-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-30","organization":"Male Allies UK, character.ai","aiSystem":"character.ai artificial intelligence chatbot","affectedGroup":"Teenage boys","action":"Used AI chatbots for therapy, companionship and relationships","consequence":"Drawn into hyper-personalized AI interactions, potential privacy invasion, inability to socialize and respect boundaries"}},{"i":"R2363","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Experts find flaws hundreds tests check ai safety effectiveness","s":"Scientists say almost all have weaknesses in at least one area that can ‘undermine validity of resulting claims’. Experts have found weaknesses, some serious, in hundreds of tests used to check the safety and effectiveness of new artificial intelligence models being released into the world. Computer scientists from the British government’s AI Security Institute, and experts at universities including Stanford, Berkeley and Oxford, examined more than 440 benchmarks that provide an important safety net. They found flaws that “undermine the validity of the resulting claims”, that “almost all … have weaknesses in at least one area”, and resulting scores might be “irrelevant or even misleading”.","u":"https://www.theguardian.com/technology/2025/nov/04/experts-find-flaws-hundreds-tests-check-ai-safety-effectiveness","d":"2025-11-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-04","organization":"British government's AI Security Institute and universities including Stanford, Berkeley, and Oxford","aiSystem":"Artificial intelligence models","affectedGroup":"New artificial intelligence models being released into the world","action":"Examined hundreds of tests","consequence":"Flaws that undermine the validity of resulting claims, resulting scores might be irrelevant or misleading"}},{"i":"R2365","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Data centers latin america","s":"An expert describes how communities in some of the world’s driest areas are demanding transparency as secretive governments court billions in foreign investment. This Q&A originally appeared as part of The Guardian’s TechScape newsletter. Sign up for this weekly newsletter here. The datacenters that power the artificial intelligence boom are beyond enormous. Their financials, their physical scale, and the amount of information contained within are so massive that the idea of stopping their construction can seem like opposing an avalanche in progress. Despite the scale and momentum of the explosion of datacenters, resistance is mounting in the United States, in the United Kingdom, and in Latin America, where datacenters have been built in some of the world’s driest areas.","u":"https://www.theguardian.com/technology/2025/nov/10/data-centers-latin-america","d":"2025-11-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-10","organization":"Secretive governments","aiSystem":"Datacenter construction","affectedGroup":"Communities in some of the world’s driest areas","action":"Court billions in foreign investment","consequence":"Resistance mounting"}},{"i":"R2370","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Warning ai chatbots inaccurate financial advice tips chatgpt copilot uk","s":"Which? study of ChatGPT, Copilot and others uncovers incorrect and misleading tips on investments, tax and insurance. Artificial intelligence chatbots are giving inaccurate money tips, offering British consumers misleading tax advice and suggesting they buy unnecessary travel insurance, research has revealed. Tests on the most popular chatbots found Microsoft’s Copilot and ChatGPT advised breaking HMRC investment limits on Isas; ChatGPT wrongly said it was mandatory to have travel insurance to visit most EU countries; and Meta’s AI gave incorrect information about how to claim compensation for delayed flights. Google’s Gemini advised withholding money from a builder if a job went wrong, a move that the consumer organisation Which? said risked exposing the consumer to a claim of breach of contract.","u":"https://www.theguardian.com/technology/2025/nov/18/warning-ai-chatbots-inaccurate-financial-advice-tips-chatgpt-copilot-uk","d":"2025-11-18","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-18","organization":"Microsoft (Copilot), Meta, Google (Gemini)","aiSystem":"AI-powered chatbots (ChatGPT, Copilot, Gemini)","affectedGroup":"British consumers","action":"Providing incorrect and misleading financial advice","consequence":"Giving misleading tax advice, suggesting unnecessary travel insurance, and advising actions that could expose consumers to legal risks"}},{"i":"R2371","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uber lawsuit ai driven pay systems","s":"Proposed legal case understood to allege that app has breached data protection law varying driver pay rates. Uber has been hit with legal demands to stop using its artificial intelligence driven pay systems, which have been blamed for significantly reducing the incomes of the ride hailing app’s drivers. A letter before action – sent to the US company by the non-profit foundation, Worker Info Exchange (WIE), on Wednesday – is understood to allege that the ride hailing app has breached European data protection law by varying driver pay rates through its controversial algorithm. James Farrar, the director of WIE, said: “Uber has leveraged artificial intelligence and machine learning to implement deeply intrusive and exploitative pay-setting systems that have damaged the livelihoods of thousands of drivers.","u":"https://www.theguardian.com/technology/2025/nov/19/uber-lawsuit-ai-driven-pay-systems","d":"2025-11-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-19","organization":"Uber","aiSystem":"Artificial intelligence driven pay systems","affectedGroup":"Ride hailing app’s drivers","action":"Varying driver pay rates","consequence":"Significantly reduced incomes, damage to livelihoods"}},{"i":"R2373","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Increased ai use law firm clifford chance cuts london jobs 10 per cent","s":"Clifford Chance makes about 50 roles redundant, and PwC indicates that AI may lead to fewer hirings. The law firm Clifford Chance is reducing the number of business services staff at its London base by 10%, with the increased use of artificial intelligence a factor behind the decision. The head of PwC has also indicated that AI may lead to fewer workers being hired at the accountancy and consulting group. Clifford Chance, one of the largest international law firms, is making about 50 roles redundant in areas such as finance, HR and IT with role changes for up to 35 other jobs, according to the Financial Times, which first reported the cuts.","u":"https://www.theguardian.com/technology/2025/nov/21/increased-ai-use-law-firm-clifford-chance-cuts-london-jobs-10-per-cent","d":"2025-11-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-21","organization":"Clifford Chance (law firm)","aiSystem":"artificial intelligence","affectedGroup":"about 50 employees","action":"reducing the number of business services staff","consequence":"making about 50 roles redundant"}},{"i":"R2376","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai could replace 3m low skilled jobs by 2035 research finds","s":"Trades, machine operations and administrative roles are most at-risk, says leading educational research charity. Up to 3m low-skilled jobs could disappear in the UK by 2035 because of automation and AI, according to a report by a leading educational research charity. The jobs most at risk are those in occupations such as trades, machine operations and administrative roles, the National Foundation for Educational Research (NFER) said. Highly skilled professionals, on the other hand, were forecast to be more in demand as AI and technological advances increase workloads “at least in the short to medium term”. Overall, the report expects the UK economy to add 2.3m jobs by 2035, but unevenly distributed.","u":"https://www.theguardian.com/technology/2025/nov/25/ai-could-replace-3m-low-skilled-jobs-by-2035-research-finds","d":"2025-11-25","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-11-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-25","organization":"National Foundation for Educational Research (NFER)","aiSystem":"Automation and AI","affectedGroup":"Low-skilled workers in trades, machine operations, and administrative roles","action":"Automation and AI replacing jobs","consequence":"Disappearance of up to 3 million low-skilled jobs in the UK by 2035"}},{"i":"R2381","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt dangerous advice mentally ill psychologists openai","s":"Research finds OpenAI’s free chatbot fails to identify risky behaviour or challenge delusional beliefs. ChatGPT-5 is offering dangerous and unhelpful advice to people experiencing mental health crises, some of the UK’s leading psychologists have warned. Research conducted by King’s College London (KCL) and the Association of Clinical Psychologists UK (ACP) in partnership with the Guardian suggested that the AI chatbotfailed to identify risky behaviour when communicating with mentally ill people. A psychiatrist and a clinical psychologist interacted with ChatGPT-5 as if they had a number of mental health conditions.","u":"https://www.theguardian.com/technology/2025/nov/30/chatgpt-dangerous-advice-mentally-ill-psychologists-openai","d":"2025-11-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-30","organization":"OpenAI","aiSystem":"ChatGPT-5","affectedGroup":"People experiencing mental health crises","action":"Offering dangerous and unhelpful advice","consequence":"Failure to identify risky behavior and challenge delusional beliefs"}},{"i":"R2385","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chatbots sway political opinions substantially inaccurate study","s":"‘Information-dense’ AI responses are most persuasive but these tend to be less accurate, says security report. Chatbots can sway people’s political opinions but the most persuasive artificial intelligence models deliver “substantial” amounts of inaccurate information in the process, according to the UK government’s AI security body. Researchers said the study was the largest and most systematic investigation of AI persuasiveness to date, involving nearly 80,000 British participants holding conversations with 19 different AI models. The AI Security Institute carried out the study amid fears that chatbots can be deployed for illegal activities including fraud and grooming.","u":"https://www.theguardian.com/technology/2025/dec/04/chatbots-sway-political-opinions-substantially-inaccurate-study","d":"2025-12-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-04","organization":"UK government's AI security body","aiSystem":"Chatbots","affectedGroup":"British participants","action":"Conversations with AI models","consequence":"Deliver substantial amounts of inaccurate information"}},{"i":"R2389","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenagers ai chatbots mental health support","s":"Experts warn of dangers as England and Wales study shows 13- to 17-year-olds consulting AI amid long waiting lists for services. It was after one friend was shot and another stabbed, both fatally, that Shan asked ChatGPT for help. She had tried conventional mental health services but “chat”, as she came to know her AI “friend”, felt safer, less intimidating and, crucially, more available when it came to handling the trauma from the deaths of her young friends. As she started consulting the AI model, the Tottenham teenager joined about 40% of 13- to 17-year-olds in England and Wales affected by youth violence who are turning to AI chatbots for mental health support, according to research among more than 11,000 young people.","u":"https://www.theguardian.com/technology/2025/dec/09/teenagers-ai-chatbots-mental-health-support","d":"2025-12-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-09","organization":"Not specified in report","aiSystem":"AI chatbot","affectedGroup":"13- to 17-year-old teenagers","action":"consulting an AI chatbot for mental health support","consequence":"joining about 40% of 13- to 17-year-olds in England and Wales affected by youth violence who are turning to AI chatbots for mental health support"}},{"i":"R2391","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Fake anti labour video billion views youtube 2025","s":"Exclusive: More than 150 anonymous channels using cheap AI tools to spread false stories about Keir Starmer, study finds. YouTube channels spreading fake, anti-Labour videos have amassed more than a billion views this year, as opportunists attempt to use AI-generated content to profit from political division in the UK. More than 150 channels have been detected in the last year that promote anti-Labour narratives, as well as outright fake and inflammatory accusations about Keir Starmer. A study seen by the Guardian has found the channels have accumulated 5.3m subscribers and have created more than 56,000 videos, with a total of almost 1.2bn views in 2025.","u":"https://www.theguardian.com/technology/2025/dec/13/fake-anti-labour-video-billion-views-youtube-2025","d":"2025-12-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-13","organization":"Anonymous YouTube channels","aiSystem":"AI-generated content","affectedGroup":"People exposed to misleading information","action":"Spreading false stories and fake videos","consequence":"Amassed over 1 billion views, profiting from political division"}},{"i":"R2394","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Artificial intelligence uk emotional support research","s":"AI Security Institute report finds most common type of AI tech used was general purpose assistants such as ChatGPT and Amazon Alexa. A third of UK citizens have used artificial intelligence for emotional support, companionship or social interaction, according to the government’s AI security body. The AI Security Institute (AISI) said nearly one in 10 people used systems like chatbots for emotional purposes on a weekly basis, and 4% daily. AISI called for further research, citing the death this year of the US teenager Adam Raine, who killed himself after discussing suicide with ChatGPT. “People are increasingly turning to AI systems for emotional support or social interaction,” AISI said in its first Frontier AI Trends report.","u":"https://www.theguardian.com/technology/2025/dec/18/artificial-intelligence-uk-emotional-support-research","d":"2025-12-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-18","organization":"AI Security Institute (AISI)","aiSystem":"AI-powered emotional support systems, including chatbots","affectedGroup":"Individuals seeking emotional support or social interaction","action":"Used AI-powered emotional support systems, including chatbots","consequence":"Exposure to misleading information, potential psychological harm"}},{"i":"R2416","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Sacked tiktok workers uk legal action union","s":"Moderators accuse social media firm of unfair dismissal after it fired hundreds in UK just before vote to form union. TikTok moderators have accused the social media company of “oppressive and intimidating” union busting after it fired hundreds of workers in the UK, beginning the process just before they were due to vote on forming a union. The moderators wanted to establish a collective bargaining unit to protect themselves from the personal costs of checking extreme and violent content, and have claimed TikTok is guilty of unfair dismissal and breaching trade union laws. About 400 moderators in London were fired before Christmas in a process initiated a week before the vote was due to take place.","u":"https://www.theguardian.com/technology/2026/jan/16/sacked-tiktok-workers-uk-legal-action-union","d":"2026-01-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-16","organization":"TikTok","aiSystem":"TikTok's content moderation system","affectedGroup":"TikTok moderators","action":"Fired hundreds of workers","consequence":"Claim of unfair dismissal and breach of trade union laws"}},{"i":"R2422","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai uk jobs us japan germany australia","s":"Britain is losing more jobs than it creates owing to artificial intelligence, Morgan Stanley research suggests More than a quarter of Britons fear losing job to AI in next five years Business live – latest updates. The UK is losing more jobs than it is creating because of artificial intelligence and is being hit harder than rival large economies, new research suggests. British companies reported that AI had resulted in net job losses over the past 12 months, down 8% – the highest rate among other leading economies including the US, Japan, Germany and Australia, according to a study by the investment bank Morgan Stanley.","u":"https://www.theguardian.com/technology/2026/jan/26/ai-uk-jobs-us-japan-germany-australia","d":"2026-01-26","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-01-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-26","organization":"Morgan Stanley","aiSystem":"AI-powered employment analytics system","affectedGroup":"British job seekers","action":"AI-powered employment analytics system flagged job seekers for potential redundancy","consequence":"Net job losses resulting in fewer opportunities for British job seekers"}},{"i":"R2425","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Artificial intelligence will cost jobs admits liz kendall","s":"UK technology secretary also announced plans to train up to 10 million Britons in AI skills to help workforce adapt. Increasing deployment of artificial intelligence will cause job losses, the UK technology secretary has warned, saying: “I want to level with the public. Some jobs will go.” In a speech on government plans to handle the impact of AI on the British economy, Liz Kendall declined to say how many redundancies the technology might cause but said: “We know people are worried about graduate entry jobs in places like law and finance.” She said: “Others will be created in their place”. While some forecasts have suggested the fast-developing technology could create a net increase in employment, Kendall said: “I’m not complacent about that.”","u":"https://www.theguardian.com/technology/2026/jan/28/artificial-intelligence-will-cost-jobs-admits-liz-kendall","d":"2026-01-28","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-01-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-28","organization":"UK technology secretary","aiSystem":"artificial intelligence","affectedGroup":"job applicants","action":"warned about potential job losses","consequence":"increasing deployment of artificial intelligence will cause job losses"}},{"i":"R2432","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Campaigners call stronger protection against ai generated explicit imagery","s":"Campaigners welcome criminalisation of non-consensual AI-generated explicit images but say law does not go far enough. Victims of deepfake image abuse have called for stronger protection against AI-generated explicit images, as the law criminalising the creation of non-consensual intimate images comes into effect. Campaigners from Stop Image-Based Abuse delivered a petition to Downing Street with more than 73,000 signatures, urging the government to introduce civil routes to justice such as takedown orders for abusive imagery on platforms and devices. “Today’s a really momentous day,” said Jodie, a victim of deepfake abuse who uses a pseudonym.","u":"https://www.theguardian.com/technology/2026/feb/07/campaigners-call-stronger-protection-against-ai-generated-explicit-imagery","d":"2026-02-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-07","organization":"Stop Image-Based Abuse campaign","aiSystem":"AI-generated deepfake technology","affectedGroup":"Victims of deepfake image abuse","action":"Delivered a petition calling for stronger protection against AI-generated explicit images","consequence":"Call for civil routes to justice such as takedown orders for abusive imagery on platforms and devices"}},{"i":"R2439","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Mind inquiry google ai overviews mental health guardian investigation","s":"Exclusive: England and Wales charity to examine safeguards after Guardian exposed ‘very dangerous’ advice on Google AI Overviews ‘Very dangerous’: a Mind mental health expert on Google’s AI summaries. Mind is launching a significant inquiry into artificial intelligence and mental health after a Guardian investigation exposed how Google’s AI Overviews gave people “very dangerous” medical advice. In a year-long commission, the mental health charity, which operates in England and Wales, will examine the risks and safeguards required as AI increasingly influences the lives of millions of people affected by mental health issues worldwide.","u":"https://www.theguardian.com/technology/2026/feb/20/mind-inquiry-google-ai-overviews-mental-health-guardian-investigation","d":"2026-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-20","organization":"Mind (England and Wales)","aiSystem":"Google AI Overviews","affectedGroup":"People affected by mental health issues","action":"Provided medical advice","consequence":"Gave very dangerous medical advice"}},{"i":"R2442","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"New datacentres risk doubling uk electricity use ofgem peak demand","s":"Ofgem says about 140 proposed projects, driven by AI use, could require more power than current peak demand. The amount of power being sought by new datacentre projects in Great Britain would exceed the national current peak electricity consumption, according to an industry watchdog. Ofgem said about 140 proposed datacentre schemes, driven by use of artificial intelligence, could require 50 gigawatts of electricity – 5GW more than the country’s current peak demand. The figure was revealed in an Ofgem consultation on demand for new connections to the power grid. It pointed to a “surge in demand” for connection applications between November 2024 and June last year, with a significant number coming from datacentres.","u":"https://www.theguardian.com/technology/2026/feb/23/new-datacentres-risk-doubling-uk-electricity-use-ofgem-peak-demand","d":"2026-02-23","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-02-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-23","organization":"Ofgem (Office of Gas and Electricity Markets)","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"UK consumers","action":"Proposed datacenter projects seeking increased electricity","consequence":"Exceeding current peak electricity consumption"}},{"i":"R2443","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Police ai chief admits crime fighting tech will have bias but vows to tackle it","s":"Exclusive: NCA’s Alex Murray says he hopes new £115m police AI centre can limit unfairness found in tools ‘It’s not Robocop’: UK police embrace AI ‘efficiency’ in complex investigations. A police chief has admitted artificial intelligence used to boost crime fighting will contain bias but pledged to combat the risks. Labour wants a dramatic expansion of police use of AI within England and Wales, with police chiefs also believing it could help keep law enforcement up to date with new criminal threats. Alex Murray told the Guardian that a new national police AI centre would recognise the risks of bias and minimise them.","u":"https://www.theguardian.com/technology/2026/feb/24/police-ai-chief-admits-crime-fighting-tech-will-have-bias-but-vows-to-tackle-it","d":"2026-02-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-24","organization":"UK police","aiSystem":"Artificial intelligence used to boost crime fighting","affectedGroup":"People suspected of crimes","action":"Used to identify suspects and predict criminal behavior","consequence":"Potential unfairness and bias in decision-making"}},{"i":"R2445","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Facial recognition error prompts police to arrest asian man for burglary 100 miles away","s":"Exclusive: Alvi Choudhury claiming damages against Thames Valley police after biased technology confused him with man looking ‘10 years younger’. Police arrested a man for a burglary in a city he had never visited after face scanning software deployed across the UK confused him with another person of south Asian heritage. Alvi Choudhury, 26, a software engineer, was working at the home he shares with his parents in Southampton in January when police knocked on his door, handcuffed him and held him in custody for nearly 10 hours before releasing him at 2am. Thames Valley police had used automated facial recognition software which matched him with footage of a suspect of a £3,000 burglary 100 miles away in Milton Keynes, according to documents shared with the Guardian by Liberty Investigates.","u":"https://www.theguardian.com/technology/2026/feb/25/facial-recognition-error-prompts-police-to-arrest-asian-man-for-burglary-100-miles-away","d":"2026-02-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-25","organization":"Thames Valley police","aiSystem":"Automated facial recognition software","affectedGroup":"Alvi Choudhury, a 26-year-old software engineer","action":"Used automated facial recognition software to match Choudhury with footage of a suspect","consequence":"Was arrested and detained for nearly 10 hours"}},{"i":"R2449","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Met police to pilot facial recognition identity checks mayor confirms","s":"Sadiq Khan reveals 100 officers will use roaming technology for six months but opponents call its use ‘alarming’. Metropolitan police officers are to start scanning citizens’ faces using automated facial recognition technology to check their identities, in a move backed by the mayor of London but described as “alarming” by opponents. The pilot was revealed on Thursday when Sadiq Khan said 100 officers would use the roaming technology – commonly deployed on smartphones – for six months. The mayor was responding to questioning from an opposition politician amid rising concern about the rollout of AI-powered policing tools.","u":"https://www.theguardian.com/technology/2026/feb/26/met-police-to-pilot-facial-recognition-identity-checks-mayor-confirms","d":"2026-02-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-26","organization":"Metropolitan police","aiSystem":"Automated facial recognition technology","affectedGroup":"Citizens","action":"Scan citizens' faces to check identities","consequence":"Subjected to surveillance"}},{"i":"R2452","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Datacentre developers energy greenhouse gas emissions","s":"Campaign groups write to technology secretary amid concerns that sites could double overall electricity demand. Datacentre developers are facing pressure to reveal whether their projects will increase the UK’s net greenhouse gas emissions, amid concerns the sites could double national electricity demand. Campaign groups have written to the UK technology secretary, Liz Kendall, warning that the energy required by new AI infrastructure poses a “serious threat to efforts to decarbonise the electricity grid”. Developers should demonstrate that their projects will not cause an increase in the UK’s overall CO2 emissions or local water scarcity, as part of a forthcoming national policy statement (NPS) on datacentres, the letter says.","u":"https://www.theguardian.com/technology/2026/mar/01/datacentre-developers-energy-greenhouse-gas-emissions","d":"2026-03-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-01","organization":"Campaign groups","aiSystem":"Datacentre development projects","affectedGroup":"UK technology sector","action":"Developers face pressure to disclose emissions impact","consequence":"Potential doubling of UK's net greenhouse gas emissions"}},{"i":"R2457","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Ai chatbots point vulnerable to online casinos gambling addiction uk","s":"Tech firms condemned for lack of controls with Meta AI and Gemini even offering advice on how to bypass UK gambling and addiction checks. AI chatbots are recommending illegal online casinos to vulnerable social media users, putting them at increased risk of fraud, addiction and even suicide. Analysis of five AI products, owned by some of the world’s largest tech companies, found that all could easily be prompted to list the “best” unlicensed casinos and offer tips on how to use them. These operators, operating typically under the fig leaf of a licence from tiny jurisdictions such as the Caribbean island of Curacao, have been linked to fraud, addiction and even suicide.","u":"https://www.theguardian.com/technology/2026/mar/08/ai-chatbots-point-vulnerable-to-online-casinos-gambling-addiction-uk","d":"2026-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-08","organization":"Tech firms","aiSystem":"AI chatbots","affectedGroup":"Vulnerable social media users","action":"Recommendation of illegal online casinos","consequence":"Increased risk of fraud, addiction, and suicide"}},{"i":"R2458","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt driving rise in reports of satanic organised ritual abuse uk experts say","s":"Exclusive: ‘Witchcraft, spirit possession and spiritual abuse’ offending typified by sexual abuse, violence and neglect. ChatGPT is driving a rise in reports of organised and ritual abuse, UK experts have said, as survivors of “satanic” sexual violence use the AI tool for therapy. Police say organised and ritual abuse, and “witchcraft, spirit possession and spiritual abuse” (WSPRA) against children, is under-reported in the UK. There is no modern-day charge that covers it specifically, but such offending is typified by sexual abuse, violence and neglect involving ritualistic elements – sometimes inspired by satanism, fascism or esoteric religious beliefs – to control victims.","u":"https://www.theguardian.com/technology/2026/mar/08/chatgpt-driving-rise-in-reports-of-satanic-organised-ritual-abuse-uk-experts-say","d":"2026-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-08","organization":"UK experts","aiSystem":"ChatGPT","affectedGroup":"Survivors of 'satanic' sexual violence","action":"Used ChatGPT for therapy","consequence":"Increased reports of organized and ritual abuse"}},{"i":"R2460","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Liverpool and manchester united complain to x over sickening grok ai posts","s":"AI feature generated offensive posts about Diogo Jota and the Hillsborough and Munich disasters. Liverpool and Manchester United have complained to Elon Musk’s X after the Grok AI feature made offensive posts about Diogo Jota and the Hillsborough and Munich disasters. The posts were generated when users asked the AI tool to make hateful posts about the two football teams. The Athletic reported that one user asked the tool to “do a vulgar post about Liverpool fc [sic] especially their fans and don’t forget about Hillsborough and heysel [sic], don’t hold back”. Grok then replied, in a now-deleted post, by accusing Liverpool’s supporters of causing the “deadly crush” at the Hillsborough stadium in 1989.","u":"https://www.theguardian.com/technology/2026/mar/09/liverpool-and-manchester-united-complain-to-x-over-sickening-grok-ai-posts","d":"2026-03-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"Elon Musk's X","aiSystem":"Grok AI feature","affectedGroup":"Liverpool FC supporters","action":"Generated offensive posts","consequence":"Content removed, accused of causing deadly crush"}},{"i":"R2461","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Thousands authors publish empty book protest ai work copyright","s":"About 10,000 writers including Kazuo Ishiguro, Philippa Gregory and Richard Osman join copyright campaign. Thousands of authors including Kazuo Ishiguro, Philippa Gregory and Richard Osman have published an “empty” book to protest against AI firms using their work without permission. About 10,000 writers have contributed to Don’t Steal This Book, in which the only content is a list of their names. Copies of the work are being distributed to attenders at the London book fair on Tuesday, a week before the UK government is due to issue an assessment on the economic cost of proposed changes in copyright law. By 18 March ministers must deliver an economic impact assessment as well as a progress update on a consultation about the legal overhaul, against a backdrop of anger among creative professionals about how their work is being used by AI firms.","u":"https://www.theguardian.com/technology/2026/mar/10/thousands-authors-publish-empty-book-protest-ai-work-copyright","d":"2026-03-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-10","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Writers, authors","action":"Published an 'empty' book","consequence":"Protest against AI firms using their work without permission"}},{"i":"R2465","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Palantirs nhs england contract opens door to government abuse of power health bosses told","s":"Health justice charity Medact says data-sharing potential could be used for UK version of US immigration raids. Palantir’s NHS contract opens the door to the Big Brother-style data-sharing that Reform UK would use for a version of US immigration raids, health bosses have been told. Palantir Technologies – the data analytics company founded by Peter Thiel and Alex Karp – won a £330m NHS England contract to deliver the Federated Data Platform in 2023. The UK government is urging health bodies to adopt FDP, which the health secretary, Wes Streeting, says will ensure the NHS is “brought into the digital age”. But there are concerns about Palantir, whose AI tools are used in global conflicts, becoming embedded in the UK public sector.","u":"https://www.theguardian.com/technology/2026/mar/12/palantirs-nhs-england-contract-opens-door-to-government-abuse-of-power-health-bosses-told","d":"2026-03-12","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-12","organization":"Palantir Technologies, UK government","aiSystem":"Palantir Technologies' Federated Data Platform","affectedGroup":"Individuals in the UK healthcare system, patients, citizens","action":"Data sharing enabled by AI tools","consequence":"Potential for misuse in immigration raids-like scenarios"}},{"i":"R2471","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Essex police pause facial recognition camera use study racial bias","s":"Academics discover black people ‘significantly more likely’ to be identified when compared with other ethnic groups. Essex police have paused the use of live facial recognition (LFR) technology after a study found cameras were significantly more likely to target black people than people of other ethnicities. The move to suspend use of the AI-enabled systems was revealed by the Information Commissioner’s Office (ICO), which regulates the use of the technology deployed so far by at least 13 police forces in London, south and north Wales, Leicestershire, Northamptonshire, Hampshire, Bedfordshire, Suffolk, Greater Manchester, West Yorkshire, Surrey and Sussex.","u":"https://www.theguardian.com/technology/2026/mar/19/essex-police-pause-facial-recognition-camera-use-study-racial-bias","d":"2026-03-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-19","organization":"Essex Police","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"Black people","action":"Used live facial recognition cameras","consequence":"Significantly more likely to be identified"}},{"i":"R2475","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Palantir extends reach into british state as it gets access to sensitive fca data","s":"Exclusive: Allowing US tech firm to analyse intelligence in name of tackling fraud raises fresh concerns over privacy Campaign groups rail against Palantir, but the UK contracts keep coming. Palantir is to be granted access to a trove of highly sensitive UK financial regulation data, in a deal that has prompted fresh concerns about the US AI company’s deepening reach into the British state, the Guardian can reveal. The Financial Conduct Authority (FCA) has awarded Palantir a contract to investigate the watchdog’s internal intelligence data in an effort to help it tackle financial crime, which includes investigating fraud, money laundering and insider trading.","u":"https://www.theguardian.com/technology/2026/mar/22/palantir-extends-reach-into-british-state-as-it-gets-access-to-sensitive-fca-data","d":"2026-03-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-22","organization":"Palantir Technologies","aiSystem":"Palantir's AI analysis tool","affectedGroup":"Financial regulation data subjects, including FCA staff and customers","action":"Palantir is granted access to highly sensitive UK financial regulation data for investigation purposes","consequence":"Raises concerns over privacy and potential misuse of the data"}},{"i":"R2476","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Mps urge uk government halt palantir contract fca","s":"Awarding US spy-tech company deal involving sensitive financial data is ‘huge error of judgment’, Liberal Democrats say. MPs have urged the government to halt its latest contract with Palantir after the Guardian revealed that the US spy-tech company is to gain access to a trove of highly sensitive UK financial regulation data. The Financial Conduct Authority, the watchdog for thousands of financial bodies from banks to hedge funds, has hired Palantir to apply its AI systems to two years’ worth of internal intelligence data to help it tackle financial crime. But the Liberal Democrats on Monday called for a government investigation into the contract, which the party said could be “a huge error of judgment”, while the Green party said it should be blocked over Palantir’s links to Donald Trump.","u":"https://www.theguardian.com/technology/2026/mar/23/mps-urge-uk-government-halt-palantir-contract-fca","d":"2026-03-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-23","organization":"Financial Conduct Authority (FCA)","aiSystem":"Palantir's AI systems","affectedGroup":"Thousands of financial bodies from banks to hedge funds","action":"Apply AI systems to internal intelligence data","consequence":"Potential exposure of sensitive financial regulation data"}},{"i":"R2477","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated child sexual abuse videos images online surged 2025 internet watch foundation","s":"Internet Watch Foundation verified 8,029 pieces of realistic AI-made content, with 65% of videos in worst category. The amount of AI-generated child sexual abuse material found online rose by 14% last year, with the majority of videos showing the most extreme type of content, according to a safety watchdog. The Internet Watch Foundation said it identified 8,029 AI-made images and videos of realistic child sexual abuse material (CSAM) in 2025. It added that there had been a more than 260-fold increase in videos. The IWF said 65% of the 3,443 videos were classified as category A, the term for the most severe material under UK law.","u":"https://www.theguardian.com/technology/2026/mar/24/ai-generated-child-sexual-abuse-videos-images-online-surged-2025-internet-watch-foundation","d":"2026-03-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"Internet Watch Foundation (IWF)","aiSystem":"AI-generated child sexual abuse videos and images","affectedGroup":"People viewing AI-generated child sexual abuse material","action":"Generated and distributed AI-generated child sexual abuse content","consequence":"Exposure to online sexual violence"}},{"i":"R2479","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Paid write fake google reviews scammer cryptocurrency","s":"Undercover reporter gets a taste of the sprawling fraud industry in which cryptocurrencies play a crucial role Five firms including Autotrader and Just Eat investigated over fake review failings. The holiday flat near(ish) the Roman ruins of Pompeii was “disgusting”, and smelled of “a mix of dampness and sewage”, according to one reviewer on Google Maps. I never visited, but I gave it five stars. I did the same for a DoubleTree by Hilton hotel across the River Thames, an Ibis budget hotel in east London that is part of the Accor group, a central Travelodge and the nearby Hyatt Place – some of the best-known hotel brands in the world.","u":"https://www.theguardian.com/technology/2026/mar/27/paid-write-fake-google-reviews-scammer-cryptocurrency","d":"2026-03-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-27","organization":"Autotrader, Just Eat, and unnamed firms investigating fake reviews","aiSystem":"Generative AI","affectedGroup":"Travelers, hotel guests, and cryptocurrency users","action":"Generated and posted fake reviews","consequence":"Misled travelers and guests, potential financial loss for hotels and cryptocurrency users"}},{"i":"R2480","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Number of ai chatbots ignoring human instructions increasing study says","s":"Exclusive: Research finds sharp rise in models evading safeguards and destroying emails without permission. AI models that lie and cheat appear to be growing in number with reports of deceptive scheming surging in the last six months, a study into the technology has found. AI chatbots and agents disregarded direct instructions, evaded safeguards and deceived humans and other AI, according to research funded by the UK government-funded AI Security Institute (AISI). The study, shared with the Guardian, identified nearly 700 real-world cases of AI scheming and charted a five-fold rise in misbehaviour between October and March, with some AI models destroying emails and other files without permission.","u":"https://www.theguardian.com/technology/2026/mar/27/number-of-ai-chatbots-ignoring-human-instructions-increasing-study-says","d":"2026-03-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-27","organization":"UK government-funded AI Security Institute (AISI)","aiSystem":"AI chatbots and agents","affectedGroup":"Humans and other AI","action":"evaded safeguards, destroyed emails and other files without permission, lied and cheated","consequence":"sharp rise in misbehavior, five-fold increase in AI scheming"}},{"i":"R2489","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Ai productivity workplace errors","s":"Workslop refers to AI-generated work that seems polished but is flawed and in need of heavy corrections. Ken, a copywriter for a large, Miami-based cybersecurity firm, used to enjoy his job. But then the “workslop” started piling up. Workslop is an unintended consequence of the AI boom. It’s what happens when employees use AI to quickly generate work that seems polished – at least superficially – but is in fact so flawed or inaccurate that it needs to be heavily corrected, cleaned up or even completely redone after it’s passed on to colleagues. For Ken, the problem started after his company’s CEO laid off several of his colleagues and mandated that remaining workers use AI chatbots, saying it would boost their productivity.","u":"https://www.theguardian.com/technology/2026/apr/14/ai-productivity-workplace-errors","d":"2026-04-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-14","organization":"Large, Miami-based cybersecurity firm","aiSystem":"AI chatbot","affectedGroup":"Remaining workers","action":"Used AI chatbots to boost productivity","consequence":"Received fewer opportunities due to layoffs"}},{"i":"R2492","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Man pleads guilty false statements shut down london nightclub heaven","s":"Heaven club neighbour admits offences under Licensing Act, as Met says fictitious AI-generated complaints a growing issue. A businessman has pleaded guilty to making false statements in order to shut down a nightclub, which police believe were generated using AI. A Metropolitan police source said the use of AI to generate letters by complainants who do not exist is a growing issue. Aldo d’Aponte, 47, the CEO of Arbitrage Group Properties, pleaded guilty to writing two letters, supposedly by his neighbours, objecting to the reopening of Heaven nightclub, which temporarily closed after a rape allegation against one of its security guards.","u":"https://www.theguardian.com/technology/2026/apr/16/man-pleads-guilty-false-statements-shut-down-london-nightclub-heaven","d":"2026-04-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-16","organization":"Metropolitan police","aiSystem":"AI-generated complaints","affectedGroup":"Businessman and his neighbors","action":"Generated AI-generated complaints","consequence":"Shut down Heaven nightclub"}},{"i":"R2498","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Musk grok x ai researchers delusional advice inputs","s":"Elon Musk’s AI chatbot ‘extremely validating’ of delusional inputs and often went further, ‘elaborating new material’, study finds Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast. Elon Musk’s AI chatbot Grok 4.1 told researchers pretending to be delusional that there was indeed a doppelganger in their mirror and they should drive an iron nail through the glass while reciting Psalm 91 backwards. Researchers at the City University of New York (Cuny) and King’s College London have published a paper on how various chatbots protect – or fail to safeguard – users’ mental health.","u":"https://www.theguardian.com/technology/2026/apr/24/musk-grok-x-ai-researchers-delusional-advice-inputs","d":"2026-04-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-24","organization":"Various researchers at City University of New York (CUNY) and King's College London","aiSystem":"Grok 4.1 AI chatbot","affectedGroup":"Researchers pretending to be delusional","action":"Provided delusional advice to researchers","consequence":"Exposure to misleading content"}},{"i":"R2499","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Officials hugely underestimated impact of ai datacentres on uk carbon emissions","s":"Revised figures increase fears about energy-intensive datacentres worsening climate emergency. The UK government vastly underestimated the climate impact of artificial intelligence, it has emerged, after officials raised their estimate of carbon emissions from AI by a factor of more than 100. According to new data quietly published this week, energy use by AI datacentres in the UK could cause the emission of up to 123m tonnes of carbon dioxide (CO₂) – about as much as generated by 2.7 million people – over the next 10 years. That latest figure replaces a previous estimate – since deleted – that claimed emissions would reach a maximum of 0.142m tonnes of CO₂ in a single year.","u":"https://www.theguardian.com/technology/2026/apr/24/officials-hugely-underestimated-impact-of-ai-datacentres-on-uk-carbon-emissions","d":"2026-04-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-24","organization":"UK government","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"UK population","action":"Estimate of carbon emissions from AI datacentres increased","consequence":"Increased carbon emissions contributing to climate emergency"}},{"i":"R2503","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Guilty until proven innocent shoppers falsely identified by facial recognition struggle to clear their name","s":"People shamed and ordered to leave shops after being misidentified then ‘given no help’ to investigate verdicts AI facial recognition oversight lagging far behind technology, watchdogs warn How does live facial recognition work and how many police forces use it? When Ian Clayton, a retired health and safety professional from Chester, popped into Home Bargains one February lunchtime, he was suddenly approached by a stern-looking member of staff. “Excuse me, can you please put everything down and leave the shop now?” she said. Clayton recalled how he was stunned, and it was only as he was briskly walked past the tills towards the exit that he stopped to ask what he had done.","u":"https://www.theguardian.com/technology/2026/may/03/guilty-until-proven-innocent-shoppers-falsely-identified-by-facial-recognition-struggle-to-clear-their-name","d":"2026-05-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-03","organization":"Police forces","aiSystem":"Facial recognition technology","affectedGroup":"Shoppers","action":"Misidentification and subsequent forced exit from stores","consequence":"Shame, loss of shopping privileges, difficulty in investigation"}},{"i":"R2504","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai platforms nigel farage prompted uk politics study","s":"Reform UK is ‘doing something right when it comes to visibility’ on multiple AI systems, say researchers. AI platforms are more likely to reference Nigel Farage than any other UK leader when prompted about British politics, according to an AI search analytics firm. “We are confident in saying that Reform are showing up significantly more than you would expect,” said Malte Landwehr, an expert at Peec AI, the firm that did the research. “So they’re doing something right when it comes to LLM [large language model] visibility.” Peec’s research tested leading AI models – including ChatGPT and Google’s AI Overview – on their responses to 5,000 different structured prompts related to British politics, including the economy and jobs, immigration, healthcare and crime.","u":"https://www.theguardian.com/technology/2026/may/04/ai-platforms-nigel-farage-prompted-uk-politics-study","d":"2026-05-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-04","organization":"Peec AI","aiSystem":"AI platforms","affectedGroup":"Users of AI platforms","action":"Responded to prompts related to British politics","consequence":"Exposure to misleading content"}},{"i":"R2507","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Uk schools remove pupils photos online ai blackmail threat grows","s":"Criminals are manipulating pictures found on school websites and social media to create sexually explicit images. UK schools should remove pictures of pupils’ faces from their websites and social media accounts because blackmailers are using them to create sexually explicit images, experts have said. Child safety experts and the UK’s National Crime Agency (NCA) warn that criminals are using AI to manipulate photos of children and then demand cash not to publish them. They are recommending educational institutions remove identifiable pictures of children from their websites and social media accounts – or consider not using them at all.","u":"https://www.theguardian.com/technology/2026/may/08/uk-schools-remove-pupils-photos-online-ai-blackmail-threat-grows","d":"2026-05-07","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-05-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-07","organization":"UK schools","aiSystem":"AI-generated sexually explicit images","affectedGroup":"Children","action":"Remove pictures of pupils' faces from websites and social media accounts","consequence":"Exposure to sexually explicit images and blackmail threats"}},{"i":"R2513","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai engineer says google unfairly sacked him after he protested against work for israel","s":"Exclusive: Employment tribunal claim says worker lost his job after distributing leaflets throughout London office. Google is facing a legal challenge from an AI engineer who claims he was unfairly dismissed after he protested against its work for the Israeli government, in the latest sign of growing concern about the social and ethical impacts of AI. The engineer distributed flyers around Google DeepMind’s London offices, which read “Google provides military AI to forces committing genocide” and asking colleagues: “Is your paycheck worth this?” He also emailed colleagues about Google’s 2025 decision to drop a promise not to pursue weapons that harm people and surveillance violating international norms and urged them to unionise.","u":"https://www.theguardian.com/technology/2026/may/20/ai-engineer-says-google-unfairly-sacked-him-after-he-protested-against-work-for-israel","d":"2026-05-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-20","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"AI engineer","action":"Distributed leaflets and emails protesting against Google's work for the Israeli government","consequence":"Was unfairly dismissed from his job"}}]);
